INSERT INTO songs (song_number, title, category, songbook, song_text, tune, words, music, notes, lang, count, created_at) VALUES 
(1, 'Отче наш', 29, 11, 'Куплет 1\nОтче наш, що єси на небесах!\nНехай святиться Ім’я Твоє,\nНехай прийде Царство Твоє,\nНехай буде воля Твоя, як на небі, так і на землі.\n\nRefrain \nХліб наш насущний дай нам сьогодні;\nІ прости нам провини наші,\nЯк і ми прощаєм винуватцям нашим.\nІ відверни нас від спокуси,\n\nVerse 2\nАле визволи нас від лукавого.\nБо Твоє є Царство і сила,\nІ слава во віки віків. Амінь.', '', '', '', '', 'ua', 4, NULL),
(2, 'Отче Небесний Боже Могутній', 1, 11, 'Куплет 1\nОтче Небесний, Боже Могутній,\nТи Утішитель, Дух Правди  Ти,\nВсюди присутній і Всевідучий,\nБудь тут із нами, нас просвіти!\n\nКуплет 2\nОтче Небесний, Скарбе ласк многих!\nНас, дітей своїх, не забувай;\nПрийди, вселися в серцях убогих,\nБлагослови нас, щастя нам дай!\n\nКуплет 3\nОтче Небесний, збав нас від скверни\n І чистотою душу вкраси;\nХай Твоя ласка радість нам верне,-\n Нас у недолі, Боже, спаси!', '', '', '', '', 'ua', 1, NULL),
(3, 'О Боже вчуй мене Господи мій', 0, 11, 'Куплет 1\nО, Боже, вчуй мене, Господи мій!\nХочу Тебе любить якнайщиріш.\nХочу Тебе любить (2р.) якнайщиріш (2р.).\n\nКуплет 2\nХочу сердечно я із коленим днем Твоє хвалить Ім’я любві вогнем.\nТвоє хвалить Ім’я (2р.) любві вогнем (2р.).\n\nКуплет 3\nБлукав я в марноті - до зла ішов,\nА щастя лиш в Христі навік знайшов.\nА щастя лиш в Христі (2р.) навік знайшов (2р.).\n\nКуплет 4\nСкорботи іноді смутять спокій, - Хочу я і тоді любить щиріш.\nХочу я і тоді (2р.) любить щиріш (2р.).\n\nКуплет 5\nКоли й моє життя в вічність піде,\nБуду і в небі я любить Тебе.\nБуду і в небі я (2р.) любить Тебе (2р.).\n\nКуплет 6\nІ вірю, - буду там у славі жить,\nДе вічний Божий храм, Творця хвалить.\nДе вічний Божий храм (2р.), Творця хвалить (2р.).', '', '', '', '', 'ua', 0, NULL),
(4, 'О Боже милосердний Ти нас благослови', 0, 11, 'Куплет 1\nО, Боже милосердний, Ти нас благослови,- \nСвій дощ ізлий небесний: /серця всіх оживи!/(2р.)\n\nКуплет 2\nДай нам у всьому мудрість, у праці помагай,\n Небесне світло - радість /постійно посилай!/ (2р.)\n\nКуплет 3\nЗавсіди будь Ти з нами: навчай, охороняй, - \nПремудрими путями /до Царства направляй!/ (2р.)', '', '', '', '', 'ua', 0, NULL),
(5, 'Боже почуй мої моління', 0, 11, 'Куплет 1\nБоже, почуй мої моління,\nТебе, Господь, благаю я:\nПрийми мій плач і сокрушіння,- \nВ Тобі надія вся моя!\n\nКуплет 2\nМоя молитва нехай лине \nДо Тебе, наче фіміам,\nІ серце лине безупинно \nВ чудовий Твій небесний храм.\n\nКуплет 3\nСердечно я Тебе благаю, - \nПрости мені, чим я згрішив;\nТобі злі вчинки відкриваю,\nПровини всіх минулих днів.\n\nКуплет 4\nПрости усі мої провини,\nСкорботне серце підкріпляй:\nВ безрадній і тяжкій годині \nДля боротьби Ти сили дай.\n\nКуплет 5\nЩоб повсякчасно за Тобою \nУ світлі правди міг я йти.\nМій Боже, я Тебе благаю,- \nПочуй мої моління Ти!', '', '', '', '', 'ua', 0, NULL),
(6, 'О Господи Боже благаю Тебе', 0, 11, 'Куплет 1\nО, Господи Боже, благаю Тебе:\nВізьми Ти у жертву життя все моє;\nОчисть моє серце і дух обнови,\nОбмий всі провини в пречистій крові!\n\nПриспів: \nКров’ю обмий, кров’ю обмий,\nЗішли в моє серце небесний спокій!\n\nКуплет 2\nО, Господи Боже, почуй Ти мене,\nНавчи прославляти Ім’я лиш Твоє;\nІзлий в моє серце святу благодать,\nДай радість спасіння душею прийнять!\n\nКуплет 3\nОбмий мою душу в пречистій крові,\nІ стану, обмитий, за сніг я біліш.\nО Боже, дай твердість у вірі мені,\nЩоб овоч приносив завжди я Тобі!', '', '', '', '', 'ua', 0, NULL),
(7, 'Не минай мене мій Спасе', 0, 11, 'Куплет 1\nНе минай мене, мій Спасе, - в серце світла дай!\nВсюди молять Тебе люди: Боже, не минай!\n\nПриспів: \nБоже, Боже, о почуй мене!\nВсюди молять Тебе люди: Не минай мене!\n\nКуплет 2\nЯ утомлений душею, - поможи мені,\nБудь завсіди Ти зі мною в тяжкі й кращі дні.\n\nКуплет 3\nЯ на Тебе покладаю надії мої, - \nОживи мій дух, благаю, сили дай мені!', '', '', '', '', 'ua', 0, NULL),
(8, 'Я утомлений безсилий', 0, 11, 'Куплет 1\nЯ утомлений, безсилий, Боже мій, до Тебе йду!\nТільки в Тобі, Боже милий, Я спокій душі знайду!\n\nПриспів: \nБоже мій, до Тебе йду я,\nОживи мене, молю!\nПідкріпляй постійно Духом,\nСерцю дай любов Твою!\n\nКуплет 2\nБезутішний, скрізь блукав я, - де ж міг радість я знайти?\nДо Тебе тепер прийшов я: вірю, втішиш мене Ти.\n\nКуплет 3\nВсю марноту і тривогу Сам розвій, о Боже мій;\nПоможи пройти дорогу-цей тернистий шлях земний!\n\nКуплет 4\nІ коли я знеможуся в боротьбі тут на землі, - \nМій Спасителю, молюся, поможи тоді мені!', '', '', '', '', 'ua', 0, NULL),
(9, 'Я чую поклик Твій', 0, 11, 'Куплет 1\nЯ чую поклик Твій, ласкавий Спасе мій, - \nОбмитися в Крові святій, знайти душі спокій!\n\nПриспів: \nО, Спаситель мій, йду до Тебе я:\nВірю, змиє гріх тяжкий Пречиста Кров Твоя!\n\nКуплет 2\nНадія вся моя і сила лиш в Тобі:\nКріплюсь Тобою завжди я в життєвій боротьбі.\n\nКуплет 3\nТи всім життя даєш, хто за Тобою йде,\nІ в Царство Правди тих ведеш, в любові хто живе.\n\nКуплет 4\nСпасителю, хвала, хвала любві Т воїй:\nДуша моя в Тобі знайшла і радість, і спокій!', '', '', '', '', 'ua', 0, NULL),
(10, 'О Спаситель через хвилі', 0, 11, 'Куплет 1\n О, Спаситель, через хвилі, через степи нас веди: \nНемічні ми і безсильні, - завжди перед нами йди; \nХліб небесний (2р.) дай нам, любий Спасе наш!\n\nКуплет 2\nІ струмінь води живої нам відкрий Ти із скали;\nНас дорогою вузькою Сам, Спасителю, веди!\nО, Спаситель (2р.), будь Ти з нами в кожний час!\n\nКуплет 3\nСтоїмо ми над Йорданом, — нам дорогу освіти, \nЩоб в Країну ту бажану всі могли ми увійти;\nСпів хваління (2р.) буде линути Тобі!', '', '', '', '', 'ua', 0, NULL),
(11, 'О Спаситель благодать на святі слова пролий', 0, 11, 'Куплет 1\nО, Спаситель, благодать на святі слова пролий!\nДай нам більше пізнавать волю у любві Твоїй.\n\nПриспів:\nДух єднання дай серцям, в святості охороняй,\n Засіяй, як сонце, нам, - Твоїм Словом научай!\n\nКуплет 2\nХай відкриє Святий Дух наше серце і наш слух -\n На святі діла любві, Боже, нас благослови!', '', '', '', '', 'ua', 0, NULL),
(12, 'Спасителю будь з нами всіх нас охороняй', 0, 11, 'Куплет 1\nСпасителю, будь з нами, всіх нас охороняй, -\nПремудрими путями до світла направляй!\n\nКуплет 2\nО, Боже, пробуди світ, людей об’єдини,\nЩоб за Тобою йшли вслід, у згоді всі жили!\n\nКуплет 3\nДай нам думки єдині, любов зогрій в серцях,\nЩоб всі були ми вірні у правді до кінця!\n\nКуплет 4\nСпасителю ласкавий, Ти нас благослови; \nПролий дощ благодатний, - нас знову оживи!', '', '', '', '', 'ua', 0, NULL),
(13, 'Милосердний Спасе вічно з нами будь', 0, 11, 'Куплет 1\nМилосердний Спасе, вічно з нами будь,\nЩоб небесний голос Твій могли ми чуть.\nВелика нам радість, коли Ти із нами:\nТи нас підкріпляєш живими словами В скорботах всіх.\n\nКуплет 2\nЩоб спасти загиблих, Ти з небес зійшов,\nНа цей світ скорботний у тілі прийшов;\nЗа нас, о Спаситель, терпів Ти страждання, \nЩоб грішним нам дати усім оправдання В крові святій.\n\nКуплет 3\nТи нас захищаєш, як пастир овець;\nТи покірних любиш, як сина отець;\nДай нам більше віри, втішай Святим Духом. \nПостійно будь нашим Заступником, Другом,\nНас научай!\n\nКуплет 4\nО, дай шлях тернистий в святості пройти,\nІ для Тебе, Спасе, овоч принести.\nНавчи ж нас завсіди на Тебе взирати,\nТепер і повіки Тебе прославляти В Царстві Твоїм!', '', '', '', '', 'ua', 0, NULL),
(14, 'Ось зібрались знову ми Тебе Отче прославлять', 0, 11, 'Куплет 1\nОсь зібрались знову ми Тебе, Отче, прославлять. \nБоже наш, хвалу прийми, - і пошли нам благодать! \nДух наш в вірі підкріпляй, щоб Тобою ми жили,- \nКрай земний, дочасний край свято, радісно пройшли.\n\nКуплет 2\nО, Спасителю, навчай, як у світі маєм жить.\nСилу Духа посилай, щоб могли ми всіх любить. Поможи, щоб ми жили в згоді, як одна сім’я, Вірними у всім були до приходу Твого дня!\n\nКуплет 3\nБудем з радістю в серцях Господа Отця молить, - Віджене Він горе, страх, вірних нас благословить. Всю забудьмо марноту, будем Господу співать,\nІ Спасителю Христу, у піснях хвалу складать.', '', '', '', '', 'ua', 0, NULL),
(15, 'Предвічний Дух прийди Любов в серцях зогрій', 0, 11, 'Куплет 1\nПредвічний Дух, прийди! Любов в серцях зогрій \nІ Царство Правди утверди поміж Твоїх дітей.\n\nКуплет 2\nДай чисті почуття, будь з нами в кожний час, \nОсвітлюй темряву життя, веди вперед Ти нас.\n\nКуплет 3\nДай глибше нам пізнать премудрість слів Твоїх,\nНавчи Твій голос відрізнять від голосів чужих.\n\nКуплет 4\nНавчи перемагать спокуси всі земні;\nНавчи нас правди лиш шукать в небесній стороні.\n\nКуплет 5\nДай з радістю приймать страждання за Тебе,\nЩоб все життя могли віддать в служінні для Тебе.', '', '', '', '', 'ua', 0, NULL),
(16, 'О Спасе мій благаю я', 0, 11, 'Куплет 1\n О, Спасе мій, благаю я: прости провини всі мої!\nВ тузі моїй приходжу я й гріхи всі визнаю Тобі.\n\nКуплет 2\nОсь боротьбу з гріхом веду, і сам не маю сили я;\nЗа поміччю до Тебе йду: безмірна є любов Твоя!\n\nКуплет 3\nВід всіх гріхів мене обмий, дух підкріпи, пошли спокій. \nПрости мені, Спаситель мій, і буду вже повік я Твій!\n\nКуплет 4\n \nМене, о Боже, не суди, - перед Тобою я стою;\nПо милості Твоїй прости, прости, Спасителю, молю!\n\nКуплет 5\nРозбійника Ти сам простив і двері в рай йому відкрив; \nІ я на поклик Твій спішу, прощення, Господи, прошу!', '', '', '', '', 'ua', 0, NULL),
(17, 'Ісуса люблю я бо Він спас мене', 0, 11, 'Куплет 1\nІсуса люблю я, бо Він спас мене;\nДо Нього молюся, бо Він чує все.\nМій любий Ісусе, за мене Ти вмер, - \nЛюбити я щиро бажаю Тебе!\n\nКуплет 2\nВ житті і в час смерті любитиму я\n Спасительну жертву Благого Христа,\nМій любий Ісусе, Ти гріх мій простив,\nСлужити я завжди бажаю Тобі!\n\nКуплет 3\nУ славі небесній, при зборі святих \nІз уст спів чудесний поллється моїх.\nТам вічно вже буду я жити в Христі,\nА горе забуду, що мав на землі!', '', '', '', '', 'ua', 0, NULL),
(18, 'Днесь молитви шлемо ми', 0, 11, 'Куплет 1\nДнесь молитви шлемо ми,- друже, чуєш біль душі?\nТебе кличе Дух Святий, - чи ж не прийдеш, друже мій?\n\nПриспів: \nО, спіши (о, спіши), о, спіши (о, спіши), \nДнесь до Господа прийди! (2р)\nТи далеко заблудив; чи ж так й далі будеш жить?\nНаверни лице своє: тобі ласку Спас дає..\n\nКуплет 2\nТебе світ обманював, і спокою ти не знав;\nДо Христа вернись мерщій, в Нім однім знайдеш спокій.\n\nКуплет 3\nПрийди, визнай кожний гріх, - Він є Лікар ран твоїх. \nВсе життя віддай Христу, - душу Він спасе твою.', '', '', '', '', 'ua', 0, NULL),
(19, 'Всім серцем прагну я хвалить Небесного Отця', 0, 11, 'Куплет 1\nВсім серцем прагну я хвалить Небесного Отця, \nБажаю Богові служить в житті цім до кінця.\n\nКуплет 2\nХристос за мене постраждав, - мене Він полюбив;\nГосподь життя Своє віддав, - і двері в рай відкрив.\n\nКуплет 3\nПодяку, честь, хвалу Христу спішу в піснях складать: \nВін кров пролив Свою святу; нас хоче оправдать.\n\nКуплет 4\nІ ти, о друже змучений, Христа не забувай:\nПовір, - і ти відкуплений! Іди в Небесний Край!\n\nКуплет 5\nЖиттям святим ти приклад дай, шоб грішники прийшли \nДо ніг Спасителя Христа й спасіння в Нім знайшли.\n\nКуплет 6\nВ цей час смиренно всі прийдім до Господа Творця, \nВін сповнить Духом нас Святим, утішить всі серця.', '', '', '', '', 'ua', 0, NULL),
(20, 'Гляньте браття вгору в синій небозвід', 0, 11, 'Куплет 1\nГляньте, браття, вгору, в синій небозвід,\nНа шляхи небесні, на молочний слід!\nСонце, місяць, зорі, - хто їх засвітив?\nТу красу Всесильний Бог наш сотворив.\n\nКуплет 2\nГляньте, браття, в море, в темний океан,\nЩо водно хвилює, мов пшеничний лан.\nХто життям глибини морські наповнив?\nТвори ті Всесильний Бог наш сотворив.\n\nКуплет 3\nГляньте, любі браття, в повітряний світ:\nВесело гуляє там пташиний рід.\nХто орлам, соколам крила приростив?\nДива ті Всесильний Бог наш сотворив.\n\nКуплет 4\nГляньте кругом себе, на луги й поля:\nПишно вбрана в квіти рідная земля.\nХто в ліси й левади звірів нагніздив?\nВсе те Всемогутній Бог наш сотворив.\n\nКуплет 5\nГляньте всі на себе, гляньте на братів!\nХто серденькам нашим битися звелів?\nХто спрагу науки й віри в нас вселив?\nВсе це, браття, Бог дав, Він це сотворив.\n\nКуплет 6\nХто світи тримає у своїх руках,\nТак про сонце дбає, як і про комах, - \nТой ще більше дбає про дітей Своїх:\nДобром наділяє Господь нас усіх.', '', '', '', '', 'ua', 0, NULL),
(21, 'Як славний наш Господь в Сіоні', 0, 11, 'Куплет 1\nЯк славний наш Господь в Сіоні,\nТого наш розум не обняв;\nВеличний в небесах на троні - \nЖиття Він всьому й устрій дав.\nТи, Боже наш, повсюди славний,\nТи серед дня і ночі явний.\n\nКуплет 2\nТи сонця світло посилаєш \nВ проміннях ясних для людей,\nНебесним хлібом підкріпляєш \nСвоїх улюблених дітей.\nТи смертних, Боже, навіщаєш \nІ благодаттю оживляєш.\n\nКуплет 3\nО, Господи, у Край Небесний \nХай дійдуть наші голоси,\nПрийми хваління спів сердечний,\nЯк перли ранньої роси.\nСерця для Тебе відкриваєм,\nТебе в піснях ми величаєм!', '', '', '', '', 'ua', 0, NULL),
(22, 'Коли в житті цім утомлюся', 0, 11, 'Куплет 1\nКоли в житті цім утомлюся,\nВ борні затрачу я спокій,\nТоді благаю і молюся:\nПошли спокій, о Боже мій!\n\nПриспів:\n Зішли спокій примирення,\nДай мир і радощі спасіння,\nПошли бажаний спокій,\nО, Боже мій, пошли спокій!\n\nКуплет 2\nСкажи лиш слово - й стихне буря,\nУляжуть хвилі, і спокій.\nВсі прожене думки понурі,- \nІ стане знову світ ясний.\n\nКуплет 3\nЗнов проясни мою свідомість, - \nЩо тільки Ти Спаситель мій,\nЩо Ти зі мною в час утоми,\nІ в час досвідчень, в час грізний!\n\nКуплет 4\nІ Бог моління ці приймає \nИ душі зсилає свій спокій,\nІ їй предивно сповіщає,\nЩо дасть спокій ще більш ясний.\n\nКуплет 5\nНе буде то спокій вмирання,\nЧи спокій сну, чи забуття...\nЦе буде спокій воскресіння,\nІ спокій райського життя.\n\nКуплет 6\nТо буде спокій всехваління \nПо перемозі світлих сил,\nВ безсмерті вічного спасіння,\nКоли загине страх могил.', '', '', '', '', 'ua', 0, NULL),
(23, 'Я знаю так я знаю живе Спаситель мій', 0, 11, 'Куплет 1\nЯ знаю, так, я знаю, - живе Спаситель мій:\nВ Нім однім я лиш маю і радість, і спокій (2р.).\n\nКуплет 2\nЯ знаю, хто в хвилини недолі і журби \nМені дарує сили в земній тут боротьбі (2р.).\n\nКуплет 3\nЯ знаю, що скорботну Він душу утіша:\nНасичує голодну, на поміч поспіша (2р.).\n\nКуплет 4\nЯ знаю, навіть з мертвих мене підійме Він.\nВін знищив жало смерті: жить вічно буду з Ним (2р.).', '', '', '', '', 'ua', 0, NULL),
(24, 'У Край Небесний я іду', 0, 11, 'Куплет 1\nУ Край Небесний я іду,\nДе всі багатства у Христа:\nТам відпочинок я знайду,\nБлаженство вічного життя.\n\nПриспів: \nО, дивний Край, небесний рай!\nТуди, туди пливе човен,\nДе в ясних променях життя \nВ оселях вічних у Христа,\nЯ бачу берег вже новий,\nДе наш царює Бог Живий!\n\nКуплет 2\nЯ йду услід лиш за Христом,\nВеде мене Він під щитом;\nНадія в Нім моя уся:\nВвійду за Ним у небеса.\n\nКуплет 3\nВ краю тім дерева цвітуть,\nКвітки чудовий запах ллють,\nЖива вода струмком дзюрчить,\nНіколи там не в’яне цвіт.\n\nКуплет 4\nТам тихий віє вітерець,\nПриносить радість для сердець:\nТо — пісня ангелів святих \nДалеко від тривог земних.', '', '', '', '', 'ua', 0, NULL),
(25, 'Честь Тобі Спаситель слава Тяжкі муки Ти прийняв', 0, 11, 'Куплет 1\nЧесть Тобі, Спаситель, слава! Тяжкі муки Ти прийняв; \nЩоб були ми діти Божі, право радісне нам дав.\n\nПриспів: \nЧесть Тобі, Спаситель, слава!\nТяжкі муки Ти прийняв; \nЩоб були ми діти Божі,\nПраво радісне нам дав.\n\nКуплет 2\nДовго я блукав у світі, прагнув щастя і добра, —\nЛиш тепер усе знайшов я у Спасителя Христа.\n\nКуплет 3\nІ тепер моя надія на Христа - Його любов;\nЛиш Йому я довіряю: Він пролив за мене кров.\n\nКуплет 4\nІ живу я чи вмираю, — Відкупитель вічно мій:\nЛиш Йому хвалу складаю, - в Нім вся радість і спокій!\n\nКуплет 5\nВін, як Пастир, щохвилини стереже мене від зла \nІ до вічної Країни приведе, - Йому хвала!\n\nКуплет 6\nЧесть Тобі, Ісусе, й слава за терпіння на хресті,\nІ за поклик Твій ласкавий до життя в святій красі!', '', '', '', '', 'ua', 0, NULL),
(26, 'Великий Бог Коли на світ погляну', 0, 11, 'Куплет 1\nВеликий Бог! Коли на світ погляну,\nІ бачу все, що Ти створив в красі,\nЯк кожний цвіт склада Тобі пошану,\nІ як обняв любов’ю Ти усіх.\n\nПриспів:  \nТоді, Господь, мій дух співа Тобі:\nЯк славен Ти! Як славен Ти! - 2р\n\nКуплет 2\nКоли дивлюсь на мерехтючі зорі - \nТам, де горять світи незнані нам,\nДе сонце й місяць в вічному просторі \nПливуть в тиші, подібно кораблям.\n\nКуплет 3\nЯк навесні природа розцвітає,\nІ чую я в діброві солов’я,\nІ запах піль квітуючих вдихаю,\nЛюбов’ю сповнена душа моя.\n\nКуплет 4\nКоли із хмар навислих грім лунає,\nІ в пітьмі ночі блискавка мигтить,\nЯк під дощем природа оживає,\nВеселка в небі барвно заяснить.\n\nКуплет 5\nКоли читаю Книгу Заповітів,\nІ про Твої читаю я діла: \nЯк полюбив Ти нас, людей на світі \nІ для спасіння Сина нам послав.\n\nКуплет 6\nЯк зрю Христа cмиренного між людом,\nІ думаю я про Його любов,\nЯк Він прийняв за нас усіх наругу,\nІ на хресті пролив невинну кров.\n\nКуплет 7\nКоли спокуси серце огортають,\nІ дух мій тужить у важкій журбі,\nІ Він пречисті руки простягає,\nІ я кріплюсь в Його любві святій.\n\nКуплет 8\nКоли Господь мене Сам закликає,\nІ світить промінь сяєва Його, - \nТоді мій дух в смиренні замовкає,\nПризнавши велич Господа свого.', '', '', '', '', 'ua', 6, NULL),
(27, 'Як зір багато є вгорі', 0, 11, 'Куплет 1\nЯк зір багато є вгорі! \nЗоря ясніша від зорі.\nТа краще зір усіх краса \nЛюбові вічної Христа! (2р.)\n\nПриспів: \nЛюбов Христа (Зр.) -\nВона світліша сонця й зір.\n\nКуплет 2\nО, серце стомлене, радій:\nТворець усіх - Спаситель твій...\nЛюбов Христа шляхом вузьким \nВведе тебе у Вічний Дім (2р.).\n\nКуплет 3\nЛюбов веде всіх до Христа \nКрізь морок зла, в тісні врата; \nВона свята душі моїй, - \nЯ довіряюсь тільки їй (2р.).\n\nКуплет 4\nЯк зір багато є вгорі!\nЗоря ясніша від зорі,\nТа краще зір усіх краса \nЛюбові вічної Христа! (2р.)', '', '', '', '', 'ua', 0, NULL),
(28, 'Є кращий інший світлий Край', 0, 11, 'Куплет 1\nЄ кращий інший - світлий Край, | світ ясний! (2р.) \nНезнаний там є сум, відчай - | Край Святий! (2р.) \nСпівають там святі пісні,\nІ духи там живуть ясні.\nНіхто не знає там гріха, - | світ ясний! (2р.)\n\nКуплет 2\nБлакитне небо там без хмар, - | світлий край! (2р.) \nЖиття не має там примар, | Божий рай! (2р.)\nІ радості там без кінця \nПеред ясним лицем Творця.\nТам скрізь нев’януча краса, | дивний Край! (2р.)\n\nКуплет 3\nМи винні всі перед Христом, - | Він нас спас! (2р.) \nХоч світ пройнятий весь гріхом, — І Він нас спас! (2р.) \nІ Хто прийшов страждать за нас,\nТой може знять провини з нас,\nІ в край блаженства нас введе, — | Він нас спас! (2р.)\n\nКуплет 4\nЗа Господом усі ідіть, | вслід за Ним! (2р.)\nЗ Ним будемо там вічно жить,- | вслід за Ним! (2р.) \nНе гайтесь! Скоро час іде, - \nЧи в вірі вас Господь знайде,\nКоли за нами знов прийде? | Вслід за Ним! (2р.)', '', '', '', '', 'ua', 0, NULL),
(29, 'Я співаю як Спаситель мене дивно полюбив', 0, 11, 'Куплет 1\nЯ співаю, як Спаситель мене дивно полюбив.\nЯк страждав Він, мій Учитель,\nІ мене навік простив.\n\nПриспів:\nПісня ллється про Ісуса, смертю Він мене купив, \nКров пролив Свою невинну і мої гріхи простив..\n\nКуплет 2\nЯ співаю - дивні звуки: щоб мене від мук спасти, \nВін прийняв за мене муки,\nДав Себе Він розп’ясти.\n\nКуплет 3\nЯ співаю, як Спаситель в небі чистому сія,\nЯк всіх любить Відкупитель, - \nВічно з Ним там буду я .', '', '', '', '', 'ua', 0, NULL),
(30, 'Дізнавсь я про Церкву живую', 0, 11, 'Куплет 1\nДізнавсь я про Церкву живую -\n В ній радість для серця знайшов,\nНікуди вже більш не піду я,\nПрийнявши Христову любов.\n\nПриспів: \nО, друже, йди в Церкву живую,\nТам спокій і радість знайдеш.\nПовір і віддайся Ісусу,\nУ вічне блаженство ввійдеш.\n\nКуплет 2\nЧи знаєте Церкву живую ви,\nБраття і сестри мої?\nІдіть на дорогу святую - \nДо Церкви живої усі!\n\nКуплет 3\nСерця, що не мали спокою,\nЗнайшли там і щастя й спокій:\nТам ллються молитви рікою, - \nЖиве наш Спаситель у ній.\n\nКуплет 4\nХодив я усюди по світу,\nІ щастя ніде не знайшов;\nЗакінчився шлях безпросвітний,\nКоли я в ту Церкву прийшов.', '', '', '', '', 'ua', 0, NULL),
(31, 'Бог є любов о велике щастя', 0, 11, 'Куплет 1\nБог є любов, о велике щастя!\nБог є любов, любить Він і нас.\n\nПриспів: \nХай кожний радісно співа та славить,\n Його хай славить: Бог є любов!\n\nКуплет 2\nБог є любов; ми Його не знали;\nБог є любов, Він нам світло дав.\n\nКуплет 3\nБог є любов. Ми гріху служили, - \nБог є любов, - нам гріхи простив.\n\nКуплет 4\nІсус-Спаситель вмирав за мене,\nМій Відкупитель спасіння дав.\n\nКуплет 5\nТебе я буду величать, славить,\nЯ буду славить Твою любов!', '', '', '', '', 'ua', 0, NULL),
(32, 'В рідний Край в рідний Край серцем лину я', 0, 11, 'Куплет 1\nВ рідний Край, в рідний Край серцем лину я:\nТам щастя, радість вся моя, - забуду мук одчай.\nЦей світ чужий душі моїй, не рідний він мені;\nЗнайду я серцю лиш спокій в небесній стороні.\n\nКуплет 2\nВ небесах, в небесах, в оселі святій,\nО, скільки любих в тих краях, і там - Спаситель мій.\nУ цьому світі тяжко жить, стомивсь я в боротьбі;\nЯ хочу дні мої прожить з Тобою і в Тобі.\n\nКуплет 3\nСкоро я, скоро я в рідний Край ввійду.\nВстає зоря нового дня, святі часи ідуть.\nЧого ніколи на землі Не бачив я й не знав,\nГосподь спасенним і мені навік приготував.', '', '', '', '', 'ua', 0, NULL),
(33, 'Вперед сміліше браття спішімо всі вперед', 0, 11, 'Куплет 1\nВперед, сміліше, браття, спішімо всі вперед;\nІдімо без вагання лиш за Христом услід!\nНесімо хрест терпіння, - в серця спокій прийде;\nА хто Христа не прийме, той в Царство не ввійде.\n\nПриспів: \nВ небі жде нас спокій, (2р.)\nВ небі жде нас, (Зр.) спокій!\n\nКуплет 2\nХристос є наш Світильник, -\n Він попереду йде\n І путь нам освітляє, до щастя нас веде.\nХто серцем і душею довіриться Йому,\nТой в радості й спокою жить вічно буде з Ним.\n\nКуплет 3\nБагато дітей Божих вже спочивають там,\nДе сил нема ворожих, - Бог дав спокій серцям.\nМи теж там скоро будем у небі вічно жить...\nНе будем, як в цім світі, ми плакать і тужить.', '', '', '', '', 'ua', 0, NULL),
(34, 'Співайте хваліте Творця', 0, 11, 'Куплет 1\nСпівайте, хваліте Творця,\nХоч хрест ми несем на землі!\nХристос прийде в славі Отця, - \nО, як же нам буде тоді?\n\nКуплет 2\nОбмились ми в крові Христа,\nТепер же готуймось туди,\nДе в Божій любові життя.\nО, як же нам буде тоді?\n\nКуплет 3\nУ Агнця весілля для нас, - \nРадіючи, йдем ми туди,\nХоч сумно буває не раз...\nО, як же нам буде тоді?\n\nКуплет 4\nВ Божественнім Слові дзюрчить \nСтрумочок живої води, - \nІз нього ми можемо пить...\nО, як же нам буде тоді?\n\nКуплет 5\nХристос нас усіх відкупив, - \nВід нас Він тепер жде плодів;\nВін нам Царство Правди відкрив.\nО, як же нам буде тоді?\n\nКуплет 6\nУ вічному Царстві Христа Не будемо жити в біді:\nМинеться земна марнота.\nО, як же нам буде тоді?', '', '', '', '', 'ua', 0, NULL),
(35, 'Чи зможе хто на всьому світі', 0, 11, 'Куплет 1\nЧи зможе хто на всьому світі\nСвободу вірним відібрать,\nЩоб волю нашу ув’язнити \nІ дух в кайдани закувать?\nНаш дух закутий був в темряві,\nТа Бог звільнив і волю дав:\nЙому кайданів світ лукавий \nЩе і донині не скував.\n\nКуплет 2\nО, ні, ніхто на всьому світі \nНе візьме правди й честі в нас, \nХоч злобно будуть нас ганьбити \nИ гонить за правду в кожний час. \nПідіймем вгору прапор правди, \nЗлобу любов’ю обснуєм,\nІ честь не в славі цього світу, - \nВ любові вічній ми знайдем.\n\nКуплет 3\nО, ні, ніхто на всьому світі \nБагатства не візьме у нас.\nХай в жертву боротьби святої \nВ нас заберуть в жорстокий час \nІ золото, і все, що маєм, - \nСумління ж ми не віддамо:\nМи тайну щастя всім відкриєм,\nІ нею світ збагатимо.', '', '', '', '', 'ua', 0, NULL),
(36, 'Коли ти знеможений впадеш в безсилля', 0, 11, 'Куплет 1\nКоли ти знеможений впадеш в безсилля \nОслабнеш в нерівній, тяжкій боротьбі \nІ краплю по краплі із чаші страждання \nПить будеш з докором недолі своїй, - \nДушею не падай, вперед іди знов:\nЄ віра, надія, любов.\n\nКуплет 2\nКоли твоє серце заниє порою,\nІ прийдуть сумні та безрадісні дні,\nДуша не почує ні слова спокою,\nНіхто їй не скаже: "Іди, відпочинь!" \nЗгадай, що зігріє і душу, і кров, - \nЦе віра, надія, любов.\n\nКуплет 3\nКоли тебе стріне в житті якась втрата,\nНе плач безутішно, в тугу не впадай; \nЗнай, доля така є від Бога, мій брате:\nПризначення це неземного суда!\nТоді твою душу потішить лиш знов, - \nЦе віра, надія, любов.\n\nКуплет 4\nЗабракне терпіння, ослабнуть всі сили,\nІ буде тонуть у сумнівах душа, - \nОдну бережи в серці ціль до могили,\nБо й в тяжких стражданнях нам любе життя. \nНайбільше нам щастя у тому лежить: \nНадіятись, вірить, любить!', '', '', '', '', 'ua', 0, NULL),
(37, 'Спасен я О яка то радість', 0, 11, 'Куплет 1\nСпасен я! О, яка то радість,\nСпасенний я Кров’ю Христа;\nСпасен я по милості Божій - \nТепер я вже Боже дитя.\n\nПриспів:\nТак я, так я, спасенний я Кров’ю Христа,\nТак я, так я, тепер я вже Боже дитя!\n\nКуплет 2\nСпасен я! Щасливий в Ісусі,\nЩоб вияснити, - нема слів;\nВін в серці моїм поселився,\nІ любо мені жити з Ним.\n\nКуплет 3\nЯ думаю завжди про Спаса,\nІ безперестанно, ввесь день \nПро Його любов я співаю,\nЩо змістом є моїх пісень.\n\nКуплет 4\nЙого я побачу у славі —\nЦаря, в Кому розкіш моя;\nВін кроки мої направляє,\nНа путь Свій - у вічне життя.\n\nКуплет 5\nУ славі вінець мене жде вже,\nЩо Спас приготовив мені;\nЯк земне життя закінчиться,\nВін його доручить мені.', '', '', '', '', 'ua', 0, NULL),
(38, 'Буде дощ благословення', 0, 11, 'Куплет 1\nБуде дощ благословення, що нам Господь обіцяв. \nЙ грішники знайдуть спасіння в Христовій святій крові.\n\nПриспів: \nБлагословення нині нам, Боже, зішли. \nТебе ми щиро всі просим:\nДухом Святим нас сповни!\n\nКуплет 2\nБуде дощ благословення: хмари надходять уже! \nДуха Святого хрещення, Боже, пошли нам тепер!\n\nКуплет 3\nБуде дощ благословення... Боже, його нам зішли!\n В Христі новонародження дощ благодатний зішли!\n\nКуплет 4\nБуде дощ благословення... Зішли нам, Боже, тепер; \nВ тобі шукаєм спасіння, почуй нас, просим Тебе!', '', '', '', '', 'ua', 0, NULL),
(39, 'Слухай Чуєш Спасів голос', 0, 11, 'Куплет 1\nСлухай! Чуєш Спасів голос:\n«Хто з вас стане до діла?\nНиви білі, повний колос, - хто збере Мої жнива?» \nЛюбий голос Спаса кличе й нагороду обіця...\nХто з нас перший радо скаже:\n«Посилай мене, - ось я!»?\n\nКуплет 2\nЯк не можеш ти далеко нести добру новину,\nТо знайдеш усюди, брате, впавшу душу не одну. \nЯк не можеш дати тисяч, - Лепту вдовину хоч дай!\nСпас й те прийме до скарбниці,\nТільки щире серце май.\n\nКуплет 3\nХоч не так ти красномовний,\nЯк апостол був Павло, - Ближнім можеш поміч дати,\nВслід їх вести за Христом.\nКоли люди не зважають на твої любві слова,\nТи збери дітей маленьких і провадь їх до Христа.\n\nКуплет 4\nХай ніхто з нас не говорить:\n«Як я можу помогти?»\nБо навколо люди гинуть, - рятувати їх спіши! \nСлухай радо, що Спас каже,\nЩастя в праці тій знайди.\nЩирим серцем відізвися: «Ось я, Ти мене пошли!»', '', '', '', '', 'ua', 0, NULL),
(40, 'З любовію Ісус прийшов', 0, 11, 'Куплет 1\nЗ любовію Ісус прийшов, мене загиблого знайшов,\nІз глибини гріха, стида Ісус мене підняв...\n\nПриспів:\nАж з глибини Він спас мене, рукою Він підняв мене \nЗ нічної тьми до світла дня: о, слав Його, душе моя!\n\nКуплет 2\nІсус мене тоді шукав, коли я був ще у гріхах;\nЯк голос я Його почув, - і Він мене здвигнув...\n\nКуплет 3\nЗранений був з терня вінцем - кров потекла Його лицем, \nПрибити дав Він своїх рук,- тим спас мене від мук.\n\nКуплет 4\nЧому Ісус так постраждав, за людський гріх себе віддав? \nНе можу висловити я, - як Він з гріхів звільня...', '', '', '', '', 'ua', 0, NULL),
(41, 'Де знайде душа у країні якій', 0, 11, 'Куплет 1\nДе знайде душа, у країні якій,\nДля серця свойого і ласку й спокій?\nХто зміг би журливу її утішать,\nБо люди не можуть рятунку їй дать?\nНі-ні, ні-ні, світ нам чужий,\nЛиш в Царстві Христовім є повний спокій.\n\nКуплет 2\nУсім, хто Ісусові серце віддав,\nВін місто на небі святе збудував, - \nІ місто те сяє, як дивний вінець;\nЧи ж рідний то дім для спочинку сердець?\nТак-так, так-так - дім дорогий,\nЙ мені там з святими є вічний спокій.\n\nКуплет 3\nВізьми, мій Спасителю, Ти і мене,\nДе хори святих величають Тебе;\nДуша моя хоче в тім сонмі стоять,\nЗа Кров, за страждання Тебе прославлять. \nЖди, жди, скоро час твій прийде, —\nУ славу небесну тебе Він візьме,\n\nКуплет 4\nНадійся, душе, - недалеко той Край, \nНедовго і скажуть: Іди спочивай! \nБорися, не падай в тяжкій боротьбі: \nТам буде і слава, і спокій тобі. \nРадість, радість там у Отця \nУсім, хто терпить на землі до кінця.', '', '', '', '', 'ua', 0, NULL),
(42, 'Не хотів би я без плоду перед Господа прийти', 0, 11, 'Куплет 1\nНе хотів би я без плоду перед Господа прийти,\nХоч одну хотів би душу, - сніп один хоч принести.\n\nПриспів:\nНе хотів би я без плоду перед Господа прийти,\nХоч одну хотів би душу, - сніп один хоч принести.\n\nКуплет 2\nСпас життя дав, - добре знаю,- і я смерті не боюсь, \nАле сам себе питаю: 3 чим я перед Ним з''явлюсь?\n\nКуплет 3\nКоли б міг літа минулі, що намарно я прожив,\nЗ днів далеких повернути, -я б лиш Господу служив.\n\nКуплет 4\nО, працюйте, діти Божі! Подивіться - вже смерка:\nВсі негайно закликайте грішні душі до Христа!', '', '', '', '', 'ua', 0, NULL),
(43, 'Непослушне я дитя був залишив я отчий дім', 0, 11, 'Куплет 1\nНепослушне я дитя був, залишив я отчий дім.\nНа дорозі злій я гинув, - думу в серці я носив:\n\nПриспів:\nЯ вернусь, я вернусь! Отче любий, я вернусь!\nВсі гріхи Тобі скажу я, знов до Тебе я вернусь!\n\nКуплет 2\nЯ згрішив перед Тобою, признаюся я в сльозах; \nБуду я Тобі слугою, - не дай згинути в гріхах.\n\nКуплет 3\nО, тяжке життя моє є, бо далеко мій Отець!\nВсюди бачу тільки горе, та прийде йому кінець.\n\nКуплет 4\nОтче Ти мій милостивий, руку дай мені Свою! \nУчини мене щасливим, прийми сина, як слугу.', '', '', '', '', 'ua', 0, NULL),
(44, 'Милість Господня велика', 0, 11, 'Куплет 1\nМилість Господня велика так,\nЩо більша, як всі наші гріхи:\nТам на Голгофі з’явилася, - \nАгнець-Христос кров Свою пролив.\n\nПриспів:\nБожа милість (Божа милість) (2р.),\nВсім нам прощає вона гріхи,\nБожа милість (Божа милість) (2р.),\nБільша є, як наші всі гріхи.\n\nКуплет 2\nГріх і вагання, як море те,\nБушують, щоби душу згубить,\nНад всі гріхи милість більша є, -\n Вона навчає нас свято жить.\n\nКуплет 3\nНаші провини - не скриєм їх,\nЩо ж може змити їх нам з душі?\nГлянь, ось струмок на змиття тече, - \nБілим, як сніг, зробить він тебе.\n\nКуплет 4\nЦя милість дивна й безмежна є,\nПокриє тих, що вірні Йому;\nВсі, що готові любить Його,\nМилість в цю хвилю прийміть святу.', '', '', '', '', 'ua', 0, NULL),
(45, 'Любить нас Христос безмірно', 0, 11, 'Куплет 1\nЛюбить нас Христос безмірно, - як любить Він! \nЗавжди ласкаво і вірно, - як любить Він!\n(Щастя світу проминає, кращий друг нас забуває, \nСпас же ні, - не покидає! Як любить Він!)\t (2р)\n\nКуплет 2\nНа хресті Ісус в стражданнях... \nЯк любить Він! Грішним дав \nВін оправдання, - як любить Він! \n(Він минуле все прощає, радість дивну посилає, \nХто Йому лиш довіряє, - як любить Він!)\t(2р)\n\nКуплет 3\nХто пізнать Його бажає, - як любить Він, \nСпокій, щастя той пізнає, - як любить Він!\n(Він лікує усі болі; хто покірний Його волі, -\n Утішає Своїм Словом, - як любить Він!)\t (2р)', '', '', '', '', 'ua', 0, NULL),
(46, 'Небо яснеє темніє пітьма ночі настає', 0, 11, 'Куплет 1\nНебо яснеє темніє, пітьма ночі настає!\nМоже скоро вже Спаситель \nДух у вічність твій візьме.\n\nКуплет 2\nІ тоді ти пригадаєш, в Слові Божім, що читав, \nТоді гірко заридаєш,\nЩо Христа ти не прийняв.\n\nКуплет 3\nТа дарма, вже буде пізно: там не можна того взять,\n Що в житті ти цім відкинув...\nДармо будеш лиш благать.\n\nКуплет 3\nКнига Божа вже розкрита, перевірка там іде; \nНе записаний хто в Книзі,\nВ Царство Боже не ввійде.\n\nКуплет 4\nДруже, втомлений гріхами, у неправді не ходи,\nА небесний вчувши голос,\nДо Христа скоріш іди!', '', '', '', '', 'ua', 0, NULL),
(47, 'Пам’ятай про Бога завжди', 0, 11, 'Куплет 1\nПам’ятай про Бога завжди, друже мій, не забувай: \nЖиттям, словом і ділами Його в світі прославляй.\n\nКуплет 2\nТи собі все помишляєш: "Молодий, то веселись!\nА коли вже постарієш, тоді кайся і молись".\n\nКуплет 3\nО, нещасний, ти не знаєш, в яку пору ти умреш!\nМоже завтра вже не встанеш, - жити більше не будеш.\n\nКуплет 4\nМоже завтра побудують гріб сосновий вже тобі,\nІ земля навік покриє твоє тіло в глибині.\n\nКуплет 5\nО душе, душе, загинеш, так, загинеш ти тоді.\nПізно каятися буде, любий друже, вже тобі!\n\nКуплет 6\nТреба всі гріхи лишити, - грішнику, це пам’ятай:\nНе забудь Христа прийняти, - все життя Йому віддай!\n\nКуплет 7\nПам’ятай про це, мій друже, в молодих твоїх літах! \nПрославляй Христа Ісуса, - будеш з Ним у небесах.', '', '', '', '', 'ua', 0, NULL),
(48, 'По морю буйнім друже мій', 0, 11, 'Куплет 1\nПо морю буйнім, друже мій,\nПливеш ти прямо в Край святий,\nТвій Адмірал велить тобі: | "Вперед!" (Зр.)\n\nПриспів: \nВперед, вперед, і скоро буря ця \nУтихне, і перейде тьма,і Вперед (2р.). \nЖивий Бог, - Він велить: "Вперед, вперед!"\n\nКуплет 2\nХоч море шумить і реве,\nІ буря вітрила так рве;\nТа пристань недалеко вже, | "Вперед!" (Зр.)\n\nКуплет 3\nОсь корабель увесь дрижить,\nІ серце злякано тремтить,\nТа голос Божий все звучить: | "Вперед!" (Зр.)\n\nКуплет 4\nХоч буря так сильна й грізна \nІ човен вода залива,\nСтій, друже, на словах Христа: ''''Вперед!" (Зр.)', '', '', '', '', 'ua', 0, NULL),
(49, 'Вбачу я Царя радість це моя', 0, 11, 'Куплет 1\nВбачу я Царя, радість це моя;\nЯк узрю Царя в той день, - \nВ славнім тім раю, там я з Ним буду.\nБуду там завжди я з Ним.\n\nПриспів: \nВ Його славі вбачу я Царя,\nІ цю пісню заспіваю я,\nЩо за мене Він на хресті умер;\nВбачу я Царя в той день.\n\nКуплет 2\nВ славнім тім раю славу вбачу я,\nТам вже ночі не буде!- \n3 моїм Господом вічно буду там,\nВічне світло там буде.\n\nКуплет 3\nВбачу я Царя й принесу все я,\nБіля ніг Його складу!\nЗаспіваю я, як Він спас мене\nИ вдержав мене до часу.', '', '', '', '', 'ua', 0, NULL),
(50, 'О прокиньсь байдужий грішник', 0, 11, 'Куплет 1\nО, прокиньсь, байдужий грішник, годі, годі тобі спать!\nТи страждаєш, безутішний? - Ісус радість тобі дасть.\n\nПриспів: \nТи, що прагнеш очищення?\nВір! - і радість буде у душі твоїй,\nВстань! Спаситель кличе твій.\n\nКуплет 2\nХто приніс гріхи покірно до Голгофського хреста,\nТой знайшов душі прощення у Спасителя-Христа.\n\nКуплет 3\nО, прийди скоріш до Бога! Ти в гріхах, в неправді жив.\nЗа багатих і убогих кров Свою Христос пролив.', '', '', '', '', 'ua', 0, NULL),
(51, 'Знаєш друже річеньку ту', 0, 11, 'Куплет 1\nЗнаєш, друже, річеньку ту,\nЩо з Христа струмочком біжить?\nЗнаєш, Хто всім радість дає,\nНавчає прощати й любить?\n\nПриспів: \nХоч мій гріх великий, тяжкий:\nУ гріхах я довго блукав,\nАле став за сніг я біліш,\nЯк любов Христову прийняв.\n\nКуплет 2\nНа хресті в терновім вінку \nНаш Спаситель в муках вмирав:\nНедаремно Кров Він пролив, - \nТо за нас Він тяжко страждав.\n\nКуплет 3\nЯ у світі довго блукав,\nДумав в людях правду знайти;\nЛиш Господь мене пожалів,\nСилу дав до Нього прийти.\n\nКуплет 4\nВ серці довго я не вагавсь, -\n Кликав Він, - я встав і пішов,\nІ велику радість душі \nЯ навіки в Ньому знайшов.\n\nКуплет 5\nВ думах я люблю уявлять \nРічку, що з Голгофи біжить:\nЗ гріхів обмиває вона,\nІ життя та радість дарить.', '', '', '', '', 'ua', 1, NULL),
(52, 'Радіснії співи линьте в небеса', 0, 11, 'Куплет 1\nРадіснії співи, линьте в небеса!\nБлудний син, одумавшись, прийшов:\nЗ Богом примирився в радісних сльозах,\nВ рідний дім Отця він увійшов.\n\nПриспів: \nСлава, слава Богу в небесах!\nПрославляй уся земля Творця!\nНе вмовкайте співи в праведних устах,\nПрославляйте всі любов Отця!\n\nКуплет 2\nРадіснії співи, линьте в небеса,\nБо знайшлась загублена вівця:\nГрішник, що був мертвий у своїх гріхах,\nВін тепер прийшов вже до Отця.\n\nКуплет 3\nРадіснії співи, линьте в небеса!\nПрославляйте всі любов Христа,\nХай звучить подяка в радісних серцях,\nХай Христа прославлять всі уста.', '', '', '', '', 'ua', 0, NULL),
(53, 'Голос Духа Святого звучить', 0, 11, 'Куплет 1\nГолос Духа Святого звучить:\nВсіх до Спаса Він кличе: Прийдіть!\nО, друже, вчуй голос святий!\n\nПриспів: \nПрийди (кличе Він), прийди (кличе Він)!\nПрийди скоріш! Христос дасть спокій.\n\nКуплет 2\nРозкіш світу тебе обмане...\nА Спаситель все кличе тебе, - \nЧому ж до Ісуса не йдеш?\n\nКуплет 3\nТо за тебе Син Божий вмирав,\nДар спасіння тобі завіщав.\nВізьми ж дар Ісуса тепер!', '', '', '', '', 'ua', 0, NULL),
(54, 'Я дізнавсь про любов Христа', 0, 11, 'Куплет 1\nЯ дізнавсь про любов Христа,\nЯк ходив Він колись по землі,\nЯк робив Він великі діла,\nЯк страждав і умер на хресті (хресті). | (2 р.)\n\nПриспів: \nТак, так, за мене, мене,\nТак, так, за мене;\nСпаситель з небес, повний слави, чудес, \nУмирав, щоб спасти вас, мене.\n\nКуплет 2\nЯ дізнавсь, як Ісус страждав,\nЯк томився Він в муках і вмер.\nЗ Книги Божої я дізнавсь,\nЩо Христос умирав за мене (мене). | (2 р.)\n\nКуплет 3\nЯ дізнавсь про Небесний Край,\nДе святі будуть в славі Христа,\nО, чи є там, у тім Краю,\nПриготоване місце мені (мені)? | (2 р.)\n\nКуплет 4\nО, я знаю Господні слова:\n- Життя вічне Я вірним даю. -\n Так, я вірю і люблю Христа!\nЗнаю, дасть мені місце в раю (в раю). | (2 р.)', '', '', '', '', 'ua', 0, NULL),
(55, 'Ми вибрані Богом на діло святеє', 0, 11, 'Куплет 1\nМи вибрані Богом на діло святеє, - \nСкрізь працю Христову по світі звершать;\nЛюбити безмежно, що тільки живеє,\nНа благо для ближніх себе віддавать.\n\nПриспів: \nМи слуги Христові (ми слуги Христові),\nГосподар Він наш (Господар Він наш),\nДля нас Свою працю Бог дав (працю Бог дав), \nВиконуймо щиро (виконуймо щиро)\nГосподній наказ (Господній наказ),\nНам царство дать Бог обіцяв.\n\nКуплет 2\nМи вибрані Богом - скрізь спокій творити,\nНещасних в недолі, в біді потішать;\nПро Бога та правду всім людям вістити,\nЗ гріха та неволі усіх визволять.\n\nКуплет 3\nМи вибрані Богом, щоб Слово Христове,\nМов добре зерно розсівати кругом;\nНа всякеє добреє діло готові,\nНе скаржитись тяжким життєвим хрестом..', '', '', '', '', 'ua', 0, NULL),
(56, 'О ласкавий ласкавий Спаситель', 0, 11, 'Куплет 1\nО, ласкавий, ласкавий Спаситель!\nНа хресті Він за мене вмирав;\nВін єдиний є наш Примиритель, - \nВін всім вірним життя вічне дав.\n\nПриспів: \nВін за мене на хресті постраждав (2р.), \nНа хресті постраждав, за мене вмирав, \nВін за мене на хресті постраждав.\n\nКуплет 2\nГрішні Праведника осудили,\nНа Голгофі Його розп’яли,\nЙого одіж собі поділили,\nТак немудрі Творця прийняли.\n\nКуплет 3\nДав життя Своє в жертву Син Божий,\nЩоб від смерті людей врятувать;\nПереміг темні сили ворожі,\nВірним Він дав Свою благодать.', '', '', '', '', 'ua', 0, NULL),
(57, 'Слава слава Богу в небі', 0, 11, 'Куплет 1\nСлава, слава Богу в небі, - \nНа землі мир - благодать!\nЗакликайте, браття, ближніх:\nБудем Бога прославлять.\n\nПриспів: \nАлілуя! Алілуя! | Слава Богу в небі. (2р.) \nТой, Хто світом володіє,\nМає в небі Свій престол,\nЗалишив небесну славу,\nЯк людина в світ прийшов.\n\nКуплет 2\nО, друззя! Всім вам прощення \nБог сьогодні хоче дать:\nБожий Син звершив спасіння,\nПоспішіть Його прийнять.\n\nКуплет 3\nВ Вифлеємі Спас родився,\nВ бідних яслах Він лежав;\nЗадля нас Христос смирився, -\n То для нас Він приклад дав.\n\nКуплет 3\nО, друззя, прийдіть, не гайтесь,\nДо Ісуса поспішіть.\nУ гріхах своїх покайтесь, - \nВ серце всі Христа прийміть!', '', '', '', '', 'ua', 0, NULL),
(58, 'Коли горе на серце наляже', 0, 11, 'Куплет 1\nКоли горе на серце наляже, І скажи Ісусу! (2р.)\nКоли душу смуток дуже зв’яже, -\nСкажи Ісусу про все.\n\nПриспів: \nСкажи Ісусу, скажи Ісусу, - Він друг, Який знає все;\nНема брата ліпшого в цім світі,\nЯк наш Спаситель Христос.\n\nКуплет 2\nКоли сльози твій спокій зворушать, - скажи Ісусу! (2р.) \nКоли тайні гріхи душу мучать...\nСкажи Ісусу про все.\n\nКуплет 3\nКоли бачиш, що біда надходить,- | скажи Ісусу! (2р.) \nКоли голод або смерть приходить, - \nСкажи Ісусу про все.\n\nКуплет 4\nКоли в світі загинуть не хочеш,- | скажи Ісусу! (2р.) \nКоли в Царстві Божім бути хочеш, - \nСкажи Ісусу про все.', '', '', '', '', 'ua', 0, NULL),
(59, 'Нехай хвалять Тебе земля і всі світи', 0, 11, 'Куплет 1\nНехай хвалять Тебе земля і всі світи,\nНехай творіння все повік хвалить Тебе.\nБо Ти великий Бог, Творець землі й небес,\nЗ глибин всього мого чуття хвалю Тебе!\n\nКуплет 2\nПрославлю я Того, Чия любов сильна;\nМене від злого захища Його рука.\nВ нечистоті гріхів, мов у неволі жив.\nТа кровію Христос мене з гріхів обмив.\n\nКуплет 3\nЯ бачу Край новий спокою і добра,\nДе кожен справді вільним є вже від гріха.\nНа тих височинах царює вічно Спас, - \nУ сяєві Отця Свого у небесах.\n\nКуплет 4\nХор ангельський Йому невпинно все співа: \n«Святий, святий, святий єси! Тобі хвала!»\nІз ангелами я Спасителя хвалю;\nТи, Боже, незначну хвалу прийми мою. Амінь.', '', '', '', '', 'ua', 0, NULL),
(60, 'Як чудесно змінилося моє життя', 0, 11, 'Куплет 1\nЯк чудесно змінилося моє життя,\nВідколи я Христа пізнав.\nІ я маю спокій, що його я шукав...\nВідколи я Христа пізнав.\n\nПриспів: \nВідколи я Христа пізнав (2р.),\nРіки радості в душу мою все пливуть, \nВідколи я Христа пізнав.\n\nКуплет 2\nЯ лишив мандрівки і блукання мої,\nВідколи я Христа пізнав, - \nІ гріхи мої змиті з моєї душі,\nВідколи я Христа пізнав.\n\nКуплет 3\nЯ надію одержав тверду і певну,\nВідколи я Христа пізнав, - \nІ я більше не маю вагань ні страху,\nВідколи я Христа пізнав.\n\nКуплет 4\nЙду долиною смерті, Спас - світло моє,\nВідколи я Христа пізнав...\nЯ є певний, що Він є зі мною усе,\nВідколи я Христа пізнав.\n\nКуплет 5\nЯ в небесний дім йду, там Господь жде мене, \nВідколи я Христа пізнав, - \nДе побачу Ісуса лицем у лице,\nБо я серцем Його пізнав.', '', '', '', '', 'ua', 0, NULL),
(61, 'Вірю я в обітниці ХристаЦаря', 0, 11, 'Куплет 1\nВірю я в обітниці Христа-Царя,\nБезупинно хай звучить Йому хвала.\nСлава Богу в небі, вже зійшла Зоря!\nВірю я в обітниці Христа!\n\nПриспів: \nВірю (Зр.), я в обітниці Христа, я вірю, \nВірю, вірю, вірю я в обітниці Христа.\n\nКуплет 3\nВірю я в обітниці, живу з Христом, - \nПокоряюсь всім своїм Йому єством;\nПо правиці хочу бути я з Христом:\nВірю я в обітниці Христа!\n\nКуплет 4\nВірю я в обітниці, в них я кріплюсь;\nБлагодаттю Божою я веселюсь...\nЩо ж буде за радість, як зустрінусь з Ним?!\nВірю я в обітниці Христа!', '', '', '', '', 'ua', 0, NULL),
(62, 'Ісус Спаситель вмер на Хресті', 0, 11, 'Куплет 1\nІсус Спаситель вмер на Хресті, - \nВмер Він за грішних, щоб їх спасти;\nДушу скропіть ви Кров’ю Христа,\nІ Він пройде, пройде мимо вас!\n\nПриспів: \nЯк Я вбачу кров, (Зр.)\nЯ пройду, Я пройду мимо вас!\n\nКуплет 2\nВ силі Спаситель грішних усіх \nСпасти з найбільших тяжких гріхів;\nВін обіцяв Сам зняти гріх ваш,\nІ Він пройде, пройде мимо вас!\n\nКуплет 3\nСуд Божий прийде скоро всім нам,\nКожний заплату матиме там.\nСкрийся в крові, пролитій за нас,\nІ Він пройде, пройде мимо вас!\n\nКуплет 4\nІсус - Приятель, повний любві, - \nСила чудесна в Його Крові;\nВін спасти може ще нині вас,\nБо Він страждав і умер за нас!', '', '', '', '', 'ua', 0, NULL),
(63, 'Я лицем в лице з Ісусом стрінусь скоро в небесах', 0, 11, 'Куплет 1\nЯ лицем в лице з Ісусом стрінусь скоро в небесах, \nКоли Він прийде у славі всіх судити по ділах.\n\nПриспів:\nЯ лицем в лице з Ісусом стрінусь скоро в небесах,\nЯк Він явиться у славі всіх судити по ділах.\n\nКуплет 2\nІ тепер я через віру можу бачити Христа, - \nА тоді Його побачу, як Він є - у небесах.\n\nКуплет 3\nВічно утішатись буду - в славі Господа мого,\nБо все горе й зло забуду і не знатиму його.\n\nКуплет 4\nЯ лицем в лице Ісуса стріну скоро Його там,\nДе предвічне «Алілуя» буде в вірних на устах.', '', '', '', '', 'ua', 0, NULL),
(64, 'Нащо журитися мені', 0, 11, 'Куплет 1\nНащо журитися мені,\nКоли скарби земні \nНалежать до Царя царів,\nА Він - Приятель мій?\n\nПриспів:\nО, так, Приятель мій! \nЗі мною ділиться Він всім. \nВсе є Його, а Він є мій. \nНащо журба мені?\nБо Ісус є Приятель мій!\n\nКуплет 2\nВін сонце, місяць й зорі всі \nДержить в Своїй руці,\nДо Нього скрізь належить все, - \nВін є Приятель мій.\n\nКуплет 3\nДля мене Він є хліб життя, - \nІ при Його столі \nДається їжа людям всім.\nВін є Приятель мій!\n\nКуплет 4\nЯк Він прийде й вбере своїх \nУ ясний білий стрій,- \nЦе все тоді скаже мені,\nЩо Він - Приятель мій!', '', '', '', '', 'ua', 0, NULL),
(65, 'О скрізь розголосіть вість людям всім скажіть', 0, 11, 'Куплет 1\nО, скрізь розголосіть, вість людям всім скажіть,\nДе тільки є душа не знаюча Христа.\nХай кожний, хто спасен, цю новину несе,\nЩо Дух Святий прийшов.\n\nПриспів: \nО, Дух Святий прийшов! (2р.)\nУтішитель з небес, що обіцяв Отець.\nО, скрізь розголосіть,\nВість людям всім скажіть,\nЩо Дух Святий прийшов!\n\nКуплет 2\nНіч темна вже мина, рання Зоря зійшла,\nТьму розганяє вже, - день вічний настає.\nЛюдство гріхи лиша, - приходить до Христа;\nБо Дух Святий прийшов.\n\nКуплет 3\nОсь, Цар царів прийде, Христос з небес зійде, \nЩоби забрати нас - всіх тих, котрих Він спас. \nНехай труба звучить, щоб голос чути скрізь, \nЩо Дух Святий прийшов.', '', '', '', '', 'ua', 0, NULL),
(66, 'О слава Богу що Ісус прийшов', 0, 11, 'Куплет 1\nО, слава Богу, що Ісус прийшов,\nІ Він на Себе всі гріхи забрав;\nСлава Спасителю за Його кров,\nСлава! Алілуя! Ісус спас мене!\n\nПриспів: \nІсус спас мене, Ісус спас мене!\nВ моїм серці свідок - Він спас мене!\nВін гріхи простив, Духом охрестив: \nСлава! Алілуя! Ісус спас мене!\n\nКуплет 2\nО, як я довгий час гріху служив,\nВін кров’ю Своєю мене купив; ,\nТепер я буду все Христу служить:\nСлава! Алілуя! Ісус спас мене!\n\nКуплет 3\nЛюбов Його задовольняє всіх,\nІ теж зціляє всіх слабих й калік; \nЩе нині Він до себе кличе всіх: \nСлава! Алілуя! Ісус спас мене', '', '', '', '', 'ua', 0, NULL),
(67, 'Все віддам я для Ісуса', 0, 11, 'Куплет 1\nВсе віддам я для Ісуса, і все серце Йому дам;\nХочу я Йому служити, як Він Сам служив і нам.\n\nПриспів: \nВсе Тобі даю, все Тобі даю,\nВсе для Тебе, мій Ісусе, нині віддаю!\n\nКуплет 2\nВсе це я зроблю з Ісусом, бо Він силу дасть мені;\nЗ ним я вічно жити буду там - в небесній стороні.\n\nКуплет 3\nЗа для Спаса я здолію в світі хрест тяжкий нести,\nБо на Нього я надіюсь, що Він може помогти.\n\nКуплет 4\nСлава й честь Тобі, Ісусе, за любов Твою святу,\nЩо відкрив для мене ясне світло правди в цім житті.', '', '', '', '', 'ua', 2, NULL),
(68, 'Як ваше серце світ в рану оберне', 0, 11, 'Куплет 1\n, - \nСпасові те в молитвах розкажіть:\nВін біль утишить вам, вихід покаже, - \nРан тих немає, щоб Спас не зцілив.\n\nКуплет 2\nСпас - втіха в смутку, світло незрячим,\nНемічним міцність, Спас - сила в борні;\nГолос потіхи все скривдженим: мовить:\n«Спас ваші рани загоїть усі!»\n\nКуплет 3\nГляньте на Хліб Життя, на Живу Воду, - \nДари, що ними спасенний живе;\nЙдіть на обід любві у повній вірі, - \nСпас вам турботи усі розжене!', '', '', '', '', 'ua', 0, NULL),
(69, 'Я ходжу в світлі куди лиш піду', 0, 11, 'Куплет 1\nЯ ходжу в світлі, куди лиш піду, - \nЧи то по горах, чи долами,\nІсус сказав: «Я тебе не лишу!»\nІ я іду все прямо за Ним.\n\nПриспів: \nСвітло небесне, світло небесне, \nВсю освітило душу мою! Алілуя! \nРадуюсь я все – \nПісні співаю: Слава Христу!\n\nКуплет 2\nТьма скрізь - довкола і наді мною,\nТа тьма не зможе скрити Христа,\nБо Він є світло, в Нім тьми немає,\nІ близько Нього завжди йду я.\n\nКуплет 3\nВ цім яснім світлі радуюсь все я, \nСпіваю Богу пісні хвали;\nІ я прямую просто в Дім Вічний, -\nЯ ходжу в світлі, в світлі любві.', '', '', '', '', 'ua', 0, NULL),
(70, 'О друже вчуй Нині приємний ще час', 0, 11, 'Куплет 1\nО, друже, вчуй! Нині приємний ще час:\nТвої всі провини простить хоче Спас.\nНе будь же байдужим, - Бог кличе усіх,\nБо може Дух Божий замовкнуть зовсім.\n\nКуплет 2\nХристос закликає усіх до Отця,\nІ Духа зливає в покірні серця.\nВчуй голос Ісуса, до Нього іди, \nУчителя Духа ти не засмути!\n\nКуплет 3\nБез Бога блукав ти і втратив спокій,\nІ попіл присипав вже жертівник твій.\nХрам Бога Живого, о друже, пильнуй \nІ Духа Святого ти ревно шануй!', '', '', '', '', 'ua', 0, NULL),
(71, 'Гірко плакав Христос на скорботній землі', 0, 11, 'Куплет 1\nГірко плакав Христос на скорботній землі,\nСльози горя текли із очей...\nВін дививсь на цей світ і в нім бачив у злі \nПогибаючих марно людей.\n\nПриспів:\n О, Я плачу за вас, \nЯ ллю Свої сльози і кров;\nЯ приніс вам на землю\nНебесну любов, - Та за неї розпнете Мене!\n\nКуплет 2\nЧерез що, наш Спасителю, Ти у сльозах?\nМоже храми твої не блищать?\nЧи ж не Твій віковічний престол в небесах?\nЧи страждання Тебе тяготять?\n\nКуплет 3\nЯ дивлюся вперед на людей, як братів:\nВсі страждають в гріхах на землі \nНе цінують крові, що за них Я пролив,\nТа забули страждання Мої.\n\nКуплет 4\nЯ молюся за вас! Мною куплені ви,\nО, прийміть же ви жертву Мою!\nЯ даю вам спасіння в пролитій крові,\nЯ віддав за вас душу Свою.', '', '', '', '', 'ua', 0, NULL),
(72, 'Пригадаймо муки Христову любов', 0, 11, 'Куплет 1\nПригадаймо муки, Христову любов,\nЯк страждав Син Божий, пролив за нас кров...\nОсь у Гефсиманськім темному саду \nЧути шум і гомін: вороги ідуть.\n\nКуплет 2\nЙдуть вони з вогнями, дико гомонять,\nЗ кіллями, мечами, Спаса хочуть взять.\nЯк вже близько стала ворогів юрба,\nТихо і ласкаво їх Христос спитав:\n\nКуплет 3\n«Кого вам тут треба уночі, друззя?\nЯк тільки Ісуса, то це - самий Я!»\nВороги змовчали від тих слів краси,\nЗлякавшись, упали на землю усі.\n\nКуплет 4\nАле зрадник Юда перед Спасом став,\nІ лице Господнє він поцілував.\n«Радуйся, Учитель!» - Юда так сказав,  \nА його Спаситель лагідно спитав:\n\nКуплет 5\n«Чого з ворогами, друже, ти прийшов?\nНащо залишаєш ти Мою любов?...\nВ той час нарід лютий на Христа напав,\nІ святії руки Господу зв’язав...', '', '', '', '', 'ua', 0, NULL),
(73, 'О як печально й гірко нам як згадуємо ми про день', 0, 11, 'Куплет 1\nО, як печально й гірко нам, як згадуємо ми про день, \nКоли Син Божий Сам | муки за нас прийняв. (Зр.)\n\nКуплет 2\nЯк Агнця тихого взяли, Правди Учителя,\nІ на Голгофі розп’яли | Христа-Спасителя. (Зр.)\n\nКуплет 3\nПішов Спаситель наш Христос прийняти смерть за нас,- \nI муки хресні Він терпів, І і нас від смерті спас,.(Зр.)\n\nКуплет 4\nЗа грішників Безгрішний був розп ’ятий на хресті; \nРозбійника благання вчув, | гріхи йому простив .(Зр.)\n\nКуплет 5\nПроколото Його ребро - стекла вода і кров:\nЗа нас Він тяжко так страждав, | відкрив Свою Любов. (Зр.)\n\nКуплет 6\nДо грішників причислили Спасителя Христа...\nУ гробі був - і в третій день І Христос із мертвих встав. (Зр.)', '', '', '', '', 'ua', 0, NULL),
(74, 'Ночі пізня вже година всюди тиша і все спить', 0, 11, 'Куплет 1\nНочі пізня вже година, всюди тиша і все спить,\nА Ісус в саду самотній тихо став Отця молить:\n«Отче Мій Святий, - чи може проминути чаша ця?\nТільки хай буде, о Боже, воля лиш у всім Твоя!»\n\nКуплет 2 \nМолить Він Отця, благає так у другий, в третій раз, - \nПіт кривавий виступає на обличчі в скорбний час.\nВ саду молиться Спаситель. Учнів всіх сон подолав.\nВсі дрімають, їх Учитель докоряє, як друзів:\n\nКуплет 3\n«Годі, годі вам дрімати!» - Своїм учням Він сказав: \n«Ось Мене ідуть узяти, час страждання Мій настав.\nІ проллю Я кров невинну за цей грішний світ, за вас»..- \nІ з вогнями в ту хвилину вороги явились враз.\n\nКуплет 4\nЗ ними разом - Юда-зрадник; він Христа поцілував, - \nКого мали вони взяти, цілуванням показав.\nПізня ніч... з саду сторожа із вогнями геть іде, - \nА із нею Він, Син Божий, сповнить волю Отця йде.', '', '', '', '', 'ua', 0, NULL),
(75, 'Уже північ навкруги все спить', 0, 11, 'Куплет 1\nУже північ... навкруги все спить...\nЧорні хмари по небу пливуть;\nТемний сад Гефсиманський мовчить, - \nНіби молиться Хтось - в тиші чуть.\n\nКуплет 2\nУже північ... Ісус в боротьбі \nЧисті руки в молитві підняв,\nЙого серце в смертельній журбі,\nІ лицем до землі Він припав.\n\nКуплет 3\nУже північ... Христос - без вини – \nПочав Господа тихо благать;\nЧує - час наблизився сумний;\nЙого мучити візьмуть, розпнуть.\n\nКуплет 4\nУже північ... сад прокинувся, - \nТо Ісуса взяти вже прийшли...\nПоцілунок Юди, то зрада.\nБула північ, Ісуса взяли...', '', '', '', '', 'ua', 0, NULL),
(76, 'Поглянь поглянь Ось повели', 0, 11, 'Куплет 1\n Поглянь, поглянь! Ось повели \nХриста на гору й розп’яли.\nI у тяжких Він муках там \nПридбав усім спасіння нам.\n\nПриспів: \nГолгофський хрест (2р.), - \nІсус за мене там страждав. \nГолгофський хрест (2р.), - \nІсус за мене там вмирав.\n\nКуплет 2\nЗемля стряслась... всіх сум обняв...\n «Звершилося!» - Христос сказав.\nТо Він умер за грішний світ \nІ в рай відкрив спасіння вхід.\n\nКуплет 3\nСпасителю! Ти многих спас \nВ той скорбний час, голгофський час. \nЙ за мене Ти там постраждав, - \nМені життя Ти смертю дав.', '', '', '', '', 'ua', 0, NULL),
(77, 'Чи читали ви повість про той хрест', 0, 11, 'Куплет 1\nЧи читали ви повість про той хрест,\nДе вмер Ісус за нас,\nДе Він заплатив наш борг кров’ю,\nЩо текла із Його ран?\n\nПриспів:\n Христос прийняв смерть тоді за нас \nХристос прийняв смерть за нас!\nОй, як же Він нас полюбив,\nЩо вмер на хресті за нас!\n\nКуплет 2\nЧи читали ви про вінок з терну \nНа голові Його?\nЯк молився Він: «Отче, їм прости,\nБо не знають, що чинять!»\n\nКуплет 3\nЧи читали, як лиходія спас,\nЩо висів разом з Ним,\nКотрий смутно глянув і сказав Йому:\n«У Царстві спом’яни мене!»\n\nКуплет 4\nЧи читали ви, як зітхнувши,\n Він «Звершилося!» - сказав?\nЧи сказали ви: «Тобі дякую,\nЩо життя за мене дав!»', '', '', '', '', 'ua', 0, NULL),
(78, 'Прийдіть та погляньте на страшні знущання', 0, 11, 'Куплет 1\nПрийдіть та погляньте на страшні знущання...\nНаш гріх приготовив Ісусу страждання;\nОсь руки і ноги пречисті пробили,\nЗ тернини вінка на чоло положили.\n\nПриспів:\nСлава! Алілуя! Алілуя Господу!\n\nКуплет 2\nВже люди дізнались про муки Христові.\nЧому ж їх не цінять? Не мають любові?\nВідкиньте ж марні всі свої мудрування!\nПрийміть усім серцем Христові страждання!\n\nКуплет 3\nХто прагне душею, шукає спасіння.\nТой в крові Ісуса знайде очищення.\nЗа гріх, хто по правді себе докоряє,\nТому двері Царства Сам Бог відкриває.\n\nКуплет 4\nЗа наші гріхи ми всі мали страждати, - \nХристос постраждав, щоб усіх врятувати. \nВіддаймо Спасителю честь, поклоніння,\nНа землю приніс Він для нас всіх спасіння.', '', '', '', '', 'ua', 0, NULL),
(79, 'Зійдім на Голгофу друззя', 0, 11, 'Куплет 1\nЗійдім на Голгофу, друззя!\nСпаситель у жертву віддав там життя.\nМесія лиш правди людей научав,\nНедужих зціляв, - за що так постраждав?\nСхилімсь перед Ним!\n\nКуплет 2\nЗійдім на Голгофу, друззя!\nІсус там мучення терпить до кінця.\nВін прагне, а оцет Тому подають,\nІз уст Чиїх води живії течуть.\nСхилімсь перед Ним!\n\nКуплет 3\nЗійдім на Голгофу, друззя!\nСпаситель в любові благає Творця:\n«Прости їм, - не знають, що чинять Мені!» \nХристова молитва знялась від землі...\nСхилімсь перед Ним!\n\nКуплет 4\nЗійдім на Голгофу, друззя!\nПочуєм Ісуса слова до Отця:\n«О, Боже Мій! Нащо Мене залишив?»\nО любі друззя, то за нас \nВін терпів! Схилімсь перед Ним!\n\nКуплет 5\nЗійдім на Голгофу, друззя!\nНевже ж не зворушаться наші серця?.., \n«Звершилось! Я Дух Мій Тобі віддаю!»\nЗа нас Він пожертвував душу Свою.\nСхилімсь перед Ним!\n\nКуплет 6\nЗійдім на Голгофу, друззя!\nТам грішного світу отрута уся \nСтраждання безмірні Христу завдала. \nЛиш Божа любов нас від смерті спасла. \nСхилімсь перед Ним!', '', '', '', '', 'ua', 0, NULL),
(80, 'Чи тобі все одно що Спаситель страждав', 0, 11, 'Куплет 1\nЧи тобі все одно, що Спаситель страждав?\nВсе одно, все одно, чи тобі все одно?\nТи байдуже стоїш,- Він же кров проливав,\nА тобі все одно, а тобі все одно.\n\nКуплет 2\nЗа тебе на Голгофі Христос умирав,\nА тобі все одно, а тобі все одно.\nВсі провини людей на Себе Він узяв,\nА тобі все одно, а тобі все одно?\n\nКуплет 3\nЗа кого ж Він вмирав? Чи ти думав про те?\nЩоб гріхи Він простив, чи благав ти Його? \nВідкупитель Христос кличе в Царство тебе, - \nО, невжеж в своє серце не приймеш Його?\n\nКуплет 4\nНаближається вічність... подумай про те!\nНа суді, знай, ніхто не заступить тебе. \nСтануть всі перед білим престолом Христа, - \nДе ж тоді ти сховаєш нечисті діла?', '', '', '', '', 'ua', 0, NULL),
(81, 'Хто з гріхів мене спасе', 0, 11, 'Куплет 1\nХто з гріхів мене спасе?\nО, ніхто, лиш кров Ісуса!\nЩо знов оживить мене?\nО, ніщо, лиш кров Ісуса!\n\nПриспів: \nО, кров Ісусова спасає від гріха!\nНіщо нас не спасе, тільки кров свята Ісуса\n\nКуплет 2\nЗ Богом хто з’єдна мене?\nО, ніхто, лиш кров Ісуса!\nСерцю що спокій дає?\nО, ніщо, лиш кров Ісуса!\n\nКуплет 3\nХто знов підкріпить мене?\nО, ніхто, лиш кров Ісуса!\nЩо знов душу підійме?\nО, ніщо, лиш кров Ісуса!', '', '', '', '', 'ua', 0, NULL),
(82, 'Друззя Двері райські відкрив Сам Христос', 0, 11, 'Куплет 1\nДруззя! Двері райські відкрив Сам Христос,\nВсіх кличе Він в Царство Своє.\nСпішіте ввійти, ще сьогодні є час!\nХто знає, що завтра нас жде?\n\nПриспів: \nСпіши, друже любий, прийнять \nВелику святу благодать:\nЖиття вічне - Божий дар прийми!\nПрийди до Ісуса, прийди!\n\nКуплет 3\nСпаситель наш скоро, вже скоро прийде,\nДе місце знайдеш ти собі?\nСпасенних Він в Царство Своє всіх візьме, \nЗачиняться двері тоді.\n\nКуплет 4\nПокайся негайно, - гріхи Він простить, \nОбмиє пороки твої,\nІ душу, і тіло твоє оживить.\nНе гайсь, до Ісуса іди!', '', '', '', '', 'ua', 0, NULL),
(83, 'Путь до спасіння вічний живий', 0, 11, 'Куплет 1\nПуть до спасіння вічний, живий,\nВ слові Своїм Господь нам відкрив;\nВін всі провини наші простив,\nВін кличе всіх: «Прийдіть!»\n\nПриспів: \nРадість, радість буде в небесах, \nРайські співи будуть на устах,\nТам вічне світло в святих серцях - \nВічна любов Христа!\n\nКуплет 2\n«Будьте, як діти!» - Він так сказав,\nВ любові жити заповідав,\nДо покаяння всіх закликав,\nКличе й тепер: «Прийдіть!»\n\nКуплет 3\nДруже! Спаситель кличе й тебе \nВ вічне небесне Царство Своє,\nЙому довірся, - Він тебе жде!\nОсь, кличе Він: «Прийди!»', '', '', '', '', 'ua', 0, NULL),
(84, 'У сльозах покірно біля ніг Христа', 0, 11, 'Куплет 1\nУ сльозах покірно біля ніг Христа \nСлухала Марія Божії слова,\nСерцем прагнула прийнять \nВід Ісуса благодать...\nЖити з Ним бажаю, служити Йому,\nВ хорі зі святими принести хвалу.\n\nКуплет 2\nМиро найдорожче Марія лила \nЩиро для Ісуса - в жертву віддала. \nЩирий дар Христос прийняв,\nГріх тяжкий Він з неї зняв...\nБіля ніг Христових, як Його слуга, \nХочу утішатись радістю і я.\n\nКуплет 3\nПершою Марія поспішила йти,\nЩоб Ісуса тіло в гробі там знайти,\nІ ось чудо із чудес:\nЗ мертвих вже Христос Воскрес! \nЇй Христос живий тоді явився Сам \nІ сказав: «Іди, скажи Моїм учням».', '', '', '', '', 'ua', 0, NULL),
(85, 'В долині паслася отара овець', 0, 11, 'Куплет 1\nВ долині паслася отара овець, \nЇх сто всіх було, як одна.\nІ добрий їх Пастир стеріг, як Отець;\nАж ось заблудилась одна;\nВід Пастиря свого далеко зайшла,\nДо Нього вернутись сама не змогла.\n\nКуплет 2\nДев’яносто дев’ять пасуться в гурті, - \nБлукає одна в самоті.\nІ Пастир промовив: «А де ж та одна? \nЛюблю всіх, і люба вона;\nПіду Сам за нею по горах крутих, - \nБажаю її Я привести до них».\n\nКуплет 3\nІ Пастир ласкавий за нею пішов,\nВсі гори й поля обійшов,\nІ бачить: над ровом овечка стоїть,\nІ Пастир до неї спішить.\nКаміння і терен Його не здержав;\nВівцю погибаючу Він врятував.\n\nКуплет 4\nНа плечі спасенну овечку Він взяв,\nЗ любов’ю її пригортав;\nНа пашу зелену її Він пустив, - \nЖиттям її Пастир зрадів.\nРадіють всі ангели... співи звучать... \nЇм любо за неї Творця прославлять.', '', '', '', '', 'ua', 0, NULL),
(86, 'Свій маяк Господь Всесильний вічним світлом засвітив', 0, 11, 'Куплет 1\nСвій маяк Господь Всесильний вічним світлом засвітив. \nНам же Він вогонь небесний зберігати доручив.\n\nПриспів: \nХай же світло наше сяє,\nПромінь ласки ближнім ллє,\nВ тиху пристань направляє,\nДо спокою всіх веде!\n\nКуплет 2\nМов ті хвилі, гріх бушує, хоче душу затопить; \nПодорожній там бідує, йому треба посвітить.\n\nКуплет 3\nО поправ, мій брате, нині свій сердечний каганець!\nГлянь, на хвилях вітри буйні б’ють човен з кінця в кінець.', '', '', '', '', 'ua', 0, NULL),
(87, 'Найкраще одне Ім’я нам то Ім’я є Ісус', 0, 11, 'Куплет 1\nНайкраще одне Ім’я нам, то Ім’я є - Ісус!\nЛиш в Нім спасіння всім серцям, Ним тільки я кріплюсь,\n\nКуплет 2\nІсус сердечний гоїть біль і душу веселить.\nДає своїм Він вірним сил тернистий путь звершить.\n\nКуплет 3\nІсус - маяк мій, до Нього по хвилях я пливу,\nВ Нім відпочинок від всього навіки я знайду.\n\nКуплет 4\nІсус - мій Спас, а не суддя, Він добрий Пастир мій;\nВ Нім щастя вічного життя і радість, і спокій.', '', '', '', '', 'ua', 0, NULL),
(88, 'Хто ці спасенні й відкіля прийшли', 0, 11, 'Куплет 1\nХто ці спасенні, й відкіля прийшли?\nБілі одежі де собі взяли?...\nЛлються співи їх хвали: Агнець їх кров’ю обмив.\n\nПриспів: \nАгнець нас привів у Новий Єрусалим \nЙ кров’ю Своєю обмив, обмив...\nМи жить вічно будем \nВ небесній славі з Ним, —\nАгнець нас кров’ю обмив.\n\nКуплет 2\nХристос Спаситель в Царство їх зібрав,\nЗа них страждав Він, на хресті вмирав,\nБог їх спас і оправдав, Агнець їх кров’ю обмив.\n\nКуплет 2\nВсі, всі слідом за Агнцем вони йшли,\nЧерез великі смутки перейшли,\nУ Христа спокій знайшли, Агнець їх кров’ю обмив.\n\nКуплет 3\nШляхом тернистим їм прийшлось іти,\nХристос поміг його їм перейти,\nВін стеріг їх на путі, Агнець їх кров’ю обмив.\n\nКуплет 4\nЗа Євангельську віру всі вони\n Були постійно з ворогом в борні,\nВірно жили у всі дні, Агнець їх кров''ю обмив.\n\nКуплет 5\nБог їх простив, навіки полюбив,\nВ Небесний Край для радості привів,\nТам новий лунає спів: Агнець нас кров’ю обмив!', '', '', '', '', 'ua', 0, NULL),
(89, 'Браття сестри молоді не гайтесь', 0, 11, 'Куплет 1\nБраття, сестри молоді, не гайтесь,\nПоспішіть на Божу ниву жать,\nЯк один, на труд святий віддайтесь:\nСлухайте, вас кличе Сам Господь.\n\nПриспів:\nО, підем же дружно всі на поле,\nЩоб хто снопик, два, хто більш нажать \nІ принести до святого трону,\nЩоб Спасителю Христу віддать.\n\nКуплет 2\nБраття, сестри, дружно всі готуйтесь,\nХай не буде перешкоди вам,\nІ в святій любові всі згуртуйтесь,\nІ Спаситель поведе вас Сам!\n\nКуплет 3\nПодивіться - нива побіліла.\nГоді вам на торжищі стоять!\nТам потрібні ви і ваша сила,\nДе вас хоче Сам Господь найнять.\n\nКуплет 4\nМоже вже останній поклик чуєш:\nЗавтра вже Господь не прийме нас,\nО, тоді навіки засумуєш, - \nЯк почуєш: «Я не знаю вас!»', '', '', '', '', 'ua', 0, NULL),
(90, 'О де ж ті женці щоб зібрать снопи', 0, 11, 'Куплет 1\nО, де ж ті женці, щоб зібрать снопи \nЗ ланів світа й Господу принести?\nЗ серпами любові до праці йдіть,\nНевпинно працюйте, лани зіжніть!\n\nПриспів: \nО, де ж ті женці? Хто з нами враз\nПоділить ту працю, що вже жде на нас? \nХто нам поміч дасть зібрати з піль \nДобра снопи, вибрати кукіль?\n\nКуплет 2\nШукайте колосся, що десь в траві;\nКукіль із пшениці ви виберіть; \nЗберіть ті колосся, що при путі,\nНічого не киньте, усе зберіть!\n\nКуплет 3\nЛани вже дозріли, й зерно в них є,\nІ жнив тих великих вже світ наш жде. \nРобітників мало, а праці скрізь...\nНе гаймось, до праці усі берімсь!\n\nКуплет 4\nБеріть же ви, браття, свої серпи, - \nНесіть ті багаті зерном снопи...\nГотуйтесь зустріти Христа-Царя:\nВін дасть нагороду нам за жнива.', '', '', '', '', 'ua', 0, NULL),
(91, 'Хрест тяжкий терпіння', 0, 11, 'Куплет 1\nХрест тяжкий терпіння (2р.) на Голгофу Він \nНіс покірно й сміло (2р.) - вічний Божий Син.\n\nКуплет 2\nІ Його є воля (2р.), щоб в житті земнім \nЯ ішов покірно (2р.) із хрестом своїм.\n\nКуплет 3\nЙшов смиренно й тихо (2р.) на Голгофу Він.\nПадав у знемозі (2р.) під хрестом тяжким.\n\nКуплет 4\nІ мій хрест суворий (2р.) Сам Він облегшив:\nІз кайдан гріховних (2р.) мене увільнив.\n\nКуплет 5\nЯрмо Його любе (2р.) у моїм житті.\nРадість і відвагу (2р.) маю у Христі.\n\nКуплет 6\nТягар Його знаю (2р.) - він легкий мені,\nНа Нього взираю: (2р.) моя сила в Нім.', '', '', '', '', 'ua', 0, NULL),
(92, 'Коли б до скали що є вища ніж я', 0, 11, 'Куплет 1\nКоли б до скали, що є вища, ніж я,\nЯ духом із битви піднятися міг!\nСлаба в мене віра і немічний я...\nСкала та - Христос, щит і захист Він мій.\n\nПриспів: \nСкриюсь в Тобі, скриюсь в Тобі,\nСкала - мій Ісус, я укриюсь в Тобі!\n\nКуплет 2\nВ південній тиші, і в годинах тяжких,\nІ в пору спокус, як душа в боротьбі,\nІ в грізну теж бурю на хвилях морських,- \nСкала - мій Ісус, я укриюсь в Тобі.\n\nКуплет 3\nЯк змучений часто в нерівній борні,\nБіжу до скали - щоб знайти захист в ній... \nВона, віковічна, ясніє в тиші:\nСкала та - Христос: в Нім спокій для душі.', '', '', '', '', 'ua', 0, NULL),
(93, 'Коли погляну в вірі я', 0, 11, 'Куплет 1\n Коли погляну в вірі я\nНа хрест, де Божий Син страждав,\n(Тремтить тоді душа моя,\nСоромлюсь, що Його не знав.)(2р)\n\nКуплет 2\nО, Спасе, хорони мене,\nЩоб в світі слави не шукав,\n(Щоб Твої муки, смерть Твоя \nБули вінцем моїх похвал.)(2р)\n\nКуплет 3\nВ любві гарячій, Спасе мій,\nЗа нас пролив свою Ти кров.\n(Терпів зневагу від людей:\nВелика є Твоя любов.)(2р)\n\nКуплет 4\nКоли б я все Тобі віддав, \nЖертва моя була б мала.\n(Що ж за любов Твою я дам? \nО, Спасе мій, я весь Твій сам!)(2р)', '', '', '', '', 'ua', 0, NULL),
(94, 'Плачте очі лийтесь сльози умирає на хресті', 0, 11, 'Куплет 1\nПлачте очі, лийтесь, сльози, - умирає на хресті \nСам Ісус Христос, Син Божий; ллється кров із ран святих!\nЩо зробив кому Ти злого? Чому мусиш так страждать? \nЗа розбійника якого забажав відповідать?\n\nПриспів: \nПлачте очі, лийтесь, сльози,\nУмирає на хресті\nСам Ісус Христос, Син Божий;\nЛлється кров із ран святих.\n\nКуплет 2\nУ вінку терновім чоло, чистий погляд - в небеса.\nЖурно робиться навколо, ніч удень, - холодний жах.\nЦе за мене всі страждання, за гріхи мого життя...\nО, Ісусе! Вчуй благання: хочу мать прощення я.\n\nКуплет 3\nЯ іду, хоч і безсилий, силу Духа дай мені!\nХочу завжди, до могили бачить образ в муках Твій. \nХочу мать одне бажання - Твій тримати заповіт,\nІ в душі святим стремлінням всі до Тебе дні горіть.', '', '', '', '', 'ua', 0, NULL),
(95, 'Я вірю прийде Судний день', 0, 11, 'Куплет 1\nЯ вірю - прийде Судний день,\nТоді зблідніють з жаху люди;\nЗамовкне хор гучних пісень, -\nІ скрізь скорботно й страшно буде.\n\nКуплет 2\nТемрява чорна землю вкриє,\nПогасне сонце, згаснуть зорі.\nЗаграють сумно води моря,\nІ вітер в темряві завиє.\n\nКуплет 3\nВеликий жах на світ повіє,\nЗатрублять ангели у труби,\nЗ могил устануть усі люди,\nВсе змовкне раптом, заніміє.\n\nКуплет 4\nЯ вірю - прийде Судний День,\nІ гірко плакатимуть люди;\nЗамовкне хор гучних пісень,\nСкорботно всюди й страшно буде.', '', '', '', '', 'ua', 0, NULL),
(96, 'Відкритий мені був Суд Божий', 0, 11, 'Куплет 1\nВідкритий мені був Суд Божий:\nТруби звук під небом гримів;\nБіля трону зібрались народи,\nИ рішалась навік доля їх.\nІ з неба зійшов світлий ангел.\nВін став на землі й на воді,\nИ посвідчився Богом небесним,\nЩо час вже пройшов для людей.\n\nПриспів: \nОдчай, крик, благання і стогін \nПовстав на тім страшнім суді:\nВ мольбі многі крились у гори,\nТа вже було пізно тоді.\n\nКуплет 2\nБули там багаті, що в світі \nСумління своє продали, - \nСтояли вони бідні, грішні,\nДіла бо їх з ними прийшли.\nТакож там вельможні стояли,\nЩо славились тут на землі,\nТа ангели в книзі небесній \nВеличності їх не знайшли.\n\nКуплет 3\nТам сироти стали, вдовиці, - \nГосподь всі їх сльози згадав;\nЗневажених світом, убогих \nСпаситель ласкаво прийняв.\nА «праведність» всіх лицемірів,\nВсю гордість, що нею світ жив,\nЯк рештки старої одежі \nСуддя вогнем правди спалив.', '', '', '', '', 'ua', 0, NULL),
(97, 'Пильнуй у всякий час брате всі дні пильнуй', 0, 11, 'Куплет 1\nПильнуй у всякий час, брате, всі дні пильнуй:\nХай вчують голос твій, - всім говори: \n«Пильнуй!» Пильнуй, як Бог велить, - служи Йому всі дні; \nПильнуй, - ось Він спішить дати спокій тобі.\n\nПриспів: \nПильнуй — молись, пильнуй - молись, \nПильнуй вночі, та будь готовий і вдень, \nВсякий час пильнуй!\n\nКуплет 2\nПрокиньсь від сну і стій, брате, на варті стій! \nТримай Завіт святий, даний Христом самим.\nБрате, пильнуй, молись, бо Сам Спаситель твій \nЗа тебе кров пролив і умер на хресті.\n\nКуплет 3\nВ час битви із гріхом на Господа вповай; \nВіддайсь Йому цілком - Він перемогу дасть. \nКоли зоря зійде, — прокинься, не дрімай!\nА як Господь прийде, то нас введе в Свій рай.', '', '', '', '', 'ua', 0, NULL),
(98, 'Іду вгору на небеса і все щораз то вище я', 0, 11, 'Куплет 1\nІду вгору на небеса, і все щораз, то вище я;\nТакож я Господа молю:\n«Провадь мене у вись святу!»\n\nПриспів: \nМене, мій Боже, піддержи,\nЩоб міг встояти в боротьбі,\nБо я пізнав - Твоя любов Людей спасає знов і знов.\n\nКуплет 2\nНе хочу жити так, як жив,\nХоч ворог стріли нагострив;\nЯ чую райськії пісні, пісні святих, в святій землі.\n\nКуплет 3\nЯ хочу в самий верх зійти, але не маю сили йти, \nТебе, о Боже, я молю:\n«Провадь мене у вись святу!»', '', '', '', '', 'ua', 0, NULL),
(99, 'Я сиджу в ногах Ісуса слухаю Його слова', 0, 11, 'Куплет 1\nЯ сиджу в ногах Ісуса - слухаю Його слова:\nО, як любо, як солодко научатись від Христа.\n\nКуплет 2\nЯ сиджу в ногах Ісуса - на минуле дивлюсь я...\n Милість Його так велика, що збагнуть не можу я.\n\nКуплет 2\nЯ сиджу в ногах Ісуса, Він мене благословля.\nВін гріхи простив мої всі і спокоєм наповня.\n\nКуплет 2\nЯ сиджу в ногах Ісуса: люблю теж молитись я,\nІ пісні хвали співати, в славу для Спасителя.\n\nКуплет 2\nО, благослови, мій Спасе, біля ніг Твоїх мене,\nГлянь на мене із любов’ю і яви Своє лице.\n\nКуплет 2\nОтче! Дай Духа Святого, а також любов Христа,\nЩоб я міг тут свято жити, серцем линуть в небеса.', '', '', '', '', 'ua', 0, NULL),
(100, 'О як радісно в дружбі з Господом Йти', 0, 11, 'Куплет 1\nО, як радісно в дружбі з Господом Йти, \nОпершись на Його рам’я;\nЯк солодка та дружба з Господом,\nПрославляю я Його Ім’я.\n\nПриспів: \nЛюбо йти з Ним (Любо іти з Ним (2р.))\n Опершись на Його рам’я;\nЛюбо й мило (Любо і мило (2р.)) \nСлавити Його святе Ім’я!\n\nКуплет 2\nО, як радісно йти в дорозі з Ним...\nВсе покласти на Його рам’я;\nО, як добре з Ним жити в кожнім дні,\nЗавжди славити Його Ім’я.\n\nКуплет 2\nО, нічого я тепер не боюсь,\nБо підтримку маю від Христа.\nІ спокійно я Господу молюсь, - \nПрославляю я Його Ім’я.', '', '', '', '', 'ua', 0, NULL),
(101, 'Ми ідемо в Ханаан мандруєм в путі', 0, 11, 'Куплет 1\nМи ідемо в Ханаан, мандруєм в путі...\nСмілий хто через Йордан вірою іти?\n\nПриспів: \nБудь, як був Ісус Навин. «Я піду!» - скажи,\n «Я і дім мій - ми будем Господу служить!»\n\nКуплет 2\nБезліч горя бачим ми на нашім путі;\nПроти сили зла і тьми вірою ідім.\n\nКуплет 3\nЯк Червоне море нам ляже впереді,\nПам’ятаймо ці слова: «Вірою іди!»\n\nКуплет 4\nДля всіх вірних Ісус Сам є Проводирем, - \nМи в небесний Ханаан вслід за Ним ідем.', '', '', '', '', 'ua', 0, NULL),
(102, 'Я не залишу вас самих коли від вас піду', 0, 11, 'Куплет 1\nЯ не залишу вас самих, коли від вас піду, - \nСвятого Утішителя, Небесного Учителя \nЯ вам навік зішлю.\n\nПриспів: \nПрийняв ти Його? Прийняв ти Його? \nУтішителя прийняв чи ні?\nГосподь докорить світ за гріхи,\nКоли прийде до нас Дух Святий.\n\nКуплет 2\nО, Церкво Божа, час вставать, всю повноту прийнять!\nЩоб грішники по всіх місцях\nПокаялись в своїх гріхах, - прийняли благодать.\n\nКуплет 3\nДари духовні в небесах у Бога є для нас.\nВперед, молімся з вірою, - Господь наділить силою \nВ борні у кожний час.\n\nКуплет 4\nМи до П’ятидесятниці скоріш, скоріш спішім:\nСвятим життям усі живім\nХрещення Духом ми Святим у Бога всі просім!', '', '', '', '', 'ua', 0, NULL),
(103, 'Там на хресті де Христос страждав', 0, 11, 'Куплет 1\nТам, на хресті, де Христос страждав,\nТам всі провини мої Він зняв,\nТам Він спасіння для нас звершив. О, хвала Йому!\n\nПриспів: \nО, хвала Йому! (2р.)\nТам всі провини мої Він зняв.\nО, хвала Йому!\n\nКуплет 2\nКров’ю Спас душу мою обмив.\nІ Словом правди Він відродив,\nДухом Святим Він мене хрестив. О, хвала Йому!\n\nКуплет 3\nЛюбі друззя, ще приємний час:\nБог нині хоче спасти всіх вас,\nТож поспішіть до Христа в цей час! О, хвала Йому!', '', '', '', '', 'ua', 0, NULL),
(104, 'О Слово Боже вірне В нім наше все життя', 0, 11, 'Куплет 1\nО, Слово Боже вірне! В нім наше все життя.\nБагатство в нім нетлінне - наука це Христа.\nХристос в любві втішає і душу оживля,\nЗ сумніву визволяють Його святі слова:\n\nПриспів:\n Прийди до Христа: в Нім твоє життя;\nДруже безутішний, не вагайсь, іди! (2р.)\n\nКуплет 2\nО, серце, не вагайся, Спасителю повір,\nНавік Йому віддайся, проси у Нього сил.\nНещасний, хто блукає далеко від Христа,\nЩасливий, хто приймає Божественні слова.\n\nКуплет 3\nО, Боже, будь Ти з нами і вдень, і уночі,\nЩоб світлими путями до Тебе йшли мерщій; \nМогутньою рукою веди нас всіх вперед \nДорогою вузькою все за Собою вслід!', '', '', '', '', 'ua', 0, NULL),
(105, 'Ніч яка темна настала', 0, 11, 'Куплет 1\nНіч яка темна настала...\nЧорно і холодно скрізь...\nХтось там самотній ридає,\nХтось обезсилів від сліз. \t(2р)\n\nКуплет 2\nНащо ж ви знов задрімали?\nВстаньте, прокиньтесь, не спіть!\nНіч яка темна настала...\nГрішних спасайте,- будіть! \t (2р)\n\nКуплет 3\nСили темрява збирає...\nІ чорні сни свої снить:\nГоспода люди не знають \nИ не хочуть Йому служить. \t (2р)\n\nКуплет 4\nНащо ж ви знов задрімали,\nЧому не йдете спасать?\nБачите темно як стало:\nВсюди байдужість, всі сплять.  (2р)\n\nКуплет 5\nПравди на світі так мало,\nМіж людьми гасне любов:\nСумом нас й жахом обняло \nЙ бачу я горе і кров.  \t(2р)', '', '', '', '', 'ua', 0, NULL),
(106, 'Дрімає Гефсиманський сад', 0, 11, 'Куплет 1\nДрімає Гефсиманський сад. Друзі Ісуса мирно сплять.\nА там пооддаль Сам один Отця благає Божий Син.\n\nКуплет 2\nВін приклонивсь, лице схилив і гаряче Отця молив,\nІ голос скорбної душі почувся в дрімотній тиші:\n\nКуплет 3\n- Хай чаша мук пройде оця, та воля не Моя - \nТвоя Хай буде, Отче. Я іду! - все було тихо у саду.\n\nКуплет 4\nІ капав піт з лиця Його, як краплі крові, - вкрив чоло.\nІ ангел Божий тут стояв, Христа в молитві підкріпляв.', '', '', '', '', 'ua', 0, NULL),
(107, 'В день коли труба Господня', 0, 11, 'Куплет 1\nВ день, коли труба Господня,\nВсіх святих згромадить там\nНад прозорою рікою, як кришталь (як кришталь).\nНа весільну там вечерю забере Ісус нас Сам:\nО, яка ж то зустріч дивна буде там!\n\nПриспів: \nО, яка ж то зустріч!\n(О, яка ж то зустріч буде, де зберуться святі люди).\nІ збавлення звістить трубний Голос нам (голос нам).\nО, яка ж то зустріч!\n(Там зустрінем наших близьких серед райських радощів там).\nО, яка ж то зустріч дивна буде там!\n\nКуплет 2\nІ звістить всім ангел Божий,\nЩо нема вже більш часу!\nМи будем підхоплені у небеса (в небеса);\nТам усіх Ісус-Спаситель вдягне в славу нас Свою...\nО, яка ж то зустріч дивна буде там!\n\nКуплет 3\nТе, що тайне і закрите, в той день виявиться все,- \nЯк Господь буде судити всіх людей (всіх людей). \n«Увійдіть, - Він скаже правим - В радість Пана свойого!»\nО, яка ж то радість дивна буде там!\n\nКуплет 4\nТам при звуках гуслів стройних,\nАрф небесних золотих, -\nГімн спасіння й перемоги викликнем (викликнем): \nПісню Агнця і Мойсея заспіваєм всі разом ...\nО, яка ж то радість дивна буде там!', '', '', '', '', 'ua', 0, NULL),
(108, 'Душа Утішайся Ісусом', 0, 11, 'Куплет 1\nДуша! Утішайся Ісусом:\nГріхи Він обмив всі твої,\nЛюбов’ю тебе окриляє,\nДобро посилає тобі.\n\nПриспів:\nЩасливий я вічно з Ісусом!\nСпочинок в Христі я знайшов: \nМені дав спокій Він і радість, \nКоли я до Нього прийшов.\n\nКуплет 2\nЩасливий я всюди з Ісусом!\nВін Духом мене оживив,\nЯк щедрий Отець у любові,\nНебеснеє Царство відкрив.\n\nПриспів:\nЩасливий я всюди з Ісусом!\n Тягар свій зложив у Христа: \nСпокій я знайшов і блаженство\n В любові Ісуса Христа.\n\nКуплет 3\nЩасливий я всюди з Ісусом!\nХоч шлях мій тернистий, вузький,\nМене до мети доведе Він,\nДе вічний знайду я спокій.\n\nПриспів \n-Щасливий я всюди з Ісусом!\nЗавжди бути в спільності з Ним; \nУ серці Його відчувати\n І тішитись Ним лиш одним.', '', '', '', '', 'ua', 0, NULL),
(109, 'Обізвись мій милий Боже', 0, 11, 'Куплет 1\nОбізвись, мій милий Боже, Боже - Правдо Ти моя! \nОбізвись в тяжку годину, як подам свій голос я.\n\nКуплет 2\nМені тісно було, Боже, а Ти дав мені простір,\nІ тепер мене помилуй та пошли душі Твій мир!\n\nКуплет 3\nМайте страх ви перед Богом, усі люди на землі, \nПомишляйте в ваших серцях про діла Його святі!\n\nКуплет 4\nЗасіяй над нами, Боже, світлом Твойого лиця,\nТим святим, небесним світлом, що сіяє без кінця!', '', '', '', '', 'ua', 0, NULL),
(110, 'Ось прийшов молитви час Господу принесім', 0, 11, 'Куплет 1\nОсь прийшов молитви час, Господу принесім,\nВесь тягар, що мучить нас, і знайдем радість в Нім. \nСам Господь нам дав це знать, що нас хоче прийнять \nІ святі благословення на життя посилать.\n\nПриспів: \nО, молитви час! О, молитви час!\nЗ Господом в святім єднанні В серці радість і мир.\t2р.\n\nКуплет 2\nОсь прийшов молитви час, ми благаєм Тебе:\nБоже, Дух пролий на нас та відкрий нам Себе!\nПісня слави ллється хай, душі нам зогрівай,\nІ любов, і мир рікою у серця проливай.\n\nКуплет 3\nОсь, прийшов молитви час, - всі зібралися ми;\nО, прийди, Господь, до нас, всіх в одно з’єдини.\nМир подай усім серцям, мир пролий з неба нам,\nВсі почуй наші моління, Боже, будь з нами Сам!', '', '', '', '', 'ua', 0, NULL),
(111, 'До Тебе Боже мій ближче я йду', 0, 11, 'Куплет 1\nДо Тебе, Боже мій, ближче я йду;\nХоч би і на хресті розп’ятий був,\nСпівав би я й тоді: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 2\nХоч би, мов мандрівник, сонце зайшло,\nНа скелі в тьмі моє ложе було,\nСпівав би я і в сні: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 3\nХай вбачу сходи в сні, що в небо йдуть;\nДані дари мені від Тебе суть.\nХай ангели Твої путь вказують мені, - \n«До Тебе, Боже мій, ближче я йду!»\n\nКуплет 4\nПрокинусь, і в думках моїх, як дар,\nПоставлю, Боже мій, Тобі вівтар.\nСпіватиму й в журбі: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»\n\nКуплет 5\nКоли б у небо я навіть злітав, - \nСонце, місяць, зірки я б проминав...\nСпівав би я й тоді: «До Тебе, Боже мій,\nДо Тебе, Боже мій, ближче я йду!»', '', '', '', '', 'ua', 0, NULL),
(112, 'Ми всі уповаємо на Скалу', 0, 11, 'Куплет 1\nМи всі уповаємо на Скалу, - \nСкала та - Христос Спаситель:\nІ в бурю страшну, і в час негод знайдемо захист в ній.\n\nПриспів: \nХристос - та Скала,\n(Ми всі уповаєм на ту Скалу)\nХристос - та Скала,\n(Ми всі уповаєм на ту Скалу)\nМи всі уповаєм на ту Скалу,\nСпаситель наш - Скала.\n\nКуплет 2\nСвої всі надії на піску поклали тут всі байдужі: \nБагатство і слава, в світі честь - \nЛише в цім їх бажання.\n\nКуплет 3\nПрийдіть і будуйтесь на Скані, усі проженіть сумніви, \nА хто прагне правди, хай прийде:\nТут всі знайдуть спасіння.', '', '', '', '', 'ua', 0, NULL),
(113, 'Пливе світами пісня любові', 0, 11, 'Куплет 1\nПливе світами пісня любові...\nСпів той хай громом могутнім гуде!\n(Для нас спливає щастя чудове:\nСам Господь Христос у славі іде. )\t(2р)\n\nКуплет 2\nВ маній хатині, в мирній оселі \nГостить безмежне там щастя - любов.\n(Сам Христос Господь, що на Голгофі \nЗа гріхи світу віддав в жертву кров.)\t(2р)\n\nКуплет 3\nО, пресвятая Тайна любові!\nПеред Тобою і мудрість є німа.\n(В кожний час спомину тіла і крові \nХай за нас молить теж віра тверда.)\t(2р)\n\nКуплет 4\nХай за нас молить і серце чисте;\nКаяння сльози у наших очах. \n(Вітай між нами, Спасе наш, Христе,- \nВсесильний Боже, в чудових ділах!)\t(2р)', '', '', '', '', 'ua', 0, NULL),
(114, 'Чи знаєш битву Ісуса', 0, 11, 'Куплет 1\nЧи знаєш битву Ісуса, - муки страшні від хреста? \nВесь я сльозами заллюся, смерть як згадаю Христа. \nО, як над Ним там знущались, як розпинали Його! \n(Цвяхи, мов змії, в’їдались\nВ руки і ноги Його.) (2р)\n\nКуплет 2\nЗ ран кров стікала струмочком, Син Божий там умирав, \nА непроглядна мла-морок землю тоді покривав... \nТам дух злоби притаївся - змій беззаконня - гріхів...\n(О, як в страждальця він в’ївся! \nТемні хрести три обвив.) (2р)\n\nКуплет 3\nВесь я сльозами заллюся, як пригадаю той час,\n Коли Спаситель у муках прагнув спасти усіх нас. \nЯк умирав Він, молився за розпинателів злих,\n(Як до кінця полюбив нас!\nВзяв на Себе весь наш гріх.) (2р)\n\nКуплет 4\nГлянь на Зорю Воскресіння! Вчуй спів чудовий хвали.\n Бачиш, - виходить нетлінний Цар і Спаситель землі. \nДишучи злістю німою, змій той побитий лежить,- \n(Пастир до стада явився,\nЩоби овець хоронить.) (2р)', '', '', '', '', 'ua', 0, NULL),
(115, 'Бажаю все Тебе о Боже мій', 0, 11, 'Куплет 1\nБажаю все Тебе, о Боже мій!\nЛаскавий голос Твій дає спокій.\n\nПриспів: \nТи захист мій, надія в кожний час, о Боже, \nБлагослови, мій Спасе - до Тебе йду!\n\nКуплет 2\nБажаю все Тебе: зі мною будь!\nЗ Тобою у пітьмі ясніє путь.\n\nКуплет 3 \nБажаю я усе, Боже, Тебе;\nБез Тебе є марне життя моє.\n\nКуплет 4\nБажаю все Тебе, - сил мені дай,\nЯк жити на землі, мене навчай.', '', '', '', '', 'ua', 0, NULL),
(116, 'Хваліте Господа співайте', 0, 11, 'Куплет 1\nХваліте Господа, співайте,\nЯк радісно складать хвалу!\nЙого Єдиного прославте,\nВіддайте серце все Йому!\n\nПриспів:\nХваліте Господа (хваліте всі),\nСпівайте (співайте всі), -\nЯк радісно складать хвалу, (хваліте всі), —\nЙого Єдиного прославте (Його Єдиного прославте (2р.)),\n Віддайте серце все Йому (серце все Йому)!\n\nКуплет 2\nУсім світилам, сонцю, зорям \nШляхи у небі призначив \nВеликий Бог,- світів простори\nПремудро-дивно сотворив.\n\nКуплет 3\nІ хмари в небі чередою \nПо слову Господа пливуть,\nВін скроплює квітки росою,\nСади в красі Творця цвітуть.\n\nКуплет 4\nЗвірям, пташкам дає Бог їжу,\nІстотам всім Він дав життя,\nВін людям всім дає одежу,\nІ постанови дав царям.\n\nКуплет 5\nЛаскаво тихих Бог приймає \nІ захист праведним дає;\nУ гордих силу відіймає,- \nІ мудрості в них не стає.\n\nКуплет 6\nНачніте ж Бога, ви начніте,\nВсі людські пізнавать уми,\nДля слави ви Його спішіте \nСкладати співи і псальми.', '', '', '', '', 'ua', 0, NULL),
(117, 'Він у двері стукає з любовію', 0, 11, 'Куплет 1\nВін у двері стукає з любовію.\nО, впусти (впусти Його), впусти Його (впусти Його).\nХоче Він спасти з гріха твою душу,\t\nО, впусти (впусти Його), впусти Його (впусти Його)!\n\nПриспів: \nСтук, стук! Стук, стук! Двері відчини,\nДнесь Христа впусти (Христа впусти).\nВ серце ти своє (в серце своє).\nСтук, стук! Стук, стук! Він подасть спокій,\nЯк приймеш Його в дім свій (у дім свій).\n\nКуплет 2\nТебе кличе лагідно, з любовію.\nО, впусти (впусти Його), впусти Його (впусти Його)!\nГлянь! Який Він милосердний до тебе,\nО, впусти (впусти Його), впусти Його (впусти Його)!\n\nКуплет 3\nВін чекає на тебе з любовію,\nО, впусти (впусти Його), впусти Його (впусти Його).\n Ти прийми Його днесь радо до себе,\nО, впусти (впусти Його), впусти Його (впусти Його)!', '', '', '', '', 'ua', 0, NULL),
(118, 'Коли складаєш ти хваління і веселишся', 0, 11, 'Куплет 1\nКоли складаєш ти хваління і веселишся, брат,\nРадієш, що знайшов спасіння,\nДуші нетлінний скарб, -\nПоглянь лиш на життєве море, і в нім побачиш ти \nПотоки сліз, людей у горі, що тонуть в марноті.\n\nКуплет 2\nБез світла віри у темряві плавці кудись пливуть, \nІ Сонце Правди, їм незнане, не освітляє путь. \nХто ж з нас відкликнеться на горе -\nТих моряків спасать?...\nїм руку помочі на морі, о, поспішіть подать!', '', '', '', '', 'ua', 0, NULL),
(119, 'Як праця скінчиться тут вже моя', 0, 11, 'Куплет 1\nЯк праця скінчиться тут вже моя,\nІ в Край Небесний перейду вже я:\nГосподню славу побачу там я, - \nЗ того буде вічна радість моя...\n\nПриспів: \nО, то буде радість моя, (2р.)\nКоли обличчя побачу Христа!\nТо буде радість, то радість моя!\n\nКуплет 2\nСпас приготовив там місце мені \nВ домі Отця, у небесній красі,\nО, що за радість: там вбачу Христа, - \nЗ того буде вічна радість моя!\n\nКуплет 3\nТам я зустріну всіх близьких моїх,\nЩо жили ми разом тут на землі.\nТам буде правда й Христова рідня,\nЗ того буде вічна радість моя.', '', '', '', '', 'ua', 0, NULL),
(120, 'Прекрасний білий стрій прекрасний дім святий', 0, 11, 'Куплет 1\nПрекрасний білий стрій, прекрасний дім святий, \nСвітла земля свята, - там ночі вже нема.\nТам я вінець життя одержу від Христа,\nБуде він сяяти, наче зоря.\n\nПриспів:\nПрекрасний стрій (прекрасний білий стрій) \nСвітла земля (прекрасна та земля),\nПрекрасний дім (прекрасний дім святий),\nДля вірних там (для вірних слуг є там),\nСлавний вінець (славний вінець нас там жде), \nСіяючий (ясно так, ясно сія)...\nЧудесний хор там є (чудесний хор там є), \nСлавить Христа (все славить Христа).\n\nКуплет 2\nПрекрасні ті думки радують так мене, - \nМи вічно там будем, як це життя пройде. \nРадість небесна там наповнить всі серця, \nБажаю бути там, - про це молюсь...\n\nКуплет 3\nПрекрасні речі там, де наш Спаситель сам;\nВід смутку й марноти скоро підем туди,\nДе смерті вже нема, а вічне там життя;\nДе правда вічная - в землі святій...', '', '', '', '', 'ua', 0, NULL),
(121, 'Христос за гріх наш викуп дав', 0, 11, 'Куплет 1\nХристос за гріх наш викуп дав, о, чудесний Спаситель! \nМи куплені, - ціна дана, о, чудесний Спаситель!\n\nПриспів: \nО, чудесний Спаситель, є Ісус, мій Ісус,- \nО, чудесний Спаситель, Ісус, мій Господь.\n\nКуплет 2\nВін кров святу за нас пролив, о, чудесний Спаситель !\nІ з Богом примирив мене, о, чудесний Спаситель!\n\nКуплет 3\nІз мого серця гріх Він стер, о, чудесний Спаситель!\nІ Сам царить Він в нім тепер, о, чудесний Спаситель!\n\nКуплет 4\nВ дорозі йде зі мною Він; о, чудесний Спаситель !\nІ поміч Він дає в біді, о, чудесний Спаситель!\n\nКуплет 5\nВін перемогу нам дає, о, чудесний Спаситель!\nІ радість в горю подає, о, чудесний Спаситель!\n\nКуплет 6\nЙому я серце дав своє, о, чудесний Спаситель!\nВ нім місця світ немає вже, тільки любий Спаситель!', '', '', '', '', 'ua', 0, NULL),
(122, 'О як мило чути голос голос той дивний', 0, 11, 'Куплет 1\nО, як мило чути голос, голос той дивний: \nВчора, нині і навіки Ісус той самий! ;\nВін спасає всіх нас грішних, а тих, хто слабий - \nВін зціляє від недугів, - Бог наш дорогий!\n\nПриспів:\nВчора, нині і навіки Ісус той самий,\nВсе зміниться, Він - ніколи, Він все той самий,. \nСлава все Йому, слава все Йому!  Все зміниться, \nВін - ніколи: слава все Йому!\n\nКуплет 2\nВін для грішників був другом, згублених спасав.\nО, прийдіть усі до Нього - Він же кров пролляв.\nВін колись сказав до жінки: «Не суджу тебе,\nЙди і більше не гріши вже», й скаже так тобі.\n\nКуплет 3\nВін колись зціляв недужих, як був на землі,\nІ також оздоровляє Він і в наші дні.\nВін давав здоров’я многим, бо Він мав ту власть; \nХто до Нього приторкнеться, Він і нині дасть.\n\nКуплет 4\nЯк колись на Еммаус йшли, - з ними був в той час; \nТак і в нашім Він житті є завжди близько нас;\nСкоро знов Його побачим - того дня ждем всі... \nТой самий Ісус все буде, як вознісся Він.', '', '', '', '', 'ua', 0, NULL),
(123, 'Будем розсівати Слово Боже рано', 0, 11, 'Куплет 1\nБудем розсівати Слово Боже рано,\nВ півдні, й при заході сонця, і вночі;\nБудемо чекати овочу, що зродить;\nЗ радощами в серці принесем снопи.\n\nПриспів: \nПринесем снопи (2р.), \nЗ радощами в серці принесем снопи.\n\nКуплет 2\nЧи то в пору добру, чи в час непогоди,\nНавіть в часі бурі, спеки чи дощу \nМи не занедбаєм доброї нагоди, - \nЗ радощами в серці принесем снопи.\n\nКуплет 3\nБудем поширяти правду Божу всюди,\nХоч і перешкоди всякі навкруги:\nСкоро час настане, жниво дозріває.\nЗ радощами в серці принесем снопи.', '', '', '', '', 'ua', 0, NULL),
(124, 'Не знаю чому Бог мені відкрив Свою любов', 0, 11, 'Куплет 1\nНе знаю, чому Бог мені відкрив Свою любов,\nАбо чому Спаситель мій пролив за мене кров?\nНе знаю, як Бог дав мені спасіння дар прийнять,\nІ сила Його Слова як дає нам благодать.\n\nПриспів: \nАле знаю, в Кого я вірю, -\nНіщо мене з Христом не розлучить; \nМені Він насліддя вручить \nВ день, коли Він знов прийде.\n\nКуплет 2\nНе знаю я, як Дух Святий хоронить в вірі нас,\nІ відкриває нам Христа в Божественних словах?\nНе знаю я часу, ні дня, коли Господь прийде - \nЧи через смерть,чи Сам мене в той день Він забере?', '', '', '', '', 'ua', 3, NULL),
(125, 'Я чужоземець тут у стороні чужій', 0, 11, 'Куплет 1\nЯ чужоземець тут у стороні чужій.\nНа небесах, в святім краю, там дім є мій.\nЯ посланець є тут з Царства Небесного, - \nПриношу вістку для людей!\n\nПриспів:\nВістку приношу із небес, що ангели співають все: \n«О, примирітеся, - звучать слова Царя, -\n О, примирітесь з Богом всі!»\n\nКуплет 2\nЦе є Царський наказ, щоби всі люди скрізь \nВ гріхах покаялись, і Він простить їм гріх.\nО, нині, друже мій, прийми Христа і жий! -\n Приношу вістку для людей.\n\nКуплет 3\nМій дім гарніший є, як саронські квітки,\nІ радість вічна там над всіма вірними.\nНе замовкаю я і кличу всіх туди —\nДо Господа, мого Царя.', '', '', '', '', 'ua', 0, NULL),
(126, 'Вже темно і народ тремтить весь', 0, 11, 'Куплет 1\nВже темно і народ тремтить весь.\nЗдригаються небо й земля.\nА ось мертві вже воскресають, - \nЯвляється слава Христа.\n\nПриспів: \nХристос прийде, своїх візьме, \nСпасенних в славу всіх збере; \nХристос прийде! О, славний час \nДля всіх людей, котрих Він спас.\nО, радісний для нас той день, (2р.) \nКоли Христос з небес прийде,\nУ славу нас введе.\n\nКуплет 2\nПрийде Він не так, як приходив \nВмирати за людські гріхи,\nА прийде у славі Владика - \nСудити живих і мертвих.\n\nКуплет 3\nО, люди, від сну пробудіться! \nПокайтесь, втікайте від зла!\nЗабудьте злобу, обніміться!\nІ будем чекати Христа.', '', '', '', '', 'ua', 0, NULL),
(127, 'Ти пішов так далеко геть від Отця', 0, 11, 'Куплет 1\nТи пішов так далеко геть від Отця,\nСмуток, горе і блуд в світі цім;\nОсь лагідний днесь голос зове тебе:\n-Сину мій, сину мій, йди в свій дім!\n\nПриспів: \nСину мій, (йди в свій дім), (2р.) \nСину мій, о, йди в свій дім!\n(Сину мій, о йди в свій дім!)\nЙди в свій дім (2р.)\n(Це Отець твій кличе днесь):\nСину мій, йди в свій дім, в свій дім! \n(Сину мій, іди в свій дім!)\n\nКуплет 2\nХочуть хвилі морські потопить тебе,\nНебезпека тебе жде в путі;\nОсь дім захисту жде у Отця тебе,\nСину мій, сину мій, йди в свій дім!\n\nКуплет 3\nВін благає тебе, поклик вчуй Його,\nЯк Він просить тебе: сину мій, - \nВ дім Отця твого йди і більш не блуди. \nСину мій, сину мій, йди в свій дім!', '', '', '', '', 'ua', 0, NULL),
(128, 'Коли страх мене обгорне', 0, 11, 'Куплет 1\nКоли страх мене обгорне, о, Спасе, тримай!\nІ коли віра ослабне, Ти мене тримай!\n\nПриспів: \nЗа руку тримай, за руку тримай!\nСпасителю Всемогутній, Сам мене тримай\n\nКуплет 2\nЯ не можу сам триматись, о, Спасе, тримай!\nДай на Тебе покладатись, Ти мене тримай!\n\nКуплет 3\nВ ясний час чи в час нещастя, о, Спасе тримай!\nВ дні недолі чи у щастю Ти мене тримай!\n\nКуплет 4\nСтережи Сам мою душу, о, Спасе, тримай!\nТи купив мене ціною, Ти мене тримай!', '', '', '', '', 'ua', 0, NULL),
(129, 'Як солодко йти з Ісусом', 0, 11, 'Куплет 1\nЯк солодко йти з Ісусом, крок за кроком, день за днем.\nУ Його сліди ступати і ходити все за Ним.\n\nПриспів: \nСлідом в слід (2р.) піду за Ісусом.\nКожний день, кожний час піду за Ісусом.\n\nКуплет 2\nЯк безпечно йти з Ісусом, спершись на рам’я Иого - \nЙти усюди, де веде Він, поки є життя мого.\n\nКуплет 3\nКрок за кроком йду з Ісусом, всякий час усе за Ним; \nХоч я немічний, безсилий, але сила моя в Нім.\n\nКуплет 4\nО, тримай мене, мій Спасе, близько, близько при Собі, \nЩоб ніколи не зблудив я, щоб ступав в сліди Твої!', '', '', '', '', 'ua', 0, NULL),
(130, 'Любо вірити в Ісуса і святим Його словам', 0, 11, 'Куплет 1\nЛюбо вірити в Ісуса і святим Його словам;\nЯ душею підношуся в Край Небесний, де Він Сам.\n\nПриспів:\nМій Спасителю, Ісусе! Ти є добрий Пастир мій.\nМій Спасителю, Ісусе, я вже вічно буду Твій!\n\nКуплет 2\nЯ надіюсь на Ісуса, на Його святу любов;\nЯ Йому служу й молюся: Він пролив за мене кров.\n\nКуплет 3\nЯк приємно знати Бога, духом пробувати з Ним, \nПідкріплятись Його Словом і ходити завжди з Ним!', '', '', '', '', 'ua', 0, NULL),
(131, 'Більш про Ісуса хочу знать', 0, 11, 'Куплет 1\nБільш про Ісуса хочу знать,\nБільше про Його благодать,\nБільш про Його святу любов,\nЩо Він за мене умирав.\n\nПриспів: \nБільш, більш про Ісуса, (2р.)\nБільш про святу Його любов,\nЩо Він за мене умирав.\n\nКуплет 2\nБільш до Ісуса я спішу,\nЩоб волю пізнавать святу;\nЩоб Дух Святий учив мене,\nЯк маю свято жить усе.\n\nКуплет 2\nБільш про Ісуса хочу знать,\nСлово Його святе читать,\nБачити в Нім Його любов,\nЯк за людей пролив Він кров.\n\nКуплет 4\nБільше я хочу знати те,\nЯк вічно Він Царем буде,\nБільш про Його славний прихід,\nЯк прийде взяти Він своїх.', '', '', '', '', 'ua', 0, NULL),
(132, 'Як олень спрагнений в степу біжить до джерела', 0, 11, 'Куплет 1\nЯк олень спрагнений  степу біжить до джерела, \nТебе так прагне, Боже мій, моя сумна душа. (2р.)\n\nКуплет 2\nТи є цілюще джерело, що в нім жива вода,\nЯка відсвіжує наш дух і спрагнені серця. (2р.)\n\nКуплет 3\nЧого ж ви журитесь, брати, чого такі сумні? Надійтесь, \nБог оберне жаль у радісні пісні. (2р.)\n\nКуплет 4\nКріпіться, браття, та з душі ви смуток геть женіть.\nМи ж діти Того, що держить в руках Своїх весь світ. (2р.)\n\nКуплет 5\nО, Спасе! Спрагненим серцям живої дай води,\nІ нас знеможених кріпи, шляхом життя веди! (2р.)', '', '', '', '', 'ua', 0, NULL),
(133, 'Спокій небесний я знайшов', 0, 11, 'Куплет 1\nСпокій небесний я знайшов, як до Христа прийшов: \nМоє Він серце відродив, мої гріхи простив.\nТам біля студні Сихаря я був з Христом моїм,\nНераз була душа моя там в Галилеї  з Ним.\n\nПриспів: \nТам, в Галилеї з Ним,\nІ часто бачу я себе там, в Галилеї з Ним.\n\nКуплет 2\nПостійно я стремлюсь вперед, в небесний вічний рай;\nЛиш за Христом іду я вслід в обітований Край.\nТепер надіюсь на Нього, і рад Йому служить,\nІ я спішу в ногах Його тягар гріха зложить.\n\nКуплет 3\nЯ бачу той тернистий шлях, на нім Христову кров; \nМи всі томились у гріхах, нас всіх спасла Любов. \nЛюбов Христа нас підняла із рова марноти. \nБушують в світі хвилі зла, життя ж лиш у Христі.', '', '', '', '', 'ua', 0, NULL),
(134, 'Без Бога я блукав у світі', 0, 11, 'Куплет 1\nБез Бога я блукав у світі, спокою не мав,\nЛише Спаситель в Своїй крові спокій мені дав.\n\nПриспів: \nДивний спокій Христос дарував,\nНа хресті дар спасіння придбав.\nХоч ще гріх навкруги так бушує, кипить, \nАле Бог нас хранить.\n\nКуплет 2\nМарноти світу затопляли душу вже мою,\nТоді Збавитель для спасіння руку дав Свою.\n\nКуплет 3\nНезмінне щастя, милість Божу серцем я пізнав: \nХристос за наші всі провини на хресті вмирав.\n\nКуплет 4\nХоч втомлені ви і безсильні в боротьбі земній, \nСпішіть ви до Христа, - Він дасть вам радість і спокій.\n\nКуплет 5\nСердечні двері відчиніте і прийміть Христа,\nВін вашу душу знов очистить, дасть нове життя.', '', '', '', '', 'ua', 0, NULL),
(135, 'Працю всім працю всім нам Господь доручив', 0, 11, 'Куплет 1\nПрацю всім, працю всім нам Господь доручив:\nВ путь підем, що Спаситель наш Сам проложив.\nІ Дух Правди Його буде нас підкріплять,\nВіру, сили, й життя кожний день обновлять.\n\nПриспів: \nПрацю всім (працю всім), (2р.)\nВірним Бог (вірним Бог)\nДоручив (доручив).\nО, працюй і молись,\nПоки Спаситель наш прийде.\n\nКуплет 2\nВсі до праці, усі! Хліб голодний знайде\nІ, хто правди шукає, - до Бога прийде.\nМи всі маєм про істину ближнім сказать,\nВ смутку-горю знеможеним поміч подать.\n\nКуплет 3\nВсі до праці, усі! Світ страждає у злі... \nЦарство Правди поширюймо тут на землі, \nТоді Бог Сам оселиться в наших серцях,\nБуде рай на землі, як тепер в небесах.\n\nКуплет 4\nВсі до праці, усі! Наш небесний Отець \nВ нагороду за працю дасть правди вінець.\nТам всі хори зіллються в божественний спів:\nВічна слава Тобі, наш Господь, Цар царів!', '', '', '', '', 'ua', 0, NULL),
(136, 'Візьми хрест сві', 0, 11, 'Куплет 1\n«Візьми хрест свій, йди за Мною!» (Зр.)\nСам Спаситель кличе вас, мене.\n\nКуплет 2\nЯ іду, куди веде Він, (Зр.)\nПо путі тернистім в світі цім.\n\nКуплет 3 \nЯ іду через Голгофу,  (Зр,) \nЗ Ним пройду страждання всі земні.\n\nКуплет 4\nЯ пройду з Ним перешкоди (Зр.)\nІ ввійду в небесний Вічний Край.\n\nКуплет 5\nВсюди Він мені поможе, (Зр .) \nБлагодаттю підкріпить мене.\n\nКуплет 6\nО, душе моя, кріпися! (Зр.) \nЗа тобою скоро Він прийде.', '', '', '', '', 'ua', 0, NULL),
(137, 'Сіється зерно при ранній зорі', 0, 11, 'Куплет 1\nСіється зерно при ранній зорі,\nСіється зерно в південній жарі,\nСіється зерно, як ляже тінь, \nСіється зерно, - скінчивсь вже день.. .\nЩо будеш, друже, жать?  \nЩо, друже, будеш жаты?\n\nПриспів: \nСіється в ясний чи похмурий час, \nСіється в силі чи в немочі в нас; \nЗібране тут чи то там в небесах, \nПраведне жниво чекає нас.\n\nКуплет 2\nПадає зерно на стежці твердій, \nі Падає зерно на грунт кам’яний,\nПадає зерно і у бур’ян,\nПадає зерно й на добрий лан...\nЩо будеш, друже, жать?\nЩо, друже, будеш жать?\n\nКуплет 3\nСіється зерно і мрій, і зітхань,\nСіється зерно плачу і страждань,  \nСіється зерно ганьби, гріха,\nСіється зерно і кривди, і зла...\nЩо будеш, друже, жать?\nЩо, друже, будеш жать?\n\nКуплет 4\nСіється зерно і добре, і зле,- \nВсякеє зерно свій плід принесе...\nСіється зерно до того дня,\nАж поки Божі прийдуть жнива...\nЩо будеш, друже, жать? \nЩо, друже, будеш жать?', '', '', '', '', 'ua', 0, NULL),
(138, 'Пригадаймо браття сестри тіминулії часи', 0, 11, 'Куплет 1\nПригадаймо, браття, сестри, ті-минулії часи,\nЯк зібрались на вечерю діти Божі у любві;\nНе щоб тілу догоджати час проводили вони,\nЛиш щоб Бога прославляти, ж одна сім’я, в любві.\n\nКуплет 2\nЗа столом псалми хваління щиро Неслися з сердець \nЗа дароване спасіння, що у Сині дав Отець.\nУ той час любов Христову відчували вірні всі: \nЦеркви Божої будова виростала у красі.\n\nКуплет 3\nІ тепер ми знов зійшлися за братерським цим столом,\nНаші співи знов злилися у Божественний псалом.\nО, Спасителю, благаєм: будь Ти з нами по всі дні,\nДух Святий хай нас навчає жити в радості, в любві!', '', '', '', '', 'ua', 0, NULL),
(139, 'О дивний день чудовий час', 0, 11, 'Куплет 1\nО, дивний день, чудовий час, коли Спаситель в перший раз \nЗі мною в заповіт вступив, спокоєм серце наділив.\n\nПриспів:\nДивний день, (2р.) коли Господь гріхи простив,\nТепер зі мною Сам Ісус, Він захищає від спокус: \nДивний день, (2р.) коли Господь гріхи простив!\n\nКуплет 2\nО, дивний день, коли Христос знайшов мене в долині сліз. \nТепер Він Пастир добрий мій, я вже Його, я вже не свій!\n\nКуплет 3\nО, дивний день, коли в любві Він руку простягнув мені; \nСумніви серця розігнав, — хвалу я Господу віддав.\n\nКуплет 4\nО, дивний день, коли життя моє воскресло у Христі, \nКоли мої всі почуття Він Духом обновив Святим.\n\nКуплет 5\nО, дивний день; коли пізнав душею я любов Христа.\nІ в серце Господа прийняв, - щасливим став на все життя.', '', '', '', '', 'ua', 0, NULL),
(140, 'О Боже Ти бачиш мене', 0, 11, 'Куплет 1\nО, Боже, Ти бачиш мене, \nТи знаєш стремління душі, \nПрийми в жертву серце моє,\nНавчи, як служити Тобі!\nЯ хочу веління Твої завсіди з любов’ю сповнять.\nО, Боже, дай сили мені Твоє лиш Ім’я прославлять.\n\nКуплет 2\nСпасителю мій! Обновляй постійно мої почуття,\nІ серце моє оживляй, освітлюй моє Ти життя, - \nЩоб вірним слугою Твоїм Трудився у Церкві живій,\nСлужив Тобі серцем усім завсіди, Спасителю мій\n\nКуплет 3\nРукою могутньою Сам, о, Боже, мене Ти веди, \nЩоб міг я в святі небеса дорогою правди іти.\nО, Боже, дай сили мені,\nЩоб хрест свій щоденний я ніс,\nНе впав у земній боротьбі і плід я для Тебе приніс!', '', '', '', '', 'ua', 0, NULL),
(141, 'Іди в виноградник робота там є', 0, 11, 'Куплет 1\nІди в виноградник, робота там є,\nДавно уже жде тебе діло святе.\nБагато всього там ще треба зробить,\nРобітників мало, щоб все закінчить:\nТам треба копать і полоть, прочищать,\nІ часто водою усе поливать;\nВід холоду, вітру і бур берегти \nІ часто від хижих вовків стерегти.\n\nПриспів:\n Іди (іди, іди), іди (іди, іди),\nіди в виноградник, робота там є.\nІди (іди), іди (іди, іди)!\nРобітників мало, а час нас не жде.\n\nКуплет 2\nІди в виноградник, іди вже скоріш!\nСтраждав Я за тебе, навіки ти Мій.\nВесь час твій, і розум, і сили твої,\nВіддай ти віднині для праці Мені.\nТебе дорогою ціною придбав, - \nУ муках тяжких Свою кров проливав.\nЯк тяжко було там страждати Мені;\nУмер Я, щоб дати спасіння тобі.\n\nКуплет 3\nІди в виноградник, ще поки є день;\nЧас тіні, час ночі вже скоро прийде:\nВже сонце на захід схилилось, біжить, - \nЯк зайде, не зможеш прийти і робить. \nПрацюй від зорі до зорі, і \nЯ Сам Навчать тебе буду і сили подам. \nБлажен, хто, почувши Мій голос, прийде \nУ Мій виноградник, де працю знайде.', '', '', '', '', 'ua', 0, NULL),
(142, 'За тебе Я вмирав і кров Свою пролив', 0, 11, 'Куплет 1\nЗа тебе Я вмирав і кров Свою пролив,\nСтражданням на хресті тебе Я відкупив.\nЖиття віддав тобі, а що Ти дав Мені? (2р.)\n\nКуплет 2\nЯ на землі прожив в скорботах та журбі,\nЩоб ти у небі жив, щоб щастя дать тобі.\nЯ радість дав тобі, а що ж ти дав Мені? (2р.)\n\nКуплет 3\nКоли Я умирав у муках на хресті,\nТобі життя Я дав, твої гріхи простив.\nСтраждав за тебе Я, подяка де ж твоя? (2р.)\n\nКуплет 4\nО, друже дорогий, Христу життя віддай:\nЛиш Він - Спаситель твій, Йому хвалу складай.\nНа землю Він прийшов, пролив за гріх твій кров. (2р.)', '', '', '', '', 'ua', 0, NULL),
(143, 'О скільки душ страждають без Бога в світі цім', 0, 11, 'Куплет 1\nО, скільки душ страждають без Бога в світі цім,\nУ темряві гріховній грозить загибель їм:\nБез Пастиря блукають на гибельнім путі,\nКуди ідуть, - не знають... Що жде їх впереді?\n\nПриспів: \nХодім же шукать заблудлих,\nДо Христа їх приведім.\nМожна буде і нам у той день сказать:\n«Я прийшов сюди з моїм».\n\nКуплет 2\nХто жертви не страшиться, на все готовий йти,\nЩоб тих овець заблудлих від гибелі спасти?\nХто показать піде їм путь правди, дім Отця.\nЛюбов’ю хто потішить розбиті їх серця?\n\nКуплет 3\nВелика радість буде при зустрічі Христа.\n«Наш добрий Пастир, - скажеш, овечка знайдена!\nВ гущавині блукала і змучилась в біді,\nЯ взяв її безсильну... Прошу, її прийми!»', '', '', '', '', 'ua', 0, NULL),
(144, 'До Христа мій друже йди з вірою скоріш', 0, 11, 'Куплет 1\nДо Христа, мій друже, йди з вірою скоріш,\nВін прийшов тебе спасти, дасть тобі спокій.\n\nПриспів: \nХай прославлять всі уста Господа Христа!\nВін за грішників страждав і їм вічність дав.\n\nКуплет 2\nВін престол Свій залишив в славних небесах,\nІ на землю Він прийшов, знищив смерті страх.\n\nКуплет 3\nДруже! Спас Себе віддав за твоє життя.\nНа хресті Він Сам сказав: «Завершилося!»\n\nКуплет 4\nНе вагайся, поспішай, скинь тягар душі,\nВсе життя Христу віддай і Йому служи!', '', '', '', '', 'ua', 0, NULL),
(145, 'Для світу спасіння', 0, 11, 'Куплет 1\nДля світу спасіння - Христова любов:\nЗа наші провини Ісус пролив кров;\nСпасіння звершив Він, дав радість, спокій,\nРадійте всі вірні, (Зр.) в любові святій!\n\nКуплет 2\nЯ вірю Ісусу, Він нас відкупив,\nЗ гріхів Він нас кров’ю Своєю обмив,\nВін світлом небесним серця освітив: \nСпасіння від Бога, (Зр.) і Господа сил.\n\nКуплет 3\nСин Божий розп’ятий вмирав на хресті, \nРозп’ятий для світу і я у Христі,\nІ світ цей для мене розп’ятий з гріхом.\nІ з Ним все живу я, (Зр.) з Ісусом Христом.\n\nКуплет 4\nГосподь дасть насліддя для вірних \nСвоїх, На небі оселить навіки святих.\nЗіллються там хори спасенних усіх: \n«Хвала, честь Ісусу, (Зр.) хай буде повік!»', '', '', '', '', 'ua', 0, NULL),
(146, 'Буду співати славу складати Тому', 0, 11, 'Куплет 1\nБуду співати, славу складати Тому, \nХто на хресті за нас вмирав.\nДивний Учитель - Христос Спаситель:\nВін нам спасіння всім дарував.\n\nКуплет 2\nСлавити вічно буду Христа:\nВ Ньому знайшов я світло й життя \nСили ворожі з Ним переможу \nВ земній тут боротьбі. (2р.)\n\nКуплет 3\nЯ на Ісуса завжди дивлюся,\nНим лиш одним на світі я живу.\nВін - мій Спаситель, Пастир, Учитель,\nДасть мені місце в небі, в раю.\n\nКуплет 4\nРадості в людях я не знайду \nІ від Ісуса куди піду?\nЗ Богом іду я і неземную \nРадість знайду в раю. (2р.)\n\nКуплет 5\nТут все минає, - там в Божім раю \nВтомленим душам дасть Господь спокій. \nКоли ввійду я в славу святую,\nТам мене прийме Спаситель мій.\n\nКуплет 6\nТам залунає пісня свята, -\nСлавити вірні будуть Христа.\nПісню спасіння, пісню хваління \nБуду співати й я. (2р.)', '', '', '', '', 'ua', 0, NULL),
(147, 'Пошли Господь сказати про Твою безмірну любов', 0, 11, 'Куплет 1\nПошли, Господь, сказати про Твою безмірну любов,\nЯк послав Ти Сина з неба, сказати знову і знов.\n\nПриспів: \nЗнову і знову скажи, (2р.)\nЧудову ту вість про Ісуса знову і знову скажи!\n\nКуплет 2\nПошли, Господь, сказати про Христову до всіх любов, \nЯк прийшов до нас Він з неба, сказати знову і знов.\n\nКуплет 3\nПошли, Господь, сказати про Христову пролиту кров. \nВін воскрес, вознісся в небо, сказати знову і знов.\n\nКуплет 4\nПошли, Господь, сказати, що Христос спасіння дає.\nХто Його благає щиро, радість життя пізнає.', '', '', '', '', 'ua', 0, NULL),
(148, 'Заспіваймо всі пісню що потішить нас', 0, 11, 'Куплет 1\nЗаспіваймо всі пісню, що потішить нас!\nСкоро ми підем у Вічний Дім;\nНіч гріха мине, і прийде спасіння час,\nСкоро ми підем у Вічний Дім.\n\nПриспів:\nСкоро ми підем, (2р.) перейдем через Йордан,\nІ ввійдемо в Край, в довгожданний Ханаан.\nСкоро ми підем у Вічний Дім.\n\nКуплет 2\nМи для Бога всі будем разом працювать,\nСкоро ми підем у Вічний Дім;\nА Христос на поміч Свою дасть благодать, \nСкоро ми підем у Вічний Дім.\n\nКуплет 3\nПокажімо всім правду в нашому житті,\nСкоро ми підем у Вічний Дім;\nА Христос спасіння Своє нам також дасть,\nСкоро ми підем у Вічний Дім.\n\nКуплет 4\nНі недуг, ні смерті нема в Краю святім,\nСкоро ми підем у Вічний Дім;\nМи знайдем спокій в місті вічнім, золотім,\nСкоро ми підем у Вічний Дім.', '', '', '', '', 'ua', 0, NULL),
(149, 'Кріпися ти безсильний', 0, 11, 'Куплет 1\nКріпися ти безсильний, поможе Бог тобі;\nЛиш будь Йому все вірний, Він поміч дасть в біді.\nГосподь розвіє хмари, і сонце засія...\nДуші спокій пошле Він і оживить тебе.\n\nПриспів: \nКріпись, кріпись, і сонце освітить тебе, \nКріпись, кріпись, і Господь оживить тебе.\n\nКуплет 2\nКріпись, християнине! Будь вірним до кінця;\nЯк трапиться нещастя - на поміч клич Христа. \nСкінчиться ця дорога, заплати день прийде:\nБо праця, що для Бога, марною не буде.\n\nКуплет 3\nКріпись, християнине, про Божу правду дбай!\nЗа Богом йди Єдиним, в душі Йому співай.\nІсус наш скоро прийде, і близько вже той час.\nЯка то радість буде, коли Він візьме нас!', '', '', '', '', 'ua', 0, NULL),
(150, 'Проміння радості з небес горять в моїй душі', 0, 11, 'Куплет 1\nПроміння радості з небес горять в моїй душі;\nЯсніше Він понад усе - то є Спаситель мій.\n\nПриспів: \nДивне сяйво,(2р.) як минають у спокою дні:\n Коли Ісус явля лице - дивне сяйво є в душі.\n\nКуплет 2\nЧудесний гімн в моїй душі звучить Царю царів:\nЦю пісню чує Він, хоч би співати я не міг!\n\nКуплет 3\nВесна царить в моїй душі, як близько є Христос;\nІ голуб миру для душі красу життя приніс.\n\nКуплет 4\nПроміння радості в душі, надії і любві.\nХвала Йому за всі дари, що Він дає мені!', '', '', '', '', 'ua', 0, NULL),
(151, 'О брате час вже пробудися', 0, 11, 'Куплет 1\nО, брате, час вже, - пробудися \nВід сну гріха і марноти.\nХристос зове тебе: Прокинься!\nТебе Він кличе у любві.\n\nПриспів: \nНе ухиляйсь, бо Він в любві зове тебе,\nА поспішай скоріш, скоріш до Нього йди.\n\nКуплет 2\nВін полюбив тебе, мій брате,\nЗа тебе Він на хрест пішов,\nЩоб за гріхи твої страждати,\nЩоб ти у Нім життя знайшов.\n\nКуплет 3\nІз ран Його свята кров ллялась,\nЛюбов’ю зір Його горів.\nО, брате мій, ми провинились, - \nНевинно Він за нас терпів.\n\nКуплет 4\nПречиста кров нас очищає,\nЗмиває з серця всякий гріх;\nВона і душу відновляє,\nСпокій дає для вірних всіх.', '', '', '', '', 'ua', 0, NULL),
(152, 'Я спасіння знайшов', 0, 11, 'Куплет 1\nЯ спасіння знайшов, як до Бога прийшов, - \nУсім серцем я вірю в Ісуса! Він спокій дав мені,\nІ тягар зняв з душі, - в Сина Божого вірую я.\n\nПриспів: \nВірю я, (2р.) усім серцем я вірю в Ісуса.\nВірю я, (2р.) в Сина Божого вірую я!\n\nКуплет 2\nВін мене відкупив, - вірою я прийняв,\nУсім серцем я вірю в Ісуса! У незмінній любві\n Він Хранитель душі,-в Сина Божого вірую я!\n\nКуплет 3\nЩо за радість тепер, Він зі мною є все,- \nУсім серцем я вірю в Ісуса! Хочу славити все,\nБо Він спас і мене, - в Сина Божого вірую я!', '', '', '', '', 'ua', 4, NULL),
(153, 'Кращі літа молодії', 0, 11, 'Куплет 1\nКращі літа молодії, - свіжії сили в ці дні весни, - \nМи присвятім їх Ісусу в дар для Нього дорогий.\nЩо може бути ще краще нам, як Ісусу служить?\nТут, у житті цім дочаснім, серце Христу присвятім.\n\nКуплет 2\nВчуй, як Христос закликає, час благодатний для нас настав; \nБільше вагатись не можем: Спас нам життя дарував. Сестри!\n Ми прапор підіймем з Іменем чудним Христа.\n Промінь небесний зогріє віру й любов у серцях.\n\nКуплет 3\nСміло, во Ім’я Ісуса, браття, вперед в боротьбі з гріхом! \nТисячі гинуть в темряві. З світлом до них ми підем.\nХоч нас зустрінуть гоніння, смерть за Христа не страшна;\nЗ вірою все переможем для слави Спаса Христа.', '', '', '', '', 'ua', 0, NULL),
(154, 'Вже Сонце засіяло і правди', 0, 11, 'Куплет 1\nВже Сонце засіяло і правди, і добра,\nПуть Божий освітило, вставати пора!\nПогляньте! Божа нива жовтіє навкруги;\nМи чуєм голос Божий, -- час до праці йти.\n\nКуплет 2\nНе втомлюйтесь душею на ниві трудовій, \nПрацюйте всі для Нього у любві святій.\nЯк вже жнива скінчаться - Пройдем ми шлях земний,\nБудем відпочивати в країні святій.\n\nКуплет 3\nОб’єднуйтеся, браття і сестри, всі гуртом \nВ союзі благодаті у святім труді.\nХоч хмари насувають, хоч не вгаває зло,\nАле всі вірні знають, що Сонце зійшло!', '', '', '', '', 'ua', 0, NULL),
(155, 'Господь мені спасіння дав', 0, 11, 'Куплет 1\nГосподь мені спасіння дав | в крові святій, (2р.)\nЛюбов Ісуса я пізнав в крові Його святій.!\n\nПриспів: \nКров’ю святою, Спасе мій,\nДушу мою обмий ізнов!\nО, Спаситель, Пастир мій,\nТи Сам пролив за мене кров!\n\nКуплет 2\nЄдиний захист маю я | в крові святій, (2р.)\nЗнаходжу я спокій, життя в крові Його, святій.\n\nКуплет 3\nЄ сила для відродження | в крові святій. (2р.)\nМоїх гріхів всіх прощення в крові Його святій.\n\nКуплет 4\nГосподь оздоровив мене І в крові святій, (2р.)\nІ серце обновив моє в крові Своїй святій.', '', '', '', '', 'ua', 0, NULL),
(156, 'О наш Отець на небесах', 0, 11, 'Куплет 1\nО, наш Отець на небесах,\nПочуй моління Ти моє!\nХай у житті, в благих ділах святиться Ім’я ввік Твоє.\n\nКуплет 2\nТи Всевідучий, Господь сил, \nтремтить перед Тобою все. \nСоздателю усіх світил,\nХай прийде царство вже Твоє!\n\nКуплет 3\nО, Боже, як премудрий Ти!\nІ ціль життя мого одна:\nВ часи безрадні і тяжкі,\n хай буде воля ввік Твоя.\n\nКуплет 4\nТи Цар і Бог наш Всеблагий, \nжиття даєш усім єствам, \nТебе благаєм, Всесвятий: \nдай хліб щоденний нині нам!\n\nКуплет 5\nТи Милосердний, Боже наш,\nПрости провини наші нам,\nЯк ми прощаєм в кожний час \nзлі вчинки нашим ворогам!\n\nКуплет 5\nХто без Тебе спастися б міг?\nВід всіх спокус нас захисти. \nНас немічних, дітей Твоїх, від злого духа хорони.\n\nКуплет 6\nПремудрі всі Твої діла,\nТвоє і царство, Боже сил,\nТобі і слава, і хвала повіки вічнії. Амінь.', '', '', '', '', 'ua', 3, NULL),
(157, 'Я подорожній тут на землі', 0, 11, 'Куплет 1\nЯ подорожній тут на землі:\nТут я скитаюсь на чужині.\n\nПриспів: \nТам в небі дім мого Отця, \nТуди стремиться моя душа.\n\nКуплет 2\nЯ переходжу цю чужину,\nВертаю в рідну я Вітчизну.\n\nКуплет 3\nТяжко і тісно, смутно мені,\nЯк то звичайно на чужині.\n\nКуплет 4\nХочу як швидше тут перейти,\nМоє скитания закінчити.\n\nКуплет 5\nКоли земне життя я скінчу,\nТоді навіки в домі спічну.\n\nКуплет 6\nВведе у дім Свій мене Отець,\nТоді стражданням прийде кінець.', '', '', '', '', 'ua', 0, NULL),
(158, 'Ідуть подорожні додому ідуть', 0, 11, 'Куплет 1\nІдуть подорожні, додому ідуть,\nВ Край Вічний, де радість, спокій.\nНі горя, ні сліз вони там не знайдуть:\n їх прийме Христос дорогий.\n\nПриспів: \nТам нема (там нема) вже зла (нема зла),\n Темрява (темрява) пройшла,\n(вже пройшла),\nСонце Правди там вічно сія. (2р.)\n\nКуплет 2\nНемає там смерті, немає страждань,\nТам кривди і гніву нема,\nНі голосу злого, ні грішних бажань...\nТам світло Господнє сія.\n\nКуплет 3\nІдуть подорожні... вже близько той Край,\nДе праведні душі усі;\nТуди їх Спаситель зібрав в дивний рай,\nДе сяє все в Божій красі.', '', '', '', '', 'ua', 0, NULL),
(159, 'Неділя день спочинку', 0, 11, 'Куплет 1\nНеділя - день спочинку, день світла і тиші,\nДень молитов, розваги, день скріплення душі.\nВ неділю ми в родину збираємось в одну,\nСпіваємо Творцеві псалми, хвалу святу.\n\nКуплет 2\nВ день перший у неділю Бог світло сотворив,\nВ неділю Спас від гробу печаті відломив.\nАпостолам в неділю Бог Духа з неба дав, \nВідвагу в них збудивши, на проповідь послав.\n\nКуплет 3\nВ неділю, день Господній, зміцниться в нас душа,\nЩоб краще ми сповняли побожнії діла.\nХвала Отцеві в небі і Синові Його,\nІ Духові Святому за радість дня цього!', '', '', '', '', 'ua', 0, NULL),
(160, 'Страшно бушує життєвеє море', 0, 11, 'Куплет 1\nСтрашно бушує життєвеє море,\nХвилі мій човен гойдають і б’ють.\nВ смертній тривозі, в великому горі,\nБоже, молюся, - не дай потонуть!\n\nКуплет 2\nЗглянься на мене, спаси і помилуй, - \nЗ днів моїх ранніх зі злом я борюсь,\nБільше боротись не маю вже сили...\nБоже, помилуй! - благаю, молюсь.\n\nКуплет 3\nНе залишай мій човен в хвилях моря,\nБоже мій милий, о Боже Благий!\nБлизько вже берег небесний, - і скоро \nТам лиш знайду для душі я спокій!', '', '', '', '', 'ua', 0, NULL),
(161, 'Хвала що час вже той минув', 0, 11, 'Куплет 1\nХвала, що час вже той минув,\nКоли у темряві гріха тонув. \nСпокою в світі цім я не знайшов, - \nГосподь мій спас мене, до Нього я прийшов.\n\nПриспів: \n3 Христом я буду в небесах\nЗ вітками дивних пальм в руках,\nЗ золотим на голові вінцем,\nСпівати буду там: Спасен Христом!\n\nКуплет 2\nСумніви й страх Спаситель віддалив,\nВін силу смерті смертю переміг.\nВ святій крові мене Він обілив,\nМене в гріхах погибшого Він полюбив.\n\nКуплет 3\nХвала Спасителю! Тепер Він мій:\nВін збудував у серці храм святий;\nЯ не страшусь: Господь мене хранить,\nВід зла Христос мене спасе і захистить.\n\nКуплет 4\nТепер завсіди я уже Його,\nВін - щит мій, і Він захист від всього;\nСпаситель мій, і скеля Він моя.\nЙому від всіх хай буде слава і хвала!', '', '', '', '', 'ua', 0, NULL),
(162, 'Брате знову нагадай про святу любов', 0, 11, 'Куплет 1\nБрате, знову нагадай про святу любов,\nПро Ісусові слова розкажи нам знов.\nСпів любові ллється, дух до неба рветься.\n\nПриспів: \nСлавте Христа, (2р.)\nСлавте любов Христа!\n\nКуплет 2\nЛюдям всім Христос приніс із небес Любов;\nУтіша в годину сліз нас Його любов.\nНас Христос навчає, - грішних Бог прощає.\n\nКуплет 3\nБрате, знову нагадай про святу любов; \nЗникне з серця сум, одчай, буде радість знов. \nКличе спів любові на дорогу нову.', '', '', '', '', 'ua', 0, NULL),
(163, 'Уже Йорданські береги здалека бачу', 0, 11, 'Куплет 1\nУже Йорданські береги здалека бачу я;\nТам рідний край мій дорогий, Вітчизна там моя.\n\nПриспів:\nДо пристані ми пливем, де бур нема, ні хвиль.\nЩезає мла, світліють дні, човен пливе вперед.\n\nКуплет 2\nО, берег дивний, берег мій, до тебе я пливу;\nВвійду у Край я рідний свій і там спокій знайду.\n\nКуплет 3\nІ скоро, скоро буду там, де зла немає вже,\nДе всім спасенним сльози Сам Спаситель наш утре.\n\nКуплет 4\nЧудова пристань жде мене, Святий Єрусалим;\nЗ Христом човен мій все пливе, там вічно буду з Ним.\n\nКуплет 5\nХвороби там не буде вже, ні смерті, ні плачу;\nЗемне страждання промине, коли туди ввійду.\n\nКуплет 5\nНавіки буду царювать і славити Христа,\nХристос дасть право споживать плід дерева життя.', '', '', '', '', 'ua', 0, NULL),
(164, 'Усі що у Христа хрестилися', 0, 11, 'Куплет 1\nУсі, що у Христа хрестилися,\nУ Христа зодягнулися.\n\nПриспів: \nАлілуя!', '', '', '', '', 'ua', 0, NULL),
(165, 'Із ран Спасителя текла струмком пречиста кров', 0, 11, 'Куплет 1\nІз ран Спасителя текла струмком пречиста кров, - \nПрощення всім вона дала, до Нього хто прийшов.\n\nКуплет 2\nКоли розбійник на хресті розп’ятий умирав, - \nТо від Христа, в крові святій спасіння одержав.\n\nКуплет 3 \nБез Господа і я блукав, і гинув в марноті, - \nМені Христос спасіння дав в Своїй крові святій.\n\nКуплет 4\nСтрумок предивний я знайшов в божественній крові. \nПізнав Його святу любов і став щасливий в Нім.\n\nКуплет 5\nКоли ж я, немічний, колись в моїм житті згрішу,\nВ Крові Спасителя Христа прощення я знайду.', '', '', '', '', 'ua', 0, NULL),
(166, 'Господь коли ученикам про смерть Свою відкрив', 0, 11, 'Куплет 1\nГосподь, коли ученикам про смерть Свою відкрив, \nТоді ласкаво, як друззям,- взяв хліб, благословив.\n\nКуплет 2\nІ, розламавши, їм подав й слова до них сказав: \n«Прийміте ви і їжте всі; це - тіло є Моє!»\n\nКуплет 3\nЗ вином також Він чашу взяв, благословив її:\n«Оце є кров Моя, - сказав, — із неї пийте всі!»\n\nКуплет 4\nНовий Мій Заповіт в крові Я вам усім даю:\nОце робіть завсіди ви, - смерть згадуйте Мою!»\n\nКуплет 5\nО, Господи, дозволь же й нам Твою пречисту кров, \nПролиту на хресті, згадать - Твою прийнять любов.', '', '', '', '', 'ua', 0, NULL),
(167, 'Я є вівця Ісуса', 0, 11, 'Куплет 1\nЯ є вівця Ісуса, - Він Пастир добрий мій;\nНим всюди я хвалюся: Він дав душі спокій.\nСебе віддав на муки, за мене постраждав,\nВід смерті, від розпуки мене урятував.\n\nКуплет 2 \nЯ є вівця Ісуса, - Він Пастир добрий мій; \nКоли прийде спокуса, знаходжу захист в Нім. \nПречистою Він кров’ю мої гріхи обмив, \nНебесною любов’ю мене Він оживив.\n\nКуплет 3\nЯ є вівця Ісуса, - Він Пастир добрий мій;\nВін, в знак любві союзу, на вечері святій\nВзяв хліб, благословивши, апостолам роздав,\nПро смерть Свою відкривши, з вином їм чашу дав.\n\nКуплет 4\nЯ є вівця Ісуса, - Він Пастир добрий мій,\nЙому я віддаюся, — Він є Спаситель мій...\nВін душу наповняє любві вином святим,\nХліб з неба посилає, і я кріплюся Ним.', '', '', '', '', 'ua', 0, NULL),
(168, 'Вже чую я шум', 0, 11, 'Куплет 1\nВже чую я шум, наче шум той води,\nІ стогін людей від безсилля...\nГотуйся, Невісто! Жених твій іде!\nВже скоро вечеря весільна.\n\nПриспів: \nПрийди, о Спасителю мій дорогий:\nЯ можу вже бути з Тобою!\nМене обілив Ти у крові святій,\nКупив дорогою ціною.\n\nКуплет 2\nЗабудь про усе, чим світ вабив тебе,\nМарні залиши вже бажання;\nЗгадай, як Збавитель твій любить тебе;\nЗа тебе терпів Він страждання.\n\nКуплет 3\nЛюби, як Спаситель тебе полюбив,\nРадій же та будь Йому вірна!\nЗгадай, як Господь твій тобі все простив,\nІди за Ісусом покірно!\n\nКуплет 4\nО, вір, що навік Він тебе полюбив,\nО, вір, що Він любить незмінно,\nЩо вище і глибше всіх гір і морів \nЛюбов Його вічна, безмірна!', '', '', '', '', 'ua', 0, NULL),
(169, 'Христос Господь у Галилеї', 0, 11, 'Куплет 1\nХристос Господь у Галилеї \nНа шлюб у Кану приходив,\nСвятою силою Своєю \nТам перше чудо Він звершив.\n\nПриспів:\nО, Господи, (Господи) до нас прийди (Ти прийди)\nI славу Свою яви,\nО, Г осподи, (Г осподи) до нас прийди (Ти прийди)\nІ нас благослови!\n\nКуплет 2\nПрийди до нас, як Гість небесний,\nІ Сам цей шлюб благослови,- \nСкріпи союз у славі й честі,\nЩоб жили в вірності й любві!\n\nКуплет 3\nСоюз подружжя закріпляєш...\nВ живій Ти Церкві, як Жених;\nНа шлюбі вірних Ти буваєш \nПоміж відкуплених Твоїх.\n\nКуплет 4\nТи всіх зовеш на свято славне...\nБлагаєм ми, щоб і вони \nЖили для Тебе свято, вірно \nВ Твоїй любові по всі дні.\n\nКуплет 5\nІ Ти невісту вибираєш\nЗ людей відкуплених Своїх,\nЛюбов Свою їй відкриваєш,\nНевісті-Церкві, як Жених.\n\nКуплет 6\nНемає щастя на цім світі \nБез Твого світлого лиця;\nО, поможи їм - Твоїм дітям \nПрожити вірно до кінця!', '', '', '', '', 'ua', 0, NULL),
(170, 'Христа хай величають всі', 0, 11, 'Куплет 1\nХриста хай величають всі, | і ангели в красі (2р.) \nХвалу Йому хай принесуть.\n\nПриспів: \nПрославте (4р.),\nПрославте Бога сил!\n\nКуплет 2\nІ ви, страдальці за Христа, звіщайте всім життя, (2р.) \nЦаря царів прославте всі!\n\nКуплет 3\nТи, Богом вибраний народ, | стомився від скорбот, (2р.) \nПрослав, і Він тебе спасе!\n\nКуплет 4\nНароди, люди, племена, | всі, як сім’я одна, (2р.) \nХриста хай славлять за любов!', '', '', '', '', 'ua', 0, NULL),
(171, 'Дай Боже їм щастя', 0, 11, 'Куплет 1\nДай, Боже, їм щастя, у всім помагай,\nВід бур, від нещастя, від зла захищай. (2р.)\n\nКуплет 2\nВ житті хай з Тобою вони проживуть.\nІ світло любові всім ближнім несуть. (2р.)\n\nКуплет 3\nХай міцно з’єднає їх щира любов,\nВ час горя втішає серця знов і знов. (2р.)\n\nКуплет 4\nДай, Боже, їм мудрість, щоб вірні були,\nДаруй Твою тихість, щоб свято жили. (2р.)\n\nКуплет 5\nДай їм пізнавати, що з ними Твій Дух,\nПовік пам’ятати, що Ти — вірний Друг! (2р.)', '', '', '', '', 'ua', 0, NULL),
(172, 'Дві руки в цей час з’єднались', 0, 11, 'Куплет 1\nДві руки в цей час з’єднались для життя, надій і втіх.\nБоже вічний, Боже милий, Сам благослови Ти їх!\nДвоє уст тепер сказали перед Богом «Так» святе, \nЖити вірно обіцяли на усе життя своє.\n\nКуплет 2\nДві душі віднині стали у любові разом жить.\nЩоб і щастя, горе, й жалі поміж себе все ділить.\nБоже наш, Тебе благаєм: дай щасливе їм життя, - \nТвоя воля хай з’єднає їх на многії літа!\n\nКуплет 3\nПідкріпляй їх, Боже милий, в горю їх не залишай,\nІ Святого Духа силу завжди Ти їм посилай.\nХай вони уже віднині в згоді, в радості живуть,\nБоже, у земній долині Сам Заступником їм будь!', '', '', '', '', 'ua', 0, NULL),
(173, 'Де Божий Дух в серцях', 0, 11, 'Куплет 1\nДе Божий Дух в серцях живе, там радість, щастя, мир, \nЛюбов там близьких обійме, -примирить ворогів.\n\nПриспів: \nТвою любов, Господь, пошли,\nЛюбов’ю всіх нас освіти,\nНавчи любить Ім’я Твоє \nІ прославляти лиш Тебе.\n\nКуплет 2\nДе Божа лиш любов горить, там єдність, там спокій,\nТам вірних Бог не залишить, - Він Пастир дорогий;\n\nКуплет 3\nДе всі живуть в любві святій - в громаді чи в рідні, \nЇх супроводить Бог живий, щасливі там усі.', '', '', '', '', 'ua', 0, NULL),
(174, 'Даруй Боже святість', 0, 11, 'Куплет 1\nДаруй, Боже, святість, пошли тихість, страх,\nДля всього дай мудрість, будь в наших серцях. \nПобільшуй в нас віру, чуття обнови, \nІзлий любов щиру, сумнів віддали!\n\nКуплет 2\nНавчи бути вдячним за милість Твою,\nСтремлінням сердечним дай силу Свою.\nВ хвилину страждання дай сльози мені,\nЩоб щирі благання приносив Тобі!\n\nКуплет 3\nДай чисте лиш серце, духовно зрости,\nІ світлом небесним мій дух освіти.\nНавчи приклад брати в житті від Тебе,\nНавчи прославляти ім’я лиш Твоє!', '', '', '', '', 'ua', 0, NULL),
(175, 'Ти думками йдеш до неба', 0, 11, 'Куплет 1\nТи думками йдеш до неба... Що ж про діток ти забув?\nВони ж прагнуть життя-хліба; ти у Слові теє чув. Приспів:\n\nКуплет 2\nО, батьки! Ви своїх діток, тих, що Бог вам дарував,\nПриведіте до Ісуса, бо й за них Він постраждав.\n\nКуплет 3\nТи сидиш в Господнім Домі, веселишся у Христі,- \nДітки ж бідні у Содомі... Чи байдуже це тобі?\n\nКуплет 4\nЧом не видно їх з тобою? На кого їх залишив?\nСпас ласкавою рукою тут би їх благословив.\n\nКуплет 4\nЇм ласкавий Відкупитель Царство Боже обіцяв. \nПриведи ж їх до Ісуса, щоб Він світлом осіяв!', '', '', '', '', 'ua', 0, NULL),
(176, 'Закликає Спас діток', 0, 11, 'Куплет 1\nЗакликає Спас діток, кличе їх до Себе всіх;\nВін збирає їх в гурток, любить Він, хоронить їх.\n\nПриспів:\nКличе всіх Ісус діток, кличе Він, кличе Він.\nВ вічний райський Свій садок, де немає перемін.\n\nКуплет 2\nМолоді серця свої зберігайте в чистоті,\nНепорочні хай уста прославляють лиш Христа.\n\nКуплет 3\nДітки, всі до одного вчуйте заклик ви Його - \nТож Спаситель кличе вас. Поспішайте в той же час.', '', '', '', '', 'ua', 0, NULL),
(177, 'Слава На Сіонгорі', 0, 11, 'Куплет 1\n«Слава!» - На Сіон-горі дітки кликали тоді,\nЯк в’їздив у місто Спас; тож і нині кликнім враз:\n\nПриспів: \nВикликуйте: Благословен Спас!\nКличте всі, хай кожний чує вас:\nСлава в вишніх! (Зр.) - Спас іде!\n\nКуплет 2\nСлів Христових вчили нас; Духа втіхи дав нам Спас.\nМи до неба маєм шлях. Спас живе у нас в серцях.\n\nКуплет 3\nСтарші і молодші - всі, заспіваймо враз пісні,''\nХай наш спів до хмар злетить, в небесах загомонить.', '', '', '', '', 'ua', 0, NULL),
(178, 'Малих Бог любить пташечок', 0, 11, 'Куплет 1\nМалих Бог любить пташечок і їжу їм дає...\nПро всі істоти дбає Бог, - Він любить і мене.\n\nПриспів: \nТак, любить Бог, так, любить Бог,\nЯ знаю, - любить Він;\nДіток маленьких любить Бог,\nВін любить і мене.\n\nКуплет 2\nБог любить лілеї в полях, де річенька тече;\nКоли Він любить квіточки, - Він любить і мене.\n\nКуплет 3\nГосподь пташкам і квіточкам життя й красу дає, \nВін дбає про малих дітей, Він любить і мене.', '', '', '', '', 'ua', 0, NULL),
(179, 'Книгу Божу маю я', 0, 11, 'Куплет 1\nКнигу Божу маю я, хоч поношена вона...\nДні пригадую давно минулії;\nМоя мама там знайшла дар спасіння у Христа.\nНе забуду я щасливих тих хвилин!\n\nПриспів: \nО, чудова, найдорожча Книга Божа!\nЯ люблю, люблю тебе: Ти зблудити не даєш, \nВ Царство Боже нас ведеш,\nВ Край, куди прийме Господь вас і мене!\n\nКуплет 2\nПам’ятаю: про Христа все читала мама там,\nЯк любив, страждав, вмирав Він на хресті.\nЯ уважно слухав все..."Пам’ятай, то за тебе,-\nГоворила мама: — Ти Його люби!"\n\nКуплет3\nТе давно-давно я чув, але слів тих не забув.\nІ мені та Книга світлом є в житті.\nЯ слова Христа люблю, все вперед за Ним іду, \nЩоб до щастя вічного життя дійти.', '', '', '', '', 'ua', 0, NULL),
(180, 'О дітки ідіте', 0, 11, 'Куплет 1\nО, дітки, ідіте, ідіть же скоріш,\nДо Спаса усі поспішайте мерщій:\nЗоря освітила ніч темну з небес, \nДала знак про дивнеє чудо з небес!\n\nКуплет 2\nПогляньте, як в яслах Спаситель лежить:\nНебесна в Нім святість, мов світло горить.\nНебесне Дитятко — краса на весь світ,\nЙому хори ангельські шлють всі привіт.\n\nКуплет 3\nО, дітки, для вас Він у яслах лежить;\nМарія і Иосиф Ісуса глядять...\nПочувши від ангелів вістку святу,\nПрийшли пастухи поклонитись Христу.', '', '', '', '', 'ua', 0, NULL),
(181, 'Прийде знову', 0, 11, 'Куплет 1\nПрийде знову, прийде знову, на землю Спаситель, - \nЗбере перли найдорожчі - маленьких діток.\n\nПриспів: \nНіби ясні ті зірки, що вночі в небі сяють,\nТак і дітки засяють в Царстві Христовім.\n\nКуплет 2\nЇх Спаситель позбирає у Край Свій небесний,\nВід землі візьме Він діток всіх любих Своїх.\n\nКуплет 3\nХто із діток щирим серцем Спасителя любить,\nТі, як перли-самоцвіти, засяють у небі.', '', '', '', '', 'ua', 0, NULL),
(182, 'При Божім троні', 0, 11, 'Куплет 1\nПри Божім троні в небесах зібрались діточки;.\nСпівають радісні пісні, ясніють, як зірки.\n\nПриспів: \nІ там (і там, і там) (2р.)\nРадіють у Христі;\nІ там (і там, і там) (2р.)\nСпівають Йому всі \n(Слава Господу повік, повік).\n\nКуплет 2\nТа хто ж у небо їх привів - в світ Божої любві?\nІ як туди, де вічний мир, вони, малі, ввійшли?\n\nКуплет 3\nЗа них Спаситель кров пролив, щоб змити всякий гріх,\nЩоб і вони у небесах зазнали райських втіх,\n\nКуплет 4\nІ Божу ласку всі вони прийняли на землі,\nТому тепер лице Христа так близько бачать всі.', '', '', '', '', 'ua', 0, NULL),
(183, 'Дітки на діло', 30, 11, 'Куплет 1\nДітки! На діло ревно і сміло \nВсі, як один, поспішім,\nПро відкуплення, вічне спасіння \nЛюдям усім розкажім. (2р.)\n\nПриспів:\nБудем трудитись, будем молитись,\nБога усі прославлять.\nЗа кров невинну будем постійно \nХриста усі величать. (2р.)', '', '', '', '', 'ua', 0, NULL),
(184, 'Стою біля Йордана', 0, 11, 'Куплет 1\nСтою біля Йордана я і бачу впереді \nОбітований вічний Край, де думи всі мої.\n\nПриспів: \nТам спочнем, друззя, навік \nЗ Христом (близький час)\nВ світлі берега, де всі святі (всі святі),\nЗ ними пісню заспіваєм ми, (близький час) \nІз Ісусом вічно будем ми.\n\nКуплет 2\nВ небеснім тім Краю горить яскраве світло дня:\nТам Божий Син в любві царить, у славі все сія.\n\nКуплет 3\nКоли ж і я ввійду в той Край, де радість і спокій,\nДе вічне щастя, Божий рай, де Відкупитель мій?\n\nКуплет 4\nХоч грізні хвилі навкруги, я все ж туди пливу,\nДе вічні Божі береги, - я там спокій знайду.', '', '', '', '', 'ua', 0, NULL),
(185, 'За днями линуть дні', 0, 11, 'Куплет 1\nЗа днями линуть дні, все ближче Край!\nІ думка все моя - все ближче Край!\nВже скоро буду я у рідній стороні.\nВсе ближче рідний Край, все ближче Край!\n\nКуплет 2\nМинають мої дні, - все ближче Край!\nДо Господа я йду, - все ближче Край!\nТам чуть святих пісні, і я туди прийду. \nВсе ближче рідний Край, все ближче Край!\n\nКуплет 3\nСкінчу я шлях земний, - все ближче Край!\nІ горе все скінчу, - все ближче Край!\nВід суму і плачу піду я в край Святий; \nВсе ближче рідний Край, все ближче Край!', '', '', '', '', 'ua', 0, NULL),
(186, 'І буде Божі діти встануть', 0, 11, 'Куплет 1\nІ буде: Божі діти встануть,\nУсі зберуться до Христа,- \nВ нетлінній славі засіяють,\nПоллється пісня їх свята,\n\nКуплет 2\nСтарі, і молоді, і діти, \nЗодягнені усі в виссон,\nТам будуть Бога прославляти,\nКоли зберуться на Сіон.\n\nКуплет 3\nГосподь: усіх ласкаво прийме \nСвоїх улюблених дітей,\nНеславу від людей з них здійме \nІ сльози обітре з очей.\n\nКуплет 4\nТам вже ніхто ні мук, ні болю \nНе нанесе ніколи їм,\nІ хто томився тут в неволі,\nВвійде в небесний супокій.\n\nКуплет 5\nНе буде й тіні там страждання,\nІ смерть повіки не прийде, \nІ світло Божого проміння \nНе потемніє, не зайде.\n\nКуплет 6\nВони, як зорі, засіяють \nВ небесній славі і красі;\nБлаженства вічного дізнають \nВ Христовім Царстві вірні всі.', '', '', '', '', 'ua', 0, NULL),
(187, 'Ми знаєм про Край', 0, 11, 'Куплет 1\nМи знаєм про Край, де царює Спаситель,\nІ місто збудоване Богом для нас;\nХристос приготовив для нас там оселі,\nТам щастям наділить відкуплених Спас.\n\nПриспів: \nРайське нам щастя,\n(Райське нам щастя Голгофа дає),\nРайську нам радість \n(Райська нам радість з Голгофи тече), \nКров’ю святою Спаситель придбав. \n(Куплені кров’ю ми Агнця, \nприносим Христові подяку за все).\nАлілуя! Божий Син відкрив двері раю. \nСлава Христу, (слава навіки Ісусу Христу!), \nВін від смерті нас спас.\n\nКуплет 2\nАпостоли, вірні й святії пророки,\nУсі там спасенні з Ним вічно живуть;\nІ ми перейдемо у край той навіки,\nДе душі в спокою і сліз вже не ллють;\n\nКуплет 3\nТут в світі панують лукаві бажання,\nА наша душа прагне щастя й життя.\nО, браття і сестри, вперед без вагання! \nГотуймось у вічнеє, Царство Христа!', '', '', '', '', 'ua', 0, NULL),
(188, 'Де будеш в вічності', 0, 11, 'Куплет 1\nДе будеш в вічності ти жить?\nПодумав ти про це чи ні? \nПитання це для нас усіх:\nДе будеш в вічності ти жить?\n\nПриспів: \nО, вічність, вічність без кінця ! \nДе будеш в вічності ти жить?\n\nКуплет 2\nВже многі до Христа прийшли,\nГріху покинули служить;\nЖиття і щастя в Нім знайшли...\nДе будеш в вічності ти жить?\n\nКуплет 3\nЯке життя ти тут ведеш?\nТи ж можеш Богові служить! \nЯкий кінець тебе там жде, - \nДе будеш в вічності ти жить?\n\nКуплет 4\nО, друже мій, у той же час \nХристу віддайсь: тебе Він спас, - \nІ поспішай усім звістить:\n«З Ним буду в вічності я жить!»', '', '', '', '', 'ua', 0, NULL),
(189, 'Радісно радісно', 0, 11, 'Куплет 1\nРадісно, радісно в путь я іду,\nДе відпочинок навіки знайду;\nПуть той Спаситель відкрив Сам мені,\nМій відпочинок в Ісусі Христі.\nСкоро проходять земні мої дні...\nПрацю закінчу, піду я туди, \nДе вже не буде ні смерті, ні сліз:\nСмерть наш Спаситель уже переміг.\n\nКуплет 2\nВ вічних оселях, в святих небесах \nВсі ми прославим Ісуса Христа;\nСпів наш поллється з цілої душі...\nБрате наш любий, і ти поспіши!\nСпіви солодкі там дивно звучать,\nХвилями радості в серце пливуть.\nЗвуки небесні наповнюють рай,\nКличуть ласкаво в небесний той Край, -\n\nКуплет 3\nВ край, де повіки з Христом будеш жить,\nВічно за жертву спасіння хвалить!\nТам ми забудем турботи земні,\nБудемо жити в Христовій любві.\nВічності ранок там ясно зійде,\nСмерті не буде, і горе пройде.\nБогові буду співати хвалу .\nРадісно в вічнім небеснім Краю.', '', '', '', '', 'ua', 0, NULL),
(190, 'Чи зустрінемось з тобою', 0, 11, 'Куплет 1\nЧи зустрінемось з тобою, де святі усі живуть,\nДе спокійною рікою води чистії течуть?\n\nПриспів:\nТак, зустрінемось з тобою\nНад світлою, чудовою рікою,\nТам усі з достойною хвалою \nМи Ісусові будем служить.\n\nКуплет 2\nПоміж нами і рікою смертна пропасть ще була, - \nБожий Син ціною крові путь спасіння нам проклав.\n\nКуплет 3\nТам над світлою рікою ми Христа побачим всі, - \nЗалунає спів хвалою в вічній радості-красі.\n\nКуплет 4\nТам зусрінемось з тобою, де спокій і благодать,\nТам ми будем над рікою вічно Бога прославлять.', '', '', '', '', 'ua', 0, NULL),
(191, 'Несем ми тіло на спокій', 0, 11, 'Куплет 1\nНесем ми тіло на спокій,\nСхоронимо його в землі;\nБог всіх на смерть приговорив,\nУ гріх упавших осудив...\n\nКуплет 2\nО, браття й сестри, всі туди \nВ свій час ми маєм відійти;\nТурботам всім прийде кінець,\nПокличе в вічність нас Творець...\n\nКуплет 3\nЯк скоро день за днем летить!..\nЖиття, мов хвиля, пробіжить, - \nЧи близько, чи далеко час...\nЩо в вічності чекає нас?\n\nКуплет 4\nБог відграничив тут наш вік,\nДе смертний кожен чоловік...\nХристос смерть смертю подолав,\nЖиття нам вічне дарував.', '', '', '', '', 'ua', 0, NULL),
(192, 'Повний благості', 0, 11, 'Приспів: \nПовний благості, повний радості \nНам день Христового Різдва.\n\nКуплет 1\nСвіт в гріхах томився, Спас нам народився, \nЗадля нас зійшов, - Йому хвала!\n\nКуплет 2\nАнгели злетіли, співами звістили:\nСлава в небі, спокій між людьми!\n\nКуплет 3\nНам родивсь Спаситель,- Вічний Примиритель. \nРадуйтеся, славте всі Христа!', '', '', '', '', 'ua', 0, NULL),
(193, 'Вістку ангельську прийми', 0, 11, 'Куплет 1\nЗвістку ангельську прийми: народився Цар землі!\nЗ неба Він до нас зійшов,\nЩоб ти в Нім спокій знайшов.\nВсі народи, пробудіться!\nВже пора всім примириться!\nПрославляйте всі Отця, - неба і землі Творця!\n\nПриспів: \nВістку ангельську прийми!\nНародився Цар землі.\n\nКуплет 2\nПрославляймо всі Його:\nЦар Христос - Предвічний Бог.\nВін від Діви народивсь,\nДо нас грішних Спас явивсь.\nБожий Син став Чоловіком,\nЯк призначено від віку:\nСин Творця небесних сил, Спас Ісус Еммануїл!\n\nКуплет 3\nВірні шлють Христу привіт:\nВ тілі Бог прийшов на світ;\nСвітло Правди Він відкрив,\nНарід з Богом примирив;\nЗалишив небесну славу,\nСмерті переміг державу, - \nНародивсь, щоб нас піднять,\nЗвиш народження нам дать.', '', '', '', '', 'ua', 0, NULL),
(194, 'Ось Спаситель на землю зійшов', 0, 11, 'Куплет 1\nОсь, Спаситель на землю зійшов,\nНаше тіло на Себе прийняв.\nЗа оселю Він ясла обрав:\nЛюдиною в цей світ прийшов.\n\nПриспів: \nСлава! (слава) Христу! (слава),\nСлава (Зр.) Христу! (славу,\nМир і радість нам всім Він приніс). (2р.)\n\nКуплет 2\nСам Син Божий на землю прийшов,\nНе в пошані, не в царськім вінці,\nНе в палацах, не в пишнім вбранні, - \nВ бідних яслах Він місце знайшов.\n\nКуплет 3\nЦар Небесний до нас Сам прийшов,\nЩоб з Творцем нас, людей, примирить;\nЗ нами хоче повіки Він жить,\nОб’явивши небесну любов.', '', '', '', '', 'ua', 0, NULL),
(195, 'Нині всі вірні Христа прославляють', 0, 11, 'Куплет 1\nНині всі вірні Христа прославляють.\nСили небесні Ісуса вітають:\n«Спас народився! - звіщають в хвалі,\nСлава Богу в небі, мир на землі!»\n\nПриспів:\nСлава, слава, (слава Богу в небі, мир на землі)\nСлава Богу в небі, мир на землі!\nСлава, слава, (Цар народився Христос, Господь)\nЦар народився Христос!\n\nКуплет 2\nХристос родився, - радійте душею!\nПсалми хваління хай ллються рікою;\nВірні, співайте Творцеві в хвалі:\n«Слава Богу в небі, мир на землі!»\n\nКуплет 3\nЗірка небесна вказала Дорогу \nТрьом мудрецям, що вклонилися Богу: \nЦінних принесли Ісусу дарів, -\nЗнали, що є те Дитя - Цар царів.\n\nКуплет 4\nІрод почув, що Христос народився,\nВ заздріснім серці своїм розлютився,\nТайно Дитятко убити рішив,\nДе Спас родився, шукати велів.\n\nКуплет 5\nЙосифові сон від Бога приснився:\nІрод шукати Ісуса рішився, - \nРано візьми ж ти Марію й Дитя,\nАж у Єгипті спасай їх життя!\n\nКуплет 6\nІрод з військами діток побиває, - \nМати з Дитятком в Єгипет вступає;\nДивно спаслося Предвічне Дитя, -  \nЩоб нам, всім людям, принести життя.', '', '', '', '', 'ua', 0, NULL),
(196, 'Хто у бідних яслах', 0, 11, 'Куплет 1\nХто у бідних яслах спить? Там чиє Дитя лежить?\nТо - Господь, Христос-Спаситель, Божий Син, наш\nВідкупитель.\n\nПриспів: \nМи до Нього всі прийдім,\nІ склонімся перед Ним!\n\nКуплет 2\nХто там нарід науча, то Чиї слова звучать?\nДо Кого слабих несуть та сліпих, кривих ведуть?\n\nКуплет 3\nХто там, плачучи, стоїть, де сном смерті Лазар спить?\nВ честь Кого лунає спів? До Кого біжать з домів?\n\nКуплет 4\nХто в саду припав лицем, молиться перед Отцем?\nХто так на хресті терпів? Хто смерть смертю переміг?\n\nКуплет 5\nХто воскрес, щоб оживлять, мертвих до життя піднять? \nХто весь круг земний держить, хто Вселенну всю глядить?', '', '', '', '', 'ua', 0, NULL),
(197, 'Для мене мій Спаситель', 0, 11, 'Куплет 1\nДля мене мій Спаситель зійшов з святих небес,\nВін залишив всю славу - Небесний Край чудес.\n\nПриспів:\nЗа мене Ти (так, за мене, за мене Спаситель) \nПрийняв Голгофський хрест,\nХвала Тобі (хвала Тобі, о мій Відкупитель),\nХвала Тобі і честь!\n\nКуплет 2\nДля мене мій Спаситель у яслах народивсь;\nСин Божий, Примиритель, в любві до нас явивсь.\n\nКуплет 3\nСпасителя любов’ю моя душа живе.\nО, Спасе за Тобою серце стремить моє.\n\nКуплет 4\nБажаю відпочити я лиш в Тобі Однім.\nДай свято, чисто жити, - в серці царюй моїм!', '', '', '', '', 'ua', 0, NULL),
(198, 'Пастухи в полях дрімали', 0, 11, 'Куплет 1\nПастухи в полях дрімали... Ось проміння засіяло, \nДивне сяйво із небес, - сталось чудо із чудес:\nАнгел Божий прилітає, -\n«О, не бійтесь! - їм звіщає, -\nЯ від Бога вам приніс нині радісную вість:\n\nКуплет  2\nВ місті древньому Давида, без величності і виду, \nВідкупитель народивсь, в яслах, як дитя, смиривсь. \nТвердо вірте, не страшіться,\nУ Христі всі веселіться:\nБожий Син до вас прийшов, проявіть свою любов.\n\nКуплет  3\nО, не тратьте віри, люди!\nЦар Всесвіту з вами всюди:\nХто у яслах тут лежить, грізні бурі усмирить:\nЛюдям, що живуть в темряві, засіяє світло слави,\nІ до Нього хто прийде, вічну радість в Нім знайде».', '', '', '', '', 'ua', 0, NULL),
(199, 'Браття всі радійте', 0, 11, 'Куплет 1\nБраття, всі радійте, - славний день настав,\nСестри, веселіться, - Бог нам радість дав!\nМи були чужими, а тепер - друззя:\nМи всі з’единились кровію Христа.\n\nПриспів: \nВсі співайте «Алілуя!»\n(Всі співайте «Алілуя!»2р.),\nБог нас спас і оправдав \n(Бог нас спас і оправдав! 2р.)\nНаші імена навіки \n(Наші імена навіки 2р.)\nВ життя книгу записав\n(В життя книгу записав, навіки записав).\n\nКуплет 2\nНе закон Сінайський - заповіт старий,\nЩо прийняв Ізраїль на святій горі,\nА слова ми чуєм Господа Христа:\nГрішників спасає благодать свята.\n\nКуплет 3\nМи живем в надії, вірі і любві,\nВід гріхів обмились у святій крові.\nДух Господній тішить, веселить серця.\nБудьмо, браття-сестри, вірні до кінця!', '', '', '', '', 'ua', 0, NULL),
(200, 'Христос воскрес із мертвих', 0, 11, 'Куплет 1\nХристос воскрес із мертвих,\nСмертю смерть подолав, -\n І тим, що у гробах, життя дарував! Амінь.', '', '', '', '', 'ua', 0, NULL),
(201, 'Радість з неба сяє', 0, 11, 'Куплет 1\nХристос Воскрес! (2р.)\nРадість з неба сяє ясна, завітала Пасха красна;\nВсі радіймо щиро нині, Бог дав щастя всій родині;\nБог дав радість нам з небес: | Христос Воскрес! (2р.)\n\nКуплет  2\nХристос воскрес! (2р.)\nМир нам Сам Христос приносить,\nМир нам небо днесь голосить,\nМир той Божий всі вітаймо, -\nБожу Пасху споминаймо, -\nБоже чудо всіх чудес: І Христос Воскрес! (2р.)\n\nКуплет  3\nХристос Воскрес! (2р.)\nГімн апостоли співають, жах і смуток забувають; \nСлово Боже всім голосять і спасіння їм приносять,- \nА спасіння йде з небес: | Христос Воскрес! (2р.)\n\nКуплет  4\nХристос Воскрес! (2р.) В Божій правді просвітімся,\nВ Божій правді звеселімся;\nЩезла вже страшна недоля, завітала краща доля - \nБожа благодать з небес: | Христос Воскрес! (2р.)\n\nКуплет  5\nХристос Воскрес! (2р.)\nРадуйтеся, Божі люди, хай між вами згода буде, - \nХай зросте в нас любов Божа,\nЯк барвиста квітка рожа.\nТа любов прийшла з небес: | Христос Воскрес! (2р.)', '', '', '', '', 'ua', 0, NULL),
(202, 'Як сонце в небі засіяло', 0, 11, 'Куплет 1\nЯк сонце в небі засіяло,\nХристос Спаситель наш Воскрес;\nХвилина дивная настала, - \nЗвершилось чудо із чудес!\nХристос Воскрес із мертвих!\n\nКуплет 2\nХристос Воскрес! Усім спасіння \nВін воскресінням показав;\nХристос Воскрес ! Гріхів прощення \nИ життя нам вічне дарував.\nХристос Воскрес із мертвих!\n\nКуплет 3\nВоскресла радісна надія,\nУ серці мир, - Христос Воскрес!\nІду до Тебе я з хвалінням,\nМій захист, Цар, Творець чудес!\nХристос Воскрес із мертвих!', '', '', '', '', 'ua', 0, NULL),
(203, 'У гробі Він лежав', 0, 11, 'Куплет 1\nУ гробі Він лежав - Христос Спаситель, \nДня слави дожидав Ісус Господь.\n\nПриспів: \nІз гробу Він устав (Він устав),\nВсі ворожі сили подолав, (подолав),\nВін Воскрес, Воскрес, —\nСмерть смертю переміг.\nІ всім вірним Царство Вічне дарував.\nВін Воскрес (Він Воскрес)! (2р.)\nАлілуя! Він Воскрес!\n\nКуплет 2\nНамарно сторожать Христа у гробі;\nНащо кладуть печать?! Ісус - Господь!\n\nКуплет 3\nХристос Смерть подолав, Воскрес у славі, \nЖиття нам дарував, Ісус Господь.', '', '', '', '', 'ua', 1, NULL),
(204, 'О яку радість вірним', 0, 11, 'Куплет 1\nО, яку вірним радість велику Бог дав:\nПута смерті Христос розв’язав,\nТемні сили ворожі Господь переміг \nІ народ Свій з гріхів увільнив.\n\nПриспів:\nВ Нім, лиш в Нім, радість в Нім,\nВ Нім вічне життя і любві повнота (повнота),\nВсі серця хай прославлять Христа (лиш Христа)! (2р.)\n\nКуплет 2\nУже наше спасіння Спаситель звершив,\nІ навік смертю смерть подолав.\nХай радіють всі люди і сили небес:\nНаш Спаситель із мертвих Воскрес!\n\nКуплет 3\nВ воскресінні Його — оправдання для всіх, \nВоскресінням Його стерто гріх,\nВоскресінням Своїм переміг силу зла,\nХай лунає Йому честь, хвала!\n\nКуплет 4\nНаш Господь і Спаситель у гробі лежав,\nВін Воскрес, — перемогу здобув.\nНе намарно божественну кров Він пролив:\nВін нас з Богом навік примирив.\n\nКуплет 5\nХай живе Воскресіння Христове в серцях: \nЗникнуть всякі сумніви і страх.  \nВін воскрес, морок ночі навіки вже щез. \nВін воістину в славі Воскрес!', '', '', '', '', 'ua', 0, NULL),
(205, 'Христос Воскрес', 0, 11, 'Куплет 1\nХристос (Воскрес)! (2р.) О радість, радість нам! \nХристос (Воскрес)! (2р.) Кінець журбі й сльозам. \nХристос (Воскрес)! Христос (Воскрес)!\nСмерть смертю подолав і нам спасіння вічне дав.\n\nКуплет 2\nЙого злочинців руки на древірозп’яли,\nЗа нас тяжкії муки терпів Він у любві.\nПречиста кров лилася із ніг, рук і чола... \nЗвершилось все, - Йому хвала!\n\nКуплет 3\nЗ Ариматеї Иосиф Пилата ублагав,\nЗ хреста щоб зняти тіло, - і зняв, і поховав \nВ саду, у новім гробі... Та сонце лиш зійшло,\nХриста вже в гробі не було.\n\nКуплет 4\nДо гробу дуже рано Марія вже прийшла \nІ тіла там нежданно вона вже не знайшла... \nЯвивсь їй ангел з неба і радісно сказав:\n- Христос уже із мертвих встав!\n\nКуплет 5\nСхвильована Марія не стримала ридань...\nАж їй у яснім світлі Христос явився Сам...\n- Учитель мій! - сказала, упавши перед Ним, - \nЙ про чудо сповістила всім..', '', '', '', '', 'ua', 0, NULL),
(206, 'Любив Ісуса Йосиф', 0, 11, 'Куплет 1\nЛюбив Ісуса Йосиф щиро:\nПречисте тіло зняв з хреста,\nІ полотном обвив він чистим,\nУ гробі поховав Христа.\nВорожі сили не змовкали,\nБоялись, що Він може встать; \nВони негайно наказали \nДо гробу приложить печать.\n\nКуплет 2\nЯк тільки стало розсвітати,\nЖінки до гробу вже спішать.\nІ ось два мужі в білих шатах \nВже там на камені сидять.\nНебесні слуги в Божій силі \nКамінь відкинули, і враз \nВорожу ту печать зломили, - \nХристос Воскрес - о, дивний час!\n\nКуплет 3\nЖінки до гробу приступають і бачать чудо із чудес. \nІ ангели у них питають:\n- Кого шукаєте? - Воскрес!\nЖінки у радості вертають,\nЗвістить апостолам спішать, - \nПро чудо їм оповідають:\n- Христос Воскрес! - благовістять.', '', '', '', '', 'ua', 0, NULL),
(207, 'Ідіть розкажіте Христовим друзям', 0, 11, 'Куплет 1\nІдіть, розкажіте Христовим друзям:\nВоскрес Він із гробу, нема Його там!\nНебесний Учитель їм явиться знов; - \nПовернеться радість, поверне любов.\n\nПриспів:\nСкажіте: Христос вже із мертвих воскрес, \nСкажіте всім ближнім: Син Божий Воскрес!\n\nКуплет 2\nНесіть же ту вістку скорботним серцям:\nУтішити хоче Спаситель їх Сам;\nУсім, хто страждає і сльози тут ллє,\nНебесную радість Спаситель дає.\n\nКуплет 3\nУсім засвідкуйте про милість Христа,\nБо Він відкупив нас - дарує життя;\nВоскрес Він із мертвих, щоб нас оправдать,\nДітей Своїх вірних із мертвих піднять.\n\nКуплет 4\nНе за серафимів Спаситель страждав, - \nЗа грішних людей Божий Син умирав.\nВоскрес Він у славі і смерть подолав,\nІ грішних нас з Богом навік примирив.', '', '', '', '', 'ua', 0, NULL),
(208, 'Христа Творця святих чудес', 0, 11, 'Куплет 1\nХриста - Творця святих чудес \nПрославте всі сердечним співом.\nРадійте всі! Звершилось диво: | Христос Воскрес! (2р.)\n\nКуплет 2\nХвала, хвала! Христос Воскрес!\nЖиття! У грудях серце б’ється...\nТепер усюди пісня ллється: І Христос Воскрес! (2р.)\n\nКуплет 3\nПо всьому світу до небес \nХвала Творцеві щира ллється.\nСпів радісний нехай несеться: | Христос Воскрес! (2р.)\n\nКуплет 4\nТобі, Спаситель - Божий Син,\nТобі і слава, і хваління,\nПодяка, честь і поклоніння повіки вічнії! Амінь.', '', '', '', '', 'ua', 0, NULL),
(209, 'Зарожевів вже схід небес', 0, 11, 'Куплет 1\nЗарожевів вже схід небес, - \nХристос Спаситель наш Воскрес \nВін гріх-темряву розігнав,\nСпасіння людям дарував.\n\nПриспів: \nУ гробі вже Христос лежав,\nНа третій день Він з мертвих встав. \nСмерть не могла вдержать Його - \nЦаря царів - Творця всього.\n\nКуплет 2\nСпаситель мій, Ти ворогів -\nЗлі, темні сили подолав,\nВже каменя з грудей Ти зняв,\nІ милість я Твою пізнав.\n\nКуплет 3\nХристос Воскрес! - гріхи простив,\nМене Він з Богом примирив,\nВін в Царство вічне кличе нас,\nІ береже у кожний час.\n\nКуплет 4\nТвою любов і благодать,\nО, Спасе, будем прославлять\nТепер, і там у небесах,\nЗ святими в радісних піснях!', '', '', '', '', 'ua', 0, NULL),
(210, 'О смерть Де скажи твоє жало', 0, 11, 'Куплет 1\nО, смерть! Де, скажи, твоє жало?\nДе, пекло, звитяга твоя?\nВоскрес наш Господь! Засіяло \nВ Нім вічнеє сонце життя.\n\nПриспів: \nХристос Воскрес, - Смерть подолав,\nЩоб в людях міг Дух Божий жить.\nХристос Воскрес, щоб до життя \nНас, мертвих, з гробу воскресить.\nЯка нам радісна та вість! (2р.) \nХристос Воскрес! (2р.) Хвала Йому і честь!\n\nКуплет 2\nПогляньте: вже камінь від гробу \nВіднятий, і ангел з небес \nПромінням там сяє чудовим:\n«Ісуса ж нема: Він Воскрес!»\n\nКуплет 3\nВоскрес Він, щоб з серця людського \nГріховного каменя знять;\nВоскрес Він, щоб Духа Святого,\nЯк ангела в гріб, нам послать.\n\nКуплет 4\nВоскрес Він, щоб світлом спасіння \nЛюдей у пітьмі осіять;\nВоскрес Він, щоб в день Воскресіння \nВідкуплених в славі обнять.', '', '', '', '', 'ua', 0, NULL),
(211, 'Радійте співайте і славте', 0, 11, 'Куплет 1\nРадійте, співайте і славте \nОбмитії кров’ю Христа!\nВи пісню нову заспівайте \nТому, Хто вас спас від гріха.\n\nПриспів: \nРадійте, радійте,\nСпівайте і славте Христа!\n\nКуплет 2\nПрославмо Того, Хто на землю \nЗійшов, щоби нас оправдать. \nСпасти нас пречистою кров’ю \nІ щастя навіки нам дать.\n\nКуплет 3\nВін сили нам дасть й перемогу.\nЗ гріхом в боротьбі підкріпить, \nЛюбов’ю Своєю піддержить \nІ Духом Святим нас зміцнить.\n\nКуплет 4\nВсі радісним серцем співайте, \nВіддайте подяку тому,\nХто Сам заплатив за нас кров’ю.\nО, слава навіки Йому!', '', '', '', '', 'ua', 1, NULL),
(212, 'Як овечку Пастир', 0, 11, 'Куплет 1\nЯк овечку, Пастир сильний, Сам веди мене вперед! \nНа Твої луги просторі, - за Тобою я йду вслід,\nО, Ісус мій! О, Ісус мій! Ти за мене кров пролив.\n\nКуплет 2\nО, Спасителю незмінний, захищай нас, бережи:\nМи без Тебе всі безсильні, - у Своїх руках держи.\nО, Ісус мій! О, Ісус мій! Ти за мене постраждав.\n\nКуплет 3\nПрояви обітування, - в серце благодать зішли,\nЩирі вчуй мої благання і Твій мир мені пошли.\nО, Ісус мій! О, Ісус мій! Від спокус охороняй.\n\nКуплет 4\nДай, щоб серцем міг я вірно Твій лиш заповіт любить, \nБлижнім всім служити щиро; научи в любові жить.\nО, Ісус мій! О, Ісус мій! В моїм серці будь повік.', '', '', '', '', 'ua', 0, NULL),
(213, 'Єдиний лікар є', 0, 11, 'Куплет 1\nЄдиний лікар є для нас, - ласкавий наш Спаситель:\nВін ранами Своїми спас всіх вірних - наш Збавитель.\n\nПриспів:\nКращий скарб мені Ти дав: душу й тіло врятував, \nЩоб хвалу Тобі співав, мій Господь-Спаситель!\n\nКуплет 2\nВін всі гріхи мої простив, мій Лікар, мій Збавитель,\nВін дім Отця мені відкрив, - Ісус, наш Примиритель.\n\nКуплет 3\nЯ прагну щиро все любить Тебе, мій Відкупитель!\nТвоє ім’я люблю хвалить, Предвічний Цар, Спаситель!\n\nКуплет 4\nНедуг невиліковний твій Спаситель ізціляє;\nЙого могутність зрозумій: Він вірним помагає!\n\nКуплет 5\nПрославмо, браття, всі Христа, любов Його безмірну! \nХай славить серце і уста Господню милість дивну.', '', '', '', '', 'ua', 0, NULL),
(214, 'В вічнім спасінні укрийся', 0, 11, 'Куплет 1\nВ вічнім спасінні укрийся, навіть з великим трудом! \nКров’ю Ісуса обмийся, - ти обтяжений гріхом!\nДушу тривожить спокуса, - помочі жди від Ісуса;\nА в Нім знайдеш відпочинок,\nО, ти, обтяжений гріхом! (2р.)\n\nКуплет 2\nВін хоронить тебе буде і твій тягар понесе;\nІсус тебе не забуде, - сльози з очей Сам утре. \nБачить твої Він страждання,\nВсі заспокоїть зітхання,\nПлач віддалить та ридання, - \nВсі сльози з очей Сам утре. (2р.)', '', '', '', '', 'ua', 0, NULL),
(215, 'Побачу нове небо й землю', 0, 11, 'Куплет 1\nПобачу нове небо й землю по слову мойого Творця,\nІ славу від Бога одержу, я буду щаслив без кінця!\n\nПриспів: \nТам усі в небесах\nЖдуть з Христом і мене у Творця.\nЗ мене хрест Спас здійме \nІ в небесную радість прийме.\n\nКуплет 2\nПобачу я місто прекрасне, де всі вихваляють Творця;\nУ світлій оселі небесній я буду щаслив без кінця!\n\nКуплет 3\nДванадцять воріт там перлинних, і слава там Божа сія. \nТам вічно в проміннях Христових я буду щаслив без кінця!\n\nКуплет 4\nТам будуть спасенні народи у славі свойого Творця. \nДалеко від бур і негоди, я буду щаслив без кінця!\n\nКуплет 5\nТам в царстві небесного міста зіллються спасенні серця, \nХвалу віддадуть там всі Богу... Я буду щаслив без кінця!', '', '', '', '', 'ua', 0, NULL),
(216, 'На землі тут є тлінне', 0, 11, 'Куплет 1\nНа землі тут є тлінне срібло, золото - все,\nТільки в Бозі незмінне вічне щастя моє.\nСпас усіх научає скарби в небі збирать,\nДе іржа не з’їдає, злий не може забрать.\n\nПриспів: \nО, скажи, Боже мій, чи записаний я,\nВ вічній книзі спасенних чи записаний я?\n\nКуплет 2\nДовго, довго блукав я, у гріхах проживав \nІ спасіння не знав я, і Христа не шукав; \nТільки вічний Спаситель мене Сам віднайшов \nІ ласкаво покликав.. . Я до нього прийшов.\n\nКуплет 3\nМісто вічне для вірних в небі Бог збудував,\nІ оселі Син Божий для спасенних придбав.\nТам гріха вже немає, ані темряви-зла, - \nСонце правди сіяє,, там небесна краса.', '', '', '', '', 'ua', 0, NULL),
(217, 'Подивись на берег річки', 0, 11, 'Куплет 1\nПодивись на берег річки, де багато є роси,\nТам поміж квіток барвистих лілея цвіте в красі.\n\nПриспів:\nЯк Бог лілію так любить, (2р.) дбає про її красу, - \nТо невже ж тебе забуде? Бачить Він твою тугу...\n\nКуплет 2\nКорінці її водою підкріпляються щодня,\nКвітка скроплена росою, - світить рання їй зоря.\n\nКуплет 3\nЛілея цвіте на волі, вверх глядить у небеса;\nБджілку, що літа у полі, вабить лілеї краса.\n\nКуплет 4\nЗапах милий і пахучий розливається в полях...\nЧи ж ходив хто найбагатший в пишних шатах, як вона?\n\nКуплет 5\nОсь яка краса творіння, як про неї Бог подбав!\nБез турбот вона й мучіння. Чого ж ти в журбу упав?', '', '', '', '', 'ua', 0, NULL),
(218, 'До Христа навернись', 0, 11, 'Куплет 1\nДо Христа навернись, нащо в світі блукать,\nЦінний час марнувать? Встань, кругом подивись:\nТи в грісі потонув та про Бога забув...\nДо Христа навернись!\n\nКуплет 2\nДо Христа навернись, гріхом стомлений син,\nТи ідеш на загин; на хвилинку спинись \nТа поглянь на Христа, — ллється кров з ран свята \nЗа тебе... Навернись!\n\nКуплет 3\nДо Христа навернись, Йому серце віддай,\nВін введе тебе в рай. На цей світ, не дивись.\nСпас так тяжко страждав, за тебе умирав:\nДо Христа навернись!', '', '', '', '', 'ua', 0, NULL),
(219, 'Прийми хваління і подяку', 0, 11, 'Куплет 1\nПрийми хваління і подяку,\nСин Божий, за Твою любов!\nЗа нас терпів Ти тяжкі муки,\nЗа нас пролив пречисту кров.\n\nКуплет 2\nЗнущання всі і оплювання,\nЛаскавий Спасе, Ти прийняв, - \nЩоб дати всім нам оправдання,\nЗа нас Ти на хресті страждав.\n\nКуплет 3\nПробитою, Спасе, рукою \nМене Ти до життя підняв;\nВ Тобі лиш джерело спокою,\nЯ радість і любов пізнав.\n\nКуплет 4\nПрийми хваління і подяку, \nСин Божий, за Твою любов! \nЗа нас терпів Ти тяжкі муки, \nЗа нас пролив святую кров.', '', '', '', '', 'ua', 0, NULL),
(220, 'Прийди Святий Дух Утішитель', 0, 11, 'Куплет 1\nПрийди, Святий Дух Утішитель!\nСердечний храм мій освяти,\n Завсіди будь Ти мій Учитель,\nВідкрий Твої слова святі.\nНавчай мене пізнать Творця,\nВ Нім научи любить Отця.\n\nКуплет 2\nДаруй мені дух розуміння, - \nВ сумнів ніколи не впадать,\nЩоб всі божественні веління,\nЯ міг завсіди виповнять.\nЛюбов’ю душу знов зігрій,\nЛюбов до святості дай їй.\n\nКуплет 3\nДля мене радість і утіха,\nДух Утішитель, Ти один:\nСпокоєм серце наповняє \nТобою, вічний Божий Син.\nЛюбов, надію, шле як дар \nІ в серці віри гріє жар.\n\nКуплет 4\nБлагаю: милістю Твоєю \nІ дух, і серце обновляй,\nМоєю володій душею,\nВ смиренні волю підкріпляй.\nБлагий Учитель завжди будь \nІ направляй на світлий путь!', '', '', '', '', 'ua', 0, NULL),
(221, 'Як сумно на серці', 0, 11, 'Куплет 1\nЯк сумно на серці мені, коли я не бачу Христа, - \nСпокою не маю тоді, | змовкають (Зр.), німіють уста.\n\nКуплет 2\nІ ніби все спить навкруги: і місяць, і зорі смутні,\nНе тішать ні гай, ні луги... І сумно (Зр.) на серці в ті дні.\n\nКуплет 3\nВ Ісусі все щастя моє: з Ним всюди у світлі іду, —\nКоли Він у серці живе,  співаю (Зр.) Йому я хвалу.\n\nКуплет 4\nНайкращим для мене в житті, учитись усе від Христа, \nСлова розуміти святі, — | дочасне (Зр.) усе - марнота.', '', '', '', '', 'ua', 0, NULL),
(222, 'Грішник слухай', 0, 11, 'Куплет 1\nГрішник, слухай! (2р.) Голос чийсь звучить:\nГолос милий, голос тихий просить відчинить.\nТо не пізній перехожий в двері стукає,\nТебе просить Сам Спаситель: - О, впусти Мене! - і\n\nКуплет 2\nВ твоїм серці смерті холод, темрява нічна;\nЯк відчиниш Йому серце, стане там весна.\nРіч свята Його поллється, як небесний спів....\nЧуєш - стука, чуєш - каже: - Відчини мені!\n\nКуплет 3\nО, відкрий же Йому серце, - Він там хоче жить.\nІ твою скорботну душу світлом оживить.\nНе вагайся відчинити, не зостанься в сні;\nСкоро змовкне голос тихий: - Відчиніть Мені!', '', '', '', '', 'ua', 0, NULL),
(223, 'Повернись додому', 0, 11, 'Куплет 1\nПовернись додому! В країні чужій, чужій,\nТи блукав так довго (2р.), сину дорогий, дорогий!\n\nКуплет 2\nПовернись додому, на чужині тій, чужій,\nВзнав ти голод й холод (2р.), сину дорогий, дорогий !\n\nКуплет 3\nПовернись додому; шлях недобрий твій, шлях твій \nЗалиши навіки(2р.), сину дорогий, дорогий!\n\nКуплет 4\nПовернись додому, - в боротьбі тяжкій, тяжкій \nТи втомивсь стояти (2р.), сину дорогий, дорогий!\n\nКуплет 5\nПовернись додому, будь навіки Мій, будь Мій: \nЖду тебе давно Я (2р.), сину дорогий, дорогий!', '', '', '', '', 'ua', 0, NULL),
(224, 'Чи є місце для Ісуса', 0, 11, 'Куплет 1\nЧи є місце для Ісуса? Муки Він за нас терпів... \nВідчини ж сердечні двері! Нас Він кров’ю всіх обмив.\n\nПриспів:\nДля Ісуса - Його слави місце в серці приготуй,\nГолос вчуй Його любові, сам до Нього поспішай.\n\nКуплет 2\nТи дочасним всім турботам місце в серці сам даєш?!\nО, невже ж перед Ісусом двері серця ти замкнеш?\n\nКуплет 3\nЧи прийдеш ти до Ісуса? Ось Він кличе знов тебе.\nО, будь, друже, обережний: скоро час земний пройде!\n\nКуплет 4\nПоспішай же до Ісуса, серце ти Йому віддай,\nПоки не замовк ще голос, Сина Божого приймай!', '', '', '', '', 'ua', 0, NULL),
(225, 'Вір душа кріпися', 0, 11, 'Куплет 1\n«Вір, душа, кріпися! Я - Спаситель твій,- \nЗавжди лиш дивися на світильник Мій!\nНа шляху тернистім руку Я подам,\nЯ з тобою всюди, - вір, що уже ти не сам».\n\nПриспів: \nНі, (я не один), я не один, (я не один):\nПастир мій — Ісус! Він мене Сам захищає \nВід всіх ворожих спокус.\n\nКуплет 2\nЛілії пов’януть, сонце теж зайде,''\nА Господня слава повік не пройде.\nХоч бушує буря ніччю, чи удень, - \nВсюди Спас Зі мною, - з Ним я уже не один.\n\nКуплет \nХоч трудна дорога тут мого життя, - \nЧую Божий голос: «Ти - Моє дитя!»\nВірю, що Спаситель вірних захистить,\nІ спасенні душі будуть у небі з Ним жить.', '', '', '', '', 'ua', 0, NULL),
(226, 'Життя одне ми маєм', 0, 11, 'Куплет 1\nЖиття одне ми маєм в цьому світі,\nІ хутко як минають Його дні;\nЖиття одне, щоб славити Ісуса,\nЙому служити, не пробути в сні.\n\nКуплет 2\nВсе, що Він дав, Йому лиш поверну я,\nВесь час, всі дні і сили всі мої.\nСпаситель мій! За мене постраждав Ти:\nЯк не віддам життя моє Тобі?!\n\nПриспів: \nЖиття одне як швидко пролетить,\nЛиш все, що Боже, вічно устоїть (2р.)\n\nКуплет 3\nЖиття одне - чому нема в вас діла?\nХристос усіх на працю кличе вас \nПогляньте! Тисячі в гріхах вмирають,\nПочуйте - тисячі благають нас.\n\nКуплет 4\nВставайте всі, вставайте до роботи, - \nПролинуть скоро, скоро наші дні.\nВставайте всі, хоч спали ви так довго,\nБо прийдете до Господа-Судді.\n\nКуплет 5\nЖиття моє Тобі припоручаю, -\nПошли мене про Тебе розказать\nЗаблудлим всім, що в темряві блукають,\nПро смерть Твою, про рани нагадать.\n\nКуплет 6\nВсе, все візьми, о Боже, на служіння,\nЛиш би від смерті грішників спасти!\nЗ Тобою я - моя уся в тім слава,\nБо в радість неба можу я ввійти.', '', '', '', '', 'ua', 0, NULL),
(227, 'Нам здалека вже видно', 0, 11, 'Куплет 1\nНам здалека вже видно той Край,\nДе у славі небесній Господь.\nСам Спаситель веде в Божий рай \nСвій відкуплений, вірний народ.\n\nПриспів:\nСкоро Він (скоро Він) нас введе (нас введе)\nУ бажаний той Край дорогий (нас введе)!\nСкоро Він (скоро Він) нас введе (нас введе)\nУ бажаний той Край дорогий!\n\nКуплет 2\nТам, забувши недолю земну,\nДе чудова Країна свята,\nВсі співають Творцеві хвалу,\nПрославляють всім серцем Христа.\n\nКуплет 3\nТам зібрання спасенних усіх,\nЩо втішаються Духом Святим,\nВеличають Христову любов \nПеред троном Його пресвятим.', '', '', '', '', 'ua', 0, NULL),
(228, 'Пастир добрий', 0, 11, 'Куплет 1\nПастир добрий, стережи нас; наше щастя лиш в Тобі! \nДоглядай і підкріпляй нас: всі без Тебе ми слабі.\n\nПриспів: \nО, Ісус Христос, Спаситель!\nТи купив нас, - ми Твої.\n\nКуплет 2\nМи бажаєм за Тобою, тільки за Тобою йти;\nСам дорогою вузькою в Царство вічне нас веди.\n\nКуплет 3\nВсіх прийняти Ти бажаєш, кличеш кожного: -Прийди! \nВсі провини Ти прощаєш тим, хто вірує Тобі.', '', '', '', '', 'ua', 0, NULL),
(229, 'Будем браття жити свято', 0, 11, 'Куплет 1\nБудем, браття, жити свято, хоч панує гріх кругом.\nМи ж в єднанні брат із братом всі підемо за Христом. \nНас Христос прийняв з любов’ю,\nВ Ньому радуймося ми: Він нас спас Своєю кров’ю - \nБудьмо ж світлом між людьми.\n\nКуплет 2\nУ марнотах ми блукали, смерть за нами всюди йшла. \nБожа ласка нас шукала і, знайшовши, нас спасла. \nХоч ми духом всі убогі, -\nНам Христос багатство дав:\nПоказав у рай дорогу і спасіння дарував;\n\nКуплет 3\nЧи то в горю, чи в стражданнях,\nВірим - Бог нас підкріпить.\nПідем далі без вагання за Спасителем услід.\nХоч кипить ще зло у світі, темрява гріха царить,- \nБог в любві по заповіту від спокус нас захистить.', '', '', '', '', 'ua', 0, NULL),
(230, 'Насліддя моє в небесах', 0, 11, 'Куплет 1\nНасліддя моє в небесах, - і моя туди лине душа, \nДе Творцеві в чудових піснях \nВід спасенних лунає хвала.\n\nПриспів: \nВ небесах, (в небесах), (2р.)\nНасліддя моє в небесах, (в небесах), \nВ небесах (в небесах), (2р.) \nНасліддя моє в небесах.\n\nКуплет 2\nГосподь мене жде в небесах,\nІ Він прийме в оселю Свою,\nДе у сяйві Господнім краса \nВ Його світлім блаженнім раю.\n\nКуплет 3\nВ край світлий і я увійду, - \nЗакінчу путь тернистий земний,\nТам всіх вірних слуг Божих знайду- \nВони вийдуть назустріч мені.', '', '', '', '', 'ua', 0, NULL),
(231, 'Де живуть у злі', 0, 11, 'Куплет 1\nДе живуть у злі й без Бога, - ти життям не називай! \nДля Спасителя Ісуса серце стомлене віддай!\n\nКуплет 2\nДруже, глянь, як народ тоне у гріхах і марноті!\nНе знайдеш ти тут спокою, щастя знайдеш лиш в Христі.\n\nКуплет 3\nО, збирай борців за віру, до Ісуса закликай:\nДень за днем проходить скоро, - не барися, поспішай!\n\nКуплет 4\nСкільки душ Христа не знають і без Господа живуть... \nРозкажи їм про Ісуса, наверни на добру путь!\n\nКуплет 5\nСвідком будь ти перед ними, розкажи, що бачив сам, \nЯк любов Свою Спаситель дав покірним всім серцям.\n\nКуплет 6\nПрисвяти себе Ісусу, - всі літа ще молоді,\nПрисвяти Йому і старість, будеш з Богом жить тоді!\n\nКуплет 7\nО, віддайся ти Ісусу, - і за тебе Він страждав, \nПеретерпів хресні муки, кров невинну проливав.\n\nКуплет 8\nСерце хто віддасть Ісусу, вічне в Нім життя знайде;\nТого Сам Христос Син Божий \nВ царство радості введе.', '', '', '', '', 'ua', 0, NULL),
(232, 'Ісусу Відкупителю', 0, 11, 'Куплет 1\nІсусу-Відкупителю із роду в рід хвала!\nСлаву і честь Спасителю віддайте, племена!\n\nПриспів: \nСпівайте щиро всі, (співайте всі), (2р.)\nПро вістку радісну святу,\nБожу ласку доброту,\nСпівайте щиро всі, (співайте всі)!\n\nКуплет 2\nСпаситель кров Свою пролив, смерть смертю подолав. \nНас у любові оправдав й життя нам вічне дав.\n\nКуплет 3\nПрийдіть до Господа усі, до Джерела життя: \nВода жива є для душі у Господа Христа.\n\nКуплет 4\nЯк твоє серце ще скорбить, - до Спаса йди скоріш;\nВін твою душу оживить і дасть тобі спокій.', '', '', '', '', 'ua', 0, NULL),
(233, 'Хто хто там веселиться', 0, 11, 'Куплет 1\nХто, хто, там веселиться, так радісно співа? - \nЗаблудлий син вернувся до рідного Отця. \nНе хоче споминати Отець старих подій,\nДитя своє обняти Він хоче найщиріш..\n\nКуплет 2\nХто, хто там веселиться? Спів голосно звучить!... \nЗагублений син вдома з Отцем уже гостить.\nВін пропадав далеко, у світі цім блудив,\nВін гинув у пороках, лиш у Отця ожив.\n\nКуплет 3\nХто, хто там веселиться? То Божий є слуга;\nТепер він не смутиться: журба його пройшла.\nЛюбов його зогріла, як до Отця прийшов,\nІ радість завітала у серці його знов.\n\nКуплет 4\nХто, хто там веселиться? Христів це є слуга,\nУ рідний дім ввійшов він, де смутку вже нема. \nДруззя! І ви спішіте радіти у Христі,\nДо Бога всі прийдіте, не жийте в марноті!', '', '', '', '', 'ua', 0, NULL),
(234, 'Спасіння вічне завершив', 0, 11, 'Куплет 1\nСпасіння вічне завершив Христос для всіх людей; \nВін грішних з Богом примирив, дав світло для очей.\n\nПриспів: \nО, серце, не вагайся, вір!\nПрийми Христа тепер.\n\nКуплет 2\nГосподь всіх грішних полюбив, за них Він кров пролив.\nВін на хресті в предсмертний час Отця молив за нас.\n\nКуплет 3\nЖиття Спаситель мертвим дав, гріх переміг і тьму. \nСвоє нам слово дарував, щоб вірили Йому.\n\nКуплет 4\nГосподнє слово - меч святий, струмінь води живий; \nВоно карає всякий гріх, навчає правди всіх.', '', '', '', '', 'ua', 0, NULL),
(235, 'Як я пізнав любов Христа', 0, 11, 'Куплет 1\nЯк я пізнав любов Христа, знайшов я вічне в Нім життя, \nТепер Ісус-Спаситель мій дарує серцю Свій спокій.:\n\nПриспів:\nО, Алілуя! Сталося!... Мене Ісус вже відкупив, \nСпаситель мій дає спокій і силу в боротьбі земній.\n\nКуплет 2\nКоли я до Христа прийшов, нетлінні скарби в Нім знайшов: \nНадія, віра і любов - мене втішають знов, і знов.\n\nКуплет 3\nВсе щастя у любві Христа, земне багатство - марнота; \nХристос для мене - Хліб живий, Я вже Його, я вже не свій.', '', '', '', '', 'ua', 0, NULL),
(236, 'Чи буде заграва на сході світати', 0, 11, 'Куплет 1\nЧи буде заграва на сході світати,\nЧи яснеє сонце почне вже сіяти, - \nІз неба прийде знов Ісус в вічній славі \nУзять від землі Своїх.\n\nПриспів:\nО, наш Спасителю, Тобі заспіваєм в той день:\n«Ось, гряде Він, - Алілуя! | Алілуя, амінь!» (2р.)\n\nКуплет 2\nЧи буде опівдні, чи то опівночі,\nНежданно побачать Його наші очі;\nПрийде наш Спаситель осяяний світлом \nУзять від землі Своїх.\n\nКуплет 3\nІ ангельські сили з Ним будуть сіяти,\nХристос буде вірних Своїх зустрічати.\nІ співи хваління поллються рікою,\nЩо взяв від землі Своїх.\n\nКуплет 4\nО, радість, туди перейти без страждання,\nБез болю, тривог та недуги й зітхання,\nУ славу Господню на небо піднятим, \nКуди Він візьме Своїх.', '', '', '', '', 'ua', 0, NULL),
(237, 'Блаженні серця', 0, 11, 'Куплет 1\nБлаженні серця, що Христа прийняли,\nСпасіння і мир на Голгофі знайшли.\nПростив Ти мені, і навіки я Твій:\nЗнайшов я у Тебе і радість, й спокій.\n\nПриспів: \nПрославте любов Христа, \nДивну, Божественну.\nСпасає грішників любов Христа.\n\nКуплет 2\nДалеко в гріхах від Христа я блукав: \nСпасіння, спокою у серці не мав; - \nТепер я співаю: Спасителю мій,\nЗцілив Ти мене у любові Своїй!\n\nКуплет 3\nБлаженні відкуплені смертю Христа,- \nСпаситель відкрив їм нове вже життя: \nУтер Він їх сльози і світлом осяяв \nІсус мені силу слабому подав.\n\nКуплет 4\nО, Спасе мій милий, Ти - радість моя! \nНавчай же, щоб вірно служив Тобі я:\nПролив Ти за мене Божественну кров, \nСлавлю я милість Твою і любов.', '', '', '', '', 'ua', 0, NULL),
(238, 'Людям блукаючим шлях покажіте', 0, 11, 'Куплет 1\nЛюдям блукаючим шлях покажіте,\nТих, що зневірились, ви підбодріть, - \nВсім погибаючим правду скажіте,\nХто спить душею, ідіть, розбудіть!\n\nПриспів: \nЛюдям блукаючим шлях покажіте;\nХто спить душею, ідіть, пробудіть!\n\nКуплет 2\nПро відкуплення всім вістку несіте, - \nКожного кличе Спаситель- Прийди!\nІ научайте всіх в Господі жити,\nЩоб міг нещасний в Нім щастя знайти!\n\nКуплет 3\nЛюдям, що в світі тут ходять в темряві,\nСвітло Христове негайно несіть.\nВ серце утомлене життям гріховним \nРадість Дух Божий лиш може пролить.\n\nКуплет 4\nЩиро до праці ми, браття, підемо,\nЩоб ближнім поміч в недолі подать,\nВ праці для Господа радість знайдемо:\nНас підкріпить в ній Його благодать.', '', '', '', '', 'ua', 0, NULL),
(239, 'Слухайте вістку святу', 0, 11, 'Куплет 1\nСлухайте вістку святу в простоті,\nПоки ще маєте час:\nВірним дарує Спас вічне життя;\nБог нас від гибелі спас.\n\nПриспів: \nБог нас від гибелі спас! (2р.)\nТак, Бог нас навіки простив у Христі, \nБог нас від гибелі спас.\n\nКуплет 2\nКоли ще спомин пролинувших днів\nДушу тривожить нераз, -\nВірте, — Спаситель усе вам простив:\nБог нас від гибелі спас.\n\nКуплет 3\nКоли в темряві й життєвій борні \nПромінь надії погас,\nЗнов пригадайте ви, браття, тоді:\nБог нас від гибелі спас.', '', '', '', '', 'ua', 0, NULL),
(240, 'Скажіть мені браття', 0, 11, 'Куплет 1\n«Скажіть мені, браття і сестри, куди ви зібрались іти?\nКаміння на вашій дорозі, і терен колючий росте».\n- Ідемо ми в царство Христове,\nТам вічного щастя краса,\nКрізь темряву чорної ночі \nМи бачим світ Божого дня.\n\nПриспів: \nВже скоро, і путь ми пройдем,\nДо рідного дому ввійдем;\nГосподь в Свою радість нас прийме, \nТам вічнеє щастя знайдем.\n\nКуплет 2\n«Як дуже бажав би я з вами в далеку дорогу піти, \nТа думка одна лиш тривожить:\nНе знаю, де сили знайти?» \n- Ми слухаем Боже веління, -\nВін Духа Святого дає,\nЩо наші серця підкріпляє і сил  бородьбі подає\n\nКуплет 3\n- О, браття,тепер я рішась\nЛишити все и з вами піти! Я вірю, мені Бог поможе \nДалекий той путь перейти».\n- Вітаємо, брате, бажання!\nСкоріше нам руку подай, і підемо в путь без вагання \nВ чудовий і світлий той край.', '', '', '', '', 'ua', 0, NULL),
(241, 'Я люблю з Христом ходити', 0, 11, 'Куплет 1\nЯ люблю з Христом ходити, як апостоли колись;\nЯк зібрав їх коло Себе, й говорив їм благу вість:\nЯк прийшов Він, щоб з неволі\nУвільнити всіх людей,щоб тягар гріхів з них зняти,\nА їм дати Свій спокій.\n\nПриспів: \nЯ піду, де поведе Він,\nЯ буду там, де буде Він;\nЯ піду з Ним все і всюди - \nЯ піду з Ісусом кожний день.\n\nКуплет 2\nЯ люблю з Христом ходити,\nЯк тих два мужі в той час,\nЯк Ісус йшов з Єрихону - \nКричали: «Помилуй нас!»\nІ Христос вчув їх благання та дав зір їхнім очам;\nІ вони з радістю встали, і пішли вслід за Христом.\n\nКуплет 3\nЯ люблю з Христом ходити\nНа гору Голгофську там, -\nІ дивитись на страждання, де заплачу із жалем.\nТам Він каже, як Він любить;\nЯк мої гріхи простив. - з радістю За Ним я піду,\nДе б лиш Він мене не вів.\n\nКуплет 4\nЯ колись буду ходити з Ним в небеснім місті тім,\nЯк я земний шлях скінчу вже \nІ ввійду в той вічний дім.', '', '', '', '', 'ua', 0, NULL),
(242, 'Хто хто радість дасть', 0, 11, 'Куплет 1\nХто, хто радість дасть? Я в журбі благав- \nРадість, щастя у Христа лиш я пізнав.\n\nКуплет 2\nВін мене від зла завжди захистить, - \nБез Нього не можу я на світі жить.\n\nКуплет 3\nХочу жити з Ним, з Господом моїм, - \nВін стражданням відкупив мене Своїм.\n\nКуплет 4\nКличе Спас усіх, щоб скоріш прийшли \nІ велику радість в серце прийняли.\n\nКуплет 5\nО, мій друже, встань, до Христа прийди,\nУ цім грішнім світі більше не блуди!', '', '', '', '', 'ua', 0, NULL),
(243, 'Далеко від земних марнот', 0, 11, 'Куплет 1\nДалеко від земних марнот \nІ всіх людських турбот\nЄ край, де вічно ясний день,\nДе ллється звук пісень.\n\nПриспів:\nВ той Край (в той Край) (2р.) всім серцем лину я, \nДе вічне щастя - Божий рай, де вічне світло дня.\n\nКуплет 2\nТам лиш любов свята царить \nІ вірних веселить,\nЖиття там вічного весна,\nКраса там неземна;\n\nКуплет 3\nНове там небо і земля, - \nПо правді всі живуть;\nХристом відкуплені серця \nТам сліз уже не ллють.', '', '', '', '', 'ua', 0, NULL),
(244, 'До Господа прийдіть', 0, 11, 'Куплет 1\nДо Господа прийдіть, в любві Йому служіть: \nХристос за грішних постраждав і їм спасіння дав!\n\nПриспів:\nІдем ми з хвалінням в світлий небесний Сіон,\nУсі ми йдем до Сіону і будем там вічно з Христом!\n\nКуплет 2\nСпасенні всі спішать, і співи їх звучать;\nЗа Господом вони пішли і в Нім життя знайшли.\n\nКуплет 3\nДруззя! І ви спішіть, вслід за Христом ідіть; \nПрийміть Його в свої серця, знайдете в Нім життя.', '', '', '', '', 'ua', 0, NULL),
(245, 'Буря грізна завиває', 0, 11, 'Куплет 1\nБуря грізна завиває, і вітер страшний загув,\nХмара, як ніч, насуває, - ми гинем, а Ти заснув.\nХіба тебе не турбує, що смерть облягає нас? \nСтрашні хвилі ревуть і бушують, і можуть залити нас.\n\nПриспів:\n«І море, і буря почують Мене, затихне усе;\nМоре бурхливе смириться,\nМені тут усе впокориться:\nСоздатель землі і небес тут Сам,\nНе дасть Він ніколи загинуть вам!\nІ море, і буря вчують Мене, затихне усе»: (2р.)\n\nКуплет 2\nБоже, в великій печалі голову хилю свою,-  \nДушу гріхи заливають; о, Боже, спаси, молю!  \nСерце скорбить і страждає в тривозі, в борні земній;  \nО, я гину, помилуй, благаю, душі моїй дай спокій !\n\nКуплет 3\nБуря уже перестала, і в серці настав спокій;\nСонце з небес засіяло, ллє промінь душі моїй.\nБудь же, мій Спасе, зі мною, мене Ти охороняй \nІ в Небесну Країну спокою душу мою направляй!', '', '', '', '', 'ua', 0, NULL),
(246, 'Дружно дружно будем працювати', 0, 11, 'Куплет 1\nДружно, дружно будем працювати;\nМи на труд той з радістю підем, \nЩо для нас тепер Господь призначив \nЧесно й свято виповнять будем.\n\nПриспів: \nТруд цей для Бога \n(труд цей, труд цей весь для Бога),\nРадісно підем, (так), радісно підем\nТруд цей для Бога\n(труд цей, труд цей весь для Бога),\nВ винограднику Його.\n\nКуплет 2\nСміло, сміло про Христа розкажем,\nПро любов Його до грішних нас;\nНаш Спаситель, Божий Син у славі, \nБлагодать Він нам безмірну дасть.\n\nКуплет 3\nМи підем услід за Ним покірно,\nУ терпінню хрест наш понесем,\nІ людей, що тут живуть без Бога, \nДо Христа Ісуса приведем.', '', '', '', '', 'ua', 0, NULL),
(247, 'Я не хочу марно часу провести', 0, 11, 'Куплет 1\nЯ не хочу марно часу провести:\nВ світлі правди за Христом я буду йти,  \nКожний час-хвилину мойого життя \nХочу я віддати для Христа.\n\nПриспів:\nПонесу (понесу) я вість Христа (я вість Христа)\nПо землі (по землі) у всі місця ( у всі місця).\nХай за мене ангел скаже Господу,\nЩо услід я за Христом іду.\n\nКуплет 2\nСкільки душ блукає у гріхах і тьмі,\nСкільки сліз гарячих пролито людьми... \nДе недуги мучать душу, де печаль,\nРозказать там хочу про Христа.\n\nКуплет 3\nДе в домах незгода і тривожно жить,\nДе дітей молитись не хочуть учить,\nТам де зло і п’янство - темнота ума,\nПро Христа звістити хочу там.', '', '', '', '', 'ua', 0, NULL),
(248, 'Ми по водах океану', 0, 11, 'Куплет 1\nМи по водах океану .\nДрузі, в рідний Край пливем;\nТам за грізними водами,\nВідпочинок ми знайдем!\n\nПриспів: \nНезабаром стихне море,\nЯкір кинемо ми скоро.\nВ Небесний край ми увійдем\nДе не буде більше плачу,\nДе проблем я не побачу,\nТам вічну радість ми знайдем.\n\nКуплет 2\nПрипливем і кинем якір, де кінець журбі, сльозам; \nУвійдем в той Край прекрасний, будем вічно жити там.\n\nКуплет 3\nСкільки, скільки вже приплило до завітних берегів,\nЄ ще місце в тій Країні і для інших моряків.', '', '', '', '', 'ua', 2, NULL),
(249, 'Беззахисні тьмою вкриті', 0, 11, 'Куплет 1\nБеззахисні, тьмою вкриті, поміж хвиль учні пливуть. \n«Спасе, чи тобі байдуже? Поможи!» - Вони зовуть. \nМоре страшно розігралось, у скалистий берег б’є; \nШум вітрів не замовкає, буря стогне і реве.\n\nКуплет 2\nПроясніло, буря втихла, - все Господь перемінив,\nІ розлючені Він хвилі Своїм словом усмирив. \nЗаспіваєм: «О, Спаситель, Алілуя, честь Тобі!\nВід усього Хоронитель, впокорив Ти все Собі».\n\nКуплет 3\nО, душе! Куди прямуєш ти в житті цім без Христа? \nГріх, як хвилі, заливає,- не спасти тобі життя!\nКлич на поміч ти Ісуса,- Він за тебе кров пролив,\nЙ Він спасе тебе від бурі; Силу зла Він переміг.', '', '', '', '', 'ua', 0, NULL),
(250, 'Мир повний мир', 0, 11, 'Куплет 1\nМир, повний мир! -І там, де марнота,\nНебесний мир дає нам кров Христа.\nМир, повний мир Сам Бог нам подає,\nНадія на Христа нам мир дає.\n\nПриспів: \nМир, повний мир! (Мир, повний мир2р.) \nХоч (хоч зло навкруг) зло \nНавкруг кипить (навкруг кипить),\nТільки в Христі Ісусі.\n(Тільки в Христі Ісусі мир царить),\nМир царить, так мир царить,\nТак, (так, мир царить) мир царить,\nТак, мир царить.\n\nКуплет 2\nМир, повний мир! - Вдалі від дорогих:\nБог їх хоронить на путях земних; \nМир, повний мир, хоч тьма є впереді;  \nХристос - наш Цар, і сила наша в Нім!\n\nКуплет 3\nМир, повний мир! - Хоч смерть навкруги нас,-\nЇї вже переміг Спаситель наш.\nКоли ж кінець земній борні прийде,\nХристос в небесний дім всіх нас візьме.', '', '', '', '', 'ua', 0, NULL),
(251, 'Наш Спаситель Ісус', 0, 11, 'Куплет 1\nНаш Спаситель Ісус смерть прийняв за всіх нас, \nЩоб ми грішні життя осягли;\nНа хресті постраждав Він в призначений час, \nЩоб простити всі наші гріхи.\n\nПриспів: \nНа хресті Божий Син\nЗа всіх нас кров пролив.\nО, ж тяжко Спаситель страждав!\nЗа гріхи наші Він на хресті умирав,\nІ спасіння Він нам дарував.\n\nКуплет 2\nМилосердно й ласкаво приймає Він нас,\nІ прощає провини нам всі;\nСам Спаситель Христос відкупив усіх нас \nІ дає нам небесний спокій.\n\nКуплет 3\nВсі до Спаса прийдім, і ми будемо з Ним \nЖити в правді святій кожний день;\nА Він буде навчати нас Словом Своїм \nІ введе нас у Царство Своє.', '', '', '', '', 'ua', 0, NULL),
(252, 'Христос любові повний', 0, 11, 'Куплет 1\nХристос-любові повний,\nВ Нім світло й благодать.\nВін - Манна, Хліб небесний,\nВін - наша сила й щит;\nВ Нім наше відкуплення, життя в Нім без кінця:\nВ Нім звершене спасіння, спочинок для борця.\n\nПриспів: \nЛиш в Нім (Однім)! (2р.)\nІ благословіння повнота лиш в Нім. \nЛиш в Нім (Однім)! (2р.)\nВся повнота лиш в Нім (Однім).\n\nКуплет 2\nТепер я спочиваю, - не вискажуть уста,\nЯкий спокій в Нім маю, як любе з Ним життя!\nЯ в серці Його маю, і Він - моя хвала;\nВ душі Йому співаю за всі Його діла.\n\nКуплет 3\nКоли побачу, Боже, Тебе лицем в лице,\nТоді іще дорожчим Ти будеш для мене;\nТоді за всі даяння Тобі віддам хвалу\nЗа те, що від страждання Ти душу спас мою.', '', '', '', '', 'ua', 0, NULL),
(253, 'Хвала Тобі Христос Господь', 0, 11, 'Куплет 1\nХвала Тобі, Христос Господь,\nЩо Ти нас спас від зла-негод.\nЗа нас Ти на хресті страждав,\nЖиття загиблим дарував. Алілуя! Амінь.\n\nКуплет 2\nЄдинородний Божий Син! \nЗа безліч наших же провин, \nПрийняв Ти наше тіло й кров,\nСвою Ти проявив любов, Алілуя! Амінь.\n\nКуплет 3\nХто дав Вселенній рух, життя,\nЛежав у яслах, як Дитя\nНайкращий приклад всім подав,\nВ любові жить заповідав. Алілуя! Амінь.\n\nКуплет 4\nВін світло правди нам відкрив,\nЛюбов’ю зло Він переміг.\nІ на Голгофі постраждав, -  \nДітьми своїми нас назвав. Алілуя! Амінь.\n\nКуплет 5\nЗвершив предивне діло Спас:\nВід смерті врятував Він нас,\nХвала, о Богочоловік,\t\nТобі віднині і повік! Алілу! Амінь.', '', '', '', '', 'ua', 0, NULL),
(254, 'На шляху життя', 0, 11, 'Куплет 1\nНа шляху життя сміліше ми підем,\nКоли будем вірити Ісусу;\nСилу Божу для роботи ми знайдем,\nКоли будем вірити Ісусу.\n\nПриспів: \nЯсним стане шлях тоді,\nРадість серце оживить;\nНе здолає ворог нас,\nКоли будем вірити Ісусу.\n\nКуплет 2\nЗаповіти Божі будуть нам ясні,\nКоли будем вірити Ісусу:\nНаші всі серця наповнить Дух СВЯТИЙ,\nКоли будем вірити Ісусу.\n\nКуплет 3\nЖити будемо, як Вічний Бог велить,\nКоли будем вірити Ісусу;\nСерцем чистим будем в яснім небі жить,\nКоли будем вірити Ісусу.', '', '', '', '', 'ua', 0, NULL),
(255, 'Минула ніч', 0, 11, 'Куплет 1\nМинула ніч і день настав, Господь, хвала Тобі!\nТи мирний, тихий сон послав, був захистом мені.\n\nКуплет 2\nСьогодні, Боже, помагай з Тобою свято жить, \nЛюбити, вірити навчай, усім добро робить!\n\nКуплет 3\nЩо жде мене, не знаю я, та вірю - приймеш Ти,\nКоли скінчу моє життя, в край вічний і святий.', '', '', '', '', 'ua', 0, NULL),
(256, 'Ми зібрання закінчили', 0, 11, 'Куплет 1\nМи зібрання закінчили і додому йдем, -\nВсе, чого ми научились, у серця візьмем.\n\nПриспів:\nМирно-тихо і спокійно додому підем,\nСлово Боже, що ми чули, виповнять будем.\n\nКуплет 2\nОтож будемо ми завжди на зібрання йти \nІ учитися тут правди, як життя вести.\n\nКуплет 3\nДасть Бог жити, ми зійдемось на зібрання знов,\nЧи то в будень, чи в неділю - прославлять Його.', '', '', '', '', 'ua', 0, NULL),
(257, 'О Боже йду я відпочить', 0, 11, 'Куплет 1\nО, Боже, йду я відпочить у тишині нічній\nІ в руки віддаюсь Твої, мій Отче Всеблагий!\n\nКуплет 2\nО, Боже! Ти зі мною будь і в сні охороняй,\nЩоб тілом відпочив я тут, й душі спочинок дай!\n\nКуплет 3\nКоли ж по волі вже Твоїй сном смертним я засну, \nПрийми утомлений дух мій в Країну неземну. Амінь.', '', '', '', '', 'ua', 0, NULL),
(258, 'На спокійних хвилях моря', 0, 11, 'Куплет 1\nНа спокійних хвилях моря вдаль кудись човен пливе.\nВсюди тиша. У просторі небо ясне, голубе.\nОсь схопилася раптово буря, й хвилі заревли. \nСеред моря страшно стало,- чорні хмари налягли.\n\nКуплет 2\nМандрівці зніяковіли, у зневір’я впали враз;\nСтрашно! Де ж узяти сили? Віру тратять в грізний час. \nТам Один лиш спочиває на кермі після трудів;- \nМоряки Його благають, і Він голову підвів.\n\nКуплет 3\n«Встань, Учителю, дивися! Чи байдуже це Тобі?\nВстань, Благий, розпорядися: в морі грізнім тонем ми! »\nВін устав і, погрозивши, змовкнуть бурі приказав,\nІ друззям за маловірство співчутливо докоряв...\n\nКуплет 4\nТак у нас в життєвій битві від страху душа тремтить, \nТа Христос через молитви своїх вірних захистить.\nХай утіхою Він буде для знеможених сердець,\nІ для гинучих усюди - вірний Пастир і Отець.', '', '', '', '', 'ua', 0, NULL),
(259, 'Так той день вже близький', 0, 11, 'Куплет 1\n1-5. Так, той день вже близький,\nДень великий, страшний,\nКоли всі народи враз стануть перед Судом.\n1. Браття і сестри розлучаться (Зр.)\nНавіки, раз на все.\n2. Мужі з жонами розлучаться, (Зр.)\nНавіки, раз на все.\n3. Діти з батьками розлучаться, (Зр.)\nНавіки, раз на все.\n4. Пастирі з стадом розлучаться, (Зр.)\nНавіки, раз на все.\n5. Що тут посіяв, то там пожнеш, (Зр.)\nНавіки, раз на все.', '', '', '', '', 'ua', 0, NULL),
(260, 'За Євангельську ми віру', 0, 11, 'Куплет 1\nЗа Євангельську ми віру, як один в борню ідім,\nІ, за прикладом Христовим, всі вперед, вперед за Ним!\n\nПриспів: \nДружно, радісно підемо,\nЯк один, в борню зі злом,\nЩирим серцем, одним духом \nЗа Спасителем Христом!\n\nКуплет 2\nБоротьба іде завзята, і кипить жорстокий бій, —\nЗа Христову ми науку піднесем прапор святий!\n\nКуплет 3\nСвіт байдужий не вважає на Спасителя-Христа;\nМи ж стоять за правду будем, за Його святі слова.\n\nКуплет 4\nВіра в Бога - наша сила: Він на поміч поспішить.\nЗброя в нас, як в Гедеона, - переможем нею зло.\n\nКуплет 5\nПовні віри в перемогу правди Божої над злом,\nСміло, радісно ідімо за Начальником-Христом!', '', '', '', '', 'ua', 0, NULL),
(261, 'Друже Як хочеш свій гріх подолать', 0, 11, 'Куплет 1\nДруже! Як хочеш свій гріх подолать, - \nЄ сила в крові, сила в крові!\nСерцем в свободу Христову ввійти, - \nЄ сила в Його крові.\n\nПриспів: \nСила Божа чудодійная -\nВ крові (в крові) Христа (Христа),\nСила Божа чудодійная -  \nУ пречистій крові Христа.\n\nКуплет 2\nХочеш ти пристрасть і гордість вмертвить,- \nЄ сила в крові, в крові Христа!\nМоже Христос всі гріхи віддалить:\nЄ сила в Його крові.\n\nКуплет 3\nХочеш ти бути біліший за сніг, - \nЄ сила в крові, в крові Христа! \nКров’ю Ісус тебе може обмить: \nЄ сила в Його крові.\n\nКуплет 4\nГосподу хочеш ти вірно служить, - \nЄ сила в крові, сила в крові!\nХочеш життям ти Ісуса хвалить, - \nЄ сила в Його крові!', '', '', '', '', 'ua', 0, NULL),
(262, 'Докіль будеш спати', 0, 11, 'Куплет 1\nДокіль будеш спати, о любий мій друже,\nХіба ти не чуєш святих слів Христа?\nПочуй, як ласкаво тебе Він все кличе!\nЧому не проснешся від сплячки-гріха?!\n\nКуплет 2\nХристос тебе кличе, - прийди ти до Нього, \nСклади свій тягар і гріховне ярмо:\nВін все може зняти, тягар облегчити, —\nІ більше не будеш носити його.\n\nКуплет 3\nСьогодні Він кличе, - покайся негайно,\nЧас лине-минає, - Христові віддайсь,\nБо скоро замовкне цей зов благодаті.\nТоді буде пізно спасіння шукать.\n\nКуплет 4\nЗове Він, бо любить, як батько і мати: \n«Прийдіть всі до Мене, прийміть благодать». \nБажаю, мій друже, тебе запитати:\nЯк довго ти будеш без Бога блукать?\n\nКуплет 5\nТобі раджу, друже, скоріш навернися, —\nІсус усіх хоче до себе прийнять.\nПрийди днесь до Нього, прийди, не барися!\nХристос Сам спасіння тобі хоче дать.', '', '', '', '', 'ua', 0, NULL),
(263, 'Був ти друже на Голгофі', 0, 11, 'Куплет 1\nБув ти, друже, на Голгофі, де Христос страждав,\nЯкі рани там глибокі Він за нас прийняв?\n\nКуплет 2\nЧи ти бачив, скільки крові з ран святих стекло, \nБачив той вінок терновий на чолі Його?\n\nКуплет 3\nЧи ти чув розпуки слово: «Боже, Боже Мій!\nЧом лишив Мене Самого в боротьбі тяжкій?!..’.»\n\nКуплет 4\n«Я прийшов до них з любов’ю, прагну їх спасти,\nА вони Мене розп’яли... Боже, їм прости!\n\nКуплет 5\nЗавершилось! -І до Твоїх, Отче, рук святих \nВіддаю Мій дух покірно,-Ти його прийми!»\n\nКуплет 6\nДруже, знай, що задля моїх і твоїх провин\nМусів тяжко так страждати Святий Божий Син.\n\nКуплет 7\nТому, друже, зараз-нині на Fолгофу йди,\nВ ногах Господа Ісуса весь твій гріх зложи.\n\nКуплет 8\nА із уст Його почуєш ті слова любві:\n«Ще сьогодні ти зі Мною будеш у раю»;', '', '', '', '', 'ua', 0, NULL),
(264, 'Гopa Сіон гора святая', 0, 11, 'Куплет 1\nГopa Сіон - гора святая, \nПрестол там Господа стоїть.\nТуди всім серцем моїм лину, \nДе Сонце вічнеє горить.\n\nКуплет 2\nДе бур нема; то край спокою,\nДе радості лунає спів,\nДе все в красі, у сяйві щастя,\nДе вже нема похмурих днів.\n\nКуплет 3\nУ славі там Господь сіяє \nПоміж відкуплених Своїх;\nВін сльози їх утер навіки \nІ втішив вічним щастям їх.\n\nКуплет 4\nХваління ллється з уст спасенних,\nТам співи радості звучать, -\nЗемна ніяка людська мова\nНе може слів тих передать.\n\nКуплет 5\nО, скоро, скоро я там буду\nЗ Христом на тій горі святій:\nВін спас мене Своєю кров’ю,\nМій Відкупитель - Пастир мій.', '', '', '', '', 'ua', 0, NULL),
(265, 'Ви блудите і б’єте ноги', 0, 11, 'Куплет 1\nВи блудите і б’єте ноги, - спасіння хочете знайти,\nАле чи знаєте дорогу, яким вам шляхом треба йти?\n\nКуплет 2\nІдіть дорогою ви правди, до злих на раду не ходіть, \nЛюбіте ворога, як брата, то раєм зробиться цей світ.\n\nКуплет 3\nКоли ж ще мучитесь душею, - моліться: «Господи, прости!»\nНе допускайтеся, щоб Каїн у серці місце міг знайти.\n\nКуплет 4\nЧитайте Божу Святу Книгу, - в ній все ви можете знайти; \nВона покаже ту дорогу, якою треба вам іти.', '', '', '', '', 'ua', 0, NULL),
(266, 'Не сумуй ти душе дорогая', 0, 11, 'Куплет 1\nНе сумуй ти, душе дорогая,\nНе журися, а радісна будь!\nЖиття краще тебе дожидає:\nЛюбить всіх нас Господь, не забудь.\n\nКуплет 2\nУповай ти на Господа Бога \nІ частіше молися в тиші,\nТо затихне у серці тривога,\nІ одержиш спокій для душі.\n\nКуплет 3\nВ світі хвилі бушують, як в морі,\nВітер страшно і дико шумить;\nАле глянь, як ласкаво в тім горю \nНа тебе твій Спаситель глядить.\n\nКуплет 4\nТут терпіти уже нам недовго, - \nМи готові стоять в боротьбі;\nПерейдем у житті труд і горе,\nІ ввійдемо у вічний спокій.\n\nКуплет 5\nПристань тиха усіх нас чекає,\nБурних хвиль і тривог там нема;\nКраще сонця Господь там сіяє,\nІ для вірних там радість свята.\n\nКуплет 6\nНе сумуй же, душе дорогая,\nНе журися, а радісна будь: \nВ небі наша Країна святая, -\nВсі спасенні спокій там знайдуть!', '', '', '', '', 'ua', 0, NULL),
(267, 'Не знав я Ісуса', 0, 11, 'Куплет 1\nНе знав я Ісуса - життя я не знав:\nБез Божого світла у тьмі я блукав.\nАж чую я голос - Господні слова:\n«Він любить, Він любить!» - то любов Христа.\n\nПриспів: \nЯ жив у гріхах (я жив у гріхах),\nХристос мене спас (Христос мене спас); \nВін любить (2р.): Він умер за нас!\n\nКуплет 2\nКоли утомлюся в земній боротьбі,\nСпокою не знайду я тут для душі, - \nТоді чую голос - Господні слова:\n«Він любить, Він любить!» - то любов свята.\n\nКуплет 3\nХристові довіривсь і Ним я живу, - \nДолиною смерті без страху іду;\nІ Він не покине, твердять слова знов:\n«Він любить, Він любить, бо Він є любов!»', '', '', '', '', 'ua', 0, NULL),
(268, 'Не піддайсь спокусі', 0, 11, 'Куплет 1\nНе піддайсь спокусі, бо впадеш у гріх;\nПрикладом будь добрим у житті для всіх,\nІ зі злом борися, гніватись не смій, - \nНа Христа дивися: Він - Заступник твій!\n\nПриспів: \nСпаса зови на поміч:\nВін - твій добрий приятель,\nВчує твоє благання і дасть поміч тобі.\n\nКуплет 2\nУникай ледарства, не гріши в словах,\nІ шануй все Бога, май Господній страх.\nСвято, чесно, мудро живи у любві, - \nНа Христа дивися: Він - Заступник твій.\n\nКуплет 3\nТому, хто у світі воює з гріхом,\nБог вінець дарує і життя з Христом.\nБрате мій, кріпися і у вірі стій,\nНа Христа дивися: Він - Заступник твій.', '', '', '', '', 'ua', 0, NULL),
(269, 'Коли я до Христа прийшов', 0, 11, 'Куплет 1\nКоли я до Христа в гріхах прийшов,\nВін взяв мої гріхи; Він взяв мої гріхи;\nІ замість смутку радість я знайшов:\nВін взяв мої гріхи.\n\nПриспів: \nМої гріхи Він взяв (2р.)\nІ серцю радість дарував,\nЯ рад, що мої гріхи Він взяв\nІ радість дарував.\n\nКуплет 2\nТягар гріхів для мене був тяжким,\nВін взяв мої гріхи, Він взяв мої гріхи;\nІ я на Нього мій тягар зложив:\nВін взяв мої гріхи.\n\nКуплет 3\nОсудження для мене вже нема, -\nВін взяв мої гріхи, Він взяв мої гріхи;\nІ досконалий спокій мені дав:\nВін взяв мої гріхи.\n\nКуплет 4\nКоли й ти прийдеш до Христа тепер,\nТвої гріхи візьме, твої гріхи візьме:\nВін і тобі у серце радість дасть,\nТвої візьме гріхи.', '', '', '', '', 'ua', 0, NULL),
(270, 'Небо місце є святе', 0, 11, 'Куплет 1\nНебо місце є святе, повне ласки і любві:\nГріх не може там ввійти. І ворота чисті там, - \nНе для грішних місце там: гріх не може там ввійти!\n\nПриспів: \nГріх не може там ввійти, (2р.)\nТак, всіх грішних суд там жде,\nДруже, не дури себе:\nТи з гріхом там не ввійдеш.\n\nКуплет 2\nЯк захоч туди ввійти, як мине твоє життя,\nСвітлість ясна в домі тім: тож з гріхів очистися,\nМай в собі життя Христа: гріх не може там ввійти!\n\nКуплет 3\nЖити можеш у гріхах, благодаті не приймать,- \nТа не можеш там ввійти! Тебе здержать при дверях \nІ не впустять до Христа: гріх не може там ввійти!\n\nКуплет 4\nЯк грішити ти будеш й так життя це перейдеш, - \nВ пітьму вічну підеш ти, в місце те, де будуть всі \nТі, що жили у грісі: гріх не може там ввійти!', '', '', '', '', 'ua', 0, NULL),
(271, 'Гей борці Христові', 0, 11, 'Куплет 1\nГей, борці Христові, сміло в бій спішіть,\nПереможний прапор в гору піднесіть!\nСам Гетьман Небесний нас усіх веде,\nПолки в нас завзяті, грізний бій буде!\n\nПриспів: \nГей, борці Христові, в ряд ставайте враз, \nБо ворожі лави ідуть проти нас!\n\nКуплет 2\nАле злобний ворог врозтіч весь піде,\nЯк почує вістку: Наступ Бог веде!\nВже ворожі сили зі страху тремтять,\nГей, в ім’я Господнє час нам наступать!\n\nКуплет 3\nЄвангельське військо до бою іде,\nСміло, мов герої, бо Христос веде!\nМи не розділені, одне тіло ми,\nМи одного духа, Божі воїни.\n\nКуплет 4\nВсі світські престоли час руйнує геть,\nА Церкву Христову не здолає смерть,\nХристової Церкви пекло не звалить,\nБо Вона на Скелі - на Христі стоїть.\n\nКуплет 5\nЛюди, діти Божі, в наш табір спішіть,\nПід наш Євангельський прапор всі ідіть,\nЗ нами разом в співах Спаса прославлять,\nІ тоді відступить весь ворожий світ.', '', '', '', '', 'ua', 0, NULL),
(272, 'Вождь наш перемагає', 0, 11, 'Куплет 1\nВождь наш завсіди перемагає,\nПанцир любові на Нім;\nМеде Він військо Своє вірне, - \nСтроєм у битву йдуть всі.\nГлянь! Як всі сміло вступають\nВ бій проти зла, сатани,\nІм’я Христа викликають;\nСлухай, що кажуть вони:\n\nПриспів: \nНе для швидких перегони,\nЙ не для сильних боротьба,\nА перемога для вірних \nПо благодаті Христа.\n\nКуплет 2\nВсіх переможе Вождь наш сильний.\nХто ж Цей Чудовий є Цар?\nЧиє це військо, що веде Він,\nА спів лунає до хмар?\nВін — наш Господь і Спаситель,\nЩо переміг смерть і зло, - \nА борці Його - то вірні \nСлуги держави Його.\n\nКуплет 3\nПеремагає Вождь наш в битвах,\nІ довершить Він усе.\nЦарства й престоли світа цього \nСпаситель наш обійме.\nТоді Його військо вірне,\nЩо устоїть до кінця,\nБуде з Ним вічно у Царстві,\nУ славі Бога Отця.', '', '', '', '', 'ua', 0, NULL),
(273, 'Непереможний ми маємо прапор', 0, 11, 'Куплет 1\nНепереможний ми маємо прапор,\nВ бою за віру його підіймем!\nБог нас здобув Собі в вічне насліддя,\nНам перемогу дарує з Христом.\n\nПриспів: \nВсі за Ісусом, всі за Ісусом,\n(Всі за Ісусом сміло) (2р.)\nРадісно в бій ми підем, (ми підем),\nПовну одержим ми перемогу, \n(Повну одержим ми над злом \nПеремогу, сміло!).\nВсі за Ісусом сміліш, (всі сміліш)!\n\nКуплет 2\nЛюдську залишимо в світі ми славу;\nВзявши свій хрест, Його смерть сповістім. \nКоли страждаємо з Ним в цьому світі.\nТо в вічній славі будемо з Ним.\n\nКуплет 3\nЗ радістю приймемо ганьбу від світу,\nЗ радістю скажемо всім про Христа;\nМи покладаєм на Нього надії,\nЩиро Його славлять наші уста.\n\nКуплет 4\nБог дарував нам могутнюю силу, - \nВорога нею Христос переміг.\nНею одержим і ми перемогу \nІменем Вічного Господа Сил.', '', '', '', '', 'ua', 0, NULL),
(274, 'Коли я чую про Христа', 0, 11, 'Куплет 1\nКоли я чую про Христа, я в серці веселюсь,\nТоді співаю в простоті: Спаситель мій Ісус.\n\nКуплет 2\nКоли на тьму земного зла, де гинув, подивлюсь \nТоді звучить моя хвала: Спаситель мій Ісус!\n\nКуплет 3\nВ якій безодні потопав, — згадати я боюсь;\nГосподь мене урятував, Спаситель мій Ісус!\n\nКуплет 4\nУ світі я без Бога жив, тепер же я учусь \nУ Тебе, як Творця любить, Спаситель мій Ісус!\n\nКуплет 5\nПеред Тобою мертвим був, - тепер я веселюсь:\nМій дух від смерті оживив Спаситель мій Ісус!\n\nКуплет 6\nТи радість дав душі моїй, і я тепер молюсь, \nЩоб цілий світ Тебе пізнав, Спаситель мій Ісус', '', '', '', '', 'ua', 0, NULL),
(275, 'З Ісусом жити радісно', 0, 11, 'Куплет 1\nЗ Ісусом жити | радісно, (Зр.)\nВін нас веде в завітний Край, чудовий, світлий Край.\n\nПриспів: \nО, Ісус Спаситель! Ти вічно мій,\nТи вічно будеш мій найкращий друг.\n\nКуплет 2\nМене від смерті І відкупив (Зр.)\nІ словом правди відродив, мене Він відродив.\n\nКуплет 3\nСвятого Духа | Він послав (Зр.)\nІ Духом Він мене хрестив, і серце оживив.\n\nКуплет 4\nЯ буду Бога І прославлять (Зр.)\nЗа радість ту великую і милість вічную.\n\nКуплет 5\nЙого всім серцем І я люблю, (Зр.)\nЖиття своє я віддаю, Йому я віддаю.', '', '', '', '', 'ua', 0, NULL),
(276, 'О Спаситель мій', 0, 11, 'Куплет 1\nО, Спаситель мій, чую голос Твій,\nГолос любий, неземний!\nПромінь віри враз душу оживив,\nПолум’ям любві зогрів.\n\nПриспів: \nБлижче, ближче до Твого хреста,\nДе вмирав Ти за мене,\nБлижче, ближче, ближче до Твого хреста, \nГосподи, веди мене!\n\nКуплет 2\nСвітлом істини, о Спаситель мій,\nМоє серце осіяй,\nВсе життя візьми, - я віднині Твій, - \nМудрість для служіння дай!\n\nКуплет 3\nПонад світла всі, що у світі цім,\nНайяснішим є Христос...\nСили дай мені, о Спасителю,\nЩоб світильник мій не згас!', '', '', '', '', 'ua', 0, NULL),
(277, 'Ми у Христі вже', 0, 11, 'Куплет 1\nМи у Христі вже, -- не під законом:\nПрощені всі ми навіки Богом, - \nЗа нас Спаситель Сам постраждав,\nРаз назавсіди нас оправдав.\n\nПриспів: \nРаз Він страждав! О, грішнику, знай!\nЗа нас вмирав, - подяку віддай!\nТягар гріховний Син Божий зняв з нас,\nРаз назавсіди Спаситель спас.\n\nКуплет 2\nТепер ми вільні - нема осуду,\nХристом спасенні, з Ним жити будем.\n«Прийдіть до Мене!» - звучать слова:\n«Я відкупив вас кров’ю хреста».\n\nКуплет 3\nБожі ми діти, - То наша слава!\nВся честь Христові, хвала й держава!\nВ життя від смерті ми перейшли:\nНаше спасіння в Христі знайшли.', '', '', '', '', 'ua', 0, NULL),
(278, 'Любий Спасе будь зі мною', 0, 11, 'Куплет 1\nЛюбий Спасе, будь зі мною, як покриє тьма мене,- \nВ час, як бурхають зла хвилі, дай й тоді любить Тебе!\n\nПриспів: \nСпасе мій, Тебе я люблю (більш і більш),\nІ буду любити більш, (більше я люблю),\nЯк ввійду в небесну славу, (в місто святе),\nВ місто, де Ти Сам живеш.\n\nКуплет 2\nСпасе мій, Тебе я люблю і до Тебе ближче йду,\nБо не маю тут нікого, Хто б так близько мене був.\n\nКуплет 3\nЯ буду Тебе любити в час моєї праці тут, - \nЗнаю, що як буду вірний, то в Небесний Дім ввійду.\n\nКуплет 4\nЗадля Тебе я покинув всі розкоші в світі цім \nІ тепер живу для Тебе, хочу бути вже Твоїм.', '', '', '', '', 'ua', 0, NULL),
(279, 'Коли в житті момент важкий', 0, 11, 'Куплет 1\nКоли в житті момент важкий, й стискає серце жаль,\nТоді в молитві я святій всю виявлю печаль. (2р.)\n\nКуплет 2\nЄ сила благодатная в її словах живих,\nТаємна, життєдайная свята краса у них. (2р.)\n\nКуплет 3\nЗ душі тягар мов скотиться, і зникне десь сумнів,- \nІ вірить, плакать хочеться... І легко так мені!...', '', '', '', '', 'ua', 0, NULL),
(280, 'Так як пташка утомлена', 0, 11, 'Куплет 1\nТак, як пташка утомлена з ворогами в боротьбі,\nЯк овечка заблукана, так і я, о Боже мій!\n\nПриспів: \nХто б мені (хто б ті крила дав),\nХто б мені дав крила (хто б ті крила дав)\nГолуба (як крила у голуба), (2р.)\nЯ б полетів, полетів,\nПолетів би і заспокоївся;\nЯ б полетів на Голгофу (я б полетів)\nЯ б полетів на Голгофу \nІ там (знайшов би я) спокій.\n\nКуплет 2\nМов червяк, що крильця жде, щоб злетіти від землі,\nЯк невільник, що волі жде, так і я, о Боже мій!\n\nКуплет 3\nЯк ріка, що все пливе поміж піль, лугів, лісів, -  \nЗ тьмою світло у боротьбі, так і я, о Боже мій!', '', '', '', '', 'ua', 0, NULL),
(281, 'Прагне правди народ', 0, 11, 'Куплет 1\nПрагне правди народ, світла радості жде...\nСкільки душ ще у тьмі погибає!\nЛиш Спаситель Христос в світ спасіння приніс:\nІз неволі народ свій спасає.\n\nКуплет 2\nВін всі рани зцілить, від злих сил захистить.\nВіддалить і журбу, і страждання. \nСонце правди зійде, любов Божа прийде, -\nВ пісню радості змінить ридання.\n\nКуплет 3\nБраття й сестри, ідіть, вість спасіння несіть,\nЗ тьми гріховної народ спасайте!\nСвоє серце Христу і душі всю красу \nДля свободи людей ви віддайте.\n\nКуплет 4\nВ світі - гріховний вир, звістіть людям всім мир \nІ засмученим слово відради:\nЩо Спаситель воскрес, - двері слави небес \nВідчинив Всім шукаючим правди.\n\nКуплет 5\nВ Царство Боже ввійдем, радість вічну знайдем,\nТам не буде в насильстві людина:\nТам братерство святе всіх людей обійме,\nБудуть жити, як одна родина.', '', '', '', '', 'ua', 0, NULL),
(282, 'Укрий своє горе', 0, 11, 'Куплет 1\nУкрий своє горе від людських очей:\nСліз в світі багато і горя в людей.\nІди та подумай в нічную пору,\nСкажи твоє горе Ісусу Христу.\n\nКуплет 2\nХристос усе знає у горю твоїм, - \nТебе Він утішить на лоні Своїм.\nСвіт Божий сіяє на нашім путі;\nМи тим, що в темряві, те світло несім.\n\nКуплет 3\nСерця так страждають в неволі й нужді,\nІди із любов’ю, - утішиш їх ти.\nУкрий свої сльози, дай радість усім,\nШукай в Христі втіхи у горю твоїм!', '', '', '', '', 'ua', 0, NULL),
(283, 'Тебе я славлю Спасе мій', 0, 11, 'Куплет 1\nТебе я славлю, Спасе мій, всім серцем і життям,\nІ пісня радості й хвали наповнить хай уста!\n\nПриспів: \nО, кров Христа мене спасла (Зр.)\nІ все нове дала. І Нове, (все нове)! (2р.)\nО, кров Христа мене спасла і все нове дала!\n\nКуплет 2\nТомилась все душа моя, коли я жив у тьмі.\nТепер же хай звучить хвала Тобі, о Спасе мій!\n\nКуплет 3\nТяжке життя було в гріхах, тепер спасен вже я: \nОбмитий кровію Христа, о, як щасливий я!', '', '', '', '', 'ua', 0, NULL),
(284, 'Утіху небесную для сердець', 0, 11, 'Куплет 1\nУтіху небесную для сердець\nНам послав Отець, (2р.)\nДля радості нині зібрав Він нас, - \nЧесть Йому за втішний час!\n\nПриспів: \nВсім привіт, (всім привіт)! (2р.)\nБраттям, сестрам всім привіт, (всім привіт)! \nБог відкрив (відкрив нам)\nСвітлий край (світлий край).\nБудем радуватись в Нім!\n\nКуплет 2\nВ зібранні спасенних в Ім’я Його \nІсус буде Сам: (2р.)\nВін хоче, щоб з Ним вічний наш союз \nВ благодаті все зростав.\n\nКуплет 3\nУтіхи тієї не знає світ,\nЩо Господь нам дав. (2р.)\nМолитись ми будем, щоб Він, Благий,\nВічно з нами пробував.', '', '', '', '', 'ua', 0, NULL),
(285, 'Дорогі нам хвилини', 0, 11, 'Куплет 1\nДорогі нам хвилини Господь дарував,\nЛюбі браття і сестри в Христі!\nСам Господь з нами є, як Він нам завіщав,\nЙому даймо в серці простір!\n\nКуплет 2\nО, як радісно стрінутись з вами, брати.\nІ неспокій забувши зовсім,\nВеселитися разом у Дусі Святім,\nВ Господнім єднанні усім.\n\nКуплет 3\nВ Край Небесний ми в світлі Христовім ідем.\nВідпочинем, де Божий струмінь... \nПідкріпім свої сили і далі підем \nЗ Ісусом, як народ один.\n\nКуплет 4\nУ святому єднанні при Божих очах \nМи забули страждання путі:\nСвіжі сили знайшли у Господніх словах, \nЩоб сміло і радісно йти.\n\nКуплет 5\nМи в єднанні усі за Ісусом Христом,\nНа Начальника віри глядім, - \nЗодягнувшись у броню, під вірним щитом \nВперед, браття, дружно ідім!', '', '', '', '', 'ua', 0, NULL),
(286, 'Ми ждемо Христа Спаса', 0, 11, 'Куплет 1\nМи ждемо Христа-Спаса, як прийде, (2р.)\nМи ждемо Ісуса, що нам приготовив \nВідпочинок у Царстві Своїм.\n\nКуплет 2\nМи стрінем Христа-Спаса, як прийде, (2р.) \nМи стрінем Ісуса, - Він руки простягне \nІ візьме нас, де Сам завіщав.\n\nКуплет 3\nПобачать Його в славі, як прийде, (2р.) \nПобачать Ісуса і ті, що розп’яли,\nІ цілий світ заплаче тоді.\n\nКуплет 4\nО, друже, що ти скажеш, як прийде, (2р.) \nЯк Господь спитає, що зробив з талантом, \nЧи придбав що ним, чи закопав?\n\nКуплет 5\nЗаплачеш, друже, гірко, як прийде, (2р.)\nО, тобі, небоже, тоді не поможе,\nБо те місце сам ти заробив.', '', '', '', '', 'ua', 0, NULL),
(287, 'Де згода в сімействі', 0, 11, 'Куплет 1\nДе згода в сімействі, там мир і тишина; \nЩасливі там люди, блаженна сторона: \nЇх Бог благословляє, добро їм посилає \nІ з ними ввік живе, і щастя їм дає.\n\nКуплет 2\nДе згоди немає, там мир не царить:\nТам Бог не вітає, добра їм не дарить... \nРуйнуються пожитки: Добро їх, їхні дітки \nВсе марно пропаде... все марно пропаде!', '', '', '', '', 'ua', 0, NULL),
(288, 'Христос вийшов з храму', 0, 11, 'Куплет 1\nХристос вийшов з храму з учнями Своїми,\nІ сів на Оливній горі, -\nСкорбними словами, святими устами\nУчив своїх любих друзів.\n\nКуплет 2\n«Скажи нам, Учитель, останнєє слово,\nЩе доки Ти з нами живеш,\nСкажи нам, Учитель, Коли те все буде,\nКоли Ти судити світ прийдеш?» -\n\nКуплет 3\n- У світі почуєте чутки воєнні,\nБо встане народ на народ,\nІ будуть недуги, і голод, і помір,\nІ братськая кров потече.\n\nКуплет 4\nІ зменшиться віра, погасне надія,\nВ серцях охолоне любов,\nІ многії люди тоді поблазняться,\nПроллють неповинную кров.\n\nКуплет 5\nКоли ви гидоту побачите в храмі,\nТо знайте, що Суд при дверях,\nВважайте, щоб двері для вас не закрились,\nДержіть ви світильники в руках.\n\nКуплет 6\nВеликеє горе охопить всю землю,\nІ страшнії муки прийдуть, \nТоді скажуть люди; «Падіть на нас гори!»\nТа гори на них не впадуть.\n\nКуплет 7\nУ тії хвилини бажатимуть смерті,  \nТа смерть від людей відбіжить...\nІ хто в той час буде на даху, чи в полі, \nНехай він додому не спішить.\n\nКуплет 8\nІ сонце померкне, не дасть місяць світла,\nІ зорі із неба спадуть;\nІ мертві воскреснуть, земнії народи\nПрийдуть на Божественний Суд.\n\nКуплет 9\nЗ небес прийде в славі Син Божий на землю \nІ буде, як сонце, сіять;\nІ зібрані діти побачать Ісуса,\nІ в радості будуть стрічать.', '', '', '', '', 'ua', 0, NULL),
(289, 'Хто підійме свій зір', 0, 11, 'Куплет 1\nХто підійме свій зір на Христа на хресті,\nТой одержить спокій для душі.\nДруже мій! Ось поглянь, як Він світ полюбив: \nНа хресті Він за тебе терпів.\n\nПриспів: \nГлянь, глянь, друже, глянь!\nГлянь на рани Христові \nЙ терновий вінець,\nІ пізнай, як Він любить тебе.\n\nКуплет 2\nВід загрози і суду тебе увільнив,\nІ від смерті тебе відкупив.\nСмерть! Де жало й держава твойого буття? Пекло! Де перемога твоя?\n\nКуплет 3\nТемна хмара кругом, смуток душу вповив \nІ стражданнями серце прибив.\nАле глянь на Христа: Він в проміннях сія, \nПравда вічна у Нім і життя.\n\nКуплет 4\nО, чому ж у твоїх невідкритих очах \nВсе байдужість до правди і жах?\nДруже! Глянь на Христа ти в надії живій \nІ одержиш спасіння душі.', '', '', '', '', 'ua', 0, NULL),
(290, 'Бог з тобою до побачення', 0, 11, 'Куплет 1\nБог з тобою, до побачення!\nПуть твій хай охороняє; \nКожний крок хай направляє, - \nБог з тобою, до побачення!\n\nПриспів: \nДоки (стрінемся) ми зустрінемся,\nМи стрінемся в ногах Христа (стрінемся) \nДоки (стрінемся) ми зустрінемся, - \nБог з тобою, до побачення!\n\nКуплет 2\nБог з тобою, до побачення!\nДушу Він хай підкріпляє,\nСилу з неба посилає, - \nБог з тобою, до побачення!\n\nКуплет 3\nБог з тобою, до побачення!\nВін -рятунок у скорботах, \nВ Нім життя твоє укрите, -\nБог з тобою, до побачення!\n\nКуплет 4\nБог з тобою, до побачення!\nНа Христа ти все дивися,\nУ любві Його трудися, - \nБог з тобою, до побачення!', '', '', '', '', 'ua', 0, NULL),
(291, 'О який нам путь відкрився', 0, 11, 'Куплет 1\nО, який нам путь відкрився, щоб ним в Царство Боже йти: \nБожий Син з небес явився, щоб і нас туди ввести.\nВ світі горя Він родився, правди вчив, усім служив,\nУ любві для всіх трудився, був розп’ятий - і ожив.\n\nКуплет 2\nЗ гробу вставши, Він являвся учням своїм сорок днів, \nІ Тома переконався, оглядівши рани сам. \nЇм послать Святого Духа завіщав, щоб прийняли,- \nІ Його голгофські муки плід прекрасний принесли.\n\nКуплет 3\nІ зібрав Христос на гору всіх апостолів Своїх,\nПеред їх відкритим зором Він вознісся там від них.\nТут два мужі їм явились і сказали: «Цей Ісус,\nЩо на Нього ви дивились, прийде вдруге ще на Суд!»', '', '', '', '', 'ua', 0, NULL),
(292, 'Будьте пильні', 0, 11, 'Куплет 1\nБудьте пильні завжди і моліться:\nСкоро наш Господь прийде;\nВін лиш тих візьме у Край Небесний,\nХто Його в молитві жде.\n\nПриспів: \nВір, молись уже недовго,\n(Вір, молись, надійсь на Бога 2р.)\nВір, молись, - Господь велить,\n(Вір, молись, - Господь велить 2р.); \nСкоро Він прийде у славі,\n(Скоро Він прийде у славі (2р.),\nНас візьме, - з Ним будем жить.\n(Нас візьме, з Ним будем жить 2р.)\n\nКуплет 2\nБудьте пильні завжди і моліться!\nВорог правди все не спить,\nВ броню праведності зодягніться.\nІ візьміть ви віри щит.\n\nКуплет 3\nБудьте пильні завжди і моліться!\nБог спасе від всіх гріхів,\nВ силі Божій Духом підкріпіться,\nСтійте твердо в боротьбі.\n\nКуплет 4\nБудьте пильні завжди і моліться!\nБог ласкаво вчує вас,\nНа Ісуса з вірою дивіться, - \nВін поможе в кожний час.', '', '', '', '', 'ua', 0, NULL),
(293, 'Я подорожую тут', 0, 11, 'Куплет 1\nЯ подорожую тут на цій землі,\nЗ кожним днем зближаюсь я до Вітчизни, \nХрест несу щоденно на своїх плечах,\nІду до Вітчизни в святих Небесах.\n\nКуплет 2\nА коли я прийду до небес святих, - \nВ зустріч мені вийде небесний Жених, \nВийде стрічати, мене вітати там у воротах, \nХрест Він з мене здійме і до Себе прийме \nВ святих небесах.\n\nКуплет 3\nВузька і терниста дорога моя:\nЧерез густі терни пробираюсь я,\nІ каміння гострі на путі лежать,\nТерни і каміння все тіло ранять.\n\nКуплет 4\nА коли я прийду і т.д.\nВін рани загоїть, мене успокоїть \nВ святих небесах.\n\nКуплет 5\nГоре та недолю зустрічаю я \nІ часто сльозами заливаюся,\nТа лише надія веселить мене,\nЩо в моїй країні горя не буде.\n\nКуплет 6\nА коли я прийду і т.д.\nУтре мої сльози, змінить в радість горе \nТам у небесах.\n\nКуплет 7\nНавкруг себе бачу я хижих вовків,\nІ часто стрічаю я голодних львів.\nО, як небезпечна дорога моя, - \nДля борні готовим мушу бути я.\n\nКуплет 8\nА коли я Прийду і т.д.\nИ пісню перемоги дасть Він нам навіки \nТам у небесах.\n\nКуплет 9\nЧасто я знаходжусь на вершині скал,\nЧасто зустрічаю ураганів шал:\nРевуть страшні бурі і буйні вітри,\nХотіли б в безодню все мене звести.\n\nКуплет 10\nТа коли я прийду і т.д.\nВізьме нас з Собою, введе в край спокою,-  \nТам, де тишина.', '', '', '', '', 'ua', 0, NULL),
(294, 'Вождь Христос могутній', 0, 11, 'Куплет 1\nВождь Христос могутній в битву нас веде,\nІ нам з Ним не страшно, Він вперед іде.\nЦіль Його висока в мудрості святій,\nСміло з Ним ідемо в бій.\n\nПриспів: \nСміло! Сміло! Так нам Бог велить!\nСміло! Сміло! -Він нас підкріпить;\nРадо й мило - хай наш спів звучить:\nЛиш перемагати - Спас велить.\n\nКуплет 2\nХай наше знамено розвівається, \nЗло Христовим словом подолається.\nНаш Господь Спаситель впокорить цей світ,\nІ за Ним ми йдемо вслід.\n\nКуплет 3\nХоч страшна ще битва, та скоро кінець...\nВірним нагороду готовить Отець:\nДасть нам відпочинок у Царстві Своїм,\nКоли йдемо вслід за Ним.', '', '', '', '', 'ua', 0, NULL),
(295, 'О предвічний Цар Єгова', 0, 11, 'Куплет 1\nО, предвічний Цар Єгова! Путь в пустині освіти,\nІ втомленого, слабого подорожнього веди.\n\nПриспів:\nХліб небесний, (2р.) дай нам, Боже,\nДушу підкріпляй (підкріпляй),\nДай нам (хліб небесний), (4р.) \nХліб небесний, і ним душу підкріпляй!\n\nКуплет 2\nХай струмінь води живої нам поллється із скали;\nХай горить в час тьми нічної світло слів Твоїй Святих.\n\nКуплет 3\nПереміг Христос тьми силу, в небесах Йому хвала.\nЯ стою біля Йордану, а за ним - завітний Край.\n\nКуплет 4\nТут Вождя я дожидаю, - скоро знову Він прийде,\nІ в небесну вічну славу Сам Христос мене введе.', '', '', '', '', 'ua', 0, NULL),
(296, 'О Ісус укрий мене', 0, 11, 'Куплет 1\nО, Ісус, укрий мене в тіні крил спасіння:\nНа хресті Ти умирав, щоб нам дать прощення.\n\nПриспів:\nНа хресті, на хресті Спас нам дав прощення;\nЯ знайшов в ногах Христа для душі спасіння.\n\nКуплет 2\nПри хресті душа моя мир знайшла небесний, \nI Зоря проміння ллє в серце світло ясне.\n\nКуплет 3\nПри хресті, о Боже мій, пошли мені сили,\nЩоб Тобі служить я міг вірно до могили!', '', '', '', '', 'ua', 0, NULL),
(297, 'Дорожчим за все є Христос', 0, 11, 'Куплет 1\nДорожчим за все є Христос для мене:\nЗагине багатство земне;\nЗнайшов у Христі я багатство моє, - \nЩасливий я з Ним над усе.\n\nПриспів: \nЩасливий я всюди з Христом! (2р.)\nЗневажений в світі, я можу сказать: \nЩасливий я завжди з Христом!\n\nКуплет 2\nЯ грішник великий, осуджений був,\nБез Божого Слова блукав,\nСпаситель прийшов, - мене спас, оправдав: \nНасліддя у вічності дав.\n\nКуплет 3\nЛиш жертва одна була в силі спасти\nІ з Богом мене примирить:\nТо мій Відкупитель - за мене Він вмер, \nЩоб з Ним я повіки міг жить.\n\nКуплет 4\nПризвав, научив, правди путь показав \nІ в серце спокій мені дав; \nМолитись Він учить і в світлі ходить,\nЗавіт Його в серці носить,\n\nКуплет 5\nХоч навіть і рідні покинуть мене,\nІ всього лишусь на землі, -  \nХристові віддавсь я, Він любить мене, \nНавік я укриюся в Нім.', '', '', '', '', 'ua', 0, NULL),
(298, 'О Ісус достоєн Ти', 0, 11, 'Куплет 1\nО, Ісус, достоєн Ти слави й честі на землі,\nСлави й честі на землі від нас;  \nІ від серця повноти я співаю все Тобі,\nБуду всюди славити Тебе.\n\nПриспів: \nХорони у світі нас (2р.)\nДай у Тобі пробувать (2р.,)\nПідкріпляй нас в кожний час (2р.)\nЩоб Тебе лиш прославлять! (2р.)\n\nКуплет 2\nТи життя нам дарував, світлом правди осіяв,\nМир небесний в серце нам послав;\nТи нас кровію обмив, наші всі гріхи простив.\nНаші всі гріхи Ти нам простив.\n\nКуплет 3\nТи гріхи мої простив, Свою милість проявив, \nСвою милість проявив до нас:\nТи хорониш в кожний час, утішаєш Духом нас, \nДухом Правди утішаєш нас.', '', '', '', '', 'ua', 0, NULL),
(299, 'Радуйтесь браття', 0, 11, 'Куплет 1\nРадуйтесь, браття, і в піснях духовних, \nСлаву і честь віддавайте Христу:\nВін нас знайшов всіх в неволі гріховній,\nВін об’явив нам любві повноту, (2р.)\n\nКуплет 2\nО, як безмірно нас любить Спаситель! \nОхороняє нас в житті земнім,\nВін приготовив нам святі оселі \nІ нагородить вінцем золотим. (2р.)\n\nКуплет 3\nЗ радістю, браття, за Слово Господнє \nВсякі знущання смиренно терпім:\nБог підкріпить нас на нашій дорозі,\nВ славу введе нас у Царстві Своїм. (2р.)', '', '', '', '', 'ua', 0, NULL),
(300, 'Ой чого так плачеш', 0, 11, 'Куплет 1\n- Ой, чого так плачеш, душе утомлена?\nЧи з путі ти збилась, чи любов завмерла?\n- Я з путі не збилась, любов не завмерла,\nТільки опізнилась, бо була невірна.\n\nКуплет 2\n- Не дивись за братом, дивись за собою,\nНе гонись за прахом, утішайся Бого.\nБо земная слава - для душі отрута, \nХто з нею спізнався, той з Богом розстався.\n\nКуплет 3\nДуховнії хори ти любила слухать,\nА чужі обряди твою душу мучать.\nДуше, пробудися, бо світло явилось,\nПоспішай назустріч, та й не опізнися.\n\nКуплет 4\nЛюди повставали, стають до роботи, \nПрацюють для Бога з доброї охоти.\nА ліниві люди не хочуть робити,\nІ Господу Богу, не хочуть служити.\n\nКуплет 5\nА ви, браття, сестри, в зібрання ходіте,\nУтішайтесь Словом, та й Бога любіте.\nБо хто Бога любить, той Йому і служить,\nА хто Йому служить, того Бог полюбить.\n\nКуплет 6\nО, яка то радість Богові служити,\nА після на небі вічно з Богом жити!', '', '', '', '', 'ua', 0, NULL),
(301, 'Я славлю все Ісуса', 0, 11, 'Куплет 1\nЯ славлю все Ісуса: Він душу спас мою,\nЗа всі мої провини пролив Він кров Свою.\nЯ славлю все Ісуса! Він на хресті вмирав,\nІз темряви страшної Він Сам мене підняв.\n\nКуплет 2\nЯ славлю все Ісуса! Втішає Він мене,\nУ Край, де вічна радість; Він Сам мене веде. \nЯ славлю все Ісуса за всі Його діла,\nЯ славлю милість Божу: вона мене спасла.\n\nКуплет 3\nЯ славлю все Ісуса в долині тут земній,\nІ вірю, буду жити, де Відкупитель мій;\nТам, в царстві всіх спасенних, я буду прославлять \nСпасителя Святого безмірну благодать.', '', '', '', '', 'ua', 0, NULL),
(302, 'Не залишу ніколи', 0, 11, 'Куплет 1\nНе залишу ніколи Святої Біблії:\nВ Христі спасіння вічне дає вона мені.\n\nПриспів:\nНізащо, нізащо я Біблії не залишу,\n(Нізащо я Біблії не залишу, Біблії не залишу).\nНізащо, нізащо цеї Книги Божої,\n(Нізащо не залишу цеї святої Книги Божої).\n\nКуплет 2\nКоли я у спокусі буваю іноді, - \nВона мене навчає, підтримує й тоді.\n\nКуплет 3\nКоли човен мій хвилі в життєвім морі б’ють,\nЯ в Біблії знаходжу єдиний світлий путь.\n\nКуплет 4\nЯ їй лиш довіряю, знаходжу в ній Христа,- \nВ Нім сяє Сонце Правди й любові повнота.', '', '', '', '', 'ua', 0, NULL),
(303, 'Небо і земля', 0, 11, 'Куплет 1\nНебо і земля (2р.) нині торжествують,\nАнгели й люди (2р.) весело святкують,\n\nПриспів: \nХристос родився, Бог воплотився,\nАнгели співають, славу звіщають, \nПастухи вітають, поклін складають, \n«Чудо! Чудо!» - повідають.\n\nКуплет 2\nУ Віфлеємі (2р.) весела новина:\nПречиста Діва (2р.) породила Сина.\n\nКуплет 3\nВітцівське слово (2р.) зодяглося в тіло,\nВ темряві земній (2р.) Сонце засвітило.\n\nКуплет 4\nАнгели служать (2р.) Господеві своєму,\nСпівають: «Слава!» (2р.) Ново родженому.\n\nКуплет 5\nТри володарі (2р.) зі Сходу приходять,\nЛадан і миро (2р.), й золото приносять.\n\nКуплет 6\nМесії своєму (2р.) ті дари складають;\nПастирі людям (2р.) новину звіщають.\n\nКуплет 7\nЙого ми нині (2р.) також величаймо:\n«Слава на небі, і мир на землі!» Йому заспіваймо.', '', '', '', '', 'ua', 0, NULL),
(304, 'Нині радість стала', 0, 11, 'Куплет 1\nНині радість стала, яка не бувала:\nНад вертепом зоря ясна світові засяла.\n\nКуплет 2\nТам Христос родився, з Діви воплотився,\nЯк людина пеленками вбогими вповився.\n\nКуплет 3\nАнгели співають, Христа величають,\nВсім народам цю чудову Новину звіщають.\n\nКуплет 4\nМи також співаймо, Спаса прославляймо,\nВід Марії Родженому хвалу й честь віддаймо!', '', '', '', '', 'ua', 6, NULL),
(305, 'Спас від Діви народився', 0, 11, 'Куплет 1\nСпас від Діви народився, | прийшов днесь Він з небес, \nЩоб спасти люд свій весь, - і світ втішився | (2р.).\n\nКуплет 2\nВ Вифлеємі народився | Ісус Спас - Пастир наш,\nПравди Цар із небес нам об’явився | (2р.).\n\nКуплет 3\nСповістив це ангел Божий уночі пастирям, \nМудрецям-звіздарям - зі Сходу царям | (2р.).\n\nКуплет 4\nЩо за чудо це з’явилось: | де Марія Христа \nВповила, там зоря прийшла і стала | (2р.).\n\nКуплет 5\nІз дарами три царі йдуть | до міста Вифлеем\nІ Народженому поклін віддають | (2р.).\n\nКуплет 6\nХвалу і ми заспіваймо, | і Народженому \nБогові і Царю поклін віддаймо | (2р.).', '', '', '', '', 'ua', 0, NULL),
(306, 'Хай буде Творцеві від нас честь хвала', 0, 11, 'Куплет 1\nХай буде Творцеві від нас честь, хвала!\nГосподня любов нас від смерті спасла.\n\nПриспів: \nАлілуя! Честь і слава, алілуя повік.\nАлілуя! Честь і слава. Бог з нами. Амінь.)\n\nКуплет 2\nСпасителю наш, Тобі слава й хвала!\nБо в Тобі дар спасіння людині знайшла.\n\nКуплет 3\nНаш Отче небесний! У Дусі Святім \nПрославляйся й веди нас у вічний Свій Дім!', '', '', '', '', 'ua', 0, NULL),
(307, 'Благодать Господа', 0, 11, 'Куплет 1\nБлагодать Господа Ісуса Христа і любов \nБога Отця, та єднання Святого Духа,\nХай буде з нами. Амінь.', '', '', '', '', 'ua', 0, NULL),
(308, 'Збудись від сну', 0, 11, 'Куплет 1\nЗбудись від сну, мій дух! Свій страх марний відкинь: \nХристос - твій вірний Друг, страждав за тебе Він, \nЗаступником твоїм Він став, - \nВ небесній книзі записав. (2р.)\n\nКуплет 2\nПоглянь, Спаситель твій за тебе так страждав! \nЩоб ти з Ним вічно жив, Свою Він кров пролляв. \nХристос нас кровію обмив,\nНове життя в нас відродив. (2р.)\n\nКуплет 3\nСпаситель в небесах вже в славі у Отця,\nБлагає Він за нас Предвічного Творця...\nЗ неволі всіх Він відкупив,\nНас, грішних, з Богом примирив. (2р.)', '', '', '', '', 'ua', 0, NULL),
(309, 'О якби ти це знав', 0, 11, 'Куплет 1\nО, якби ти це знав хоч в цей останній день,\nЩо ти за світло дня прийняв лиш тільки тінь.\n\nПриспів:\nКоли б же ти пізнав хоч в цей останній день,\nЩо може дать тобі спокій, - одне, що дасть тобі спокій!\n\nКуплет 2\nО, якби ти це знав, що путь, якою йдеш,\nВеде в безодню — й там ти смерті не минеш.\n\nКуплет 3\nО, якби ти це знав - Хто, повний дивних слів,\nТебе до Себе звав, - прийти ж ти не хотів.\n\nКуплет 4\nО, якби ти це знав, Хто про тебе скорбить,\nЩо ти у гріх упав, - не хочеш в правді жить.\n\nКуплет 5\nО, якби ти пізнав, Хто полюбив тебе,\nХто за тебе віддав на смертний хрест Себе.\n\nКуплет 6\nО, якби ти пізнав Його - Царя душі!\nВ Нім Бог любві сія для тебе й для усіх.\n\nКуплет 7\nО, якби ти пізнав, що Всемогутній Він,\nЗ мольбою б ти упав й смирився перед Ним.', '', '', '', '', 'ua', 0, NULL),
(310, 'Пастир все шукає', 0, 11, 'Куплет 1\nПастир все шукає бідную вівцю,\nЩо десь заблудилась: жаль її Йому.\n\nПриспів: \nКличе тебе, кличе тебе,\nХоче Господь спасти тебе.\n\nКуплет 2\nДрахма дорогая згублена була,\nВ поросі прикрита, - знов віднайдена.\n\nКуплет 3\nРадість з Ним ділити всіх Отець зове:\nБлудний син вернувся і тепер живе.', '', '', '', '', 'ua', 0, NULL),
(311, 'В дикій пустині', 0, 11, 'Куплет 1\nВ дикій пустині безрадно я \nВ смутку проводжу мої літа.\nВ голоді ходжу чужий усім... \nВстану, піду в свій дім! \nХоч сором до Отця йти у дім,\nЩо був колись мені рідний він;\nРад би я стати слугою в нім, - \nВстану, піду в свій дім!\n\nПриспів: \nСерце стремить в рідний дім (Отця), \nВстану, піду в Отчий дім \nТам мій Отець! Піду, (піду!)\nВ рідний мій дім до Отця.\n\nКуплет 2\nЧого ще тут пропадаю я?  \nЖиття немає на чужині!  \nА в домі ріднім - усе там є;\nВстану, піду в свій- дім!\nТяжко я проти Отця згрішив. \nВина моя на мені тяжить. \nХочу признатись, чим провинив.\nВстану, піду в свій дім!\n\nКуплет 3\nО, Боже мій, куди ж я пішов?\nУсі достатки я в Батька мав.\nСам своє щастя я змарнував!...\nВстану, піду в свій дім!\nВ думках я бачу мій рідний дім, - \nЛюбі обличчя у домі тім.\nЩасливий був я Поміж друзів.\nВстану, піду в свій дім!\n\nКуплет 4\nОтець ласкавий прощає всім, - \nПрийме й мене хоч слугою в дім.\nЧого ж ще жду, чого гаюсь я?\nВстану, піду в свій дім!\nЩось то все каже: «Він не забув;\nХоч непослушний Йому ти був, - \nВін тебе любить... Хутчій, хутчій!\nВстань і іди в свій дім!»', '', '', '', '', 'ua', 0, NULL),
(312, 'Радість радість Бог дарує', 0, 11, 'Куплет 1\nРадість, радість Бог дарує, серце, наше веселить, -  \nПромінь щастя, що від Бога, в нас ніщо вже не вгасить!.\n\nКуплет 2\nБог нас Сам веде за руки, підкріпляє в боротьбі, \nНас хоронить від спокуси, помагає у біді.\n\nКуплет 3\nПо слідах підем Христових ми під захистом Його, \nЩоб у битвах всіх суворих не загинуть без Нього\n\nКуплет 4\nРадість віри нехай сяє і, як сонце, в нас горить!\nГрішних Спас лиш визволяє і добром усіх дарить.', '', '', '', '', 'ua', 0, NULL),
(313, 'Ах радість радість', 0, 11, 'Куплет 1\nАх, радість, радість буде там відкупленим серцям, \nКоли закінчим путь свою і будем там, в раю.\nРосте там дерево життя, де вічна неземна краса,\nІ там Гопцодь Спаситель мій царить в любві Своїй.\n\nПриспів:\nАх, що за радість там, радість там, радість дам!.\nАх, що за рад|сть там спасенним буде нам,\nДе всі святії без числа хвалу приносять для Христа!\nІ ми співати там будем, коли туди Прийдем;\n\nКуплет 2\nДорога вузька лиш одна для нас призначена;\nКоли ми нею не підем, спасіння не знайдем.\nКоли ж дорогу ту пройдем, що часто сльози на ній ллєм, \nТо там будем в любві Творця щасливі без кінця.\n\nКуплет 3\nХристос Воскрес,- розсіяв страх і ось,ввеликий час \nВ чудових світлих небесах Він дожидає нас.\n0, любий друже, пам’ятай, що є блаженства вічний край! \nХоч тяжко, трудно в світі нам, та радість буде там.', '', '', '', '', 'ua', 0, NULL),
(314, 'Сказав Господь', 0, 11, 'Куплет 1\nСказав Господь Бог до Ноя: «Я затоплю світ водою \nВ близький час. (4р.)\n\nКуплет 2\nТи ж збудуй собі ковчега для родини і для себе,  \nЩоб спастись». (4р.)\n\nКуплет 3\nНой повірив, - не вагався, будувати ковчег взявся \nВ той же час. (4р.)\n\nКуплет 4\nЛюди Ноя висмівали, - слова правди не приймали: \nГрішний люд... (4р.).\n\nКуплет 5\nПотоп хлинув, як те море, - люди бігли всі на гори, \nТам спастись. (4р.)\n\nКуплет 6\nВоди землю заливали, тоді люди вже благали:\nДе спастись? (4р.)\n\nКуплет 7\nВсі на себе нарікали, чому правди не прийняли:\nГнів прийшов. (4р.)\n\nКуплет 8\nПташки в небі ще літали і рятунку скрізь шукали, \nНе знайшли. (4р.)\n\nКуплет 9\nВоди землю всю покрили, всіх безбожних затопили: \nБожий суд. (4р.)\n\nКуплет 10\nЛише плавав над водами ковчег з Ноєм і синами \nВ хвилях тих... (4р.)\n\nКуплет 11\nЯк ковчег став на вершині,\nЗ Ноєм вийшла вся родина, - | всі спаслись. (4р.)\n\nКуплет 12\nТак, як було за днів Ноя,\nВсім безбожним гірка доля | знов прийде... (4р.)', '', '', '', '', 'ua', 0, NULL),
(315, 'Вище світил небесних', 0, 11, 'Куплет 1\nВище світил небесних, де тьми нема,\nВ тіні дерев чудесних наш Край є там.\nТам зла уже немає, спів ангельський луна;\nВ небесній вічній славі Христос сія.\n\nКуплет 2\nЗа нас тяжкі страждання Ісус терпів.\nІ наше осудження Він кров’ю змив.\nІ смерть Спаситель хресну прийняв від грішних рук, \nПридбав для нас спасіння від вічних мук.\n\nКуплет 3\nІ вас давно Спаситель усіх зове,\nВ небеснії оселі він нас введе.\nЩасливий, хто почує святий Його призив:\nГосподь його обмиє від всіх гріхів.', '', '', '', '', 'ua', 0, NULL),
(316, 'Xриста славте', 0, 11, 'Куплет 1\nXриста славте! Він наш великий Спаситель,\nСпівай, земле, все про любов святу.\nСлавте, славте Його, архангели Божі,\nЧесть віддайте ви за любов Йому.\nВін, як Пастир, дітей Своїх хоронить,\nІ Він носить їх на руках Своїх;\nВірні всі, що з Богом живуть на Сіоні,\nСлавте, славте у піснях радісних.\n\nКуплет 2\nХриста славте! Він наш великий Спаситель,\nВін за гріх наш постраждав на хресті.\nВін Скала й надія вічного спасіння:\nСлавте, славте Ісуса всі святі.\nВін за нас всіх терпів тяжкі страждання,\nВінець з терну Він на чолі носив;\nЗневажений, переніс Він всі знущання.\nРаз навіки Спаситель переміг.\n\nКуплет 3\nХриста славте! Він наш великий Спаситель.\nІ «Осанна» - звучить чудовий спів.\nНаш Спаситель царює в славі повіки,\nЦар, Пророк і Первосвященик Він.\nПереміг смерть! - з радістю сповіщайте.\nСмерть, де ж перемога тепер твоя?...\nВін Воскрес, - вже смерті окови не страшні:\nНаш Спаситель для всіх життя придбав.', '', '', '', '', 'ua', 0, NULL),
(317, 'Було сказано нам', 0, 11, 'Куплет 1\nБуло сказано нам про чудовий той Край,\nПро який учить нас Біблія. Де турбот вже нема,\nНі тяжкого труда, і нема там насильства вже!\n\nПриспів:\nВ тім прекраснім Краю, у небеснім раю,\nХмар грізних не буде уже;\nПройшла смерті тінь, настав вічний день,\nІ повік сонце не зайде!\n\nКуплет 2\nТам у райськім саді овочі золоті,\nВсе цвіте там, немов лілія. Там спасенні серця \nПрославляють Творця, де немає насильства вже!\n\nКуплет 3\nТам оселі для нас приготовив Христос,\nТак украшені, як скинія. Джерело там життя,\nПісня ллється свята, і нема там насильства вже!', '', '', '', '', 'ua', 0, NULL),
(318, 'Дай що найкраще для Бога', 0, 11, 'Куплет 1\nДай що найкраще для Бога, - силу для Нього віддай; \nЙому віддай всі спромоги і за Христом вслід вступай. \nВін приклад для нас залишив, сміло за правду стояв,\nІ тяжко за нас страждав Він, - у жертву життя віддав.\n\nПриспів: \nДай що найкраще для Бога,\nСилу для Нього віддай!\nЗ радістю йди на служіння - \nВсім про спасіння звіщай.\n\nКуплет 2\nДай що найкраще для Бога; в серце Його ти впусти,\nІ для служіння святого Йому усе присвяти.\nВесь на служіння віддайся: Він за нас Сина віддав; \nЖити для Нього старайся, - все, що найкраще - віддай!\n\nКуплет 3\nДай що найкраще для Бога, Він тобі більше вже дав:\nВ небі залишив всю славу, в жертву Себе Він віддав. \nСтраждав за нас Він безвинно, щоб від гріхів всіх спасти; \nДай Йому честь і хваління, все, що найкраще, віддай!', '', '', '', '', 'ua', 0, NULL),
(319, 'О не лякайсь і не страшись', 0, 11, 'Куплет 1\nО, не лякайсь і не страшись: Бог захистить тебе; \nДо Нього завжди ти молись, Бог захистить тебе.\n\nПриспів: \nБог захистить тебе в руках Своїх,\nВ путях твоїх, — Бог захистить тебе,\nБог захистить тебе, (спасе тебе).\n\nКуплет 2\nКоли прийдуть часи трудні, Бог захистить тебе. \nУ небезпеці та в біді Бог захистить тебе.\n\nКуплет 3\nВ біді Він вічний Друг є твій, Бог захистить тебе; \nВ сумнів не падай - в вірі стій, Бог захистить тебе.\n\nКуплет 4\nКоли спокуса тут прийде, Бог захистить тебе, - \nСвій захист Він тобі пошле, Бог захистить тебе.', '', '', '', '', 'ua', 0, NULL),
(320, 'Я знаю що Христос Спаситель', 0, 11, 'Куплет 1\nЯ знаю, що Христос Спаситель \nМісце мені приготував;\nЖиття відкрив для мене вічне,\nДитям Своїм мене назвав.\n\nПриспів: \nНіщо у світі цім мене\nВже від Христа не відійме.\n\nКуплет 2\nТепер Його я дожидаю,\nКоли за мною Він прийде,\nТоді візьме мене до Себе,\nУ Дім Небесний приведе.\n\nКуплет 3\nТому всім серцем довіряюсь,\nХто на хресті вмер за мене,\nДо Його зову прислухаюсь:\n«Скоріш прийди! Я жду тебе».\n\nКуплет 4\nЙoro любов усе здолала,\nВін так за мене постраждав,\nІ кров пролляв Свою невинну, - \nЖиття мені Він смертю дав.\n\nКуплет 5\nСпаситель мій прийде вже скоро\nІ Сам мене туди візьме,\nДе в Царстві правди, Царстві Божім \nМій дух навіки відпочне.', '', '', '', '', 'ua', 0, NULL),
(321, 'Я пришлець в земній долині', 0, 11, 'Куплет 1\nЯ пришлець в земній долині, все навколо - чужина,\nАле вище зір небесних - моя рідна сторона.\n\nПриспів: \nТам країна свята, там Вітчизна моя, - \nТам Отець мій благий, вся родина моя;\nВсі вони в рідній стороні,\nА я блукаю на чужині.\n\nКуплет 2\nТут насильство і неправда, скрізь ненависть і злоба, \nАле там край повний щастя: там любов царить свята.\n\nКуплет 3\nТут мене всі зневажають, ненавидять мене всі,\nАле там всі мене люблять в моїй рідній стороні.\n\nКуплет 4\nТут мене смерть ще лякає в тій похмурій чужині. \nЖиття вічне там чекає мене в рідній стороні.', '', '', '', '', 'ua', 0, NULL),
(322, 'Волі Дух Кайдани тління', 0, 11, 'Куплет 1\nВолі Дух! Кайдани тління із людських сердець здійми, \nДай, щоб дух усиновлення між Твоїми був дітьми.\n\nКуплет 2\nДух, що в день П’ятидесятий на апостолів зійшов, \nБлагодаттю Ти багатий - о, збудуй в нас Свій престол!\n\nКуплет 3\nУтішителю! В скорботі Ти утіху нам пошли,\nПоможи в Твоїй роботі, підкріпляй дітей Своїх.\n\nКуплет 4\nДай дари оздоровлення, дар пророчих дай нам слів,\nА найбільше дарування - нам пошли Ти дар любві.\n\nКуплет 5\nТи на вірних виливаєш благодать на благодать, - \nСвою Церкву укріпляєш, в ній Ти хочеш пробувать.\n\nКуплет 6\nДух любві Отця і Сина, нас, благаєм, оживи;\nХай зіллються всі в єдино у святих ділах любві.', '', '', '', '', 'ua', 0, NULL),
(323, 'Не задля почесті і слави', 0, 11, 'Куплет 1\nНе задля почесті і слави \nУ Край Небесний я стремлюсь.\nХоч шлях змагань важкий, кривавий - \nЯ все ж у вірі тій не гнусь,\n\nКуплет 2\nБо я сподвижник Твій і воїн,\nБо я за Тебе все в борні.\nЧи більша слава є від тої?\nЧи треба більшої мені?\n\nКуплет 3\nНе задля вічного спокою \nУ Край Небесний я стремлюсь;\nХоч і на шлях свій я з тугою \nІ сльози й піт нераз проллю,\n\nКуплет 4\nОдначе труд Твій - насолода \nДля духа дивна і свята, - \nНайвища серцю нагорода:\nВ ній спокій неба процвіта.\n\nКуплет 5\nНе задля благ обітування\nУ Край Небесний я стремлюсь;\nТи дав мені гріхів прощення,\nЙ те щастя дав,що я молюсь.\n\nКуплет 6\nВ нове життя мій дух покликав, \nЙого любов’ю осінив...\nО, як ця ласка є велика!\nПро це я й думати не смів.\n\nКуплет 7\nНе задля вічних втіх неземних \nУ Край Небесний я стремлюсь, - \nЛишень, щоб тут, в скорботах земних, \nВсе проявлять любов Твою.\n\nКуплет 8\nЛюбові пісня тут нерівна,\nІ часто рветься в пітьмі зла, - \nА там поллється в звуках дивних, \nЯк безконечная хвала.', '', '', '', '', 'ua', 0, NULL),
(324, 'В час коли труба', 0, 11, 'Куплет 1\nВ час, коли труба Господня \nНад землею прозвучить,\nІ як вічного дня ранок засія,\nІмена усіх спасенних Сам Ісус оголосить,\nТам по милості Господній буду я.\n\nПриспів: \nВ небесах з Христом я буду,\n(Там по милості Господній буду я),\nВ небесах з Христом я буду,\n(Там по милості Господній буду я).\nВ небесах (в небесах) з Христом я буду, \nТам по милості Господній буду я.\n\nКуплет 2\nВ день останній воскресіння \nВсіх померлих у Христі,\nВ день, коли введе спасенних в дім Царя,\nВсіх святих, омитих кров’ю,\nЩо пролив Він на хресті,\nВін покличе - і тоді відкликнусь я.\n\nКуплет 3\nДай нам сили працювати \nІ для ближніх послужить \nЗ ранку раннього і до заходу дня,\nА коли земну нам працю \nТи дозволиш закінчить,\nТо на поклик Твій небесний стану я.', '', '', '', '', 'ua', 3, NULL),
(325, 'Отець мій багатий', 0, 11, 'Куплет 1\nОтець мій багатий оселями,\nПолями, золотом і перлинами;\nВін скарби Всесвіту держить в руках,\nБагатства безмірні є в Нього для нас.\n\nПриспів: \nЯ наслідник Царя, наслідник Царя,\nЗ Христом Ісусом наслідник Царя.\n\nКуплет 2\nВсевишнього Син - Спаситель людей - \nВін жив на землі тут бідніше усіх,\nТепер в небесах - Заступник за нас;\nЯк прийде, мені Він оселю вже дасть.\n\nКуплет 3\nЗабутий я був на грішній землі,\nВід роду поганин і ріс я у злі,\nПрийнятий тепер, записаний Ним,\nНасліддя від Бога одержу з вінцем.\n\nКуплет 4\nНавіщо мені турботи земні?\nОселі Христом готуються мені.\nЯ тут чужоземець, пісня ж моя:\n«Отцю слава, честь: я наслідник Царя!»', '', '', '', '', 'ua', 0, NULL),
(326, 'Тобі я служити бажаю', 0, 11, 'Куплет 1\nТобі я служити бажаю, мій Спасе, від літ молодих,\nТа сили я мало так маю, а прошу, щоб Ти допоміг.\n\nПриспів: \nСлужити всім серцем, всім тілом Тобі \nЯ буду, зміцни ж мої сили слабі;\nНа славу Тобі все життя посвятить, \nДорогами правди Твоєї ходить.\n\nКуплет 2\nЯзнаю, що Ти мене любиш; о дай, щоб Тебе я любив \nТа вірив, що Ти не погубиш, і завжди з Тобою я жив.\n\nКуплет 3\nДо Тебе молитися завжди навчи, щоб я більше умів \nТвоєї шукав лише правди і людям про неї свідчив.\n\nКуплет 4\nПорою, як сили слабіють і в’яну під спекою дня,\nХай крила святії закриють, зміцнить мене сила Твоя.\n\nКуплет 5\nДо смерті Твоїм хочу бути, служити до гробу Тобі,\nІ в небі з Тобою злучитись у вічній чудовій хвалі.', '', '', '', '', 'ua', 0, NULL),
(327, 'Як прийде Господь', 0, 11, 'Куплет 1\nЯк прийде Господь у славі, чи готовий ти будеш?\nДосі ходиш ти в темряві і в гріхах усе живеш.\n\nКуплет 2\nПодивися на Голгофу, як Він тяжко там страждав,\nТо за тебе, милий друже, щоби ти спасіння мав.\n\nКуплет 3\nО нещасний, ти не знаєш, - скоро вже Господь прийде; \nВін і праведних і грішних - всіх нежданно тут знайде.\n\nКуплет 4\nВін розкриє вічну книгу, перегляне її Сам\nІ довідається з Неї, чи записаний ти там.\n\nКуплет 5\nКоли будеш Йому вірним, прийме з радістю тебе,\nА як будеш непокірний, Він у Царство не прийме.\n\nКуплет 6\nСкаже: «Йдіть в вогонь прокляті!»Там не буде каяття, \nВічно будеш там ридати, проклинать своє життя.', '', '', '', '', 'ua', 0, NULL),
(328, 'Часто в смутку я', 0, 11, 'Куплет 1\nЧасто в смутку я, і скорблю в душі,\nІ нема друзів, хто б поміг мені.\nІ ні в чім мені радості нема,\nВсе чогось скорбить тут душа моя.\n\nКуплет 2\nПригадаю я у нічній тиші,\nЧого гірко так плачу я в душі.\nТяжко, трудно жить без щасливих днів, ‘\nЗ чаші горя пить у житті земнім.\n\nКуплет 3\nСкільки злих людей без любві живуть,\nЗа добро вони злом лиш віддають.\nПоміж них нема вірних друзів тих,\nЗ ким би в час тяжкий горе розділив.\n\nКуплет 4\nЗорі яснії в небесах горять,\nГіркі сльози все на очах блищать...\nХто рятунок дасть в ті часи трудні,\nІ утіху хто може дать мені?\n\nКуплет 5\nХто б це зрозумів, чого плачу я?\nЗнає тільки Бог, в чім печаль моя.\nВ трудний, скорбний час до Нього піду,\nВсю мою печаль розкажу Йому.\n\nКуплет 6\nВін приблизиться близько до мене,\nСльози гіркії із очей утре.\nВ тіні крил Його відпочину я,\nІ спокій душі тільки в Нім знайду.', '', '', '', '', 'ua', 0, NULL),
(329, 'Вже поля дозріли', 0, 11, 'Куплет 1\nВже поля дозріли і чекають нас,\nБог нас посилає, близько жнива час.\nПраці є багато, але мало слуг...\nЧуєте ви, браття, що нас кличе Бог?\n\nПриспів: \nНадходить жнива день,\n(Надходить радісний жнива день), \nРадісний жнива день,\n(Надходить радісний жнива день), \nЗолоте колосся жать, - \nМи будем серпом жать.\nНадходить жнива день,\n(Надходить радісний жнива день), \nРадісний жнива день,\n(Надходить радісний жнива день).\nЗ вірою цей труд зачнем,\nДо праці враз підем!\n\nКуплет 2\nНемічному брату руку ти подай,\nI додай охоти, щоб він працював,\nПраця ця поважна, Бог заплату дасть,\nВін тебе покличе: «Йди в пробуток Мій!»\n\nКуплет 3\nПоки сонце світить, правду голоси,\nЖнива час минеться, прийдуть злі часи.\nБраття й сестри, дружно ви снопи зберіть,\nЗ радістю у серці до Христа несіть.', '', '', '', '', 'ua', 0, NULL),
(330, 'Овець заблудлих', 0, 11, 'Куплет 1\nОвець заблудлих Пастир шукає,\nХодить по горах Він ніч і день.\n"Прийдіть до Мене» - всіх закликає;\nСлова Ісуса звучать ще днесь.\n\nПриспів: \nПрямо іде Він поміж гори,\nБлудну вівцю назад несе, (Він несе),\nА в небесах співають хори\nАгнцю Христу, Спасителю (що вмер за нас).\n\nКуплет 2\nШукайте грішних в гріхах страждання,\nДуш, котрі блудять ще у гріхах,\nІ направляйте на путь спасіння,\nКотра провадить у небеса.\n\nКуплет 3\nТак і я піду слідом Христовим,\nДавати поміч всім, хто стражда:\nГрішних і бідних, калік і хворих, - \nВсіх направляти їх до Христа.', '', '', '', '', 'ua', 0, NULL),
(331, 'Я по роздолі з моїм Спасом піду', 0, 11, 'Куплет 1\nЯ по роздолі з моїм Спасом піду все,\nТуди, де квіти цвітуть і вода тече;\nДе б Він не повів мене, я піду всюди з Ним,\nЙду Його слідами у Небесний Дім.\n\nПриспів: \nПіду, піду, піду за Ісусом!\nВсюди, де поведе, я піду за Ним.\nПіду, піду, піду за Ісусом!\nДе б Він не повів, там я піду за Ним.\nЯ по роздолі з моїм Спасом все піду,\nТам де буря віє, навіть в тьму нічну, - \nВін мене веде могутньою рукою Сам.\nЯ нічого не боюсь: зі мною Спас.\nЧи то в долині, чи високо на горі,\nВ злуці з моїм Спасом скрізь весело мені:\nВін мене так певно Сам провадить по путі \nДо Свойого дому, там де всі святі.', '', '', '', '', 'ua', 0, NULL),
(332, 'Хай бере хто хоче', 0, 11, 'Куплет 1\nХай бере, хто хоче, - нині ще пора, -\nБожий дар спасіння, вічного добра.\nСлухайте, ідіте - поспішайте взять \nТе, що Бог всім хоче дать.\n\nПриспів: \nХай бере бідняк! Хай без срібла п’є!\nТо Ісус Спаситель нас усіх зове.\nОсь вода живая без кінця біжить,\nДармо пий, хто прагне пить.\n\nКуплет 2\nО, приходь, мій друже, і бери хутчій!\nНині Бог спасіння хоче дать тобі;\nЗавтра буде пізно вже тобі благать:\nЗмовкне Божа благодать.\n\nКуплет 3\nХай бере, хто хоче, Бог усіх зове:\nВічний дар спасіння хай кожний прийме.\nВсе, що обітує, Бог в любві дає, —\nВбогий духом хай прийде.', '', '', '', '', 'ua', 0, NULL),
(333, 'З небес Своїх у славі', 0, 11, 'Куплет 1\nЗ небес Своїх у славі Господь прийде;\nНе сонних нас, а пильних, Він хай знайде.\nСвітильники держімо в наших руках,\nЛюбов і дожидання в наших серцях.\n\nПриспів: \nРадість велика буде, - Господь прийде! \nВсе небо «Алілуя» співать буде. \nЗемля вся обновиться в вічній красі,\nІ в славі освітиться Його святій.\n\nКуплет 2\nЗабудем всі незгоди: Господь прийде,\nНастане Царство Правди, - Господь прийде.\nЩезне вже зло й сумніви: Господь прийде.\nНе буде сліз, томління, - Господь прийде.\n\nКуплет 3\nВін знає, як страждали ми на путі,\nТут ми не спочивали - свій хрест несли. \nГосподь тягар з нас здійме, коли прийде,\nВ славу небесну прийме: Господь прийде!', '', '', '', '', 'ua', 0, NULL),
(334, 'Брате кріпись', 0, 11, 'Куплет 1\nБрате, кріпись! Дні пробігають;\nБрате, кріпись! Хай всі вважають:\nПрийшов уже останній час, - \nБог кличе всіх до праці нас.\n\nПриспів: \nБо вічність вже | зовсім близька. (2р.)\nБо вічність вже зовсім близька.\n\nКуплет 2\nСлав, брат, Христа за радість нашу!\nСлав, брат, Христа за скорбну чашу:\nНебесний Цар до нас іде,\nБлаженство вірним Він несе!\n\nКуплет 3\nБрате, кріпись! Літа проходять;\nБрате, пильнуй! Дні злі надходять:\nЯк воїн, стій ти на часах\nЗ мечем Божественним в руках!\n\nКуплет 4\nОсь, брате, глянь! Вже день світає;\nБрате, почуй! Господь скликає \nСвоїх дітей в Небесний Дім,\nДе буде слава й радість з Ним.', '', '', '', '', 'ua', 0, NULL),
(335, 'В серце моє', 0, 11, 'Куплет 1\nВ серце моє, (2р.) Ісусе, ввійди у серце;\nВвійди в цей час, мій любий Спасе,\nВвійди, Ісусе, в серце!', '', '', '', '', 'ua', 0, NULL),
(336, 'Як скоро час біжить', 0, 11, 'Куплет 1\nЯк скоро час біжить невпинно!\nПройшли вже тисячі років, - \nІ так час нинішній пролине \nУслід забутих вже родів.\nТак в вічність день за днем стремиться,\nНе залишає і сліда.\nЖиття на крилах мов несеться:\nПрийде і наша вже черга.\n\nКуплет 2\nІ наші всі земні діяння:\nТруди, турботи, марнота - \nНемов десь зникнуть у безодні \nПодібно мрії, що пройшла.\nПощо ж на світ ти цей родився\nІ стільки переніс страждань?\nДо чого ум твій все стремився?\nЩоб статись жертвою червам?...\n\nКуплет 3\nЗемнеє щастя, привид зрадний,\nДержав тебе завсіди в тьмі:\nЗабув, що порох ти нікчемний - \nЄ перехожим на землі.\nТа є за гробом життя краще,\nВоно не знає лічби днів,\nА що ж тебе там дожидає?\nПро це ти думав вже, чи ні?', '', '', '', '', 'ua', 0, NULL),
(337, 'В ті дні останнього часу', 0, 11, 'Куплет 1\nВ ті дні останнього часу,\nО, радість нам тоді буде,\nЯк ми побачим наяву,\nКоли на землю Цар царів прийде.\n\nПриспів: \nІсус прийде, Він знов прийде.\nМи з радістю Його чекаєм, (Він прийде). \nО, може рано, може і в північ,\nМи знаєм, що прийде.\n(Скоро наш Ісус прийде).\n\nКуплет 2\nНа небі вже ознаки є,\nI на землі довкола нас,\nА Боже Слово свідчить нам,\nЩо Спаситель Ісус прийде до нас.\n\nКуплет 3\nІ всі померлі у Христі, \nЯк зазвучить труба з небес,-\nВони воскреснуть всі тоді,\nЯк у славі Господь по нас прийде.\n\nКуплет 4\nЖиві - всі перемінимось,\nВ небо підхоплені будем,\nІ з Господом зустрінемось,\nІ так ми завжди з Господом будем.', '', '', '', '', 'ua', 0, NULL),
(338, 'На горі Оливній там', 0, 11, 'Куплет 1\nНа горі Оливній - там Спас моливсь цілу ніч Сам. \nДля молитви приклад всім Спас нам дав;\nІ як ми також щодня проведем в молитві час,\nМи дізнаєм, любо як наєдині.\n\nПриспів: \nО, як любо є мені бути з Ним наєдині; \nРозказати все Йому наєдині.\n\nКуплет 2\nЄ також щасливі дні, в котрі любо так мені \nБути з Господом і наєдині; Господь душу там мою \nНаповняє радістю. О, як любо бути з Ним наєдині.\n\nКуплет 3\nЯк надія упаде, смуток душу вповине,\nДо Христа прийди ти наєдині,\nІ Він смуток віддалить, серце радістю сповнить,\nЯк прийдеш до Нього ти наєдині.', '', '', '', '', 'ua', 0, NULL),
(339, 'На Голгофській горі', 0, 11, 'Куплет 1\nНа Голгофській горі я все бачу там хрест.\nВін є символ, страждання, наруг...\nАле люблю цей хрест, він мені дорогий:\nНа нім Спас за весь світ постраждав.\n\nПриспів: \nНе забуду ніколи той хрест:\n(Хрест старий, тяжкий хрест),\nВ нім прощення дарує Отець.\nМовби в серці я ношу той хрест,\n(Хрест старий, тяжкий хрест), - \nВ славний день я зміню на вінець.\n\nКуплет 2\nДуже давній той хрест, і забутий людьми,\nАле лине до Нього душа:\nБог у жертву на нім Свого Сина віддав,\nЗа нас смерть на хресті Він прийняв.\n\nКуплет 3\nЯ все бачу той хрест, де Христос пролив кров... \nТо ж і я тут свій хрест понесу;\nА Спаситель мене в Дім Свій вічний прийме,\nІ вже вічно там з Ним я буду.', '', '', '', '', 'ua', 0, NULL),
(340, 'Глибше всіх морів та океанів', 0, 11, 'Куплет 1\nГлибше всіх морів та океанів \nВічна, недосяжна і свята,\nВище від усіх світил небесних - \nБлагодатная любов Христа.\n\nПриспів:\nВін обмив гріхи мої,\nДав одіж слави Він мені,\nДар Святого Духа звіщав,\nСвоїм дитям мене назвав\n\nКуплет 2\nЩастя я знайшов в Христі Ісусі;\nЯ спасен від смерті і суда:\nМоїм серцем гріх не володіє\nВ нім оселя Господа Христа.\n\nКуплет 3\nЖив я довго у пітьмі без світла;\nЯ блукав далеко від Христа,\nГинув я поранений, нещасний,\nТа Ісус знайшов і спас мене.', '', '', '', '', 'ua', 0, NULL),
(341, 'За все Тобі я дякую', 0, 11, 'Куплет 1\nЗа все Тобі я дякую, Спаситель Ти мій,\nЗа Духа, що з ознакою Ти дав душі моїй.\n\nПрипев\nЯ дякую за все, за те, що спас мене,\nЗа те, що життя дав, духа злого прогнав.\nМене Ти охрестив Дух в серці поселив,\nЩобі життям моїм завжди Він керував.\n\nКуплет 2\nЗа все Тобі я дякую, за Твій голгофський хрест,\nЗа Тебе, вам розп''ятого, за те, що чуеш нас,\n\nКуплет 3\nЗа все Тобі я дякую, надія Ти моя;\nВ житті я хочу славити, Тобі честь і хвала', '', '', '', '', 'ua', 5, NULL),
(342, 'О Небесна Країно', 0, 11, 'Куплет 1\nО, Небесна Країно, до тебе я йду,\nТа про тебе усім розкажу;\nЛиш у тебе царює небесний спокій\nО, прийми мене, Спасе, Ти мій\n\nПрипев\nВслід за Спасом ми підем (2р.)\nІ в Небесний Край ввійдем (2р.)\nТам життя нове ми розпочнем\n\nКуплет 2\nСвіт про тебе не знає, не може пізнать\nБо нам треба піти розказать,\nЩоб пізнали про Тебе також люди всі\nЩо вмирав Ти за них на хрестіюю.\n\nКуплет 3\nО, не раз я сльозами так гірко заллюсь;\nЯк на грішний цей світ подивлюсь;\nЩо він так у гріхах та неправді живе\nЙого кара за гріх не минею.', '', '', '', '', 'ua', 0, NULL),
(343, 'Ой у Вифлеємі весела новина', 0, 11, 'Куплет 1\nОй, у Вифлеємі весела новина, - радуйся!\n\nПриспів: \nОй, радуйся, земле,\nСин Божий народився!\n\nКуплет 2\nТам Діва Марія народила Сина, - радуйся!\n\nКуплет 3\nІ Отцівське Слово зодяглося в тіло, - радуйся!\n\nКуплет 4\nВ мороці земному Сонце засвітило, - радуйся!\n\nКуплет 5\nАнгели співають Господу своєму, - радуйся!\n\nКуплет 6\nСлаву-честь складають Йому Родженому-радуйся!\n\nКуплет 7\nІ ми Родженого Христа прославляймо, - радуйся!\n\nКуплет 8\nГосподеві Спасу всі поклін віддаймо, - радуйся!', '', '', '', '', 'ua', 3, NULL),
(344, 'Ой зійшла зійшла Правда', 0, 11, 'Куплет 1\nОй, зійшла, зійшла Правда на землю\nІ пробуває між людьми.\nВсе розказала, що треба людям;\nЯк треба жить, як Бог велить.\n\nПриспів: \nДе ж тая Правда, звідки з’явилась,\nДе ж вона нині на світі є?\nТам в Вифлеємі в яслах родилась,\nА тепер в вірних серцях живе.\n\nКуплет 2\nІ Дух Святої Правди із неба,\nНині шукає в серцях ясел,\nДе б поселитись, щоби родити\nОвочі правди в життю людей.\n\nКуплет 3\nІ в кому знайде місце для себе, \nТам запанує радість життя; \nТому дарує місце на небі,\nЩе й допоможе нести хреста.\n\nКуплет 4\nXристос є Правда, Христос є Світло, \nХристос є Хліб Життя для нас.\nО, якби люди з усього світу\nПрийшли до Нього, — Він би їх спас.', '', '', '', '', 'ua', 1, NULL),
(345, 'Небо голубе', 0, 11, 'Куплет 1\nНебо голубе, я люблю тебе,\nТи - мета моїх завітних мрій.\nЗабуваю все - прагну до тебе;\nУявляю дивний спокій твій.\n\nПриспів: \nА на цій землі сумно так мені, \nЗавжди лише сльози на очах,\nБо навкруг мене виє та реве; \nПотопає світ цей у гріхах.\n\nКуплет 2\nСпасе дорогий, голос вчуй Ти мій,\nПоможи дорогу цю пройти,\nЩоб для Тебе жить і Тобі служить,\nДосягти завітної мети.\n\nКуплет 3\nНебо голубе, хочу до тебе;\nТам мене чекає мій Творець,\nТам спочину я, заспокоюсь я,\nТам стражданням всім прийде кінець.', '', '', '', '', 'ua', 0, NULL),
(346, 'Я буду співати', 0, 11, 'Куплет 1\nЯ буду співати в кожний час, журби в мене нема. \nМене Христос від смерті спас; щасливий я без кінця.\n\nПриспів: \nСпівай, (4р.) для Господа співай.\nСпівай, (4р.) о, сумний брате, співай.\n\nКуплет 2\nСпівай тоді, коли в душі тягар тобі наляжеться,\nСпівай від серця, від душі, і легше зробиться.\n\nКуплет 3\nЯ буду співати, доки серця стук останній відіб’є,\nІ доки любий мій народ; співать зі мною буде.', '', '', '', '', 'ua', 0, NULL),
(347, 'Лине пісня про Ісуса', 0, 11, 'Куплет 1\nЛине пісня про Ісуса, про діла Його святі.\nЯ до Нього пригорнуся щирим серцем у житті.\n\nПриспів: \nВсе віддам я для Ісуса:\nСерце, душу і життя.\nІ навіки з ним зіллюся,\nВ Царстві вічного буття!\n\nКуплет 2\nПро любов Його безмірну лине пісня серед нас,\nБуду я для Нього вірним, всякий день і всякий час.\n\nКуплет 3\nНехай світ, як море грізно, клекотить, реве всю ніч, \nВ небесах моя Вітчизна, непохитною стоїть.', '', '', '', '', 'ua', 1, NULL),
(348, 'Вірний Спасителю мій', 0, 11, 'Куплет 1\nВірний Спасителю мій, Ти є найкращий мій Друг;\nЯ все Тобі віддаю, даю, серце, любов і красу.\n\nКуплет 2\nВ світі далеко я був, грішний, неправдою жив,\nТи ж мене, Боже, любив, любив, кров’ю гріхи всі обмив.\n\nКуплет 3\nПісню про ласку Твою в серце моє Ти вселив..\nДай сили хрест свій нести, нести, вірним Тобі буть завжди.', '', '', '', '', 'ua', 0, NULL),
(349, 'Дні минають швидко', 0, 11, 'Куплет 1\nДні минають швидко, мов на крилах,\nЗ днями пролетить життя,\nI свої розправивши вітрила,\nВідлетить у майбуття.\n\nКуплет 2\nПоки у горі синіє небо,\nКвітнуть молоді літа;\nЧасу марно гаяти не треба,\nВічність часу не верта.\n\nКуплет 3\nОбіб’ють дощі зів’яле листя,\nВідсумують журавлі.\nВідлунає пісня урочиста,\nЗмовкне у вечірній млі.\n\nКуплет 4\nНе марнуй же, юність, днів найкращих,\nБо з усіх життєвих втрат,\nВтрата часу — саме є найтяжче,—\nЧас - це найдорожчий скарб.\n\nКуплет 5\nТи життя - святий дарунок неба,\nПринеси до ніг Христа.\nЧасу марно гаяти не треба,\nВічність часу не верта.\n\nКуплет 6\nА літа пливуть немов на крилах,\nЗ ними пролетить життя.\nЮність, направляй свої вітрила \nУ щасливе майбуття.', '', '', '', '', 'ua', 0, NULL),
(350, 'Дух Святий навесні', 0, 11, 'Куплет 1\nДух Святий навесні, разом з сонцем ясним,\nМоє серце від сну розбудив.\nВін і радість приніс, і веселі пісні,\nПро щасливі майбутнії дні.\n\nКуплет 2\nЯ співав про любов у терновім вінку,\nЯк Христос за людей умирав.\nПро щасливу країну святу в небесах, \nЩо для вірних Христос обіцяв.\n\nКуплет 3\nЯсний промінь погас, злий орел налетів,\nВін позаздрив веселим пісням.\nВ чисте серце моє він отруту пустив, \nВирвав пісню і геть полетів.\n\nКуплет 4\nІ тепер нема слів, щоб співати пісні, \nА в очах моїх сльози блищать.\nЯ німий пред Тобою, Ісусе, стою, \nХочу скинути ношу мою.\n\nКуплет 5\nЛюбий друже Ісус, я благаю Тебе, \nПоможи в цю хвилину тяжку.\nНехай зникне сльоза, пройдуть думи сумні, \nПоверни знову пісню мені.', '', '', '', '', 'ua', 0, NULL),
(351, 'Місце є дороге', 0, 11, 'Куплет 1\nМісце є дороге, де бажав би бути ще,\nТам з моїми братами в селі.\nДе в неділю ходив, Господеві я служив,\nТам у Церкві з братами в селі.\n\nПриспів: \nО, як радують думки про минулі ті роки. \nХочеться хоч раз мені \nБути в Церкві з братами в селі.\n\nКуплет 2\nЯк я був молодий, - радувався я тоді,\nЯк моливсь там в тій Церкві в селі.\nМій Спаситель з гори по любові Своїй \nСпас мене там в тій Церкві в селі.\n\nКуплет 3\nО, коли б в наші дні так молились усі,\nЯк молились колись у селі.\nТреба серце відкрить, а Ісус благословить,\nЯк благословив нас у селі.\n\nКуплет 4\nЧасто думаю я, що мій брат і сестра;\nПерейшли вже туди в небеса.\nМоже скоро Господь вже й за мною прийде,\nІ з Ним в небі спочину там я.', '', '', '', '', 'ua', 0, NULL),
(352, 'В час горя та журби', 0, 11, 'Куплет 1\nВ час горя та журби я лину до Христа,\nВін є притулок мій; в Нім радість вся моя.\n\nПриспів: \nА Він єдиний друг і Пастир добрий мій;\nПоможе Він мені, та радість дасть душі.\n\nКуплет 2\nВ нещасті і сльозах, коли відчай душі,\nЯ Його кличу знов, молюся у тиші.\n\nКуплет 3\nА як грозить мені шалений буревій,\nТо до Христа спішу, до Нього йду скорій.\n\nКуплет 4\nБуває і в бою поранений гріхом,\nТо підіймаю взір, і лину до Христа.\n\nКуплет 5\nКоли сердечний біль, і томиться душа,\nЙому все розкажу спочатку й до кінця.', '', '', '', '', 'ua', 0, NULL),
(353, 'Ти знаєш Боже', 0, 11, 'Куплет 1\nТи знаєш, Боже, моє бажання,\nМолитву чуєш Ти мою.\nТи знаєш серця мого страждання,\nКоли я гіркі сльози ллю.\n\nКуплет 2\nТи знаєш, Боже, що я бажаю Н\nе слави, скарбів на землі.\nЯ щирим серцем Тебе кохаю \nВ мої весняні юні дні.\n\nКуплет 3\nСумує серце моє порою,\nВ устах моїх немає слів.\nІ я самотній скорблю душею,\nЗмовкає мій весняний спів.\n\nКуплет 4\nНіхто не знає, усім байдуже,\nКуди душею лину я.\nІ хто спитає, і хто потішить,\nКоли сумна душа моя.\n\nКуплет 5\nЦей світ чужий вже мені зробився,\nО, Боже, Ти зі мною будь. \nБо слабнуть сили, і я втомився,\nА ще далека моя путь.', '', '', '', '', 'ua', 0, NULL),
(354, 'В цей день славний', 0, 11, 'Куплет 1\nВ цей день славний я хочу співати для Христа.\nПро ласку, добрість і любов - прославлять Його ім''я. \nЗавжди я хочу співати своїм слабим голосом,\nЩоби у спільності бути з моїм Ісусом Христом.\n\nПриспів: \nО, за це Тебе славить душа моя,\nБо без Тебе я завжди в серці біль відчував. \nА тепер я спасенний, любов''ю зігрітий,\nІ ціною Крові Ти мене врятував.\n\nКуплет 2\nІсус тепер закликає, - не зачиняй серця ти.\nСвітлом тебе Він провадить аж до висот Голгофи. \nСміло за Ним йти рішися, - радісним будеш тоді,\nДуха Святого одержиш, щасливим повік будеш ти.', '', '', '', '', 'ua', 2, NULL),
(355, 'Вставайте вставайте браття мої', 0, 11, 'Куплет 1\nВставайте, вставайте, браття мої милі,\nПогляньте на небо, вже зійшла зо \nЯсним промінням б’є нашу руїну,\nХвилини не гайте, спішіте туди.\n\nКуплет 2\nДитя народилось у яслах на сіні,\nСин Божий на землю зійшов із небес. \nСпасати народи, з гріхів визволяти,\nНа волю пускати люд праведний весь.\n\nКуплет 3\nЦарі із Востоку до Нього приходять,\nЦіннії дарунки до Нього несуть.\nА воїни царські в степу переходять,\nНа допит невинних в палаци ведуть.\n\nКуплет 4\nТа їх не злякають тортурнії муки,\nНі підступи лживі Ірода-царя. \nЇм Дух Божий ласки дорогу торує.\nДо цілі провадить ясная зоря.\n\nКуплет 5\nСпішіте дарунки приносити Йому,\nМалому дитяті Ісусу Христу. \nВін висушить сльози заплаканій неньці \nІ добром наділить в годину тяжку.', '', '', '', '', 'ua', 0, NULL),
(356, 'Одна лиш Біблія свята', 30, 11, 'Куплет 1\nОдна лиш Біблія свята для нас - і світло, і мета.\nМи з неї знаєм, як за нас помер у муках любий Спас.\n\nПриспів: \nО, Слово Боже - світло ти,\nВ житті постійно нам світи!\nО, Слово Боже, ясно сяй,\nІ нас веди в Небесний Край.\n\nКуплет 2\nВідомо з Біблії і те, що Бог життя дає святе\nУсім, хто серце та уста поклали на вівтар Христа.\n\nКуплет 3\nХто любить Біблію читать, тому не страшно помирать.\nУсіх, кого вона веде, життя на небі вічне жде.', '', '', '', '', 'ua', 0, NULL),
(357, 'Ой над Вифлеємом зірка', 0, 11, 'Куплет 1\nОй, над Вифлеємом зірка вже зійшла,\nТам Діва Марія Сина родила. \nВ пелени сповила, у яслах поклала,\nЦе на світ родився Спаситель світу.\n\nКуплет 2\nВін на світ родився як людина, \nАнгели ж вітали Божого Сина. \nАнгели співають, пастухи вітають,\nА три царі із Персії у вертеп спішать.\n\nКуплет 3\nЗ’явилась над ними ясная зоря,\nА в яслах на сіні - маленьке Дитя.\nЙосиф і Марія над Ним вже стоять \nРучки простягає маленьке Дитя.\n\nКуплет 4\nЙосифові ангел у сні з’явився,\nЩоб з малим Дитятком він удалився \nУзяв Йосиф Сина і матір Його, \nУтікав в Єгипет від царя злого.\n\nКуплет 5\nА Ірод, цар злобний, дуже засмутивсь,\nЩо Ісус Син Божий на світ народивсь. \nВійсько посилає у ту країну,\nСказав загубити малу Дитину.\n\nКуплет 6\nСказав Ірод війську - шукати Христа, \nДо двох літ рубати маленьких дитят.\nСкільки ж душ невинних, чистих немовлят, \nБуло в Вифлеємі вбито у той час!\n\nКуплет 7\nГлянь, о Божий Сину, на дітей Своїх,\nТи Спаситель світу, Цар неба й землі.\nЗішли нам із неба дар Твій превеликий,\nБудем Тебе славить по вічні віки.', '', '', '', '', 'ua', 0, NULL),
(358, 'Ісус з Назарету', 0, 11, 'Куплет 1\nІсус з Назарету, на хресті прибитий,\nПокривало крові покрило лице.\nЛице Його миле, святе і небесне;\nВінка із тернини Йому надягли.\n\nПриспів: \n«Елі, елі, елі, лама савахтані!»,\nВзивав наш Учитель, небесний Ісус. \nНаш милий Спаситель нас так полюбив,\nІ скрикнувши сильно, Він Духа віддав.\n\nКуплет 2\nВдягли в багряницю, подали тростину, \nНавколішки стали і били Його.\n«Радій! Цар Юдейський», - вони всі кричали, \nОдежу ділили, сміялись над Ним.\n\nКуплет 3\nЗемля затряслася і сотник промовив: \n«Це справді Син Божий висить на хресті!» \nМесія-Спаситель так тяжко страждав, \nЩоб грішникам двері до раю відкрить.', '', '', '', '', 'ua', 1, NULL),
(359, 'Куди піду куди від Тебе', 0, 11, 'Куплет 1\nКуди піду, куди від Тебе?\nСпаситель мій, куди піду?\nДе зможу я навік для себе \nСпокій і мир душі знайти?\n\nКуплет 2\nХто мені скаже правди слово, \nВ розбите серце силу дасть? \nЩоб я тонув в святій любові \nІ міг її братам подать.\n\nКуплет 3\nXіба піду, де розлилися\nБезжурний сміх та п’яний спів?!\nЯ там вже був, там я томився,\nТам чорна хмара темних днів.\n\nКуплет 4\nЯк цвіт на квітці засихає,\nЯк лист пожовкне, облетить, \nТакий кінець їх всіх чекає;\nО, ні, не можу це любить.\n\nКуплет 5\nКуди піду, куди від Тебе?\nСпаситель мій, куди піду?\nЗ Тобою буду, бо для себе\nНіде я щастя не знайду.', '', '', '', '', 'ua', 0, NULL),
(360, 'Підніми мене Ісусе', 0, 11, 'Куплет 1\nПідніми мене, Ісусе, з цього світу марноти\nВ ту Країну, де з святими, пробуваєш вічно Ти. (2р.)\n\nКуплет 2\nЯ стомився в цій мандрівці, в небеса спочити йду.\nЛиш в Тобі я нові сили і спокій душі знайду. (2р.)\n\nКуплет 3\nПідніми мене, Ісусе, в Край Небес, у Край святий,\nДе минуться всі спокуси, смуток і тягар людський. (2р.)\n\nКуплет 4\nТи почуй мої благання, власний гріх я визнаю. \nСкороти мої страждання, душу обнови мою. (2р.)\n\nКуплет 5\nЛиш з Тобою я безпечно зможу йти шляхом вузьким. \nО, провадь мене, мій Спасе, у небесний вічний дім.(2р.)', '', '', '', '', 'ua', 0, NULL),
(361, 'Прийди ти до Ісуса', 0, 11, 'Куплет 1\nПрийди ти до Ісуса, мій друже дорогий.\nТебе стомив до краю великий гріх тяжкий.\n\nКуплет 2\nПрийди і не лякайся, Христос приймає всіх. \nВідкрий Йому всі рани, весь біль із себе скинь.\n\nКуплет 3\nЙого віддайся волі, Його лиш слухай ти;\nВін вилікує скоро з гріха й нечистоти.\n\nКуплет 4\nВ крові Його пречистій вздоровлення знайдеш; \nДушею в ній омитий, спасіння дар приймеш.\n\nКуплет 5\nВізьми свій хрест, з Ісусом іди вузьким шляхом; \nІдучи, не журися, не плач ти під хрестом.\n\nКуплет 6\nСтарайся шлях свій вірно пройти з Ним до кінця; \nТоді ввійдеш у вічність, в Небесний Дім Отця.', '', '', '', '', 'ua', 0, NULL),
(362, 'Не покину я вас', 0, 11, 'Куплет 1\nНе покину я вас, не забуду!\nТак Бог каже тобі і мені:\n// Турбуватись про вас завжди буду,\nУ стражданнях тяжких на землі. // - 2р.\n\nКуплет 2\nБуду в праці Я вам помагати,\nБуду силу і міць подавать,\n// І в годину сердечної втрати,\nБуду в душу бадьорість вливать. // - 2р.\n\nКуплет 3\nНе покину Я вас, не забуду,\nКоли батько і мати, й рідня \n// Відречуться від вас, то Я буду,\nРідним батьком для вас з того дня. // - 2р.\n\nКуплет 4\nНіжно буду Я вас доглядати,\nТак, як мати маленьке дитя, \n// Від усякого зла зберігати,\nІ провадить у вічне життя. // - 2р.\n\nКуплет 5\nЯ самотнєє серце розважу,\nСумні думи Я геть віджену,\n// І розбите життя Я поладжу,\nДух засмучений в вас підкріплю. // - 2р.', '', '', '', '', 'ua', 0, NULL),
(363, 'Юність ти прекрасна', 0, 11, 'Куплет 1\nЮність, ти прекрасна, цвіт життя чудовий;\nТи весняна квітка молодечих літ.\nОй, чому ж так скоро в’яне лист чарівний,\nБлиск очей погас твій, скроні в сивині?\n\nКуплет 2\nЧим би заплатить міг, щоби ти лишилась, \nЗавжди нероздільно, до кінця цвісти.\nСкоро так проходять роки золотії,\nІ ти безперечно хочеш відійти.\n\nКуплет 3\nХто би повернуть міг чарівні привілля,\nІ вогонь любові, силу повернуть.\nЮність - це є щастя днів моїх тривожних,\nПролетіли в бурях на земнім путі.\n\nКуплет 4\nНе сумуй же, брате, є надія в Бозі,\nЦей недолік в людях знав Отець завжди. \nНедаремно руки - Ті були прибиті,\nЩоб вернути юність - життя назавжди.', '', '', '', '', 'ua', 0, NULL),
(364, 'Люба мамо не плач', 0, 11, 'Куплет 1\nЛюба мамо, не плач, не журись,\nДухом не падай у тяжкій борні;\nБо мине журба, зникне вся боротьба,\nСонце засяє тобі.\n\nКуплет 2\nСкільки раз заливалась в сльозах,\nТи на колінах стояла своїх.\nІ в мольбі палкій перед Богом живим,\nБіль відкривала душі.\n\nКуплет 3\nПригадую, як просила мене:\n«Сину мій, сину, віддайсь для Христа.\nВін тебе полюбив, двері раю відкрив,\nВ Царство Він кличе своє.»\n\nКуплет 4\nТа не слухав тебе, мамо, я,\nВибрав дорогу гріха й марноти.\nНа шляху своїм щастя я не зустрів, \nЛиш змарнував я життя.\n\nКуплет 5\nТа молитва твоя все неслась,\nВ небо до Бога за ледарство моє.\nЇї Бог почув і мене навернув,\nГріх мій тяжкий з мене зняв.\n\nКуплет 6\nТепер славлю Його в серці я,\nДивне життя я отримав в Христі; \nБільш ніколи я не залишу Христа, \nЖитиму з Ним по всі дні.\n\nКуплет 7\nТо ж, люба мамо, не плач, не журись, \nДухом не падай, а серцем радій.\nОсь приходить час, коли в небо всіх враз; \nБог забере нас повік.', '', '', '', '', 'ua', 0, NULL),
(365, 'Чого ждеш на широкім шляху', 0, 11, 'Куплет 1\nЧого ждеш на широкім шляху?\nЧому досі ти служиш гріху?\nО, чому ти не хочеш прийнять \nДар безцінний - Христа благодать?\n\nПриспів: \nСпіши тепер, (2р.) - до Христа Ісуса скорій!\nСпіши тепер, (2р.) — бо в темряві згинеш нічній.\n\nКуплет 2\nТи поглянь на Ісуса Христа, - \nТо ж за тебе кров ллялась свята.\nЧашу горя за тебе Він пив \nІ від суду тебе відкупив.\n\nКуплет 3\nДля Христа все життя присвяти, - \nІ щасливий повік будеш ти.\nКров свята змиє твій тяжкий гріх,\nІ вбереш одіж білу, як сніг.', '', '', '', '', 'ua', 0, NULL),
(366, 'Коли прийде біда', 0, 11, 'Куплет 1\nКоли прийде біда, хто вам, скажіть, допоможе?\nНавіть через літа бачу я руку Божу.\nСтань на коліна, друг, коли прийде тривога,\nІ ти пізнаєш вмить щастя в єднанні з Богом!\nСвіт не поможе, ні, серце тривога ранить. \nТільки Господь тобі руки Свої простягне.\n\nКуплет 2\nВилиєш душу Йому в горі своїм і стражданнях.\nНавіть останню тьму Він перетворить в сіяння.\nСтань на коліна, друг, коли прийде тривога,\nI ти пізнаєш вмить щастя в єднанні з Богом!\nСвіт не поможе в біді, серце ще більше ранить. \nТільки Христос завжди руки тобі простягне.\n\nКуплет 3\nПрийди ти до Христа, Він тебе закликає,\nНіжно звучать слова: любить Ісус і прощає.\nІ коли, друже, ти серцем пізнаєш Бога,\nСтане в житті твоїм легкою земна дорога.\nВ небі чекають тебе вічні оселі з Богом,\nДе вже не буде біди, горя, сліз і тривоги.', '', '', '', '', 'ua', 0, NULL),
(367, 'До Тебе мій Боже душею', 10, 11, 'Куплет 1\nДо Тебе, мій Боже, душею я лину,\nДо Тебе всім серцем я рвусь.\nЩоденно борюсь я і кожну хвилину \nТобі, мій Спаситель, молюсь.\n\nПриспів: \nДо Тебе молитву приношу,\nХай Дух Твій у серці живе.\nКеруй моїм серцем, Тебе щиро прошу, \nХай буде все власне Твоє!\n\nКуплет 2\nМолюсь я за світ, що в гріхах погибає,\nЗа братство, що в світі живе.\nЧому ж так буває, що сил не хватає,\nІ плоть моя борить мене?\n\nКуплет 3\nЧому я не можу на ниві трудитись,\nЯк, було, трудився колись?\nЧому я не можу так щиро молитись,\nЯк вперше до Тебе моливсь?\n\nКуплет 4\nЧи може життя є важке непомірно?\nЧи сумнів проймає мене? \nЧи може втомивсь я на хресній дорозі? \nЧи щиро не люблю Тебе?\n\nКуплет 5\nЧи може я брата не люблю прийняти?\nЧи гордість ще мучить мене?\nЧи ворога я ще не вмію прощати?\nЧи гріх ще у серці живе?\n\nКуплет 6\nПрости, любий Боже, за те, що не діяв, - \nЯк Слово навчає Твоє,\nХоч діяти завжди у серці я мріяв, - \nПрости, Милосердний, мене.\n\nКуплет 7\nБо тільки з Тобою, я можу здолати, - \nУсе, що так гнобить мене, - \nДай сили мені у годину скорботи,\nЩоб славити вічно Тебе.', '', '', '', '', 'ua', 0, NULL),
(368, 'Радісні ті діти', 0, 11, 'Куплет 1\nРадісні ті діти, Отцем яких є Бог!\nРадісні ті діти, в яких є Дух Святий!\nРадісні ті діти, що в Церкві істинній!\nРадісні ті діти, хто двічі народивсь!\nРадісні ті діти, по вірі хто хрестивсь!\nРадісні ті діти, хто в небі буде жить!\nРадісні ті діти, чий каганець горить! \nРадісні ті діти, що люблять Біблію!\nРадісні ті діти, в любові хто живе!\nРадісні ті діти, що завжди моляться!\nРадісні ті діти, яких Спаситель спас.\nРадісні ті діти - воскреснуть для життя!\nРадісні ті діти, яким Бог дасть вінець!', '', '', '', '', 'ua', 0, NULL),
(369, 'На Христа дивися', 0, 11, 'Куплет 1\nНа Христа дивися, - Він взірець тобі.\nВіруй і молися, - поміч Він в журбі.\nВін умер за тебе, взяв твій гріх Він Сам,\nУ твоїй потребі вір Його словам.\n\nКуплет 2\nНа Христа дивися, йди за Ним услід,\nЙ хвилі не барися залишити світ\nХоча ти й безсилий в боротьбі з гріхом, \nСпас твоя є сила, йди за Ним слідом.\n\nКуплет 3\nНа Христа дивися й твердо в вірі стій,\nПеред Ним корися, Він - Спаситель твій.\nПоки день ясніє й сонечко сія.\nВіра та надія зміцниться твоя.\n\nКуплет 4\nНа Христа дивися, вірним Йому будь,\nІ коли скінчиться ця скорботна путь,\nІ важка дорога прийде до кінця,\nВід твойого Бога матимеш вінця.', '', '', '', '', 'ua', 0, NULL),
(370, 'Бог чудово створив небеса', 0, 11, 'Куплет 1\nБог чудово створив небеса:\nМісяць, зорі по небу пливуть.\nЯ свій зір підіймаю туди,\nМоє серце, думки туди йдуть.\n\nКуплет 2\nБачу в небі чудову красу,\nЩо говорить про Бога-Творця.\nЗрозуміти не можу людей,\nЩо не вірять у Сина й Отця.\n\nКуплет 3\nВся природа говорить для нас,\nЩо для всього цього є Творець.\nЗемля й небо, співайте Йому,\nБо достойний хвали наш Отець.\n\nКуплет 4\nНе лишає ніколи нас Бог,\nНе спішить, щоб карати за гріх.\nЩоб не ласка Його до всіх нас,\nТо ніхто б ввійти в небо не зміг.', '', '', '', '', 'ua', 0, NULL),
(371, 'Білий сніг', 0, 11, 'Куплет 1\nБілий сніг упав на землю, все покрив кругом,\nВся природа спочиває тихим мирним сном.\nТи Свої благословіння, Боже, нам пошли \nЯк на землю посилаєш кожної зими.\n\nПриспів: \nБілий, білий сніг (2р.) скільки оком глянь.\nТи благослови (2р.) весь наш рідний край. \nПросимо Тебе (2р.), Боже, ми в цей час, \nЩоб благословив Ти (2р.) кожного із нас.\n\nКуплет 2\nВсі сади, поля, посіви снігом Ти покрив,\nВід морозу і від вітру Ти їх захистив,\nТакож нас в житті земному, Боже, захищай,\nВід лукавого і злого нас охороняй.\n\nКуплет 3\nІ якщо багато снігу, - буде урожай \nНашу землю, нашу ниву Ти благословляй,\nДай і нам плоди принести, Боже, в цім житті,\nЩоби були ми готові в небо увійти.', '', '', '', '', 'ua', 0, NULL),
(372, 'В сльозах приходжу', 0, 11, 'Куплет 1\nВ сльозах приходжу я до Тебе, всесильний Батьку дорогий, \nТи пригорни мене до себе, дай радість Ти душі моїй.\n\nПриспів: \nНехай же буде Твоя воля,\nНехай святиться ім’я Твоє,\nНехай же буде Твоя воля, нехай, нехай.\n\nКуплет 2\nЯк часто душу огортають гіркі сумніви у житті,\nТа Ти мені допомагаєш все далі, далі йти.\n\nКуплет 3\nКоли сльоза туманить око, а серце плаче і щемить, \nТоді душа моя так хоче Тебе побачити в цю мить.\n\nКуплет 4\nНехай душа моя співає, а серце рветься в небеса. \nТебе я, Боже, величаю за чудні, дивнії діла.', '', '', '', '', 'ua', 5, NULL),
(373, 'О ласкавий мій Спаситель', 0, 11, 'Куплет 1\nО, ласкавий мій Спаситель, Ти поміг мені в житті. \nБачив Ти мої страждання, бачив Ти журбу мою.\n\nПриспів: \nМені легко на дорозі, як з Тобою я іду. \nДаєш світло Своїм Словом \nІ несеш журбу мою.\n\nКуплет 2\nО, мій Спасе, будь зі мною, захищай від ворогів.\nБо я хочу жить з Тобою скільки Ти назначив днів.\n\nКуплет 3\nХочу все Тобі віддати: душу, тіло і любов.\nХто б так міг мене кохати? Тільки Ти, що пролив кров.\n\nКуплет 4\nЯ багато настраждався, сліз немало вилив я.\nТа коли Ти йдеш зі мною, Ти надія є моя.', '', '', '', '', 'ua', 0, NULL),
(374, 'Боже великий', 0, 11, 'Куплет 1\nБоже великий, могутній та добрий,\nЯк дуже Ти любиш людей!\nТи щастя даруєш, Ти тьму проганяєш,\nТи сльози втираєш з очей.\n\nКуплет 2\nЧим ми заробили любов Твою, Боже,\nВ пороках усіх та гріхах?\nЗагинули б всі ми, та Ти доторкнувся, \nПромінням сяйнув у серця.\n\nКуплет 3\nХвала Тобі, Боже, за нашу планету,\nЗа наші щасливі серця,\nЗа хліб, що ми маєм, за ласку й турботу,\nЗа наші на небі місця.\n\nКуплет 4\nНехай же весь світ принесе щиру вдячність \nТому, Хто від смерті нас спас,\nХто кожного з нас береже й опікує,\nХто в небо веде усіх нас.', '', '', '', '', 'ua', 0, NULL),
(375, 'До Христа вузенька стежка', 0, 11, 'Куплет 1\nДо Христа вузенька стежка \nІ по ній нелегко іти.\nТам безліч перешкод, туманів і негод,\nТа з Богом йду я до мети.\n\nПриспів: \nІди зі мною по вузькій стежині,\nА Бог поможе подолати тяжкий шлях.\nІди зі мною по вузькій стежині\nКінець якої - Боже Царство в небесах.\n\nКуплет 2\nА навкруги життя кипить,\nТа без Бога воно лиш дочасне.\nКоли твій час пройде, і смерті мить прийде,\nТо лиш в Христі знайдеш Ти щастя.\n\nКуплет 3\nІсус Христос за всіх вмирав \nІ воскрес, щоб весь світ був спасенний. \nПрийди ж ти до Христа - і кров Його свята \nОбмиє гріх з душі твоєї.', '', '', '', '', 'ua', 0, NULL),
(376, 'Любий друже', 0, 11, 'Куплет 1\nЛюбий друже, скільки раз в житті \nТи в знемозі прихиляв коліна,\nІ молився Господу в журбі,\nВідганяючи усі сумніви.\n\nПриспів: \n3 хвилюванням слухав ти тоді \nВ твоїм серці радіснії звуки.\nЙ рятували завжди від біди \nДобрії, невидимії руки.\n\nКуплет 2\nСкільки раз ці руки біль душі \nНіжно так з любов’ю обіймали \nІ утомленого у житті \nТебе руки ніжно пригортали.\n\nПриспів: \nА коли непрошена сльоза\nЗастеляла взір твій в час розлуки, \nВитирали сльози ніжно так \nДобрії, невидимії руки.\n\nКуплет 3\nРуки в ранах від страждань важких \nПринесли всім грішникам спасіння,\nІ на протязі усіх віків\nРуки шлють з небес благословіння.\n\nПриспів: \nА коли гріху прийде кінець,\nЗникнуть назавжди страждання й муки, \nПокладуть на голову вінець \nГоспода сіяючії руки.', '', '', '', '', 'ua', 0, NULL),
(377, 'Ось знову день', 0, 11, 'Куплет 1\nОсь знову день, як мить, пробіг, минає так життя,\nТі сірі будні суєти, в яких Христа нема.\nКоли ж приходить Він в тиші\nХоч в дощ, хоч в град, хоч в сніг -\nВсе оживає у мені, і сум зникає вмить.\n\nПриспів: \nІсус, о Ісус! Тебе побачу я колись.\nІсус, о Ісус! З Тобою хочу буть завжди.\n\nКуплет 2\nДо Тебе я прийшов в мольбі, нічого не скривав.\nСказав: «Ісус, пробач мені». Мені Ти руку дав.\nІ з того часу у житті \nЧи в дощ, чи в град, чи в сніг,\nТак тихо й вільно на душі, коли Ти поруч є.\n\nКуплет 3\nІ не забуть мені любві Твоїх пробитих рук,\nЩо дарували і мені спасіння від всіх мук.\nЯ вірю: зустріч близька ця.\nТуди всім серцем рвусь.\nТам мрія збудеться моя, з Тобою я зіллюсь.', '', '', '', '', 'ua', 0, NULL),
(378, 'Серцем устами Ісус дорогий', 0, 11, 'Куплет 1\nСерцем, устами, Ісус дорогий,\nБуду я славить Тебе, мій Благий.\nТут на землі, серед горя й біди\nПотім на небі - спішу я туди. Алілуя! Алілуя!\n\nКуплет 2\nЗ ніжним світанком недільного дня \nПеред Тобою схиляюся я.\nДухом Святим Ти мене наповни,\nЯк Ти за мене страждав, розкажи.Алілуя! Алілуя!\n\nПриспів: \nАлілуя! Кров Христа.\nАлілуя! Нас спасла. Алілуя! Алілуя!,\n\nКуплет 4\nБуду я вічно хвалити Христа,\nПісня нехай наповняє уста.\nВ ранню весну і в холодну зиму\nБуду я вічно співати Христу. Алілуя! Алілуя!\n\nКуплет 5\nПіснею слави хай буде життя \nЗ раннього ранку до заходу дня,\nЗ юності - перших поривів любві,\nВ зрілих роках і до сивини. Алілуя! Алілуя!', '', '', '', '', 'ua', 0, NULL),
(379, 'Я дякую Спасител', 0, 11, 'Куплет 1\nЯ дякую, Спаситель, Господь із Назарету,\nБо в Тобі радість дивну я знайшов.\nКоли одного разу мене в житті зустрів Ти \nІ в Край святий дорогу показав.\n\nКуплет 2\nНазустріч мені вийшов Господь із Назарету, \nПовів шляхом, якого я не знав.\nНим люди йшли спасенні, бо кров’ю Заповіту \nТи їх обмив, простив і оправдав.\n\nКуплет 3\nЯ бачив сльози щастя і радісні обличчя \nВ усіх, хто тим святим шляхом ішов.\nЯ чую, як ласкаво Твій ніжний голос кличе \nЩоби весь світ прийняв Твою любов.\n\nКуплет 4\nВеди мене і дальше, Господь із Назарету \nДорогою любові і добра.\nЩоб людям міг я нести Твоєї правди світло \nЙшов за Тобою по твоїх слідах.\n\nКуплет 5\nВеди мене, Дух Божий, Господь із Назарету,\nЯ знаю, що Ти - Правда і Життя.\nЗа муки і страждання, за кров святу пролиту \nТобі подяка, слава і хвала!', '', '', '', '', 'ua', 0, NULL),
(380, 'Християнин неси вогонь', 0, 11, 'Куплет 1\nХристиянин, неси вогонь чудесний свій,\nДарований тобі Христом.\nПомер Він на хресті, в жертву Себе віддав,\nЛюбові всім вогонь приніс.\n\nПриспів: \nПалай, вогонь, завжди палай.\nЗігрій собою ти холоднії серця, \nІ світ новий, чудовий освіти,\nВ якому радість без кінця.\n\nКуплет 2\nОсь мандрівник... втомився він в земній борні.\nЗігрій його та підбадьор,\nСкажи, що не покине його вічний Бог,\nЗасвітить сонце на шляху.\n\nКуплет 3\nЯкщо вже мандрівник звернув з того шляху, \nКотрий до радощів веде,\nТо ти вогонь любові в ньому запали,\nЩоб він той шлях міг знов знайти.', '', '', '', '', 'ua', 0, NULL),
(381, 'Я блукав у цьому світі', 0, 11, 'Куплет 1\nЯ блукав у цьому світі, як я Бога ще не знав,\nТа, й не знав я мого Спаса, що життя я в Нім знайшов.\n\nКуплет 2\nВін Сам взяв мене за руку, очі Він мої відкрив \nТа й сказав, щоб я за Ним йшов, бо мене Він полюбив.\n\nКуплет 3\nО, як любо мати Спаса, коли в серці моїм є.\nПровідник Він в житті моїм, світло правди і добра.\n\nКуплет 4\nТепер я йду за Ісусом, бо Він душу спас мою.\nІ в цей світ більш не дивлюся, Ісус в серці моїм є.', '', '', '', '', 'ua', 0, NULL),
(382, 'Ми вам звіщаєм', 0, 11, 'Куплет 1\nМи вам звіщаєм спокій (Зр.)\nМи вам звіщаєм спокій, спокій, спокій у Христі.\n\nКуплет 2\nМи вам звіщаєм радість (Зр.)\nМи вам звіщаєм радість, радість, радість у Христі.\n\nКуплет 3\nМи вам звіщаєм любов (Зр.)\nМи вам звіщаєм любов, любов, любов у Христі.\n\nКуплет 4\nМи вам звіщаєм спокій, ми вам звіщаєм радість, \nМи вам звіщаєм любов,\nМи вам звіщаєм спокій, радість, любов у Христі.', '', '', '', '', 'ua', 0, NULL),
(383, 'Спасе мій', 0, 11, 'Куплет 1\nСпасе мій, в цьому світі гріха й марноти\nМи Тобі лише хочем служити.\nСвої юнії дні, щоб віддати Тобі,\nКаганцем у темряві світити.\n\nКуплет 2\nСерця юні свої ми цілком віддаєм \nНа служіння Тобі, любий Боже,\nСили дай в боротьбі, щоби ворога й тьму \nНам здолати Твоєю любов’ю.\n\nКуплет 3\nДай життя провести до вподоби Тобі\nІ з темряви загиблих спасати.\nДо кінця хрест тяжкий поможи донести,\nЩоб спасенними разом нам стати.', '', '', '', '', 'ua', 0, NULL),
(384, 'Коли Дух Господній', 0, 11, 'Куплет 1\nКоли Дух Господній наповняє мене,\nСпіваю, як Давид\nСпіваю, співаю, співаю, як Давид. (2р.)\n\nКуплет 2\nКоли Дух Господній наповняє мене,\nМолюся, як Давид.\nМолюся, молюся, молюся, як Давид. (2р.)\n\nКуплет 3\nКоли Дух Господній наповняє мене,\nЯ плачу, як Давид.\nЯ плачу, я плачу, я плачу, як Давид. (2р.)\n\nКуплет 4\nКоли Дух Господній наповняє мене,\nСпіваю, як Давид.\nКоли Дух Господній наповняє мене,\nМолюся, як Давид.\nСпіваю, молюся і плачу, як Давид. (2р.)', '', '', '', '', 'ua', 6, NULL),
(385, 'Як цінні ці хвилини', 0, 11, 'Куплет 1\nЯк цінні ці хвилини жити в спільності з Христом. \nРадість серце наповняє, що дітьми ми є Його. \nНе від нас це все залежить, це Спаситель нам придбав.\nНа хресті Він кров святую за нас грішників проляв.\n\nПриспів: \nСкоро день цей настає,\nІ Спаситель наш прийде.\nКожний вірний це одержить,\nЩо Спаситель нам дає.\n\nКуплет 2\nО, як Він ще закликає всіх, хто чує, до Себе.\nІ знайдете відпочинок лише тільки у Христа.\nБо нема рятунку в інших, що живуть тут на землі.\nI не знають, де шукати, - лише тільки у Христі.', '', '', '', '', 'ua', 0, NULL),
(386, 'Чи знаєте люди', 0, 11, 'Куплет 1\nЧи знаєте, люди, що прийде той день,\nЯк прийде, Спаситель судити людей. (2р.)\n\nКуплет 2\nЧи знаєте, люди, що прийде той час,\nЯк прийде Спаситель розлучати нас? (2р.)\n\nКуплет 3\nЧи знаєте, люди, що світу кінець?\nХто заслужить Царство, одержить вінець. (2р.)\n\nКуплет 4\nА гучнії громи будуть гриміти,\nА голосні труби будуть трубіти. (2р.)\n\nКуплет 5\nБуде під ногами земля дрижати,\nЩо не зможуть мертві в гробах лежати. (2р.)\n\nКуплет 6\nУставайте мертві - годі вам лежать,\nТреба перед Богом відповідь давать. (2р.)\n\nКуплет 7\nЯк зійшов Спаситель з праведним мечем, \nЗібрав праві душі і в Царство повів. (2р.)\n\nКуплет 8\nА грішнії душі плачуть, ридають,\nДо Господа Бога руки здіймають. (2р.)\n\nКуплет 9\nА Господь почув їх, відповідь їм дав:\n«Ідіть ви, прокляті, вам місця нема.» (2р.)\n\nКуплет 10\nА грішнії люди плачуть, ридають,\nОтця свого, неньку та й проклинають: (2р.)\n\nКуплет 11\n«Чом ти, моя ненько, та й не навчила,\nЩоб я собі Царство та й заслужила? (2р.)\n\nКуплет 12\nТи мене учила хороше ходить,\nА тепер прийдеться вік в вогні горіть. (2р.)\n\nКуплет 13\nТи мене учила, що Бога нема,\nНаука про Нього, що то якась тьма. (2р.)\n\nКуплет 14\nА тепер я бачу: святий Він сидить,\nРозкрив Вічну Книгу, та й буде судить. (2р.)\n\nКуплет 15\nА праведні душі та й радуються,\nЩо їхньому Царству не буде кінця.» (2р.)', '', '', '', '', 'ua', 0, NULL),
(387, 'Наша надія Ти Христос', 0, 11, 'Куплет 1\nНаша надія - Ти, Христос.\nТи наша радість, наша любов,\nТи наше щастя і життя,\nТи наше світле майбуття.\n\nПриспів: \nЛиш на Тебе ми вповаєм,\n Вгору руки підіймаєм,\nЛиш на Тебе споглядаєм\n Ввись до небес.\n\nКуплет 2\nТи постраждав за нас, Христос,\nТи на хресті пролив Свою кров\nІ нам спасіння вічне приніс,\nВикупив нас від горя й сліз.', '', '', '', '', 'ua', 1, NULL),
(388, 'Ось на наших з тобою столах', 0, 11, 'Куплет 1\nОсь на наших з тобою столах \nХліба бачим завжди достаток.\nА в далеких чужих краях \nЛюдей з голоду гине багато.\n\nПриспів: \nІсус каже: «Я є хліб».\nА без хліба життя немає.\nХто без Бога в цім світі живе,\nЖиття вічного той не має.\n\nКуплет 2\nУ голодного думка така:\nЗа окраєць віддав би маєток.\nА у нас іноді бува -\nВикидають окраєць діти.\n\nКуплет 3\nПам’ять наша не держить зла \nІ голодних не пам’ятає.\nМи лиш знаєм право таке:\nЗадарма наїдатися хлібом.\n\nКуплет 4\nОсь гряде попереду день,\nКоли жниво Господнє настане\nДобрим ділом, друже, скажи,\nЩо для Бога зерном ти став вже.', '', '', '', '', 'ua', 0, NULL),
(389, 'О невже ти підеш', 0, 11, 'Куплет 1\nО, невже ти підеш, не прийнявши Христа,\nЩоб далі в темряві блукать?\nДар Божий - спасіння - відкинеш навік \nІ не приймеш Христа благодать?\n\nПриспів: \nО, невже ти підеш? (Зр.)\nНе прийнявши Христа.\nО, невже ти підеш?\n\nКуплет 2\nІсус із любові страждав на хресті,\nЩоб грішних з темряви звільнить.\nТвої всі гріхи у пречистій крові \nВін може ще нині обмить.\n\nКуплет 3\nО, невже ти підеш? То ж другом своїм \nТи можеш прийняти Христа.\nВін став би хранителем вірним твоїм. \nЦінніша чи є честь така?\n\nКуплет 4\nО, друже, сьогодні Христа не відкинь.\nСпокій дасть тобі тільки Він.\nНа заклик Його поспіши без вагань,\nПокайся і будеш спасен.', '', '', '', '', 'ua', 0, NULL),
(390, 'Бог в світ послав', 0, 11, 'Куплет 1\nБог в світ послав Свого нам Сина.\nВін на хресті за всіх помер.\nІ хоч Його в могилу вклали,\nПорожній гріб всім свідчить нам, що Він живе!\n\nПриспів: \nБо Він живе, я надію маю.\nБо Він живе - весь страх пройде.\nІ знаю я - мене Він любить!\nТепер живу для Нього, бо Ісус живе!\n\nКуплет 2\nХоч часто це життя сумне є,\nГріх нам спокою не дає.\nВін через смерть гріхи обмив всі, - \nТо будем жити вічно з Ним, бо Він живе!\n\nКуплет 3\nІ прийде час - мій день скінчиться,\nІ з болем боротьба пройде.\nВін перемогу дасть над смертю!\nЙого побачу в небі: там Ісус живе!', '', '', '', '', 'ua', 0, NULL),
(391, 'О алілуя амінь', 0, 11, 'Куплет 1\nО, алілуя, амінь! Царство Боже близько.\nО, алілуя, амінь! Схиліться в дусі низько.\nО, алілуя, амінь! Складіть всі славу Богу.\n\nПриспів: \nАлілуя, алілуя, слава Богу\n Алілуя, алілуя, Дух Святий. (2р)\n\nКуплет 2\nО, алілуя, амінь! Живе Отець на небі.\nО, алілуя, амінь! Куди прийдуть всі діти.\nО, алілуя, амінь! В Його ми будем світлі.\n\nКуплет 3\nО, алілуя, амінь! Співайте пісню в дусі.\nО, алілуя, амінь! Немає місця смутку.\nО, алілуя, амінь! Візьміться всі за руки.', '', '', '', '', 'ua', 0, NULL),
(392, 'Пролетять стрілою молодії роки', 0, 11, 'Куплет 1\nПролетять стрілою молодії роки,\nСтомиться серденько від турбот, тривоги.\nОслабіє тіло, ослабіють сили,\nСтане душу мучить близький час могили.\n\nПриспів: \nЛиш щасливий той,\nХто в сивину глибоку\nРадісно згадає молодії роки.\n\nКуплет 2\nІ ніхто не зможе втішити ридання.\nЛиш заб’ється серце, закипить страждання.\nХто в роках пройдешніх бачить лише втрату \nТа не служить Богу, істині і брату.\n\nКуплет 3\nО, не тратьмо, друзі, дармо наші роки,\nУ Христа візьмемо добрії уроки,\nПомагайте ближнім, підбадьорте брата,\nЩоб згадать на старість юність, а не втрату.', '', '', '', '', 'ua', 0, NULL),
(393, 'Радію я і торжествую', 0, 11, 'Куплет 1\nРадію я і торжествую\nСпасенний я кров’ю Христа.\nХриста Ісуса прославляю,\nЯк вірне Його дитя.\n\nПриспів: \nІсус Христос мене звільнив\nІ дав мені вічне життя,\nГріхи простив, в крові обмив\nІ нині я - Боже дитя.\n\nКуплет 2\nСпасенний я в Христі Ісусі,\nСловами не можна сказать.\nВін в серці моїм поселився\nІ любо в Нім пробувать.\n\nКуплет 3\nВінець готовий мій, я знаю,\nУ вічних оселях Христа.\nЯ з вірою Христа чекаю,\nЩоб з Ним пробувать до кінця.', '', '', '', '', 'ua', 3, NULL),
(394, 'Бог є любов а я не знав', 0, 11, 'Куплет 1\nБог є любов, а я не знав. Мене Він полюбив,\nЩо Сина Він на смерть віддав, гріхи мої простив.\n\nПриспів: \nПростив, простив гріхи мої,\nПростив. Він кров пролив аби я жив.\nВін гріх мій на хресті простив, простив.\n\nКуплет 2\nБог є любов, чи знаєш ти? Страждав Він на хресті.\nТобі Він хоче спочинок дать, з душі тягар здійме.\n\nКуплет 3\nБог є любов. Чи хочеш ти у вічності з Ним жить?\nЧи кинеш гріх, чи поспішиш ти Богові служить?\n\nКуплет 4\nБог є любов. Він на хресті п’ять ран за нас прийняв.\nЧи є життя Його в тобі? Чи Бога ти пізнав?\n\nКуплет 5\nБог є любов. О, друже мій, до Нього ти прийди:\nСкажи: Прости, я буду Твій; тягар з душі здійми.', '', '', '', '', 'ua', 0, NULL),
(395, 'Радуйтеся усі люди', 0, 11, 'Куплет 1\nРадуйтеся усі люди,\nРадість з неба вам хай буде.\n\nПриспів: \nВеселая вам новина,\nПородила Діва Сина, | Марія! (Зр.)\n\nКуплет 2\nЗійшов до нас з високості \nТой, що всі гріхи нам простить.\n\nКуплет 3\nДо ясел всі поспішаймо,\nСлаву й честь Йому віддаймо.\n\nКуплет 4\nБудьмо щирі та багаті\nНа добро завжди завзяті.', '', '', '', '', 'ua', 0, NULL),
(396, 'Великая Школа в цім світі', 0, 11, 'Куплет 1\nВеликая Школа в цім світі існує,\nДавно для людей її Бог збудував,\nХоч ворог так часто ту школу руйнує,\nТа завжди Господь Бог той дім поправляв.\n\nПриспів:\n Мій друже, спіши до Господньої школи,\nДо серця науку святую приймай.\nТоді лиш настане кінець цій недолі, \nПовернеться радість, і щастя, і рай.\n\nКуплет 2\nВ тій Школі є милий та славний Учитель;\nТак любо навчає, як в світі цім жить.\nТо вічний, єдиний Ісус наш Спаситель\nПрийшов Він, щоб людям всім очі відкрить.\n\nКуплет 3\nВ тій Школі любов та лиш згода панує \nЛюбов в ній палає, нема їй кінця,\nА зло і неправду, ненависть руйнує,\nЗм’якшає стальні й зачерствілі серця.\n\nКуплет 4\nІ знатних й незнатних в ту Школу приймають,\nХто тільки низеньким при вході зробивсь.\nТаланти та здібності вмить наділяють,\nКорисним для Бога там всякий родивсь.', '', '', '', '', 'ua', 0, NULL),
(397, 'В очах твоїх сльози', 0, 11, 'Куплет 1\nВ очах твоїх сльози чому так блищать?\nІ рани сердечні невпинно болять?\nСумніви та смуток, що гноблять твій дух,\nЖиття огорнув такий страшний недуг.\n\nКуплет 2\nЧи віри забракло у серці твоїм?\nНадія затрачена в Бозі Живім?\nТвій Бог є великий, Всесильний, - згадай!\nДо Нього з молитвою ти поспішай.\n\nКуплет 3\nЛиш тільки до Спаса Христа ти прийдеш,\nИ Нім радість, і щастя, і спокій знайдеш.\nЗагояться рани, твій дух оживе,\nI радісна пісня з грудей попливе.', '', '', '', '', 'ua', 0, NULL),
(398, 'Вже надходить той день', 0, 11, 'Куплет 1\nВже надходить той день, де не буде горя вже.\nАні хмар на небесах, ані сліз, що на очах. \nТой спокій навіки вже в золотім краю буде.\nЩо за день, славний день той буде!\n\nПриспів:\n Що за день то буде, як побачу я Христа,\nЯк погляну на лице, на Того, Хто Спас мене, \nЯк за руку Він візьме, в Дім Отця мене введе, \nЩо за день, радісний день то буде!\n\nКуплет 2\nЩо за день то буде, як Ісус Господь прийде,\nЩоб забрати усіх нас в ті оселі,що для нас.\nЯк на хмарах Він прийде, вірних зустріч там буде!\nЩо за день, славний день то буде!', '', '', '', '', 'ua', 0, NULL),
(399, 'В чудові дні юначих літ', 0, 11, 'Куплет 1\nВ чудові дні юначих літ не знав я зла й біди,\nНе знав журби і клопотів від ранку до зорі.\nЯ не тривожився нічим, по волі жив своїй.\nА серце завжди наповняв біль матері моїй.\n\nПриспів:\nВ молитві матері\t\n(Я чув в молитві матері), 2р.\nЯ часто чув своє ім’я в молитві матері.\n\nКуплет 2\nХодив за голосом бажань, не думав про Творця,\nТим задавав я матері скорботи без кінця.\nТак серце мами день і ніч томилося одне.\nЯ чув щодня: вона в сльозах молилась за мене.\n\nКуплет 3 \nВесь час моїх веселих днів я мамин голос чув:\n«Дивись, мій сину, пам’ятай, щоб слів цих не забув:\nЗла не чини, втікай з гріха, себе ти бережи.»\nЯ чув в молитві матері своє ім’я завжди.\n\nКуплет 4\nТепер знайшов я у Христі спасіння для душі.\nТягар гріхів я склав Йому в молитві у тиші.\nІ щастя, і відкуплення, і промінь той святий \nПролив Христос на розум мій за молитви її.', '', '', '', '', 'ua', 0, NULL),
(400, 'Люблю Господь Твій Дім', 0, 11, 'Куплет 1\nЛюблю, Господь, Твій Дім, бо там Христа Любов,\nБо там я бачу Його Кров, за нас пролиту Ним.(2р.)\n\nКуплет 2\nЛюблю Предвічний Бог, я Церкву — Храм живий. \nЇї боронить Дух Святий від горя і тривог. (2р.)\n\nКуплет 3\nЗа Церкву я молю, за всіх її дітей.\nЛюблю я Церкву із людей, улюблену Твою. (2р.)\n\nКуплет 4\nЯ радий би, друззя, до віку бути в ній, \nЩоб помогти в порі сумній нести її хреста. (2р.)\n\nКуплет 5\nЯ знаю, що разом до Господа ми йдем.\nЯ вірю, вірю, що будем співать перед Христом. (2р.)', '', '', '', '', 'ua', 25, NULL),
(401, 'Дорогий Завіт Ісуса', 0, 11, 'Куплет 1\nДорогий Завіт Ісуса, що Він вірним обіцяв:\n«Нa шляху з землі до неба поведу тебе Я Сам».\n\nПриспів: \nПоведу Я, поведу Я, поведу тебе Я Сам.\n\nКуплет 2\nКоли ворог тебе зводить із шляху, що ти прийняв,\nПам’ятай, що Він говорить: «Поведу тебе Я Сам».\n\nКуплет 3\nКоли серце перестане уповати на Христа - \nТо чуй з вірою слова ці: «Поведу тебе Я Сам».\n\nКуплет 4\nКоли дні життя кінчаться, і остання хвиля йде,\nТо й тоді звучать слова ці: «Поведу тебе Я Сам».', '', '', '', '', 'ua', 0, NULL),
(402, 'Як син марнотратний', 0, 11, 'Куплет 1\nЯк син марнотратний, так і я нещасний \nВ тім світі блудив.\nДуша все стогнала, спокою не мала,\nБо гріх її томив.\n\nКуплет 2\nДуша все стогнала, була в серці спрага, \nЩоб спокій знайти.\nТа мертві обряди не дали розради \nВтомленій душі.\n\nКуплет 3\nШукав я повсюди, де казали люди \nСпасіння собі.\nАле світ лукавий, як той важкий камінь,\nВсе душу гнобив.\n\nКуплет 4\nВтомлений душою, я чув за собою \nХтось кликав мене:\n«Вернись блудний сину, ти йдеш до загину, \nЯ прийму тебе».\n\nКуплет 5\nІ я оглянувся на той дивний поклик,\nХто кликав мене.\nНа хресті прибитий, і кров’ю облитий \nСказав до мене:\n\nКуплет 6\n«Глянь на мої рани, на лице криваве,\nЗвідки кров текла.\nТи - грішник, Я знаю. Я в муках вмираю, \nЩоб дати життя».\n\nКуплет 7\nВід тої хвилини спасен я, щасливий,\nЖиття все віддав \nСпасителю свому, Цареві і Богу,\nПовік Його став.', '', '', '', '', 'ua', 0, NULL),
(403, 'Не сумуй', 0, 11, 'Куплет 1\nНе сумуй, що так склалось у тебе життя, \nТерен густо поріс на дорозі,\nНе сумуй, що нема на землі співчуття \nНа гарячі, гіркі твої сльози.\n\nПриспів:\nНе сумуй, не сумуй! Христос каже тобі і мені. \nЛиш радій, лиш радій! Нагороду тримаю тобі.\n\nКуплет 2\nНе сумуй, що у світі ніхто не зумів \nДо кінця ввесь твій біль зрозуміти.\nНе сумуй, що за те, що ти щиро любив, \nСвіт спішив тобі злом заплатити.\n\nКуплет 3\nНе сумуй, що так довго самотнім ти був,- \nВ житті, може, ще важче прийдеться.\nНе сумуй, що від ближнього ти не почув \nТепле слово від щирого серця.\n\nКуплет 4\nНе сумуй, бо твоя, друже, кожна сльоза \nВ Книзі пам’ятній пишеться в небі.\nНе сумуй, після горя - щаслива пора \nНезабаром настане для тебе.\n\nКуплет 5\nНе сумуй, бо вже явиться скоро з небес \nТой, Хто любить, Хто щиро жаліє.\nДо грудей Він, як батько, пригорне тебе,\nІ без слів до кінця зрозуміє.', '', '', '', '', 'ua', 0, NULL),
(404, 'Він так любить всіх нас', 0, 11, 'Куплет 1\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти.\nІ щоб кожен грішник, яким не був би грішним,\nЗамість смерті життя вічне міг собі знайти.\n\nПриспів:\nВін родився, щоби гріх твій на Себе прийнять,\nБув розп’ятий на Голгофі, за тебе вмирав.\nІ тобі Він дав всю славу і любов Свою,\nНазавжди вернув в Країну неземну.\n\nКуплет 2\nО, невже ж сьогодні ти Христа не приймеш? \nЧом не можеш зрозуміти ту святу любов?\nО, невже ж даремно на хресті вмирав Він? \nПроливав за тебе там Свою невинну кров.\n\nКуплет 3\nВін так любить всіх нас, що покинув небо,\nІ прийшов у грішний світ цей, щоб людей спасти.\nТож прийди сьогодні на поклик Господній!\nВідчини сердечні двері і Христа впусти.', '', '', '', '', 'ua', 0, NULL),
(405, 'Єрусалим що сходить з неба', 0, 11, 'Куплет 1\nЄрусалим, що сходить з неба \nВ проміннях ясних свого Царя.\nТам більше сонце вже не потрібно,\nБо Агнець Божий - рання зоря.\n\nПриспів: \nОце оселя свята Бога з людьми, \nДе будем жити із Богом ми.\nТам усі сльози Ісус з очей зітре. \nСмерті не буде, біль промине.\n\nКуплет 2\nЄрусалим! Нове це місто,\nПерлинні брами відкриті в нім.\nХто прагне пити - нехай приходить, - \nДжерельні води течуть у нім.\n\nКуплет 3\nЄрусалим! Тебе кохаю.\nВ тобі панує вічна любов. \nСпасенні люди в тобі зійдуться. \nПрославлять Спаса за Його кров.', '', '', '', '', 'ua', 6, NULL),
(406, 'Єдиним серцем і устами', 0, 11, 'Куплет 1\nЄдиним серцем і устами \nХвалити Господа начнім.\nЧесть Богу даймо молитвами,\nСмиренно духа приклонім.\n\nКуплет 2\nМолитва щира, Богу мила,\nАж до небес ти вознесись,\nЯк благовонний дим кадила,\nЗа Церкву всю і нарід весь.\n\nКуплет 3\nВладико, Господи Небесний,\nПомилуй нас і пом’яни,\nПрийми молитву - дар словесний \nВід нужд й недолі бережи!\n\nКуплет 4\nТобі готові ми служити \nВесь вік синівської любві,\nТебе бажаємо просити - \nТи з неба нас благослови.\n\nКуплет 5\nІ благодать Свою зливай нам \nНа всякий день і всякий час,\nБезгрішно жити помагай нам,\nСпаси нас, Боже, Отче наш.', '', '', '', '', 'ua', 0, NULL),
(407, 'З нами Бог', 0, 11, 'Куплет 1\nЗ нами Бог! Хто буде проти нас? (З нами Бог!) (Зр.) \nТак Павло Апостол нам сказав.\n\nКуплет 2\nОсь Я з вами буду кожний день! (Кожний день!) (Зр.) \nТак Господь Спаситель нам сказав.\n\nКуплет 3\nКров Христа змиває всякий гріх! (Всякий гріх!) (Зр.) \nТак Іван Апостол нам сказав.\n\nКуплет 4\nДар Святого Духа нам (Господь обіцяв) (Зр.)\nТак пророк Йоіль пророкував.', '', '', '', '', 'ua', 0, NULL),
(408, 'Залишись зі мною', 0, 11, 'Куплет 1\nЗалишись зі мною, бо темніє вже,\nТьма прикриває, не лишай мене.\nЯ покладаюсь на любов Твою.\nТи моя поміч, залишись зі мною.\n\nКуплет 2\nТак і життя день короткий пройде,\nВся земна слава щезне раз-на-все.\nУсе зміняється в світі цьому,\nДруже незмінний! Залишись зі мною!\n\nКуплет 3\nЯ все бажаю всякий час Тебе,\nБо лиш з Тобою переможу все,\nБо хто ж є інший такий вірний друг?\nО, Спасе милий, залишись зі мною!\n\nКуплет 4\nДай, Спасе, щоб Твій хрест я бачив все.\nХай Він провадить все вперед мене.\nНадходить вічний день і проганя тьму,\nВ житті і смерті будь все зі мною.', '', '', '', '', 'ua', 0, NULL),
(409, 'Ісус тебе чекає', 0, 11, 'Куплет 1\nІсус тебе чекає, щоб любив (4р.)\n\nПриспів: \nНезалежно від раси\nЧи від кольору людей -\nТи люби всіх, як братів, роби добро.\n\nКуплет 2\nТому, хто біля тебе, дай любов (4р.)\n\nКуплет 3\nЯк тебе не вітають, дай любов (4р.)', '', '', '', '', 'ua', 1, NULL),
(410, 'Іскра Божа вже погасла', 0, 11, 'Куплет 1\nІскра Божа вже погасла,\nСтали Бога забувать.\nЩо ж ви робите, нещасні?\nВи будете пропадать.\nБо колись-то обіцяв Бог - \nНа землі усіх спасти.\nПослав Сина Свого з неба,\nЩоб звільнити нас з гріхів.\n\nКуплет 2\nБо гріхи - це путь розлога,\nПо якій народи йдуть,\nВорог так завів глибоко,\nЩо не можна повернуть.\nВже багато повертало \nІз широкої путі \nІ знаходять путь-стежину,\nЩоб до Бога нею йти.\n\nКуплет 3\nБо та стежка є вузенька,\nІ сам нею не пройдеш.\nПроси в Бога супроводу,\nТо скоріше перейдеш.\nБо Бог знає твоє серце,\nЯким шляхом ти ідеш,\nШляхом правди, чи шляхом кривди,\nЩо посіяв, те й пожнеш.\n\nКуплет 4\nБо за гробом там не сіють,\nТільки будуть пожинать.\nОдні в клунях, мов пшениця,\nДругі - мов кукіль - в вогні', '', '', '', '', 'ua', 0, NULL),
(411, 'Краю мій', 0, 11, 'Куплет 1\nКраю мій, серцем лину, щоб скоріш \nЯ в брами високі вже входив твої,\nЩоб там спочити, горе забути \nІ всі зітхання на цій землі.\n\nКуплет 2\nІ в сльозах, смутку, горю та журбі \nЯ тут томлюсь завжди на цій чужині. \nКоли згадаю про тебе, Краю,\nТо жаль стискає серце мені.\n\nКуплет 3\nКраю мій, Краю любий, дорогий,\nБогом збудований для Його дітей. \nДо Тебе лину, до Тебе прагну,\nСпішу до Тебе, Краю мій.\n\nКуплет 4\nЗоря ясна виринає вдалині,\nТо мій Край сіяє в рідній стороні \nТуди спішу я, де скоро буду \nВ Сіонськім милім тім краю', '', '', '', '', 'ua', 0, NULL),
(412, 'Коли моє життя кінчатись буде', 0, 11, 'Куплет 1\nКоли моє життя кінчатись буде,\nІ страх, мов камінь, стисне мою грудь,\nКоли почую голос, що покличе \nМене в незнану путь.\n\nКуплет 2\nТоді, мій Спасе, залишись зі мною,\nТак, як в житті стояв при мені Ти.\nЄдина втіхо небесної любові,\nМене не опусти.\n\nКуплет 3\nВудь близько мене, як усе зникає:\nРідня, знайомі, сестри і брати.\nЯк очі згаснуть, серце моє змовкне,\nМене не опусти.\n\nКуплет 4\nТебе Одного, Спасе мій, благаю \nВ годину смерті Ти мене кріпи.\nПодай надію в мою бідну душу,\nМене не опусти.\n\nКуплет 5\nБлаженне місце дай мені, о Боже,\nДе вже нема гріха, ні бур життя,\nТам, де спокій сповняє душу чисту,\nЖиве любов свята.\n\nКуплет 6\nПочую там пісні, ангельський голос,\nЩо їх ніхто на світі не чував.\nПритулок мій - в Тобі, мій милий Боже, \nЯкий мені Ти обіцяв.', '', '', '', '', 'ua', 0, NULL),
(413, 'Моя мета далеко за рікою', 0, 11, 'Куплет 1\nМоя мета далеко, за рікою,\nДо неї змалку я направив путь:\nБо там брати великою сім’єю \nМене до себе на вечерю ждуть.\n\nПриспів: \nЯ все пливу, вперед свій зір керую.\nВже сонечко заходить за обрій.\nХай ураган підноситься й бушує,- \nЯ до мети направив човен свій.\n\nКуплет 2\nЯ через води човен мій направив,\nВід берега далеко вже відбивсь,\nНазустріч хвилі й люті урагани,\nНемов би хочуть, щоб скоріш втопивсь.\n\nКуплет 3\nДалеко бачу світло за рікою,\nТам вже скінчиться небезпечна путь,\nБо там брати великою сім’єю \nМене до себе на вечерю ждуть.', '', '', '', '', 'ua', 0, NULL),
(414, 'Між хвиль бурхливих', 0, 11, 'Куплет 1\nМіж хвиль бурхливих, в життєвім морі \nНіде спокою нема душі.\nДуша так прагне Тебе, Спаситель,\nМолю, мій Боже, о поможи.\n\nПриспів: \nТак прагне серце моє спокою,\nЯ так стомився в борні земній,\nДуша страждає в напливах горя.\nО, Милосердний, зі мною будь.\n\nКуплет 2\nЗлоба невір’я та лицемір’я,\nЗловіщий відблиск гріха й вогню.\nЗло торжествує, але вже близько \nВеликий, славний Господній День!\n\nКуплет 3\nЯ вірю, Боже, що Ти вже скоро \nПрийдеш покласти всьому кінець.\nХто жив в надії на поміч Твою,\nТи подаруєш їм Свій вінець.', '', '', '', '', 'ua', 0, NULL),
(415, 'Мама Мені слово це миле', 0, 11, 'Куплет 1\nМама... Мені слово це миле,\nПовне воно ласки й любві.\nМама... на руках нас носила \nІ нас зберігала в любві..\n\nКуплет 2\nМама... скільки ти пережила,\nМама... скільки горя знесла!\nНас ти берегла і Любила,\nМама... найдорожча моя!\n\nКуплет 3\nМама... Хто так ніжно голубить?\nХто так сам не цінить себе?\nМама... Хто так ніжно ласкає?\nМама... так, тільки ти одна!\n\nКуплет 4\nТи нас до Христа приносила,\nТи нам помагала в біді.\nВ горі і в недолі плекала, — \nМама, хто подібний тобі?\n\nКуплет 5\nМама... Часто діти не люблять \nСтарість і турботу твою,\nЛаску й доброту вони гублять,\nМаму не жаліють свою.\n\nКуплет 6\nПізно, пізно буде при гробі \nПлакать і скорбіти в душі. \nДіти, вам коротка дорога.\nСкоро прийде смерть і до вас.\n\nКуплет 7\nСій, друг, але жати прийдеться \nВсе, що насадила рука.\nМаму ти шануй і побачиш \nЩастя, коли горе в житті.', '', '', '', '', 'ua', 0, NULL),
(416, 'Многі вам літа', 0, 11, 'Куплет 1\nМногі вам літа! (Зр.)\nМногі вам (Зр.) літа!\nБажаєм ми вам | радості щастя. (2р.) \nРадості (Зр.) щастя.\n\nКуплет 2\nЛюбов Христова | хай буде з вами. (2р.)\nХай буде (Зр.) з вами.\nІ хай утішить | Бог Святим Духом. (2р.) \nБог Святим (Зр.) Духом.\n\nКуплет 3\nБлагословить вас | хай Його ласка. (2р.)\nХай Його (Зр.) ласка.\nЛюбіте Бога І і Його діло. (2р.)\nІ Його (Зр.) діло.\n\nКуплет 4\nБудьте ви світлом І в темряві світу. (2р.)\nВ темряві (Зр.) світу.\nЖивіте в згоді. (Зр.)\nЖивіте (Зр.) в згоді.\n\nКуплет 5\nБажаєм ми вам | радості щастя. (2р.)\nРадості (2р.) щастя.\nВеликий Боже, ми Тебе просим:  \nБлагослови їх, благослови Ти їх \nРаз і навіки.', '', '', '', '', 'ua', 0, NULL),
(417, 'Минають дитячі роки', 0, 11, 'Куплет 1\nМинають дитячі роки,\nЯк мряка, коли сонце зійде. \nІ молодість також минула, - \nГосподь уже скоро прийде.\n\nКуплет 2\nМені так миленько велося, \nПриємно мені так було жить. \nЖаль мені те, що не можу \nЯ молодість ту завернуть.\n\nКуплет 3\nТепер то усе це змінилось.\nТурботи так мучать мене.\nАх молодість ти дорогая,\nВернися ти ще до мене.\n\nКуплет 4\nТа того вже бути не може,\nПро теє і думать на варт,\nБо скоро прийде вже могила \nІ тіло покриє земля.\n\nКуплет 5\nБог долю назвав усім людям,\nЗ землі вони й в землю підуть.\nА дух їх, який є від Бога,\nКуди ж він по смерті піде?\n\nКуплет 6\nКоли б мені вічно тут жити \nІ смерті ніколи не знать,\nКоли б молодим завжди бути, \nІ з Богом весь час проживать.', '', '', '', '', 'ua', 0, NULL),
(418, 'На землі не все нам видно', 0, 11, 'Куплет 1\nНа землі не все нам видно, але гляньмо в небеса:\nПеред нашими очима розкривається краса.\nЗірки, місяць, ясне сонце, що Господь їх сотворив,\nВиповняють Божу волю, яку Він їм доручив.\n\nПриспів: \nБог нам дав безсмертну душу,\nЖиття вічне обіцяв.\nВін простив нам всі провини,\nБожий Син за нас страждав.\nО, скажи, мій милий друже,\nЩо Йому за це ти дав?\n\nКуплет 2\nПташки знають свою пору, напрямок, куди летіть.\nДерева, квіточки знають, коли їм зазеленіть.\nВсе творіння славить Бога так, як Він кому звелів,\nДруже, що ти для Ісуса в житті доброго вчинив?\n\nКуплет 3\nБог дає все, що потрібно нам для тіла і душі.\nЙого очі всюди бачать, що Ми творимо в тиші.\nЧас прийде, Господь спитає кожного, що хто зробив \nІ розплатиться по правді, як хто в Нього заслужив.', '', '', '', '', 'ua', 0, NULL),
(419, 'Господь хто увійде', 0, 11, 'Куплет 1\nГосподь, хто увійде в Твою святиню святості? (2р.)\n\nПриспів: \nВ кого чисті руки та щиреє серце,\nНе йде за цим світом, а любить Христа.\n\nКуплет 2\nГосподь, хто увійде в Твою святиню, щоб прославлять? (2р.)\n\nКуплет 3\nГосподь, хто увійде в Твою святиню, щоб вічно жить? (2р.)', '', '', '', '', 'ua', 0, NULL),
(420, 'Юність юність', 0, 11, 'Куплет 1\nО, юність, юність ти золотая,\nТи забираєш барви свої.\nІ непомітно підходить старість,\nІ заглядає в очі мої.\n\nКуплет 2\nПриходить час з тобою розстатись.\nТи відлітаєш, ніби у путь,\nІ наділяєш ти сивиною.\nОх, тебе, юність, більш не вернуть.\n\nКуплет 3\nПройшло дитинство, проходить юність,\nЗабуто все, що проживав.\nТільки одного забуть не можна,\nЩо в роках юних Бога пізнав.\n\nКуплет 4\nО, Боже, Боже, будь милосердний,\nВ тяжкі хвилини допомагай.\nДо сивини, і до могили \nТи мене, Боже, не залишай.\n\nКуплет 5\nО браття-сестри, будем трудитись.\nСпаситель буде нам помагать.\nВінець перлинний Він обіцяє \nТим, хто достоєн його прийнять.', '', '', '', '', 'ua', 0, NULL),
(421, 'О як гарне святе місце', 0, 11, 'Куплет 1\nО, як гарне святе місце, де всі вірні моляться.\nСкільки раз туди приходжу, чую, ніби в небесах.\n\nПриспів: \nПоглянь вгору, зір звернувши!\nВ небо мислями лину,\nРадість наповняє серце,\nЗабуваю про журбу.\n\nКуплет 2\nЧую тут побожні пісні, мов ангельський чудний спів. \nЗабуваю світ лукавий, рветься дух в блакить небес.\n\nКуплет 3\nТам колись при звуці сурем я з Ісусом увійду.\nУвільнить Він з журби й трудів, Його в Царстві восхвалю.', '', '', '', '', 'ua', 0, NULL),
(422, 'Правда любить Бог мене', 0, 11, 'Куплет 1\nПравда, любить Бог мене, Сам за мене постраждав.\nВ темну ніч чи в світлий день буть зі мною обіцяв.\n\nПриспів: \nПравда, любить Бог мене (2р.)\nВін за мене постраждав.\n\nКуплет 2\nПравда, любить Бог мене. Коли в горю я скорблю,\nВін, я вірю, подає руку сильную Свою.\n\nКуплет 3\nПравда, любить Бог мене. І в життєвій боротьбі \nЗлі учинки подолать подає Він сил мені.\n\nКуплет 4\nПравда, любить Бог мене. Учить Він добру без слів. \nВчитись буду в Нього я все життя до вічних днів.', '', '', '', '', 'ua', 0, NULL),
(423, 'Про любов Христа співаймо', 0, 11, 'Куплет 1\nПро любов Христа співаймо,\nПро усі Його діла.\nВ небі чистому там місце \nПриготовив Він для нас.\n\nПриспів: \nЯк ми зійдемось в небі, —\nО, як радісний для нас день буде. \nВбачим там Ісуса \nІ пісню слави викликнем.\n\nКуплет 2\nДоки ми шляхом земним йдем,\nЧасом нас вкриває тьма.\nЯк земний наш шлях скінчиться,\nСпас візьме нас в небеса.\n\nКуплет 3\nБудьмо вірні всі Ісусу \nІ служім Йому усе,\nА як Він прийде у славі,\nНам заплату принесе.\n\nКуплет 4\nВсі вперед і не вагаймось,\nСкоро вбачимо Христа.\nВін відчинить двері райські\nІ введе нас Сам туди.', '', '', '', '', 'ua', 0, NULL),
(424, 'Північ пройшла', 0, 11, 'Куплет 1\nПівніч пройшла, навколо темрява,\nТрохи спізнились ми сюди прийти.\nСвітло погасло, олії нема,\nСтукаймо, може впустять нас туди.\n\nПриспів: \nПізно, пізно, зачинені двері!\nЩоб нам не почути голос той: \n«Вже двері зачинені!»\nСпішіть (усі) тепер (ввійти), - \nЩе двері відчинені.\nІди (іди) іди (скоріш), -\nЩе двері відчинені.\nЩоб нам не почути голос той: \n«Вже двері зачинені.»\n\nКуплет 2\nПівніч пройшла, а ми ще стоїмо,\nЖдемо вже довго, відчини Ти нам.\nДобрий Господар, нас не віджени,\nЧути, як гарно всі співають там.', '', '', '', '', 'ua', 0, NULL),
(425, 'Подивися мій друже на мурашку', 0, 11, 'Куплет 1\nПодивися, мій друже, на мурашку,\nЯк все літо працює вона.\nІ не спить вона літом анітрошки:\nВона знає, що прийде зима.\n\nКуплет 2\nСам Христос тобі руку простягає,\nБо Він хоче, щоб ти працював.\nІ життя тобі дати обіцяє,\nЩоб ти серце Йому віддавав.\n\nКуплет 3\nПодивися, як праці багато,\nЗапустіла вся нива кругом.\nДруже мій, ти долай гріх завзято \nІм’ям Вічного Спаса Христа.\n\nКуплет 4\nПроживай, любий друже, покірно,\nЩоби храм твій сердечний яснів.\nБо прийде мій Спаситель, я вірю,\nПісля горя і темних цих днів.\n\nКуплет 5\nГоді Спаса народи побачать,\nЯк прийде Він судити усіх.\nТоді многії люди заплачуть, \nБo любили неправду і гріх.\n\nКуплет 6\nСпас на вірних ласкаво погляне,\nПрийме в Царство Христос Своє Сам.\nЦарство вічне Христове настане \nВ славі вічного Спаса Христа.', '', '', '', '', 'ua', 0, NULL),
(426, 'Про Божу ласку звіщайте людям', 0, 11, 'Куплет 1\nПро Божу ласку звіщайте людям.\nБог милосердний Сина послав, - \nДать людям визвіл з гріхів-кайданів.\nІ зрозуміть, що за них страждав.\n\nПриспів:\n На хресті Ісус страждав,\nВін святую кров пролляв, \nЖиття вічне Він всім нам придбав,\nНа Голгофі умирав.\n\nКуплет 2\nСпаситель кличе лагідно всіх нас:\n«Прийдіть до Мене, Я прийму вас.»\nА завтра може вже пізно буде,\nСпаситель скаже: «Не знаю вас.»\n\nКуплет 3\nВ Христі Ісусі наше спасіння,\nБо на хресті Він його придбав.\nДав людям визвіл з гріхів-кайданів,\nТо ж Він для цього і умирав.', '', '', '', '', 'ua', 0, NULL),
(427, 'Прийде Господь із Сіону', 0, 11, 'Куплет 1\nПрийде Господь із Сіону, щоб забрати нарід Свій. \nБачить Бог із Свого трону, що настав вже час тяжкий.\nНарод стогне у неволі і знемігся в боротьбі.\nБог по Своїй святій волі світить світлом у ці дні.\n\nКуплет 2\nБог поможе Своїм дітям увійти в святе життя. \nУважаймо, чи ми встоїм в правді Божій до кінця.\nБо лиш вірним Бог поможе, щоб одержати життя. \nХто сповняє Слово Боже, хай хоронить до кінця.\n\nКуплет 3\nХоч і важко в світі жити, гріх бушує навкруги.\nЯк будем Бога гнівити, то пропадем у цій тьмі.\nКоли Господь покарає тую блудницю тяжку,\nТоді мир нам завітає, поміч дасть Господь Свою.\nТреба нам тут свято жити, щоб Господь нас хоронив, \nСвітлом правди засвітити, щоб світильник наш горів.', '', '', '', '', 'ua', 0, NULL),
(428, 'Подивися на Ісуса', 0, 11, 'Куплет 1\nПодивися на Ісуса, на ті Його рани.\nЯк ми своїми гріхами Його розпинали.\nВін молився, Він томився, як ішов на муки.\nЯк привели на Голгофу, цвяхи били в руки.\n\nКуплет 2\nНa голову терен клали, били, як хотіли.\nЯк скінчили поругання, оцтом напоїли.\n«Завершилось» - сказав Господь. О, як кров лилася! \nО, як було тоді страшно, як земля тряслася!\n\nКуплет 3\nБраття, сестри дорогії, щось маю сказати:\nТреба нам себе судити, щоб не постраждати.\nІ ми нині ті страждання, браття, споминаймо,\nДо святого того хліба руку простягаймо.\n\nКуплет 4\nБо ми бачимо, як Юда нерозумно поступив.\nВін з неправдою до хліба свою руку простягнув.', '', '', '', '', 'ua', 0, NULL),
(429, 'Предвічний Небесний Учитель', 0, 11, 'Куплет 1\nПредвічний Небесний Учитель народ научав,\nІ кожний, хто Його йшов слухать, вільний доступ мав.\nНаука з уст Його лилася, оживляла всіх.\nДо Нього матері приносять діточок малих.\n\nКуплет 2\nТа учні стали не пускати їхніх матерів,\nСпаситель же їх научає: «Допустіть дітей, -\nТаких бо є Царство Небесне, - зрозумійте всі, \nТакими маєте у Царстві й самі стати ви».\n\nКуплет 3\nІ матері піднесли діток до Учителя.\nЛюбов’ю засвітліли очі у Спасителя.\nРуками ласкаво Спаситель діток обіймав, - \nПоклавши на голівки руки, їх благословляв.\n\nКуплет 4\nО, Спасе, до Тебе приносим дитятко мале,\nІсусе, благослови й нині немовлятко це!\nНа втіху щоб воно зростало, в святості жило, \nЩоб воно для Тебе, Ісусе, плоди принесло.', '', '', '', '', 'ua', 0, NULL),
(430, 'В часи предавні', 0, 11, 'Куплет 1\nВ часи предавні | сидів й співав. (Зр.)\nВ руках він арфу свою держав,\nСпівав сердечно і славив.\n\nКуплет 2 \nСпівав про Бога, про сильного,\nНема на світі Йому подібного.\nСпівав про Бога, що є любов,\nІ вічно Він той самий буде.\n\nКуплет 3\nДавидом звався | Божий співець. (Зр.)\nВін ладив арфу, співав-співав \nПро своє щастя й спасіння.\n\nКуплет 4\nНа небесах він співа тепер,\nА я скитаюсь тут на землі.\nРазом ми славим з ним Господа \nЗа те, що Він - наш Спаситель.\n\nКуплет 5\nЗ ним я співаю, | а як же ти? (Зр.)\n«Не маю арфи, - говориш ти, - \nСпівать не можу, як Давид».\n\nКуплет 6\nНе маєш арфи - співай псалом,\nСпівать не можеш - молись за всіх;\nНе можеш цього - доказуй всім,\nЩо Ісус є наш Спаситель.\n\nКуплет 7\nДавид співає | там в небесах. (Зр.)\nА я щасливий тут на землі,\nЩо Ісус є наш Спаситель.\n\nКуплет 8\nКоли ми станем перед Творцем,\nІ там з Давидом ми будем всі,\nТо урочисто співать будем,\nЩо Ісус - наш Спаситель.', '', '', '', '', 'ua', 0, NULL),
(431, 'Боже добротливий', 0, 11, 'Куплет 1\nБоже добротливий, вчуй мої благання \nНа землі журливій в дні мого страждання.\n\nПриспів: \nВірному бути дай Тобі, мій Боже,\nДушу ворог лютий хай не переможе. (2р.)\n\nКуплет 2\nЙду я долом смерті всюди за Тобою,\nО, не дай померти з ворогом в двобою.\n\nКуплет 3\nВийду переможно, Спасе мій, з Тобою,\nХоч душа тривожна, сповнена журбою.', '', '', '', '', 'ua', 0, NULL),
(432, 'Боже в серцях наших', 0, 11, 'Куплет 1\nБоже, в серцях наших розпали вогонь,\nХай горить, не гасне в нас Твоя любов.\nВсе, що тільки маєм - власність це Твоя.\nТримай Ти нас міцно у Своїх руках.\n\nПриспів: \nТи наша радість, наше Ти життя!\nВ Тобі Єдинім - світле майбуття.\nНаші молитви чуєш в час тривог, \nІсус-Спаситель, Ти наш Цар і Бог. (2р.)\n\nКуплет 2\nЗбережи нас, Боже, в світі цім від зла,\nМиром наповни наші всі серця;\nВ темноті щоденній зіркою засяй,\nНе залишай же нас, не залишай.\n\nКуплет 3\nНе втрачай надії, зіркою світи,\nЩоб могли в темряві люди шлях знайти.\nЧерез перешкоди з піснею пройти.\nІсус вже близько, зустрічать спіши.', '', '', '', '', 'ua', 0, NULL),
(433, 'В небі є моя свята Вітчизна', 0, 11, 'Куплет 1\nВ небі є моя свята Вітчизна,\nДе нема страждань, сліз і спокус.\nМісце те для мене приготовив \nМій Спаситель - Сам Ісус.\n\nПриспів: \nСкоро, скоро в небі буду я,\nДе Христос з святими мене жде.\nБог не залишить тут мене, в Небо доведе.\n\nКуплет 2\nДім мій є за хмарами високо,\nДе святі спокійно всі живуть.\nСлавлять Бога за любов велику,\nІ мене вони там ждуть.\n\nКуплет 3\nО, Небесна ти моя Країно,\nВсім своїм єством тебе люблю. \nХоч в дорозі часто знемагаю, \nЗ вірою до Тебе йду.', '', '', '', '', 'ua', 0, NULL),
(434, 'Веди нас Месія', 0, 11, 'Куплет 1\nВеди нас, Месія, по стежці вузенькій,\nНе дай нам упасти на нашім шляху.\nЗміцни нашу віру до Тебе, Учитель,\nНе дай же нам більше служити гріху.\n\nКуплет 2\nВеди нас, Месія, до Батька Святого, \nНехай ми побачим всю славу Його.\nМи впадем перед Батьком на наші коліна, \nДитячую славу Йому віддамо.\n\nКуплет 3\nА там пред Престолом Творця заспіваєм, \nСплетемо вінець із пісень тих святих, \nВозложим на вівтар завіту святого,\nРозкажем, як гірко жилося нам тут.\n\nКуплет 4\nОй важко, ой важко, хто Бога не знає, \nЖиття безталанне, гірке, як полин. \nЩасливі ті люди, що Бога шанують \nІ люблять Закон тільки Божий один.', '', '', '', '', 'ua', 0, NULL),
(435, 'В місті Вифлеємі', 0, 11, 'Куплет 1\nВ місті Вифлеємі сталась новина,\nЩо Діва Марія Сина вродила.\n\nПриспів: \nЯк радісна новина!\nСкажіть, де та Дитина?\t\nЩоб ми там поспішали, славу дали.\n\nКуплет 2\nА над Вифлеємом зоря сіяла,\nТрьом царям зі сходу шлях показала.\n\nКуплет 3\nЯк з вірою, браття, шукать будете,\nТо у Вифлеємі Дитя знайдете.\n\nКуплет 4\nА Ірод злосливий з того засмутивсь,\nЩо Христос-Спаситель на світ народивсь.\n\nКуплет 5\nНаказав воїнам всюди шукати \nІ дітей маленьких щоб убивати.\n\nКуплет 6\nДітей повбивали, Вифлеєм пройшли,\nСпасителя ж світу ніде не знайшли.', '', '', '', '', 'ua', 0, NULL),
(436, 'В земній долині', 0, 11, 'Куплет 1\nВ земній долині задоволений я,\nХоч і хатина небагата моя.\nАле в тім місті, де спасенні живуть,\nМене багаті оселі там ждуть.\n\nПриспів:\nЯ маю місце там у славній країні,\nДе не старіють, де вічна весна.\nІ вічно буду з Ісусом я жити,\nКоли ввійду вже у небеса.\n\nКуплет 2\nХоч зустрічаю горе я і недугу,\nАле все ж знаю, що до Неба я йду.\nІ лиш дочасно я з’явився сюди,\nУ Небі буду з Богом завжди.', '', '', '', '', 'ua', 1, NULL),
(437, 'Господь я в душі Тобі вдячний', 0, 11, 'Куплет 1\nГосподь, я в душі Тобі вдячний,\nЗа те, що мене просвітив.\nДо смерті Тебе буду славить,\nЗа те, що гріхи Ти простив.\n\nПриспів: \nЧасто ідучи, сил не мав,\nХоч в боротьбі я не встояв,\nДуші моєї всі думки знаєш лиш Ти.\n\nКуплет 2\nОчі, переповнені смутком,\nСерце плаче і сильно болить.\nЛиш Ти розумієш, мій Боже,\nПоможеш це все пережить.\n\nКуплет 3\nМолюся до Тебе, мій Боже,\nДушею, єством всім своїм.\nЗглянься і прости всі провини,\nДозволь же буть сином Твоїм.', '', '', '', '', 'ua', 0, NULL),
(438, 'Ісусе Тебе люблю', 0, 11, 'Куплет 1\nІсусе, Тебе люблю, тільки Тебе люблю.\nНе можу без Тебе я й дня прожить, тільки Тебе люблю.\n\nКуплет 2\nІсус, Ти є надія, Ісус, Ти є життя.\nІсус, Ти - дорога до неба, о, алілуя!\n\nКуплет 3\nІсус, Ти є мій Пастир, Ісус, Ти є мій друг.\nТобі довіряю своє життя, о, алілуя!\n\nКуплет 4\nІсус, Ти є Спаситель, від мук Ти спас мене.\nТож вічно я буду вже жити там в Небесах Твоїх.', '', '', '', '', 'ua', 0, NULL),
(439, 'Край Палестина', 0, 11, 'Куплет 1\nКрай Палестина - земля благословенна,\nТам, де народився наш Ісус.\nКрай той всім знаний, завжди величний, славний \nСяйвом з неба покритий був кругом.\n\nПриспів: \nО, незабутня є та історія,\nЯк наш Спаситель кров проливав.\nО, кров та дорогоцінна!\nСина Божого Ісуса Христа! 2р.\n\nКуплет 2\nО, незабутня для нас є та історія,\nЯк жив, учив людей колись Христос.\nВ садах оливних, серед гір тих чарівних \nЛились слова Його до слухачів.\n\nКуплет 3\nМури і стіни того Єрусалиму \nСвідчать про всі діла й чуда Христа.\nЯк наш Спаситель на хресті був прибитий, \nВипив чашу гірку за нас до дна.', '', '', '', '', 'ua', 0, NULL),
(440, 'Люди грішні', 0, 11, 'Куплет 1\nЛюди грішні, схаменіться, наверніться до Христа.\nНа Голгофу подивіться,- ллється кров Його свята.\n\nПриспів: \nБожий голос ще лунає, кличе всіх Його любов.\nВсі провини обмиває на хресті пролита кров.\n\nКуплет 2\nЧому досі вам блукати у гріховній марноті,\nСили марно витрачати, дні губити золоті?\n\nКуплет 3\nВи вже стомлені до краю, запеклась на ранах кров.\nПодивіться без відчаю на Голгофу знов і знов.\n\nКуплет 4\nВо широкая дорога - то принада для очей.\nТам лиш горе і тривога, жах безвихідних ночей.', '', '', '', '', 'ua', 0, NULL),
(441, 'Моє щастя заховане в Бозі', 0, 11, 'Куплет 1\nМоє щастя заховане в Бозі,\nНе в земному житті чи ділах,\nБо приходить воно в перемозі,\nА все інше - то тління і прах.\n\nПриспів: \nКраю мій, я радію тобою,\nІ всі мрії мої до тебе.\nТам все радість святого спокою \nІ лиш віра туди приведе.\n\nКуплет 2\nМоє серце завсіди радіє,\nІ немає для нього границь,\nБо з любов’ю Христовою діє \nІ п ’є воду з джерельних криниць.\n\nКуплет 3\nВода чиста там все прибуває,\nЩо з-під каменя завжди дзюрчить.\nВона рани мої обмиває \nІ спокійно дає відпочить.', '', '', '', '', 'ua', 0, NULL),
(442, 'О як хочеться в небо', 0, 11, 'Куплет 1\nО, як хочеться в небо мені, Боже благий!\nТам моя лиш надія, там для серця спокій.\nТам закінчу мандрівку і далеку я путь,\nАж туди мої мрії, щоб скоріш відпочить.\n\nКуплет 2\nСерце рветься, о Боже, Ти мені поможи.\nСвою руку ласкаву на мене поклади,\nОбнови мою душу, Ти мене обніми.\nКоли я в житті падаю, Ти мене підніми.\n\nКуплет 3\nБо я знаю, що в небі - там Країна моя.\nТам брати мої й сестри, моя люба рідня.\nЛиш туди мої думи, хочу бути там я.\nТам уже спочиває Ісуса рідня.\n\nКуплет 4\nТак порою є важко: перепони одні,\nІ ніхто не порадить, не поможе мені.\nДух Святий утішає тоді серце моє,\nМій Христос підкріпляє, мені силу дає.\n\nКуплет 5\nЯсне небо прекрасне і нетлінна краса,\nУ Тобі все так ясне від сіяння Христа.\nУ Тобі там і спокій, там щасливе життя,\nМоє щастя у небі, в Ісуса Христа.\n\nКуплет 6\nВін зітре мої сльози, Спас мене обніме.\nВін мене заспокоїть, там Він явить Себе.\nВ небі яснім, прекраснім з Ісусом моїм \nВічно буду я жити у Небеснім Краю.', '', '', '', '', 'ua', 0, NULL),
(443, 'О як важко іти', 0, 11, 'Куплет 1\nО, як важко іти по вузькому шляху кам’янистім.\nЯ бажаю в душі дні прожити свої життям чистим.\n\nПриспів: \nХрест несу я важкий,\nЙду тернистим шляхом І надіюсь я,\nЩо колись прийде день,\nСльози Бог обітре,\nЯк я з Ним зустрінусь.\n\nКуплет 2\nЯ - безсилий, слабий, щоб боротись в житті.\nСил дальше йти не маю. Але вірю, що Бог \nПоміч дасть в боротьбі. Це я твердо знаю.\n\nКуплет 3\nІ Христос знемагав, коли хрест важкий ніс,\nЩоб за нас померти. Він помер - з мертвих встав, \nДав життя для мене, щоб спасти від смерті.', '', '', '', '', 'ua', 0, NULL),
(444, 'Ой над Вифлеємом', 0, 11, 'Куплет 1\nОй над Вифлеємом, над щасливим краєм,\nТам небесна зірка сяє, срібним світлом грає.\nСрібним світлом грає, та й на стайню вбогу, \nЩо притулком стала нині Предвічному Богу.\n\nКуплет 2\nТам Ісус, Син Божий в темну ніч родився,\nЙ перед ясною зорею в яслах звеселився.\nВ яслах звеселився і став промовляти: \n«Підеш зірко по всім світі ясно запалати».\n\nКуплет 3\nА де зірка гляне, там добро настане,\nБуде щастя, буде доля: ні раба, ні пана.\nНі раба, ні пана, ні важкого лиха.\nРадість люба між братами, мир і згода тиха.\n\nКуплет 4\nОй, ти, ясна зоре, не зайди за море.\nЗлинь на наші рідні ниви, на степи, на гори.\nНа степи, на гори, під селянські стріхи.\nСяй на нас промінням щастя, долі та потіхи.', '', '', '', '', 'ua', 1, NULL),
(445, 'О Дух Святий', 0, 11, 'Куплет 1\nО, Дух Святий, Тебе ми благаєм,\nБлагослови і силу пролий.\nПеред Тобою серце схиляєм,\nНас навісти, любов’ю зігрій.\n\nПриспів: \nГосподи Боже наш Всемогутній, \nДухом Святим повій Ти на нас.\nЗнаєш Ти все, Ти всюди присутній, \nБлагослови нас всіх у цей час.\n\nКуплет 2\nО, Дух Святий, Ти все наповняєш,\nЩастя і радість душам даєш.\nШлях у темряві нам прокладаєш \nІ в Дім Отця, у Небо ведеш.\n\nКуплет 3\nО, Дух Святий, Ти світлом небесним \nШлях на Голгофу нам освітив.\nТам, на Голгофі, подвигом хресним \nДвері спасіння грішним відкрив.', '', '', '', '', 'ua', 3, NULL),
(446, 'Сонце місяць зорі й землю', 0, 11, 'Куплет 1\nСонце, місяць, зорі й землю - Бог усе це сотворив.\nІ життя - дарунок неба також Він нам всім послав.\n\nПриспів: \nБог є любов, (2р.) співаємо разом, \nРазом всі - Бог є любов.\n\nКуплет 2\nЩоб життя було спасенне, з неба Сина Він послав. \nНа горі, горі Голгофі в муках Він за нас вмирав.\n\nКуплет 3\nТому в житті своєму буду вдячний Йому я завжди \nЗа зорі, зорі, зорі ясні й небо, небо голубе.', '', '', '', '', 'ua', 0, NULL),
(447, 'Треба так багато мати сили', 0, 11, 'Куплет 1\nТреба так багато мати сили,\nЩоб не потонути в морі зла.\nДе б мені узяти віри крила?\nЯ би полетів - прощай Земля!\n\nКуплет 2\nВ Небо полетів би я до Бога,\nЗалишився там би назавжди.\nЗнаю до Спасителя дорогу,\nСерцем лину я нераз туди.\n\nКуплет 3\nЛюбий мій Спасителю, Ісусе,\nДай моїй душі все більше сил \nПобороти всі гріхи, спокуси \nТа піднятись в небо і без крил.\n\nКуплет 4\nДай мені в молитві пробувати,\nСерцем завжди линуть в небеса,\nЩоб там вічне щастя, радість мати,\nДе нетління Боже, де краса.', '', '', '', '', 'ua', 0, NULL),
(448, 'Тебе Творця світів просторів', 0, 11, 'Куплет 1\nТебе, Творця світів, просторів\nЯ співом прагну величать\nДай сили, ласки і покори\nСлова достойні уживать\n\nПрипев\nТобі хвалу душа складає\nТобі життя я віддаю.\nІ знаю, там в блаженстві раю,\nХвалу в піснях віддам мою.\n\nКуплет 2\nТвоя величність незмірима\nІ розум гасне, я німий.\nЛюбові грієш Ти промінням,\nЯк сонце вранці в день ясний.\n\nКуплет 3\nПремудрий Ти і Всевидючий,\nСуддя і мертвих і живих.\nСвоїх дітей завжди прощаєш,\nЖиття й надія всіх святих.\n\nКуплет 4\nЯ прагну вічно гімн хваління\nСпівать Тобі, о, Спасе мій,\nЗа дар великий, за спасіння,\nЗа подвиг хрестний, смертний Твій.', '', '', '', '', 'ua', 3, NULL),
(449, 'Ти мій Бог Святий', 0, 11, 'Куплет 1\nТи - мій Бог Святий, до Тебе дух мій,\nБо в Тобі лиш знайду я спокій.\n\nПриспів: \nНа Твоїх грудях заспокоюсь я,\nВідпочине душа там моя.\n\nКуплет 2\nЛиш в Тобі Однім радість всім святим,\nРадість Божа спасенним усім.\n\nКуплет 3\nРадість ця з небес, що дає Отець.\nНе залишить вже наших сердець.\n\nКуплет 4\nЧас мій надійде, все земне пройде,\nВ вічну радість мене Бог введе.', '', '', '', '', 'ua', 0, NULL),
(450, 'У молитві схиляюсь', 0, 11, 'Куплет 1\nУ молитві схиляюсь на коліна в тиші \nІ Тебе я чекаю, Бог - Владика душі.\nВвійди в серце, благаю, Сам засяй у ньому,\nЯ Твій голос пізнаю, Твоє слово прийму.\n\nКуплет 2\nВсі щоденні турботи залишили мене,\nСерце тиснуть скорботи, сон нічний не бере. \nДасиш відповідь, знаю, на питання душі,\nТо ж приходь, я благаю, у вечірній тиші.\n\nКуплет 3\nСловом правди щоденно шлях життя освітляй,\nДай надію нужденним, тайни нам відкривай,\nЩоб прийнять життя слово, щоб горіли серця,\nЩоб дійти до обнови, до Небес, до Отця.', '', '', '', '', 'ua', 7, NULL),
(451, 'Хіба рано віддать', 0, 11, 'Куплет 1\nХіба рано віддать тобі серце Христу?\nПолюбив Він ще юним тебе.\nХіба рано сповнять Його волю святу,\nСвітлу вістку спасіння нести?\n\nПриспів: \nНевже рано, невже рано?\nПрийди до Христа тепер (сьогодні, зараз).\nНевже рано, невже рано?\nЩастя в Ньому, о, повір.\n\nКуплет 2\nЧи ти хочеш віддати всю юність свою \nНа служіння Ісусу Христу?\nНевже варто чекати осіннюю пору,\nЦвіт зів’ялий принести Йому?\n\nКуплет 3\nБез Христа нема радості й щастя тобі.\nВін - Друг вірний, надійний для всіх.\nСпрагу, сховану часто у твоїй душі,\nУтамує в живій Він воді.\n\nКуплет 4\nТвоє бідне життя, як холодна зима,\nЯкщо миру немає в душі.\nА з тобою Христос, то й гроза не страшна, \nЯ спокійний, хоч тьма навкруги.', '', '', '', '', 'ua', 0, NULL),
(452, 'Христос є скеля', 0, 11, 'Куплет 1\nХристос є скеля, вода, з якої ллється,\nВода цілюща, що дає тобі життя.\nХристос є скеля, вода, з якої ллється,\nВода жива, що дасть тобі життя нове.\n\nПриспів: \nЯкщо хтось прагне -\nХай приходить й з неї п’є,\nОсвіжить душу і все єство своє.\nХристос є скеля, вода з якої ллється, \nВода жива, що дасть тобі життя нове.\n\nКуплет 2\nХристос - лілея на ланах квітучих,\nТроянда біла, свіжа із саду Сарон.\nХристос - життя й любов понад любов’ю,\nВін— Той, що нам Своє спасіння подає.', '', '', '', '', 'ua', 1, NULL),
(454, 'Чудову пісню Спас мені дав', 0, 11, 'Куплет 1\nЧудову пісню Спас мені дав з небесної висоти, \nТакої я ще ніколи не співав, то мелодія любві.\n\nПриспів: \nВ моїм серці є мелодія, яка чудова є!\nВ моїм серці є мелодія, то мелодія любві. \nВ моїм серці є подяка, в моїм серці є хвала, \nВ моїм серці є мелодія для Спасителя Христа.\n\nКуплет 2\nЛюбов Христа, Який вмер за нас дала мені вічне життя.\nІ в серці вселила мелодію, радію тепер вже я.\n\nКуплет 3\nБуду співати Спасові я, коли там зійдемось усі.\nО, як буде там мені радісно, коли зустріну святих.', '', '', '', '', 'ua', 0, NULL),
(455, 'Я схиляюся до Тебе', 0, 11, 'Куплет 1\nЯ схиляюся до Тебе, милосердний Батьку мій.\nТи прийми мене до Себе, радість дай душі моїй.\n\nКуплет 2\nЯ блукаю на чужині, без надії, без Христа,\nДармо трачу на чужині молоді свої літа.\n\nКуплет 3\nКину я оцю чужину, встану, в рідний край піду,\nВже не сином, а слугою в ноги Батькові впаду.\n\nКуплет 4\nІ скажу, що я - син блудний, Батьку мій, прости мене,\nІ не згадуй, що я тратив в марноті свої літа.\n\nКуплет 5\nБо я знаю серця муки, які Батько мій несе,\nДень і ніч Він виглядає, коли син Його прийде.', '', '', '', '', 'ua', 0, NULL),
(456, 'Як добре нам разом бути тут', 0, 11, 'Куплет 1\nЯк добре нам разом бути тут,\nСпівати, молитись Богу-Творцю.\nХотілося б бути так щодня,\nА покищо - до побачення...\n\nКуплет 2\nЦя земна розлука лишає жаль,\nІ в серці людини одна печаль,\nА тут на землі біда щодня,\nА покищо - до побачення.\n\nКуплет 3\nХай буде надія на зустріч з Ним,\nДе спокій всім вірним серцям святим.\nНа небі не буде розлучення,\nА покищо - до побачення.\n\nКуплет 4\nНа небі ми будемо жити з Ним,\nДе спокій всім вірним серцям святим. \nНа небі ми будем співать щодня,\nА покищо - до побачення.', '', '', '', '', 'ua', 0, NULL),
(457, 'На світанку чи пізньої ночі', 0, 11, 'Куплет 1\nНа світанку чи пізньої ночі,\nДе б тобі не прийшлося бувати \nДо Небес підіймай свої очі, - \nГоворила мені моя мати.\n\nПриспів: \nНе забудь помолитися Богу,\nБо в молитві - надія та сила.\nСтане легшою важка дорога.\nТи з молитвою будеш щасливий.\n\nКуплет 2\nТі слова мені в серце запали,\nНавесні, мов добірні зернята,\nІ рясні їх дощі поливали,\nБо за мене молилася мати.\n\nКуплет 3\nВ ніжнім смутку твоїм голубинім \nОкеан доброти відчуваю.\nТвоє слово, неначе перлина,\nВ синім небі, мов зіронька сяє.\n\nКуплет 4\nСрібло скроні мої покриває,\nВже і сонце на захід схилилось,\nАле слово її пам’ятаю:\n- Сину мій, не забудь помолитись,', '', '', '', '', 'ua', 0, NULL),
(458, 'Не залишай Ісусе', 0, 11, 'Куплет 1\nНе залишай, Ісусе, не лишай,\nБо без Тебе тут страх душі й одчай,\nЯк через ліс вночі звершати путь.\nО, Спасе мій, завжди зі мною будь.\n\nПриспів: \n3 дитячих літ я помилятись міг,\nТа Ти мене від зла завжди беріг.\nУчитель, скільки в світі зла й біди!\nНе залишай, порадь мене й веди!\n\nКуплет 2 \nБагато стріл смертельних випускав \nПротивник, щоб я на шляху упав.\nНе продержусь і дня я без Тебе, \nНачальник віри, не лиши мене!\n\nКуплет 3\nЗустріти прагну вічную весну \nЗ Тобою, Спасе. А якщо засну, - \nЯк із печери Лазаря збудив - \nМене в життя від смерті проведи.', '', '', '', '', 'ua', 0, NULL),
(459, 'Голгофа', 0, 11, 'Куплет 1\nГолгофа! (Зр.) В цій тиші я спокій знайшов,  \nІ промінь надії зійшов.\nВспокоюєш ти, і гине мій страх,\nЯк бачу крізь сльози Тебе.\n\nПриспів: \nЦвяхи рук там не пробили, а мій гріх.\nТо не люди розп’яли Тебе, а гріх.\nТо не цвяхи Тебе тримали, а мій гріх.\nХоч давно вже це все сталось - бачу Тебе.\n\nКуплет 1\nЯ бачу Тебе, Христе, там: побите лице й безліч ран.\nЦе сила любові Тебе завела,\nЩоб мене звільнити з кайдан.\n\nКуплет 2\nЯ згадую часто той день, Голгофи кривавую тінь, \nПрийшов я під хрест з гріхами в той час,\nЗвільнив мене Сам любий Спас.', '', '', '', '', 'ua', 0, NULL),
(460, 'Вперед через всі перешкоди', 0, 11, 'Куплет 1\nВперед, через всі перешкоди \nВ Країну святую ми йдем.\nЗабудем земні всі негоди,\nТам вічний спочинок знайдем.\n\nПриспів: \nВперед, все вперед, все вперед,\nВсе вперед поспішайте, брати!\nВсе вперед, все вперед,\nХай радісно спів той дзвенить.\n\nКуплет 2\nВперед через терни колючі \nПідемо ми шлях прокладать,\nВидніється край вже наш рідний,\nТам буде нас Бог зустрічать.\n\nКуплет 3\nВперед, хоч скрізь море бушує,\nМов лев хоче нас погубить.\nГосподня рука нас пильнує,\nВона нас в біді захистить.\n\nКуплет 4\nВперед просікаймо дорогу,\nЩоб бачили люди цей слід.\nНесімо плоди ми для Бога \nЗі співом нових перемог.', '', '', '', '', 'ua', 0, NULL),
(461, 'За Мною йди', 0, 11, 'Куплет 1\nЗа Мною йди, коли море бушує.\nЗа Мною йди, коли зло торжествує,\nЗа Мною йди по тернистім шляху.\nО, йди за Мною, іди.\n\nКуплет 1\nЗа Мною йди, коли горе й страждання,\nЗа Мною йди, коли сили немає.\nЗа Мною йди - допоможу тобі.\nО, йди, за Мною іди.\n\nКуплет 2\nЗа Мною йди, коли ворог лякає,\nЗа Мною йди, коли брат забуває,\nЗа Мною йди, не залишу тебе.\nО, йди, за Мною іди.\n\nКуплет 3\nЗа Мною йди, хоч дорога далека,\nЗа Мною йди, хоч порою нелегко,\nЗа Мною йди в Вічний Дім, в Небеса.\nО, йди, за Мною іди.', '', '', '', '', 'ua', 0, NULL),
(462, 'Кров Свою Син Божий', 0, 11, 'Куплет 1\nКров Свою Син Божий пролив,\nІ життя для всіх Він відкрив.\nВін Своїми ранами нас \nВсіх з гріховних пут увільнив. \nЯк вівця в далі я блудив,\nГріх в моєму серці царив.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nПриспів: \nБіліший над сніг (2р.)\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nКуплет 2\nВін вінок терновий носив,\nНа хресті розп’ятий Він був.\nСмуток і тягар Він зносив,\nВін для всіх спасіння здобув.\nЩоб до джерела я прийшов,\nЩоб Христу я серце віддав.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.\n\nКуплет 3\nОтче, я від Тебе пішов,\nЗавсіди я серцем блудив.\nЗнаю, що я тим провинив,\nІ нічим гріха я не змив.\nГосподи, до Тебе я йду,\nЗмий мою всю з мене вину.\nВмий мене з гріхів Ти моїх,\nІ буду біліший над сніг.', '', '', '', '', 'ua', 0, NULL),
(463, 'Любий Спасе', 0, 11, 'Куплет 1\nЛюбий Спасе, Тебе прошу, Тебе молю я щодня.\nХай дійде до Тебе, Спасе, просьба з уст моїх сумна.\n\nКуплет 2\nТа не тільки з уст і серця, але й з цілої душі.\nТебе прошу із безсилля - Ти почуєш голос мій.\n\nКуплет 3\nТебе прошу, вчуй мій голос і Сам мене проведи, \nБо без Тебе я безсильний, щоби до мети дійти.\n\nКуплет 4\nТи Сам бачиш, я стремлюся від літ моїх молодих.\nЯ служить Тобі бажаю серед грізних хвиль страшних.\n\nКуплет 5\nЯк човен мій все прямує, щоб до берега дійти,\nГрізні хвилі заливають, ніде помочі знайти.\n\nКуплет 6\nТож до Тебе я взиваю, одна поміч моя - Ти. \nЯ на Тебе все здаюся, Ти Сам мене проведи.', '', '', '', '', 'ua', 0, NULL),
(464, 'Сонце на захід схилилось', 0, 11, 'Куплет 1\nСонце на захід схилилось,\nОсь, день світла скоро мине.\nНастане нежданно хвилина,\nІ Син Людський в славі прийде.\n\nПриспів: \nСкоро Господь прийде з неба,\nЩоб грішних усіх засудить.\nДо Нього зберуться всі люди,\nВідділить одних від других.\n\nКуплет 2\nПраведним скаже: «Прийдіте,\nДавно жде вас вічне життя, \nЙoro приготовив Отець вам,\nЗа вас умирав тяжко Я».', '', '', '', '', 'ua', 0, NULL),
(465, 'О яка то радість буде', 0, 11, 'Куплет 1\nО, яка то радість буде, не можу сказати,\nКоли Господь Своїх вірних буде забирати.\nУсі гори, наче хори, будуть нам співати. \nСадовина-деревина - в долоні плескати.\n\nКуплет 2\nТоді розлука настане, якої не було,\nЯкої ніхто не бачив, і вухо не чуло.\nРідні сестри будуть разом на жорнах молоти. \nОдну схоче Господь взяти, а другу лишити.\n\nКуплет 3\nСтане сестра, заридає і заломить руки:\nРідну сестру Господь забрав, її ж лишив на муки.\nБатько з сином будуть разом на даху робити, \nСина схоче Господь взяти, а батька лишити.\n\nКуплет 4\nСин повірив в Слово Боже і часто молився,\nБатько за своє невірство на горе лишився. \nМати й дочка будуть в полі, розлука настане. \nРідну матір візьме Господь, а дочку залишить.\n\nКуплет 5\nДочка матір не любила, докоряла грізно.\nТоді схоче покаятись, - буде вже запізно.\nТакож невістка і свекруха будуть розлучатись,\nБо свекруху візьме Господь, невістку ж залишить.\n\nКуплет 6\nІ заплаче, заголосить невістка до Бога,\nБо свекрусі докоряла, не любила Бога.\nДвоє будуть в однім ліжку тої ночі спати,\nХристос прийде з ангелами Церкву забирати.\n\nКуплет 7\nІ заплачуть, заридають жінки й чоловіки,\nБо їх Господь вже розлучить на вічнії віки!\nЯк забере Господь вірних, то многі заплачуть,\nБо вже більше своїх рідних повік не побачать.\n\nКуплет 8\nТому, друже, ти подумай, що робити маєш:\nЧи лишитися на горе, чи гріха зречешся?', '', '', '', '', 'ua', 0, NULL),
(466, 'О християнин як ти живеш', 0, 11, 'Куплет 1\nО, християнин, як ти живеш?\nЯк до Ханаану ти ідеш?\nЧи проводиш свято дні свої,\nЧи приємні Богові вони?\n\nПриспів: \nСкоро Господь прийде,\nАле чи готовими нас знайде? \nТепер дарував Він час,\nЩоб приготувався кожен з нас.\nДавайте будем ми\nЖити справедливо між людьми.\n\nКуплет 2\nА може ти часто заглядав \nУ цей грішний світ і там блукав?\nЗнай, що там панує тільки гріх,\nТам немає радості й потіх.\n\nКуплет 3\nМоже в тебе радості нема,\nІ твоя душа чомусь сумна? \nНавернись до Господа скоріш, \nЩиро та сердечно помолись.\n\nКуплет 4\nБудем пильнувати ми щодня,\nБудем жити свято, без гріха.\nБудемо готові в кожен час \nЗустрічати Господа Христа.', '', '', '', '', 'ua', 0, NULL),
(467, 'Ой тату тату', 0, 11, 'Куплет 1\nОй, тату, тату, як сумно жити,\nКоли відходиш ти від дітей.\nЗоря не сяє, місяць не світить,\nКоли ще прийдеш до дітей?\n\nКуплет 2\nБо горе жити в земній долині. \nСльози втираю із очей.\nОй, тату, тату, коли ще прийдеш, \nРозділиш радість між дітей?\n\nКуплет 3\nРадісна пісня в домі лунала,\nСльози втирав хтось із очей,\nЯк рука твоя, наш любий тату, \nБлагословляла всіх дітей.\n\nКуплет 4\nКуди не глянеш - сумна надія, \nКоли в дитини тата нема.\nСонце хоч світить, але не гріє,\nВсіх укриває доля сумна.\n\nКуплет 5\nНема де взяти любві, поради.\nО, горе, горе все сироті.\nБез тебе, тату, все чужі люди,\nРадість щезає із душі.\n\nКуплет 6\nКоли ще ласка всіх зогрівала,\nО, любий тату, на путі \nУсе схилена голова моя;,\nІ тихо молюся в тиші.\n\nКуплет 7\nО, тату, тату, як сумно жити,\nКоли відходиш ти від дітей.\nЗоря не сяє, сонце не світить,\nКоли ще прийдеш ти до дітей?', '', '', '', '', 'ua', 0, NULL),
(468, 'О Боже милий дай мені сили', 0, 11, 'Куплет 1\nО, Боже милий, дай мені сили,\nЖиття за ближніх покладать,\nІ в серці тихім до могили \nВсі кривди ворогам прощать.\n\nКуплет 2\nНе дай з гріхами помиритись \nУ важкій життєвій боротьбі,\nІ научи мене молитись,\nМолитись гаряче Тобі.\n\nКуплет 3\nО, Боже, Боже, тут зневажають \nМене і рідні, і чужі.\nА я від серця всім прощаю,\nЯк в Слові Ти сказав мені.\n\nКуплет 4\nХай в груди кидають каміння,\nХоч важко й тужно мені жить,\nТа вірю - вчуєш всі моління,\nІ будеш Ти мене любить.\n\nКуплет 5\nО, Боже мій, дай мені сили,\nСлова Твої не забувать,\nУсім прощати до могили \nИ життя за ближніх покладать.', '', '', '', '', 'ua', 0, NULL),
(469, 'Ось вдруге приходжу', 0, 11, 'Куплет 1\nОсь, вдруге на землю приходжу,\nЗабрати готових у рай.\nВставайте, рівняйте дорогу,\nСпливає бо милості час!\n\nКуплет 2\nПогляньте, уже догорає \nГріхами знівечений світ.\nВостаннє Господь закликає:\n«Весільне вбрання зодягніть\n\nКуплет 3\nДонині ви вірили плачем,\nДух істини в серці стогнав.\nТа з вірними звершу інакше,\nВ вас все заблищить, як кришталь.\n\nКуплет 4\nЯ - Бог, Я живий, вас охрещу \nПролитим із неба вогнем,\nУ кожному серці воскресну \nЯ духом Святим у той день!\n\nКуплет 5\nБездушну, удавану віру \nЗруйную дощенту, у мить.\nЯ маску зірву з лицеміра \nІ виявлю гріх перед ним.\n\nКуплет 6\nНе буде між вами розділень, \nВідкинете з серця божків. \nСотворю любові єднання \nУ Дусі Святому навік.\n\nКуплет 7\nОхрещу таким вас хрещенням,\nЯк перших віків християн. \nРозплавлю в горнилі страждання, \nЩоб ввести святих в Ханаан».', '', '', '', '', 'ua', 0, NULL),
(470, 'Господи до Тебе зір', 0, 11, 'Куплет 1\nГосподи, до Тебе зір підношу я, таким, як є, до Тебе йду. \nВтомивсь в житті й душа болить, де спокій я знайду.\n\nКуплет 2\nСльози вночі і вдень я ллю, де спокій я знайду?\nПочуй мене, я жду, де бідний я піду, щоб мир душі знайти?\n\nКуплет 3\nГосподи, до Тебе хочу я прийти, в Тобі я хочу віднайти \nДля серця радість і спокій, прийми мене, я - Твій.\n\nКуплет 4\nБоже! Мої гріхи прости, тягар з душі зніми,\nСпокоєм наділи, самого не лиши, до неба доведи.', '', '', '', '', 'ua', 0, NULL),
(471, 'Боже Боже ми благаєм', 0, 11, 'Куплет 1\nБоже, Боже, ми благаєм: поможи нам в світі йти.\nЧасто важко нам буває, але поміч наша - Ти. (2р.)\n\nКуплет 2\nПосилай нам Твоє Слово і слабим нам силу дай.\nДари Духа і любові в серце щедро проливай. (2р.)\n\nКуплет 3\nВ цьому світі небагато нам боротись і страждать.\nПоможи прожити свято, щоб Ти міг нас в небо взять. (2р.)', '', '', '', '', 'ua', 0, NULL),
(472, 'День уже минає', 0, 11, 'Куплет 1\nДень уже минає, наступає ніч,\nПітьма прикриває кожну земну річ.\nВже на Твоїм небі миготять зірки,\nТихим сном заснули пташки і квітки.\n\nКуплет 2\nІ людей стомлених подолав вже сон. \nХай Господній ангел - сторож їх вікон. \nХай з’явиться світлий нашим діточкам, \nСторожем хай буде всім мандрівникам.\n\nКуплет 3\nКожний біль в ту нічку, Боже, усмири,\nІ до злого вчинку нас не допусти\nАнгел надзирає над народом всім,\nМир святий і спокій Ти зішли в наш дім.\n\nКуплет 4\nЗавтра нас уранці, Боже пробуди.\nІ тільки до добрих вчинків нас веди. \nЩоб могли ми завтра спів почати свій. \nСлава Тобі, Боже, в Трійці Пресвятій!', '', '', '', '', 'ua', 0, NULL),
(473, 'Зважайте люди на Слово', 0, 11, 'Куплет 1\nЗважайте, люди, на Слово Боже,\nБо воно сьогодні звучить,\nВоно замовкнути може скоро \nІ в цей час останній звучить.\n\nПриспів: \nСкажуть люди: «Слово Боже \nНехай ще повернеться нам».\nДармо люди будуть ждати,\nБо Слово не вернеться їм.\n\nКуплет 2\nСлова Амоса так ясні стали,\nЩо він сповіщав наперед:\nЩо люди сильно голодні будуть - \nНе буде то голод про хліб.\n\nКуплет 3 \nХодити будуть від моря до моря \nІ Слова ніде не знайдуть.\nЛюдей за поли хватати будуть \nІ скажуть: «Ось, Слово в тобі!»\n\nКуплет 4\nІ юнаки, і дівчата юні \nЗнеможені будуть в душі.\nЦе все за кару гріховних вчинків,\nЩо славились тут на землі.', '', '', '', '', 'ua', 0, NULL),
(474, 'З Божої ласки', 0, 11, 'Куплет 1\nЗ Божої ласки, ось, двоє людей \nСтали й бажають, щоб Ти, як дітей,\nБлагословив їх, о Боже, з’єднав,\nВ житті родиннім їм щастя подав.\n\nПриспів: \nО, поклади, Боже, руку на них,\nВ житті триматись доріг дай Твоїх.\nМи, Боже, їх доручаєм Тобі,\nБудь з ними завжди в достатку й в біді.\n\nКуплет 2\nЖиттєву разом пройдуть вони путь.\nБлизько Ти, Боже, до них завжди будь,\nЩоб, подружившись, ще краще жили,\nТобі служили усі свої дні.\n\nКуплет 3\nБоже, доглянь, щоб ці юні серця \nВірні в подружжі були до кінця.\nВ радості, в горі, у праці, в біді \nДумки в них завжди хай будуть одні.', '', '', '', '', 'ua', 0, NULL),
(475, 'До Небес мій дух злітає', 0, 11, 'Куплет 1\nДо Небес мій дух злітає, до Всевишнього Творця,\nДе любов Божа спливає на утомлені серця.\n\nКуплет 2\nСонце ясне там сіяє, тут - скитання і одчай.\nТам спокій мене чекає - то ж спішу я в рідний край.\n\nКуплет 3\nТам святі всі проживають у чудових небесах.\nВічно Бога прославляють, а я томлюся в сльозах.\n\nКуплет 4\nГоря там ніхто не знає, там - спасенних сторона.\nТам в любові процвітає вічна радості весна.\n\nКуплет 5\nЛиш до дому я бажаю, Там Христос - Спаситель мій. \nМоє щастя добре знаю - у Вітчизні дорогій.\n\nКуплет 6\nСліз ніхто не проливає, там немає вже журби.\nЯсне сонце вічно сяє Євангельської любві.\n\nКуплет 7\nНе забариться година, смерть до мене прилетить.\nЯ піду в мою Вітчизну, там я вічно буду жить.', '', '', '', '', 'ua', 0, NULL),
(476, 'Дві руки з’єднались', 0, 11, 'Куплет 1\nДві руки з’єднались нині \nПеред Богом назавжди.\nЩоб в важкій земній долині\t\nШлях свій радісно пройти.\nДля піддержки в праці спільній,\nДля потіхи в час важкий.\n\nКуплет 2\nРуку милості, Всесильний,\nПоклади тепер на них. (2р.)\n\nКуплет 3\nДвоє уст тепер сказали \nПеред Богом «Так» святе.\nЖити вірно обіцяли \nНа усе життя своє.\nБоже, ми Тебе благаєм,\nПоможи в житті їм Сам.\n\nКуплет 4\nХай Твої уста з’єднають \nЇх серця на все життя. (2р.)', '', '', '', '', 'ua', 0, NULL),
(477, 'Великі та чудні діла Твої', 0, 11, 'Куплет 1\nВеликі та чудні діла Твої,\nГосподи Боже Вседержителю!\nПраведні і правдиві дороги Твої, - Цар святих!\nХто не побоїться Тебе, Господи,\nІ не прославить імені Твого?\nБо Ти - єдиний Святий,\nВсі народи прийдуть і поклоняться перед Тобою,- \nБо суди Твої об’явились.', '', '', '', '', 'ua', 0, NULL),
(478, 'Ім’я Ісуса дороге', 0, 11, 'Куплет 1\nІм’я Ісуса дороге люблю повторювати все,\nБо завжди радує мене Святе Ім’я Ісуса.\n\nПриспів: \nО, Ісус, хвала Тобі\nХай несеться від землі.\nНайдорожче в світі цім \nСвяте Ім’я Ісуса.\n\nКуплет 2\nСтрадальцям Ім’я миле це, спокій і мир воно несе,\nЛюбов’ю Бога сповнене Святе Ім’я Ісуса.\n\nКуплет 3\nЯ люблю чути це Ім’я, ним кріпиться душа моя.\nХай славить весь народ і я Святе Ім’я Ісуса!\n\nКуплет 4\nНема слів, щоб сказать вповні, як любе те Ім’я мені.\nЙого хай славлять всі святі Святе Ім’я Ісуса.', '', '', '', '', 'ua', 0, NULL),
(479, 'Коли в душі твоїй', 0, 11, 'Куплет 1\nКоли в душі твоїй зовсім нема спокою,\nКоли сумне, о брате мій, твоє лице.\nІ всі думки твої охоплені журбою,\nТоді Ісусові ти розкажи про все.\n\nПриспів: \nА Він, як вірний друг,\nПошле душі твоїй і радість, і спокій,\nІ серце стомлене любов’ю обігріє,\nІ стане радісно тоді душі твоїй.\n\nКуплет 2\nНемає іншого нікого в цьому світі,\nЛиш Він один усякий гріх може простить. \nІ душу у Крові Святого Заповіту \nВін може чистою, як білий сніг, зробить.\n\nКуплет 3\nБо Він віддав колись життя Своє за тебе.\nЩоби сьогодні ти життя безсмертне мав.\nІ за любов оту, проявлену до тебе \nЗавжди ім’я Його величне прославляв.', '', '', '', '', 'ua', 0, NULL),
(480, 'О Боже Отче наш благий', 0, 11, 'Куплет 1\nО, Боже, Отче наш благий, хвала, хвала Тобі.\nЗа кожний дар Твій дорогий, що Ти даєш в любві.\n\nПриспів: \nХвала Тобі, Создателю, за ласку й доброту.\nХвала Тобі, Спасителю, за Кров Твою святу.\n\nКуплет 2\nПрестолуєш Ти в небесах, де вічно світлий день.\nУсі дари в Твоїх руках, Тобою ми живем.\n\nКуплет 3\nТвоя любов мене кріпить, життя мені дає.\nЗа це бажаю я хвалить Святе ім’я Твоє.\n\nКуплет 4\nІз рову темного гріхів Ісус мене підняв.\nДушею й серцем я ожив, святу любов пізнав.\n\nКуплет 5\nЯк пташка з клітки виліта на волю в поле, в гай.\nОтак стремить душа моя в Небесний світлий край.', '', '', '', '', 'ua', 0, NULL),
(481, 'О Христе прийми мою молитву', 0, 11, 'Куплет 1\nО, Христе, прийми мою молитву\nЩиру та простеньку:\nГлянь на нашу Україну, \nНашу любу неньку.\n\nКуплет 2\nДе в неволі вічно пробувають \nНаші браття рідні.\nДе роками знемагають \nЇхні душі бідні.\n\nКуплет 3\nТи пошли їм радість, щастя й волю \nЇхнього сумління.\nДай їм з неба кращу долю \nІ вічне спасіння.', '', '', '', '', 'ua', 0, NULL),
(482, 'Цілою душею я люблю Христа', 0, 11, 'Куплет 1\nЦілою душею я люблю Христа,\nТому відрікаюсь розкошів, добра.\nХристос - мій Спаситель, надія вся моя.\nВід серця люблю я Ісуса Христа.\n\nКуплет 2\nНе я Його перше - мене Він полюбив,\nЗа мене у жертву Свою кров пролив.\nВін - шлях мій до вічного щастя-буття,\nТому я так щиро все люблю Христа.\n\nКуплет 3\nВ найтяжчих хвилинах, в турботах моїх \nДо Спаса звертаюсь в благаннях моїх.\nІду за Тобою, мій Спасе, усе.\nВ добрі і в недолі я люблю Тебе.\n\nКуплет 4\nЯ прагну зустрітись з Ісусом в раю,\nСпівать переможную пісню мою.\nМоє це бажання, моя це мета, - \nНавік щоб зустрітись на лоні Христа.', '', '', '', '', 'ua', 0, NULL),
(483, 'Прощайте браття', 0, 11, 'Куплет 1\nПрощайте, браття, у Христі ріднії.\nМоже, ми з вами вже останній раз.\nІ ви прощайте, сестри дорогії,\nМоже, вам більше не бачити нас.\n\nКуплет 2\nВеселі хвилі ми з вами тут жили,\nСпільно трудились в той останній час,\nРадість і горе разом ми ділили,\nТепер настав розлуки день для нас.\n\nКуплет 3\nПрощайте, друзі наші, прощавайте.\nНе раз в незнанню шкодили ми вам.\nБог нам є світлом - всі це твердо знаєм,\nЩо ви зробили злого, ми прощаєм вам.\n\nКуплет 4\nВсі наші ближні, друзі, прощавайте, \nІдіть слідами Ісуса Христа.\nІ нас в молитвах ви не забувайте, \nПам’ять хай буде навіки свята.\n\nКуплет 5\nПрощай ти, наша дорога країно,\nВи, діти Божі, всі в правді ходіть,\nНе допускайте гріха і руїни,\nА здобувайте для Ісуса світ.\n\nКуплет 6\nПрощальну пісню кінчаєм співати,\nХай з нами буде Христова любов. \nХриста Ісуса будем прославляти,\nА в Його Царстві побачимося знов.', '', '', '', '', 'ua', 0, NULL),
(484, 'Прийди ти до Христа', 0, 11, 'Куплет 1\nПрийди ти до Христа, бо Він вмер за тебе,\nЗа гріх провин твоїх Він Сам віддав Себе. \nДобрий Ісус мій вмер, щоб все простити тобі. \nСерце своє відкрий, - Він дасть тобі спокій.\n\nПриспів:\nСумний враз день прийде, як місця більш не буде, \nДвері відкриті ще є, ввійти ти можеш ще.\nЯкщо ж ти не ввійдеш, то пізно вже буде тоді.\nО, друже мій, прийди, спасіння Його прийми.\n\nКуплет 2\nРуки Господь простер, щоб пригорнуть тебе. \nНадійсь на Нього все, а радість Він пошле. \nПровини всі відкрий, а Він тягар забере. \nТакого, як ти є, в ласці й любві прийме.\n\nКуплет 3\nПоглянь на Голгофу, як кров стікала з ран,\nЯк Агнець на хресті в муках важких вмирав.\nГолос почуй Його, що кличе у любві,\nПрийди не відкладай, Христу себе віддай.', '', '', '', '', 'ua', 0, NULL),
(485, 'Подивись як гарно', 0, 11, 'Куплет 1\nПодивись, як гарно, Бог усе створив:\nТверду землю круглу й небо голубим. \nЩоб на світі люди славили Творця,\nІм’я те святеє, Ім’я Господа Христа.\n\nКуплет 2\nЩоб пізнали люди, що Він любить їх \nІ Йому служили, залишивши гріх.\nНа горі Голгофі в муках умирав,\nБожий Син розп’ятий життя Своє віддав.\n\nКуплет 3\nО, подумай, друже, йдеш ти до кінця,\nНе провадь даремно ти свого життя.\nРозкажи Ісусу, що тебе гнітить,\nВін тобі поможе, від гріхів звільнить.\n\nКуплет 4\nХай наповнить серце радість без кінця,\nІ полине пісня слави для Творця.\nЗа любов велику, за нове життя \nЙ Вічне Царство в небі, - Господу хвала.', '', '', '', '', 'ua', 0, NULL),
(486, 'Пригадай мій друже', 0, 11, 'Куплет 1\nПригадай, мій друже, про Ісуса,\nПро Його любов до нас слабих,\nНемічних, і грішних, і байдужих,\nІ безсильних в боротьбі важкій.\n\nПриспів: \nНе забудь той хрест, що на Голгофі, \nСпаса, що за тебе умирав,\nТой вінок, вінок терновий\nІ ту Кров, що Він за нас пролив.\n\nКуплет 2\nВажко було Спасові страждати,\nВ муках умирати на хресті,\nТа рішив Він гріх там розіп’яти \nІ спасіння дати назавжди.\n\nКуплет 3\nПригорнись ти серцем до Ісуса\nІ відчуєш ти Його тепло, \nЩо тече до нас з гори Голгофи,\nНемов те цілюще джерело.\n\nКуплет 4\nО, поглянь у небо ти покірно,\nТам побачиш ти свого Отця.\nПодивись, як сонце служить вірно,\nТак служи Йому ти до кінця.', '', '', '', '', 'ua', 1, NULL),
(487, 'Почуй мене Боже', 0, 11, 'Куплет 1\nПочуй мене, Боже, коли я сумую,\nКоли моє серце втомилось страждать.\nПочуй, бо тягар мій лежить за спиною.\nУста пломеніють, не можуть мовчать.\n\nКуплет 2\nПочуй мене, Боже, бо слабну порою,\nЙдучи проти вітру вночі і в пургу.\nПочуй, бо я часто болію душею,\nВтомився я, Боже, нема сили йти.\n\nКуплет 3\nДай відповідь, я вже знесилений, прошу.\nЗніми біль, дай радість для серця мого.\nМолюся я щиро, сердечно до Тебе,\nО, Боже, почуй Ти молитву мою.', '', '', '', '', 'ua', 0, NULL),
(488, 'Проповідник один', 0, 11, 'Куплет 1\nПроповідник один із зібрання ішов \nІ в душі сумував:\nЧлени Церкви байдужі, сам зовсім став безсилий, \nВповні Слова не мав.\nХлопчик, ось, при дорозі,\nЩо себе забавляє, на колінах стоїть.\nПастор руку подав, але хлопчик сказав:\n«На колінах - найкраще».\n\nПриспів: \nНа колінах - найкраще. (2р.)\nЧи в добрі, чи в біді \nТи молись у житті,\nНа колінах - найкраще.\n\nКуплет 2\nОсь, він думати став над словами, що чув,\nНемов хлопчик все знав.\nСкоро день проминає, темна ніч вже вітає,\nА заснути не міг.\nВсе забути бажав, інших дум він шукав,\nТа спокою не мав. \nПеред ним те дитя все стоїть, промовля:\n«На колінах - найкраще».\n\nКуплет 3\nВін прийняв ті слова, як від Бога-Отця \nІ молитись почав.\nНа коліна упав, а Бог Духа зілляв,\nЧленів всіх об’єднав.\nУ байдужих людей ревність знов запалив, \nКаганці засвітив.\nПастор духом ожив, хлопця він похвалив. \nНа колінах - найкраще!', '', '', '', '', 'ua', 3, NULL),
(489, 'Пам’ятати завжди треба', 0, 11, 'Куплет 1\nПам’ятати завжди треба - Бог обітницю дав нам:\nНа шляху з землі до неба поведу тебе я Сам!\n\nПриспів: \nДе Я буду, де Я буду,\nІ слуга Мій буде там.\nЯ ніколи не забуду \nЙ поведу тебе Я Сам.\n\nКуплет 2\nКоли втома чи спокуса серце стримує слабе,\nСлухайсь поклику Ісуса: поведу Я Сам тебе.\n\nКуплет 3\nКоли подорож знеможе, як зустрінеш жах, біду, \nХай піддержить Слово Боже: Сам тебе Я поведу\n\nКуплет 4\nКоли смерть прийде за тілом, і злякається Адам,\nХай би слово це бриніло: поведу тебе Я Сам!', '', '', '', '', 'ua', 0, NULL),
(490, 'Боже в цей час', 0, 11, 'Куплет 1\nБоже, в цей час я до Тебе взиваю:\nСили пошли Ти мені.\nСам порятуй мене, - я погибаю \nВ хвилях, в морській глибині.\n\nПриспів: \nБоже, скоріше порятуй мене,\nДай мені приплисти в рідний Край.\n\nКуплет 2\nБоже, поглянь - мене хвилі ховають,\nДалі не можу я плисти. \nДовго боровся я, - і все це даремно,\nПрийди до мене, дай жить!\n\nКуплет 3\nБерег Твій вічний уже недалеко,\nХвилі навколо ревуть.\nСкоро почуй мене, слово скажи лиш, —\nІ море замовкне в ту ж мить.', '', '', '', '', 'ua', 0, NULL),
(491, 'Радість у Христі я знайшов', 0, 11, 'Куплет 1\nРадість у Христі я знайшов.\nВін - моє життя і спокій.\nКоли я до Нього прийшов,\nЗ того часу Батько Він мій.\n\nПриспів: \n3 Того часу я Його Син\nІ радію, що Він прийняв\nМене до святих тих країн,\nЩоб Його я там прославляв.\n\nКуплет 2\nЯ приніс до Нього все зло,\nВін спокій дав в серце моє.\nМені в світі добре буде,\nБо Отець спасіння дає.\n\nКуплет 3\nІ тепер радію всі дні,\nЩо мене мій Батько знайшов.\nВін подав прощення мені,\nКоли я до Нього прийшов.', '', '', '', '', 'ua', 0, NULL),
(492, 'Сину серце Мені дай', 0, 11, 'Куплет 1\nСину, серце Мені дай, на чужині не блукай.\nСерце втомлене рида, і давно воно стражда.\n\nПриспів: \nСину, серце Мені дай! (2р.)\n\nКуплет 2\nУтомився ти блудить, де ж ти зможеш відпочить? \nТо ж іди, вертайсь скоріш, нащо вік губити свій?\n\nКуплет 3\nБуде радісно тобі, коли встоїш в боротьбі.\nТоді прийдеш до Мене, виглядаю Я тебе.\n\nКуплет 4\nХто був ворогом твоїм, того довго ти кохав.\nЯ ж усе віддав тобі, ти ж любить Мене не став.\n\nКуплет 5\nСину, серце Мені дай - неподільне, все цілком. \nРозлучися жить з гріхом, на чужині не блукай.', '', '', '', '', 'ua', 0, NULL),
(493, 'Слово мама найдорожче', 0, 11, 'Куплет 1\nСлово «мама» - найдорожче,\nНим нам треба дорожить.\nЗ її ласкою, любов’ю легко нам на світі жить.\n\nПриспів: \nКоли мама ще жива є,\nТи щасливий на землі,\nБо молитви ллються в небо \nВранці, в південь і вночі.\n\nКуплет 2\nКоли був я ще малятком, мама у тиші нічній,\nНіби ангел яснокрилий, зберігала спокій мій.\n\nКуплет 3\nУ дитинстві безтурботнім я не знав, як важко жить,\nБо трудилась моя мама, щоб кормити й одягать.\n\nКуплет 4\nПам’ятаю, як матуся вчила завжди нас про те,\nЩоб розумно і взірцево ми пройшли життя усе.\n\nКуплет 5\nПам’ятаю, як бувало, я з дороги приїжджав,\nПлечі рідної матусі, як дитина, обнімав.\n\nКуплет 6\nПережив часи розлуки, як схвильована й сумна \nТихо плакала й ридала мама рідна, дорога.\n\nКуплет 7\nІ самотньою зоставшись, пломеніючи в любві,\nДо Отця в сльозах гарячих все молилась у тиші.', '', '', '', '', 'ua', 0, NULL),
(494, 'Скільки душ бажає в світі', 0, 11, 'Куплет 1\nСкільки душ бажає в світі спокій радісний знайти.\nТа ніхто їм не розкаже про Христа, куди іти.\n\nПриспів: \nДруже, брате, йди зі мною \nЛюдські душі потішать.\nБожим Словом та любов’ю \nБудем ми їх зогрівать.\n\nКуплет 2\nСвітла! Світла! - Просять люди. Хто ж піде їх просвіщать? \nХто рішуче піде всюди Правду Божу сповіщать?\n\nКуплет 3\nЩастя, волі там шукають бідні, змучені серця.\nДолі кращої не знають, - хто ж покаже їм Творця?', '', '', '', '', 'ua', 0, NULL),
(495, 'Сміло браття всі підемо', 0, 11, 'Куплет 1\nСміло, браття, всі підемо\nЗа Євангельську віру ми, з гріхом у боротьбу.\n\nПриспів: \nБог - наша сила, ми з Ним підем,\nБог - наша сила, щастя знайдем.\n\nКуплет 2\nБоротьба наша не з тілом,\nА з піднебесним духом злим, - боротись мусим ми.\n\nКуплет 3\nЗодягніться в зброю Божу,\nЩоб встояти у боротьбі у святому житті.\n\nКуплет 4\nСміло, браття, в перемогу!\nЗнайдемо поміч у Христа у Бога і Отця.', '', '', '', '', 'ua', 0, NULL),
(496, 'Сам Твоє дитя веди', 0, 11, 'Куплет 1\nСам Твоє дитя веди,\nБудь нам світлом на путі.\nМій Спаситель і мій Бог,\nБачиш Ти мій кожний крок.\n\nПриспів: \nСам веди, в руці Своїй мене веди,\nНіколи не дай зійти з Твоєї, Господь, путі.\n\nКуплет 2\nГріх як хочеш подолать,\nСам Господь нас захистить.\nНе боюсь я нічого,\nУповаю на Нього.\n\nКуплет 3\nВірю, Ти хорониш нас,\nНе залишиш ні на час,\nВ Край Небесний приведеш,\nУсі сльози Сам утреш.\n\nКуплет 4\nТам не буде вже ридань,\nКрику, горя і страждань,\nСмуток, горе перейде, - \nРадість вічна там буде.\n\nКуплет 5\nТам Єрусалим новий,\nТам наш Бог, Отець Благий,\nТам вулиця золота,\nРадість вічна і свята.\n\nКуплет 6\nПри світлі Його лиця \nСпів Мойсея і Агнця.\nЧудні пісні Мойсея \nСпіватиму Тобі я.\n\nКуплет 7\nТам мільйони є святих.\nВсі на арфах золотих \nГрають пісні без кінця,\nСлавлять Бога і Отця.', '', '', '', '', 'ua', 0, NULL),
(497, 'Скоро Спаситель на землю прийде', 0, 11, 'Куплет 1\nСкоро Спаситель на землю прийде,\nСкоро, о, скоро нам радість пошле,\nСкоро ми будемо всі в небесах,\nВічну хвалу дамо за те, що нас спас.\n\nПриспів: \nЖдемо Тебе, (2р.)\nБоже, о, Боже, ждемо Тебе.\n\nКуплет 2\nБоже, Ти бачиш, як важко жить,\nТебе ми просим: сил нам подай,\nРадість в служінні, смілі серця,\nЩоб люд невірний Тебе бачив в нас.\n\nКуплет 3\nО, ця надія - бути з Христом,\nЄ найдорожча у світі цім.\nВірить, любить і молитись Тобі \nТож поможи, Боже, хрест свій нести!', '', '', '', '', 'ua', 1, NULL),
(498, 'Співайте для Господа пісню нову', 0, 11, 'Куплет 1\nСпівайте для Господа пісню нову. (Зр.)\nСпівайте Йому, співайте Йому.\n\nКуплет 2\nЗа чуда Його цю пісню співайте. (Зр.) \nСпівайте Йому, співайте Йому.\n\nКуплет 4\nБо навіки є Його милосердя. (Зр.)\nСпівайте Йому, співайте Йому.\n\nКуплет 5\nЗа те, що Він нас хрестив Святим Духом. (Зр.) \nСпівайте Йому, співайте Йому.\n\nКуплет 6\nЗа те, що Він нас так любить безмірно. (Зр.) \nСпівайте Йому, співайте Йому.', '', '', '', '', 'ua', 2, NULL),
(499, 'Такий який я є тепер', 0, 11, 'Куплет 1\nТакий, який я є тепер,\nТвоя кров лилась за мене.\nМене Ти кличеш до Себе.\nО, Спасе мій, до Тебе йду.\n\nКуплет 2\nТакий, який є, більш не жду,\nОчиститись з гріхів хочу.\nОбмий мене з гріхів, прошу.\nО, Спасе мій, до Тебе йду.\n\nКуплет 3\nТакий, як є у скорботах \nГнітять мене вагання й страх.\nСпаси мене, бо вмру в гріхах.\nО, Спасе мій, до Тебе йду.\n\nКуплет 4\nДо Тебе йду, не віджени,\nМою Ти душу ізціли.\nВ Небесний Край мене прийми.\nО, Спасе мій, до Тебе йду.', '', '', '', '', 'ua', 0, NULL),
(500, 'Тихая ніч дивная ніч', 0, 11, 'Куплет 1\nТихая ніч, дивная ніч...\nТихий сон все сповив.\nЗ радістю в серці Марія не спить,\nДивне Дитятко у яслах лежить.\nЛюдям Спаситель родивсь! (2р.)\n\nКуплет 2\nТихая ніч, дивная ніч...\nАнгел Божий з’явивсь \nІ пастухам ніжно він проказав:\n«О, не лякайтесь, Бог радість вам дав». \nЛюдям Спаситель родивсь! (2р.)\n\nКуплет 3\nТихая ніч, дивная ніч...\nБожий Син в світ з''явивсь.\nО, нехай тішаться ваші серця,\nХай із любов’ю прославлять Отця.\nЛюдям Спаситель родивсь! (2р.)', '', '', '', '', 'ua', 0, NULL),
(501, 'У цім світі птахи мають гнізда', 0, 11, 'Куплет 1\nУ цім світі птахи мають гнізда,\nА лисиці в земних норах є.\nНаш Спаситель не мав де схилити \nНа землі Своєї голови.\n\nКуплет 2\nВін родився не в пишних палацах,\nХоч цілий світ Сам Він сотворив.\nЗнайшов місце в стаєнці, не в хаті,\nІ там Ірод вже за Ним гонивсь.\n\nКуплет 3\nДо Єгипту мусів Він втікати,\nТридцять років в Галилеї жив.\nА три роки Він ставав навчати,\nДля добра нещасних в світі жив.\n\nКуплет 4\nТа тоді напроти злобно стали \nАрхиреї гонити Його.\nПроти Нього люди бунтували,\nНазивали погано Його.\n\nКуплет 5\n«То - єретик» - на Нього казали,\nБо ВІН правда людей научав.\nБіснуватим Його називали,\nБо Він бісів із них виганяв.\n\nКуплет 6\n«Він Є грішний», - на Нього казали,\nБо Він грішних від гріхів спасав.\n«Він - нечистий», - на Нього казали,\nБо прокажених Він очищав.\n\nКуплет 7\n«Він - обманщик», - на Нього казали,\nБо Він їх із мертвих воскрешав.  \nБожевільним Його називали,\nБо Він сліпим очі відкрив.\n\nКуплет 8\n«То -прожора», - на Нього казали,\nБо Він хлібом людей годував. \nП’яницею Його називали,\nЩо живої води їм давав.\n\nКуплет 9\nТа опісля на Нього напали,\nЯк молився в саду у тиші.\nЙого взяли, руки пов’язали,\nДо Пилата на суд повели.\n\nКуплет 10\nНа голову вінок положили,\nЩо з тернини Йому там сплели.\nА на плечі важкий хрест вложили,\nНа Голгофу Його повели.\n\nКуплет 11\nНа Голгофі до хреста прибили,\nТам умер Він серед важких мук.\nЗа всі добра Йому заплатили, \nТо така заплата з грішних рук.\n\nКуплет 12\n«Не є більший слуга пана свого,—\nТак говорить Спаситель до нас. \nЗненавидів Мене той світ гордий, \nЗненавидить також він і вас».\n\nКуплет 13\n«Князь бісовський» - Мене називали,\nНазивати також будуть вас.\nТе, що в світі зі Мною робили,\nТе і з вами робити будуть.\n\nКуплет 14\nТа не бійтесь, бо і волосина \nНе забракне вам із голови,\nБо я з вами аж до кінця світу,\nЯ поможу вам у боротьбі.', '', '', '', '', 'ua', 0, NULL),
(502, 'Говори говори до душі', 0, 11, 'Куплет 1\nГовори, говори до душі,\nОбнови Ти мене Духом правди.\nГовори, говори до душі, -\nя бажаю віддатись Тобі.\n\nКуплет 2\nУ вечірній тиші Ти мені говори,\nЯк до Тебе думками я лину. \nОчищай мене, мій Господь, \nОбновляй Ти мене Духом правди.\n\nКуплет 3\nО навчи мене, Боже, покірливим буть,\nДай постійно радіти Тобою.\nОсвяти життя кожну мить,\nОбновляй Ти мене Духом правди.', '', '', '', '', 'ua', 0, NULL),
(503, 'Хочу я з Тобою жить', 0, 11, 'Куплет 1\nХочу я з Тобою жить, Спасе, Ти мій дорогий,\nХочу я Тобі служить кожний день і час земний.\nМиру без Тебе нема, щастя без Тебе дріма,\nСвітло лиш в Тобі сія, вічність в нім моя.\n\nКуплет 2\nБув в неволі я, в гріхах, Ти мене з гріха звільнив. \nМертвим був, та Ти мене з мертвих воскресив.\nСерцем де схилюся я, де спічне душа моя?\nЛиш на грудях є Твоїх спокій для Святих.\n\nКуплет 3\nНа Голгофі Ти страждав, кров Свою за нас пролив.\nВ муках Ти важких вмирав, світ цей пожалів.\nХочу, Господи, як Ти, хрест Нести аж до мети. \nТвердо знаю й вірю я: путь в Тобі моя.\n\nКуплет 4\nРозказать, що можна ще про Тебе й любов Твою?\nСльози щастя веселять душу все мою.\nХочу лиш в Тобі я жить, хочу лиш Тобі служить. \nТи - Христос, і вірю я в світле майбуття.', '', '', '', '', 'ua', 2, NULL),
(504, 'Xвалити Господа я буду', 0, 11, 'Куплет 1\nXвалити Господа я буду, поки ще сили Він дає.\nЙому співати тільки буду, поки ще серце в грудях б’є.\n\nКуплет 2\nДоки душа моя в тім світі, то працювати буду я.\nДля Господа на Його ниві, бо щастя в Нім душа знайшла.\n\nКуплет 3\nВід серця вірити я буду, що Сам Господь - моя скала.\nІ я ніколи не забуду, що кров Його мене спасла.\n\nКуплет 4\nХвалити Господа я буду, поки ще сили Він дає.\nЙому співати тільки буду, поки ще серце в грудях б’є.', '', '', '', '', 'ua', 0, NULL),
(505, 'Чому ти мій друже', 0, 11, 'Куплет 1\nЧому ти, мій друже, ще й досі байдуже \nЖивеш у гріхах? Про душу не дбаєш, \nА Біблію маєш і віри не ймеш.\n\nКуплет 2\nХіба ти не чуєш, як ласкаво кличе \nЄвангельський голос Христів? Невже не бажаєш, \nЩоб чути у серці приємність Євангельських слів?\n\nКуплет 3\nО, друже, покайся, з гріхом не дружися,\nДо Спаса прийди. Бо добре ти знаєш,\nЩо стати ти маєш на Його суді.\n\nКуплет 4\nСьогодні Бог хоче, щоб кожен охоче \nСкоріше до Нього прийшов. І замість зотління \nТи радість спасіння для себе у Нього знайшов.\n\nКуплет 5\nЧому ти блукаєш, стомився, страждаєш \nВ дорозі земній? Вернися, мій друже,\nНе будь ти байдужий, вернися скоріш!\n\nКуплет 6\nВернися до Спаса, вернися скоріше, \nПоки ще не пізно, прийди. Поки твоє серце \nЩе б’ється у грудях, старайсь життя вічне знайти.\n\nКуплет 7\nПодумай, що скаже Спаситель, мій друже,- \n«Не знаю Я вас».  Сьогодні не пізно, - \nВставай і відважно борись кожний час.\n\nКуплет 8\nБорись з своїм тілом - Спаситель поможе. \nМолися до Спаса Христа. Вчуй, як призиває \nТебе голос Божий. Спіши, друг, ще світить зоря.', '', '', '', '', 'ua', 0, NULL),
(506, 'Чи оцінюєш достойно', 0, 11, 'Куплет 1\nЧи оцінюєш достойно благодать Христа з небес?\nЯк і поміч Його нам? Попроси смиренно у молитві \nБога, як Отця. Вчує Він з небес тебе!\n\nПриспів: \nВін наповнить твоє серце до розливу. \nТільки до Нього прийди,\nСвоє серце відчини.\nВін наповнить твоё серце до розливу \nСвятим Духом і вогнем.\n\nКуплет 2\nБлагодать Його безмірна, милість Божа вічная,\nА любов великая. Згідно із Його завітом \nСвятим Духом і вогнем сповнить серце твоє Він.\n\nКуплет 3\nПринеси своє ти тіло й душу нині до Христа,\nІ обмийсь в крові Христа. Посвяти себе ти Богу, \nІ віддайсь Йому вповні, а Він Духа дасть тобі.', '', '', '', '', 'ua', 0, NULL),
(507, 'Підніму руки до Царя', 0, 11, 'Куплет 1\nПідніму руки до Царя і Богу сильному співаю, \nЩо все життя своє, мій Бог, Тобі даю.\n\nКуплет 2\nЯ не знаю всіх богів, багатства не бажаю \nІ на Тебе лиш дивлюсь, бо чисте серце маю.\n\nКуплет 3\nО, прийди, Дух Святий, живи в мені.', '', '', '', '', 'ua', 0, NULL),
(508, 'Чому безпечно ти живеш', 0, 11, 'Куплет 1\nЧому безпечно ти живеш сьогодні в світі цім?\nПеред Творцем Всевишнім і Святим \nТворіння Боже найдивніш,\nВід земного всього і найдорожче творива Його.\n\nПриспів: \nМій друже, зупинись, пильніше подивись,\nЧи є у колосі твоїм зерно. Уважно роздивись, \nГлибоко зажурись, щоб не буть лиш \nСолом’яним стеблом.\n\nКуплет 2\nБo сонце, місяць, зорі всі, що сяють в небесах,\nВістять величність Божу у віках.\nВони Йому послушні всі і служать лиш Йому.\nЧи коришся ти так в своїм житті?\n\nКуплет 3\nДивися, як Йому природа піддана у всім.\nВсе клониться перед Божим Лицем.\nНавчися в неї і дивись знов у життя своє- \nЧи так послушний Богові і ти?', '', '', '', '', 'ua', 0, NULL),
(509, 'Чи чуєш друже', 0, 11, 'Куплет 1\nЧи чуєш, друже, заклик Христа?\nНіжно з любов’ю Він кличе: "Прийди».\nЛиш у Христі, в Ньому Одному\nЩастя душі своїй можеш знайти.\n\nПриспів: \nЙди до Ісуса, поки Він кличе,\nІ не відкинь ти Спаса свого.\nЗнай, що не вічно будеш ти чути \nЛаску спасіння і заклик Його.\n\nКуплет 2\nЧи чуєш, друже, що за тебе\nСпас на хресті у стражданнях вмирав?\nЩоб у гріхах ти не загинув, \nРадість і спокій, життя вічне мав.\n\nКуплет 3\nЧи бачиш, друже, що Бог зробив — \nЛюбов’ю вічною нас полюбив.\nТвої гріхи Він взяв на Себе,\nЩоб ти не загинув, але вічно жив.', '', '', '', '', 'ua', 0, NULL),
(510, 'Чи ти був на Голгофі', 0, 11, 'Куплет 1\nЧи ти був на Голгофі, чи бачив хреста,\nНа якому Син Божий вмирав?\nЦе за наші гріхи Він життям заплатив,\nЩоб життя вічне ти і я мав.\n\nПриспів: \nПоможи, Боже мій, зрозуміти любов! \nЩо за нас показав на хресті!\nЛиш тоді зможу я за Тобою іти!\nСеред бур і страждань на землі!\n\nКуплет 2\nНе забуду ніколи страждання Христа, \nЯк між небом й землею висів.\nДе людину з Творцем назавжди примирив,\nЩоб, хто прийме Христа, вічно жив.\n\nКуплет 3\nБог давно кличе всіх, щоб до Нього прийшли,\nА ти досі ще в світі живеш.\nЧим ти платиш Йому за страждання і смерть,\nЗа пролитою кров що даєш?', '', '', '', '', 'ua', 5, NULL),
(511, 'Що то за предивна', 0, 11, 'Куплет 1\nЩо то за предивна в світі новина?\nЩо Діва Марія Сина родила.\nВона Його породила і в яселках положила \nГосподнє Дитя.\n\nКуплет 2\nЙшло три володарі до Народженого, \nНесли вони дари Сумиренному.\nВийшов Ірод та и питає і до себе закликає:\n - Куди ви йдете?\n\nКуплет 3\nА ми йдемо, йдемо до Народженого,\nНесемо ми дари Сумиренному.  \nА ви йдіте, віднайдіте і до мене знов прийдіте,\nЯ потім піду.\n\nКуплет 4\nАле злобний Ірод про те розмишляв \nІ по всьому краю вояків послав.\nДав наказ дітей вбивати, кров невинну проливати, \nХриста шукати.\n\nКуплет 5\nУ дітей маленьких життя відняли,\nПоміж ними всіма Христа не знайшли.\nСлава Йому, слава буде, Спасителю слава всюди,\nНа землі спокій', '', '', '', '', 'ua', 0, NULL),
(512, 'Що ти сіяв Що посіяв', 0, 11, 'Куплет 1\nЩо ти сіяв? Що посіяв? При дорозі що посіяв?\nОсь, летять недобрі птиці, зерна виберуть пшениці: \nЩо ж залишиться тобі? (2р.)\n\nКуплет 2\nЩо ти сіяв? Що посіяв? Між камінням що посіяв? \nМіж камінням грунту мало, що зійшло - і те зів’яло, \nЩо ж залишиться тобі? (2р.)\n\nКуплет 3\nЩо ти сіяв? Що посіяв? Поміж терни що посіяв?\nЗнай марноти та незгоди завжди глушать добрі сходи,\nЩо ж залишиться тобі? (2р.)\n\nКуплет 4\nЩо ти сіяв? Що посіяв? В добрім грунті що посіяв?\nТі посіви не зав’януть у чеканні не обмануть,\nА стократно віддадуть. (2р.)\n\nКуплет 5\nЩо ти сіяв? Що посіяв? В цім житті що ти посіяв?\nВсе, що сіяв, бувши в тілі чи то словом, чи то ділом,\nВсе пожнеш за гробом ти. (2р.)', '', '', '', '', 'ua', 0, NULL),
(513, 'Що я дам Тобі мій Спасе', 0, 11, 'Куплет 1\nЩо я дам Тобі, мій Спасе, за безмежную любов,\nЗа дароване спасіння, за святу пролиту кров?\n\nПриспів:\nДай мені своє ти серце, щоби жити міг Я в нім.\nВсе життя своє земнеє сином добрим будь Моїм.\n\nКуплет 2\nДав би я Тобі всі скарби, що на цій землі придбав,\nТа того Ти не бажаєш - так в Святім Письмі читав.\n\nКуплет 3\nДе не гляну, подивлюся, - все Твоє, о Спасе мій.\nЧим Тобі я відплачуся за той дар великий Твій?', '', '', '', '', 'ua', 0, NULL),
(514, 'Якщо тебе тягар давить', 0, 11, 'Куплет 1\nЯкщо тебе тягар давить,\nНе думай, що це тяжкий гріх.\nБажав би ти кудись піти,\nОднак терпіти треба тут.\n\nПриспів: \nЧекай. Тихим будь, не нарікай,\nЧекай, чекай, чекай, не нарікай.\n\nКуплет 2\nУ тебе терня на путі - \nХристос носив на голові.\nХрест до землі тебе припер- \nЗгадай, Христос на нім помер.\n\nКуплет 3\nКріпись і Богу вірним будь, - \nБог знає, коли хрест зняти.\nНе нарікай і не бунтуйсь,\nЧекай, будь тихим і терпи.\n\nКуплет 4\nЩе хвилька й горя не буде: \nМинеться біль, журба і гнів. \nХристос усіх нас забере \nВ край щастя, миру, вічних втіх.', '', '', '', '', 'ua', 0, NULL),
(515, 'Як тихо скрізь', 0, 11, 'Куплет 1\nЯк тихо скрізь. В глибокій сні \nСповився мрійно Вифлеєм.\nА в небі зіроньки ясні\nНад славним тішаться Царем.\n\nПриспів: \nЦе - ніч Христового Різдва,\nТо Бог Святий з Небес зійшов. \nПророчі здійснились слова, \nГосподня звершилась любов.\n\nКуплет 2\nДалеко десь лунає спів,\nВ небесній Божій висоті.\nTо людям кращих світлих днів \nБажають ангели святі.\n\nКуплет 3\nНебесні арфи золоті \nВ цю пору весело бринять.\nІ чути спів на висоті: \nХвалу віддати там спішать.\n\nКуплет 4\nЯк тихо скрізь. В душі моїй \nРіздвяна нічка сяє знов,\nВ яку в Дитині неземній \nЗ’явилась Божая любов.', '', '', '', '', 'ua', 0, NULL),
(516, 'Я пісню бажаю співати', 0, 11, 'Куплет 1\nЯ пісню бажаю співати \nТому, Хто за мене вмирав. \nІ серцем Того величати,\nСвятую Хто кров проливав.\n\nПриспів: \nПолинь, моя пісне, від серця, \nЛунай із глибини душі.\nДля слави Воскресного Сонця  \nБезкраї хваління неси.\n\nКуплет 2\nЯ пісню Тому заспіваю,\nХто нині із мертвих воскрес.\nСердечну подяку складаю,\t\nХай лине вона до небес.\n\nКуплет 3\nТому я цю пісню співаю, \nХто є поміж, нами всяк час..\nНехай моя пісня лунає, \nМов дзвін, що Спаситель нас спас.', '', '', '', '', 'ua', 0, NULL),
(517, 'Як спрагою втомлена ланя', 0, 11, 'Куплет 1\nЯк спрагою втомлена ланя \nШукає води у степах,\nТак прагне душа за Тобою,\nГосподь мій, Ісус, в небесах.\nДе в світі без Тебе спасіння \nДуші своїй зможу знайти?\nУсюди лиш гріх і страждання,\nСпасти мене можеш лиш Ти\n\nПриспів: \nЯк спрагою втомлена ланя \nШукає води у степах,\nТак прагне душа за Тобою, \nГосподь мій, Ісус, в небесах.\n\nКуплет 2\nЗ Тобою забув я ридання,\nЯ серцем радію в тиші.\nЗабув і журбу, і страждання.\nЛиш в Тобі спокій для душі.\nДля мене ті дні повні щастя,\nКоли бачу сестер, братів,\nКоли Божі діти зберуться,\nЗвучить повний радості спів.\n\nКуплет 3\nБлаженні, що Бога шукають, \nЇх пісням немає кінця.\nБлаженні, що, правди бажають \nІ прагнуть славити Отця.\nО друже, чому ти не прийдеш?\nСпаситель Сам кличе: «Прийди!»  \nСпіши, о душа, ти що прагнеш,\nДо джерел живої води.', '', '', '', '', 'ua', 0, NULL),
(518, 'Як швидко й непомітно', 0, 11, 'Куплет 1\nЯк швидко й непомітно дні життя людського йдуть. \nЩе не скінчилися одні, а вже другі пливуть.\n\nПриспів: \nРік за роком, день за днем \nДо кінця турбот ми йдем.\nОсь, прийде останній час,\nІ Христос покличе нас.\n\nКуплет 2\nХто Господа весь час любив і жив тут завжди з Ним, \nТой, хто тут праведно ходив ввійде з Ним в Вічний Дім.\n\nКуплет 3\nКоли для мене надійде останній час буття,\nХристос покаже, як буде там вічнеє життя.\n\nКуплет 4\nВсім серцем вірю, вірю я, що поклик цей Христів \nПочує і душа моя, бо я по-Слову жив.\n\nКуплет 5\nКоли відкриється вже рай й настане судний час,\nО, Боже мій, Ти спогадай того, кого Ти спас.', '', '', '', '', 'ua', 0, NULL),
(519, 'Я знайшов своє спасіння', 0, 11, 'Куплет 1\nЯ знайшов своє спасіння у Спасителі Христі,\nБо Ісус Христос - мій Пастир, Він спокій дає душі.\n\nКуплет 2\nІ тепер ніхто не зможе засмутити мир в душі, \nБо і труднії хвилини Він полегшить Сам мені.\n\nКуплет 3\nЯк в дорозі знемагаю, під крило іду Його.\nІ лиш спрагу погасити в Слові зможу я Його.\n\nКуплет 4\nВідкупитель мій зі мною, розмовляю часто з Ним,\nАле дивна та розмова не повториться ніким.\n\nКуплет 5\nВін мене не відкидає, вчувши жалобу мою.\nІ в потребах життя мого руку подає Свою.\n\nКуплет 6\nВід нещастя зберігає, Він хоронить на путі. \nІ життя дає мені Він, Він давно простив мені.\n\nКуплет 7\nЯкщо хочете дізнатись, що є щастя для душі,\nТо відкиньте всі сумніви і знайдіть Його в Христі.\n\nКуплет 8\nУ серцях своїх рішайте завжди прямо з Ним іти.\nБо безмежно Він вас любить, допоможе нам в путі.', '', '', '', '', 'ua', 0, NULL),
(520, 'О Боже мій хочу щодня', 0, 11, 'Куплет 1\nО, Боже мій, хочу щодня  \nВ житті моїм буть вірним я;\nДля Тебе лиш одного жить,  \nІ повсякчас Тебе любить.\n\nПриспів:\nТут на землі (тут на землі)\nІ в небесах (і в небесах)\nПрославлю я (прославлю я)  \nТебе в піснях (тебе в піснях)\nЗа доброту (за доброту)  \nІ за життя (і за життя),\nЯке в Тобі (яке в Тобі)\nВже маю я (вже маю я).\n\nКуплет 2\nО, Боже мій, допоможи \nБлагу цю вість усім нести,\t\nІ розказать всім про Христа, \nЯкий дає усім життя.\n\nКуплет 3\n0, Боже мій. дай Ти мені  \nШляхом Твоїм хутчій іти,\nНещасним всім допоможи \nЩастя в Тобі їм віднайти.\n\nКуплет 4\n0, Боже мій, веди мене  \nДухом Твоїм в краю земнім. \nЗабути всю журбу в житті \nІ радісно співать Тобі.', '', '', '', '', 'ua', 0, NULL),
(521, 'Я довго блукав у цьому світі', 0, 11, 'Куплет 1\nЯ довго блукав у цьому світі\nІ сам я не знав, що шукав.\nТа Ісус простягнув мені руку\nІ життя вічне Він мені дав.\n\nПриспів: \nЗвільнив Він мене від неволі,\nВід муки, біди і гріха.\nПослав в моє серце Він радість, \nСпіваю тепер для Христа.\n\nКуплет 2\nМій друже, що ти шукаєш?\nЯка є у тебе мета?\nТо ж знай, що нічого не знайдеш, \nБo щастя є тільки в Христа.', '', '', '', '', 'ua', 0, NULL),
(522, 'Поклоняюсь я Творцю землі', 0, 11, 'Куплет 1\nПоклоняюсь я Творцю землі.\nМогутній Бог, для Тебе пісня ця.\nСвятиться Ім''я Твоє! Святиться Ім''я Твоє!\n\nПриспів: \nВін Той, що був і є. Бог-Отець і Син, \nЦар царів і Пан панів!\nТвоє Ім''я, Твоє Ім''я, Твоє Ім''я святе', '', '', '', '', 'ua', 0, NULL),
(523, 'Я дякую Тобі Спаситель мій', 0, 11, 'Куплет 1\nЯ дякую Тобі, Спаситель мій,\nЗа те, що спас мене,- тепер я Твій.\nЯка велика є любов Христа!\nЗ гріхів мене спасла, життя дала.\n\nКуплет 2\nЯ дякую Тобі за мир душі,\nЗа те, що близький Ти, як я в журбі.\nТебе прославлю я, Спаситель мій, \nЗа ласку і любов, за спокій Твій.\n\nКуплет 3\nМене за руку Ти шляхом ведеш.\nУ важкі дні страждань сил подаєш.\nВ Небесний Край я йду, о, Боже мій.\nІ буду там, в раю навіки Твій.', '', '', '', '', 'ua', 1, NULL),
(524, 'Як душа моя сумная', 0, 11, 'Куплет 1\nЯк душа моя сумная, зір звертаю в небеса. \nКоли ближнього немає, зір звертаю в небеса.\n\nПриспів: \nВ небеса, в небеса,\nСвій зір звертаю в небеса. Алілуя!\n\nКуплет 2\nКоли Бог благословляє, зір звертаю в небеса.\nКоли славлю, Господа, я зір звертаю в небеса.\n\nКуплет 3\nЩоб цей світ мав радість, спокій, зір звертаю в небеса. \nЩоб всі знали про Христа, я зір  звертаю в небеса.', '', '', '', '', 'ua', 0, NULL),
(525, 'Я без Бога прожив', 0, 11, 'Куплет 1\nЯ без Бога прожив \nтільки літ І не знав Його доброї волі. \nВ марноті і неправді ходив\nНа дорозі гріха та недолік.\nТа зустрів оДИН раз християн \nІ почув слово правди святої:\nЯк Христос за гріхи умирав,\nЩоб звільнити всіх нас від неволі.\n\nПриспів:\nНі, не забудь, що Він кличе сьогодні з любовью.\nПоки ласки Господньої час, не легковаж.\nНі, не відкинь, Його голос є ніжний, ласкавий. \nВін за тебе вмирав на хресті, \nЩоб тобі дарувати життя.\n\nКуплет 2\nВін тебе жде щоночі, щодня,\nТак як батько блудного сина.\nПри дорозі стоїть, вигляда,\nЯк не прийнять такого Христа?', '', '', '', '', 'ua', 0, NULL),
(526, 'Я врятований від смерті', 0, 11, 'Куплет 1\nЯ врятований від смерті Сином Божим на хресті.  \nПриєднавсь до Його Церкви, даром взяв дари святі.\n\nПриспів: \nВін є Альфа і Омега, \nВін - Початок і Кінець.\nБільш нічого вже не треба:\nВін- утіха для сердець.\n\nКуплет 2\nЯ Христові покорився і своє життя віддав. \nДобровільно охрестився, себе Богу присвятив.\n\nКуплет 3\nБуду завжди умалятись і Спасителю служить. \nДухом Божим керуватись, По Євангелії жить.', '', '', '', '', 'ua', 0, NULL),
(527, 'Як до струменя олень', 0, 11, 'Куплет 1\nЯк до струменя олень так душа моя хоче,\nЛиш до Тебе, мій Боже, все летить і летить.\nЛиш до Тебе, Чудовий, і в півдні, і в півночі \nПориваються очі, і Сльоза в них тремтить.\n\nКуплет 2\nТи мешкаєш над морем, Ти пануєш землею. \nТи є Цар і Страдалець, мій Спаситель ІСУС.\nЯ до Тебе бажаю, як бджола до лілеї,\nЯк до струменя олень, так до Тебе і я.\n\nКуплет 3\nДе весілля безмірне, де невір''я  негідне, \nТам немає утіхи для душі без Христа.\nТільки там лиш знайду я собі щастя безмірне, \nДе панує братерство, де свята чистота.', '', '', '', '', 'ua', 1, NULL),
(528, 'Хвала Тобі о Боже мій', 0, 11, 'Куплет 1\nХвала Тобі, о Боже мій, Великий Цар небес, землі.\nВсе підкоряється Тобі на небесах і на, землі.\n\nКуплет 2\nІ все Тобою створено Володарем і вічним Богом. \nНема імення на землі, щоб називать Великим Богом.\n\nКуплет 3\nІ в світлі дивнім із небес, у сяйві слави вічної.\nТебе все славить буду я, Спаситель мій любимий.\n\nКуплет 4\nІ хай живе любов Твоя в народі вибранім Тобою.\nВ Твоїх ми зійдемось місцях, серця, оновлені Тобою.\n\nКуплет 5\nТобі і слава, мій Господь, Тобі і поклоніння,\nЩо хліб щоденний подаєш і мир Свій посилаєш.\n\nКуплет 6\nЯк дивно Ти все сотворив і серце радість наповняє. \nКоли з Тобою в самоті я, Боже мій, перебуваю.\n\nКуплет 7\nТобі і слава, і хвала, Тобі і поклоніння,\nЗа те, що полюбив мене, бо Ти — моє спасіння.\n\nКуплет 8\nО, алілуя, мій Господь, подяка і хваління.\nТебе прославлю я в піснях, бо Ти - моє спасіння.', '', '', '', '', 'ua', 0, NULL),
(529, 'Спокою часто шукав я', 0, 11, 'Куплет 1\nСпокою часто шукав я в марноті земній, \nПричину невдач всіх своїх я не бачив в собі.  \nРозвагами світу хотів я заповнить життя,\nА Він хотів все мене врятувать від Гріха.\n\nПриспів: \nВін на мене чекав. (2р.)\nЯ життя марнував, а Він мене чекав.\n\nКуплет 2\nБільше не буду шукати у світі ярма, \nВ Спасі моїм я знайшов весь зміст мого життя.\nБуду щоденно у волі Його пробувать, \nЖаль тільки того, що Він мене так довго чекав.', '', '', '', '', 'ua', 0, NULL),
(530, 'Він є любов', 0, 11, 'Куплет 1\nВін є любов, жде тебе, Він - Твій Бог  \nДруже, прийди від гріха і тривог.  \nВін є любов сердечна й свята, \nСерце своє лиш відкрий для Христа,\n\nКуплет 2\nВін є любов, залиши всякий страх,\nДруже, спіши - жде Христос в небесах.\nВін є любов, з Ним щасливе життя,\nВічний спокій в Ньому знайде душа.\n\nКуплет 3\nВін є любов, дав життя за тебе,\nО, Божий Агнець взяв гріх на Себе.\nВін є любов, за тебе Він терпів,\nІ на Голгофі Свою кров пролив.', '', '', '', '', 'ua', 0, NULL),
(531, 'Горе попереджень не да', 0, 11, 'Куплет 1\nГоре попереджень не дає,\nМногих неготових застає:\nТа коли зір віри в небесах,\nНаше горе заступає Спас.\n\nПриспів: \nЛиш відкривши очі на зорі,\nТи прямуй до Того, Хто вгорі. \nДобре нам навчитись пам’ятать,\nЩоб думки й зір в небо направлять.\n\nКуплет 2\nЗнаєм всі ми осінь і весну,\nРоки забирають всю красу.\t\nТа велика радість в небі всім,\nТам ніхто не буде вже старим.\n\nКуплет 3\nСкоро, скоро пил земних доріг,  \nЗ втомлених ми отряхнемо ніг.\nВелич Божу будем оглядать,\nВічно в небі з Богом пробувать.', '', '', '', '', 'ua', 0, NULL),
(532, 'Нива вже дозріла', 0, 11, 'Куплет 1\nНива вже дозріла і стоїть,\nЗолотії зерна обсипаються. \nТільки вітер жниво колиха,\nТа ніхто до нього не звертається.\n\nКуплет 2\nСонце теплим променем горить, \nПідбадьорить та зміцнить робочого,\nТа ніхто на ниву не спішить,\nВажко так знайти туди охочого.\n\nКуплет 3\nДе ж женці, де трудівники дня?  \nНа роботу довго щось збираються.\nХолодом вже віє на полях,\nНиви непожаті обсипаються.\n\nКуплет 4\nТож скоріше, поспішім, друззя,\nЩоб зібрать плоди святого діла.\nБо вже день приходить до кінця,\nНива довгожданна вже дозріла,', '', '', '', '', 'ua', 0, NULL),
(533, 'За горою стоїть місто', 0, 11, 'Куплет 1\nЗа горою стоїть місто, де побачив я \nВ мерехтінні світил пророчих обітницю Отця.\n\nПриспів: \nЄрусалим, Єрусалим,\nЗ пророчих слів відомо нам,\nЩо східна брама буде відкрита,  \nЄрусалим святий.\n\nКуплет 2\nЧудове місто красою вбране, ти і як колись \nЖдеш Царя, Його приходу, Єрусалим святий.', '', '', '', '', 'ua', 0, NULL),
(534, 'Листя осіннєє', 0, 11, 'Куплет 1\nЛистя осіннєє крутиться, падає,\nНемов сірим кличем летить вдалині.\nПрирода вся меркне і завмирає,\nІ провіщає, що скоро зима.\n\nКуплет 2\nЖиття, ніби літо, так швидко проходить,\nНемов човен, що на хвилях пливе.\nЗ кожним днем далі його відносить, \nЧовна, в простори життя-океан.\n\nКуплет 3\nТам я зіллюся з всіма святими,\nВ вічних оселях Бога-Отця.\nТам вже не буде днів рахування,\nТам в Бога вічне життя без кінця,\n\nКуплет 4\nЛистя все крутиться, спокійно падає \nСкоро прийде вже сива зима.\nО, не сумуй, душе, бо життя вічне нам \nДане Спасителем Христом назавжди.', '', '', '', '', 'ua', 0, NULL),
(535, 'Ти подивись лиш навкруги', 0, 11, 'Куплет 1\nТи подивись лиш навкруги, \nЯк зеленіють і цвітуть сади, \nПісня пташина в небо летить,  \nВодиця джерельна струмками біжить.\n\nПриспів: \nВ серце Спаситель до нас промовля \nЧерез ті гори, ліси і моря,\nТи своє серце для Нього відкрий.\nІ ти відчуєш, що Він - Бог Живий.\n\nКуплет 2\nСкоро Господь з неба прийде,\nВсіх Своїх вірних в життя поведе,\nТи не спіши у неправді іти,\nАдже ти можеш душу спасти.', '', '', '', '', 'ua', 0, NULL),
(536, 'Вірую', 0, 11, 'Куплет 1\nВірую в Єдиного Бога Отця Всемогутнього,\nТворця неба і землі, всього видимого і невидимого. \nЄдиного Господа Ісуса Христа Сина Божого, \nЄдинорідного від Отця родженого,\nНесотвореного перше всіх віків,\n\nКуплет 2\nСвітла від світла, Бога істинного від Бога істинного. \nРодженого, несотвореного,\nОдноістотного з Отцем, через Котрого все сталося. \nВін для нас, людей, і для нашого спасіння\nЗ неба зійшов. І тіло прийняв від Духа Святого,\n\nКуплет 3\nВід Діви Марії і стався людиною \nРозп’ятий був за нас при понтійськім Пилаті, \nСтраждав, помер і був похований.\nІ в третій день воскрес, як було написано,\nІ вознісся на небо і сидить праворуч Отця.\n\nКуплет 4\nІзнову прийде у славі судити живих і мертвих,  \nЙого же Царству не буде кінця. \nІ в Духа Святого, Господа оживляючого,\nЩо від Отця походить.\nЩо Йому з Отцем і Сином однаковий\n\nКуплет 5\nПоклін і однакова слава,\nЩо говорив через пророків.\nВ Єдиную Соборную Апостольськую Церкву. \nВизнаю одне хрещення і відпущення гріхів,\nЧекаю воскресіння мертвих і життя будучого віку. Амінь.', '', '', '', '', 'ua', 0, NULL),
(537, 'О Син Божий Примиритель', 0, 11, 'Куплет 1\nО, Син Божий - Примиритель,\nТи - мій Спас і Відкупитель,\nА я - недостойний, Твій найменший воїн,\nХочу Тобі служити.\n\nКуплет 2\nЯ бажаю в бій вступати,\nБожу правду захищати,\nТа не маю сили, мій Ісусе милий, -\nХочу Тебе просити.\n\nКуплет 3\nПідкріпляй мене слабого,\nЗішли мені Духа Святого,\nІ пошли щит віри і любов без міри,\nІ меча гострого.\n\nКуплет 4\nПрапор Твій завжди хороню, \nЗ ним я ворога здолаю.\nВсім ворожим силам мене не зламати,\nБо Твій прапор - зі мною.\n\nКуплет 5\nПоможи, Ісусе милий, \nВірним бути до могили.\nЗа Правду боротись, йти і не лякатись, - \nПодай мені сили!\n\nКуплет 6\nНе за славу цю земную\nВ бій вступати я бажаю,\nА за рани й муки, за пробиті руки, \nІ за Кров святую.', '', '', '', '', 'ua', 0, NULL),
(538, 'Небесний Краю мій', 0, 11, 'Куплет 1\nНебесний Краю мій, до тебе лину я! \nУгору, в дім святий летить душа моя.\n\nПриспів: \nО, краю мій, сердечних мрій!\nДо тебе рвуся я, - Вітчизна там моя!\n\nКуплет 2\nЯ прагну бути там, в Отця на висоті,\nДе славний Божий Храм палає у красі.\n\nКуплет 3\nВже скоро відійду з землі в Небесний Край,\nТам щастя лиш знайду - душі безсмертний рай.\n\nКуплет 4\nТам сліз не буде вже, в Небеснім Краю тім,\nА вічна радість все з Христом в Краю Святім.', '', '', '', '', 'ua', 0, NULL),
(539, 'Коли в темряві буревій', 0, 11, 'Куплет 1\nКоли в темряві буревій опівночі завиє,\nСльоза страждань спаде із вій та серденько заниє.\n\nПриспів:\nІди скоріш, - Спаситель твій тебе давно чекає. \nУтре Він сльози із очей, введе тебе до раю.,\n\nКуплет 2\nКоли минуть юначі дні, і тяжко їх забути;\nІ в грудях будять жаль вони за тим, Що Не вернути.\n\nКуплет 3\nКоли життя ти змарнував, і мрії повтікали;\nЙ тепер лиш згадок час настав,  й надії позникали.\n\nКуплет 4\nКоли не можеш йти туди, куди лиш глянуть очі,- \nДо твого Господа іди, тебе спасти Він хоче.\n\nКуплет 5\nКоли втомився ти в борбі, і смерть тебе тривожить; \nНіхто з людей твоїй судьбі дать помочі не може.', '', '', '', '', 'ua', 0, NULL),
(540, 'Сину чому пішов в даль', 0, 11, 'Куплет 1\nСину, чому пішов в даль? Вернись! -Господь зове. \nПочуй цей голос милий: Вернись! - Спаситель жде.\n\nПриспів: \nДивну ту зустріч згадай ти, мій сину,\nЯк щиро тоді ти моливсь.\nЯк моливсь! (Сину пригадай) \nЯк моливсь! (Як молився ти). Обітниці твої, молитви.\n\nКуплет 2\nДе ж ти, заблудлий сину, душею заблудивсь? \nЗагинеш ти навіки,- додому знов вернись!\n\nКуплет 3\nГосподь ласкаво кличе тебе вже так, давно.\nДай відповідь сьогодні, вернись до Нього знов!\n\nКуплет 4\nНе буде голос Божий повік тебе шукать.\nТи згубиш день спасіння, Господню благодать.', '', '', '', '', 'ua', 0, NULL),
(541, 'Не знаю я ні дня ні ночі', 0, 11, 'Куплет 1\nНе знаю я ні дня, ні ночі,\nКоли Спаситель мій прийде,\nКоли Його побачать мої очі,\nКоли той день прийде.\n\nКуплет 2\nВже чути кроки Господеві,\nНавколо страшний буревій.\nПоправ же світло в свому каганцеві,\nМолись та в вірі стій.\n\nКуплет 3\nЧи буде сонце ще світити,\nЧи, може, В темряві нічній, \nКоли почую, - буду голосити:\n«Гряди, о, Спасе мій!»\n\nКуплет 4\nТепер я бачу Ісуса \nОчима віри на землі,\nА там тоді на Нього подивлюся \nУ ангельській хвалі.\n\nКуплет 5\nПрийде Ісус Христос, я знаю, \nЗберіг я Його Заповіт.\nПрийде той Бог, Якого я чекаю\nУже десятки літ.\n\nКуплет 6\nЯ буду прославляти Бога \nТепер і там у небесах.\nЗа те, що Він спасти мене вподобав \nУ молодих літах.\n\nКуплет 7\nЧого ж ти журишся, мій брате?\t\nЧого сумуєш в почуттях?\nРадій, радій, бо хоче тобі дати\nГосподь вінець\n\nКуплет 8\nНе знаю я ні дня, ні ночі,\nТа знаю: Скоро Він прийде!\nТоді Його побачать мої очі,\nЙого вся Церква жде.', '', '', '', '', 'ua', 0, NULL),
(542, 'О любов про тебе я співаю', 0, 11, 'Куплет 1\nО, любов, про тебе я співаю,\nСповіщаю всім про Божу вість,\nЯк до нас прийшов Спаситель з неба,\nЩастя й спокій грішникам приніс.\n\nПриспів: \nЙого любов - чудовая!\nЙого любов є дивная!\nВін полюбив мене, на хрест віддав себе. \nЙого любов Є вічная!\n\nКуплет 2\nО, любов, об’явлена в Ісусі,\nЗ тих часів, як Він у світі жив.\nВін - безгрішний, наш Христос Спаситель,\nНа хресті спасіння Він приніс.\n\nКуплет 3\nО, любов, - бальзам на рани серця,\nЩит душі від бурі в світі цім.  \nОпануй цілком моїм Ти серцем, \nНаправляй мене в Небесний Дім,', '', '', '', '', 'ua', 0, NULL),
(543, 'Довго в темряві блукав я', 0, 11, 'Куплет 1\nДовго в темряві блукав я на путях гріховних! все.\nУ житті розчарувався: світ обманював мене.\nКликав я: - Хто допоможе? І журбу зніме мою?\nІ почув я тихий голос: “Я люблю тебе давно’\n\nПриспів:\nТак давно, так давно, Я люблю тебе давно.\nЯк солодкий тихий голос: “Я люблю тебе давно”.\n\nКуплет 2\nЗалиши свій шлях гріховний, лиш довірся-Він простить, \nВ вірі глянь на хрест голгофський, і тебе Він оживить. \nЯк покаєшся ти щиро, вірою приймеш Його,\nТо почуєш голос милий: “Я люблю тебе давно”.', '', '', '', '', 'ua', 0, NULL),
(544, 'Я знаю край', 0, 11, 'Куплет 1\nЯ знаю край, де горя вже не буде,\nДе більш не буде литись братня кров.\nІ в згоді житимуть щасливі люди,\nБо там панує правда і любов.\n\nКуплет 2\nВ мій рідний Край, туди моя дорога.\nЦей Край святий я змалку полюбив.\nІду туди, у Храм живого Бога,\nЩо Він мені у цім житті відкрив.\n\nКуплет 3\nІдіть туди усі скорботні люди,\nБо там уже не ллється братня кров, \nТам горя, сліз ніколи вже не буде,\nБо там панує правда і любов. 2р.', '', '', '', '', 'ua', 0, NULL),
(545, 'Вчуй Спасителю ридання', 0, 11, 'Куплет 1\nВчуй, Спасителю, ридання,\nБачиш, журно й гірко жить.\nДай забути нарікання, \nПоможи Тебе любить.\n\nКуплет 2\nБачиш, слабнуть юні крила,\nРозстелився скрізь туман,\nНадірвалась моя сила, \nВіє вітер ураган.\n\nКуплет 3\nДай, щоб стихло гучне море,\nІ щоб вітер перестав,\nЩоб всміхнулись в небі зорі,\nЩоб Тебе я прославляв.\n\nКуплет 4\nВчуй, Спасителю, благання,\nПоможи Тебе любить,\nЗміни в пісню всі ридання,\nДай для Тебе тільки жить.', '', '', '', '', 'ua', 0, NULL),
(546, 'Я скарби маю', 0, 11, 'Куплет 1\nЯ скарби маю не з цього віку,\nВони є скриті на небесах,\nТам є Отець мій, рідня без ліку, \nЖиве там кожний, мов вільний птах.\n\nПриспів: \nХай світ сміється і зневажає \nМене, що бідний я є тепер.\nМій скарб на небі мене чекає, \nЯ є багатший, ніж мільярдер.\n\nКуплет 2\nМоя Країно, моя скарбнице,\nДо тебе лину я усі дні.\nПрийду до тебе, коли скінчиться \nМоя мандрівка на чужині.\n\nКуплет 3\nЗ небес Ісуса я виглядаю,  \nВ Нім вся надія моя й мета.\nКоли ж в Ісуса той скарб я маю,\nХто мені скаже, що бідний я?', '', '', '', '', 'ua', 0, NULL),
(547, 'Сад Гефсиманський', 0, 11, 'Куплет 1\nСад Гефсиманський темрявою вкрився,\nМов перед бурею він занімів.\nСлухав уважно, як хтось там молився,\nСльози кривавії лив.\n\nКуплет 2\nСад Гефсиманський впізнав свого Друга,  \nЛюди ж впізнать не хотіли Його.\nДико кричали, ревіли навкруги, \nБога розп’яли свого.\n\nКуплет 3\nО, схаменися, невірний народе,\nЧорні заслони з очей своїх скинь,\nВсі залиши свої смертні походи, \nКров проливати покинь\n\nКуплет 4\nЗнай, що настане нежданна година,\nБог над землею відкриє Свій суд,\nПраведних сльози на тебе полинуть,\nСтрашний спіткаєш осуд.', '', '', '', '', 'ua', 0, NULL),
(548, 'В домовині немає Христа', 0, 11, 'Куплет 1\nВ домовині немає Христа!\nВ домовині Христос не лежить!\nБула воля Отцева свята - \nДо життя Його знов воскресить.\n\nПриспів: \nНе шукай (не шукай).(2р.) \nНе шукай там,\nДе мертві лежать (не шукай)!\nНе шукай (не шукай) (2р.)\nБог Христові не дав істлівать.\n\nКуплет 2\nВ домовині Христа не шукай!\nНе шукай там, де мертві лежать!\nБог Христові не дав істлівать. \nБог Христові у владу дав рай.\n\nКуплет 3\nВ домовині немає Христа, - \nЙому служать всі сили небес.\nБула воля Отцева свята,\t\nЩоб нетлінним Він з мертвих воскрес.', '', '', '', '', 'ua', 0, NULL),
(549, 'Недалеко за рікою', 0, 11, 'Куплет 1\nНедалеко, за рікою - берег вічного життя.\nМи ідем туди з хвалою до Спасителя Христа.\n\nПриспів: \nБудем з вірою ми ждати,\nДоки прийде Христос сам. \nБуде Він нас проводжати \nЧерез річку в Ханаан.,\n\nКуплет 2\nЗа рікою сонце сяє, місто там Єрусалим.\nСпіви радісні лунають, співи дивні, неземні.\n\nКуплет 3\nУже многії святії на той берег перейшли. \nЙдуть хвилини дорогії, - кликнуть нас, щоб ми ішли.\n\nКуплет 4\nНіч холодна над рікою, але далі світ сія.\nКрай Христа - то Край спокою. Там з Христом нове життя.', '', '', '', '', 'ua', 0, NULL),
(550, 'У Кані весілля', 0, 11, 'Куплет 1\nУ Кані - весілля. Христос там гостем був.\nТам перше чудо сотворив і шлюб благословив\n\nПриспів:\nО, Спасе Пресвятий (2р.) Ти  джерело любві.(2р.) \nДо наших молодих зійди (2р.) і їх благослови!\n\nКуплет 2\nІ в доброті Своїй Сам щастя Їм подай.\nНехай вони хвалять Тебе цілим життям своїм.\n\nКуплет 3\nМи просимо Тебе, Небесного Творця,\nЩоб їх серця в одно злились на ціле їх життя.', '', '', '', '', 'ua', 0, NULL),
(551, 'Це синє небо до себе тягне', 0, 11, 'Куплет 1\nЦе синє небо до себе тягне.\nЗнаю, що ти мій спаситель Христос.\nТуди я лину, щоб відпочити.\nСкорбот нема там, болю ні сліз\n\nПрипев\nО, синє  небо, красою вкрите,\nДо тебе лине душа моя;\nБажав би мат я крила віри,\nТуди піднятись там горя нема.\n\nКуплет 2\nЦе синє небо, створене Богом,\nМісяць і зорі, і наша Земля.\nМене полонить це все прегарне\nПід час півночі і білого дня.\n\nКуплет 3\nО, синє небо, до тебе лину!\nТут я скиталець, чужий я для всіх.\nТвої батьки мене втішають,\nТам відпочину в оселях Твоїх.', '', '', '', '', 'ua', 0, NULL),
(552, 'Тільки Ісус хай у серці царює', 0, 11, 'Куплет 1\nТільки Ісус хай у серці царює!\nБільш не знаю любові ніде.\nВ Нім лиш душа моя радість скоштує.\nВ Нім лиш однім душа спокій знайде.\n\nПрипев\nЛюбий Ісус мені дав перемогу.\nМіцні ворожі кайдани розбив.\nСила любові прогнала тривогу.\nДуха Святого у серце вселив.\n\nКуплет 2\nСкинь всі турботи у тяжку хвилину!\nСпас обіцяв вас ввести в Вічний Дім.\nСам Він сказав, що "Я вас не покину".\nБуря не страшна, коли ми є з Ним.\n\nКуплет3\nХоч би я впав у земній катастрофі, -\nЗнаю - Ісус підійме мене знов.\nЄ Джерело, що зпливає з Голгофи, -\nСпасова чиста, невинная кров\n\nКуплет 4\nСкінчу я працю, і в рідні оселі\nСпас із любов''ю покличе мене.\nВсе залишу тут, і в новому тілі\nВ Отчих обіймах мій дух відпочине.', '', '', '', '', 'ua', 0, NULL),
(553, 'Дороги шляхи невідомі', 0, 11, 'Куплет 1\nДороги, шляхи невідомі,\nМільйони стежок на землі.\nА стежку до щастя й любові, -\nТо де ж ви її віднайшли?\n\nПрипев\nВ дорогу, в дорогу, нову, невідому,\nВ сімейну ось двоє ідуть.\nГосподь приведе вас до Отчого Дому,\nДе радість і щастя вас ждуть\n\nКуплет 2\nДороги, шляхи невідомі,\nЛюбов і єднання сердець.\nЗійшлися в молитовнім домі,\nІ стали вони під вінець.\n\nКуплет 3\nДві стежки - юнача й дівоча,\nЗійшлися, щоб злитися в одну.\nХай бачать вас Божії очі\nІ руки ведуть до кінця.\n\nКуплет 4\nДороги ведуть до прощаня.\nМи дякуєм батькам за все.\nІ радість, і вірне кохання\nНавіки хай все збереже!', '', '', '', '', 'ua', 0, NULL),
(554, 'Ісус в Твоїм Імені сила є', 0, 11, 'Куплет 1\nІсус, в Твоїм Імені сила є,\nІсус - сліпим прозріння Він дає,\nЛиш ім''я Ісус наповнене величності,\nІсус є Бог вічності\n\nКуплет 2\nІсус - спасіння в Імені Твоїм, \nІсус - хвала єдиному Тобі, \nО, Ісус - Ти справедливість є одна, \nІсус - вічне Ти життя.\n\nКуплет 3\nІсус - мій Цар, що скоро знов прийде, \nІсус, до Тебе серце лине все.\nТобі, Ісусе, ми співаєм повсякчас, \nІсус - Ти Господь усіх нас.', '', '', '', '', 'ua', 0, NULL),
(555, 'На чудовій Україні', 0, 11, 'Куплет 1\nНа чудовій Україні квіти розквітають,\nЯк багато українців Бога ще не знають. \nА сьогодні Батьків голос ніжно так лунає:\nНа весілля Христа-Сина всіх Він закликає.\n\nПриспів: \nУкраїно, Україно! \t\nЩастя й мир тобі дарує Бог.\nВін Єдиний тільки сильний \nЗберегти у світі катастроф.\n\nКуплет 2\nНемов ненька немовлятко Він тебе кохає.\nЗ покаянням йди до Нього, - Він тебе прощає.\nІ серденька свого двері відкрий зсередини.\nДасть Христос тобі спасіння і ще й для родини.\n\nКуплет 3\nХристияни в нашім краю, просимо вас нині:\nЖивіть в мирі та любові, як в одній родині.\nЯк служити будем Богу і Його кохати - \nМальовничий край наш буде Бог благословляти.', '', '', '', '', 'ua', 0, NULL),
(556, 'Бажаю тепер сказати Тобі', 0, 11, 'Куплет 1\nБажаю тепер сказати Тобі, Спасителю мій,\nЩо люблю Тебе, бажаю Тебе всім серцем своїм.\n\nПриспів:\nБажаю тепер сказати Тобі всю правду вповні,\nЩо люблю Тебе, бажаю Тебе всім серцем своїм.\n\nКуплет 2\nСпіватиму я, бо маю спокій, заплачу і я, бо щастя знайшов, \nЩо люблю Тебе, бажаю Тебе всім серцем своїм.', '', '', '', '', 'ua', 0, NULL),
(557, 'Без Него ничего', 0, 11, 'Куплет 1\nНочь повисла над городом южным,\nСкоро вспыхнет восток голубой;\nНичего на земле мне не нужно,\nЕсли только Спаситель со мной.\n\nПриспів: \nБЕЗ НЕГО НИЧЕГО НЕ МОГУ Я,\nБЕЗ НЕГО НЕ ПРОЖИТЬ НЕ ГРЕША.\nТОЛЬКО С НИМ Я ПОЮ АЛЛИЛУЙЯ,\nТОЛЬКО В НЁМ ОТДЫХАЕТ ДУША.\n\nКуплет 2\nОн нашёл меня в мире суровом,\nСнял с души моей тягостный гнёт.\nПод Его всемогущим покровом\nМоё сердце от счастья поёт.\n\nКуплет 3\nНо бывают минуты иные,\nМир, как море, запенится вдруг;\nИ тогда не боюсь я стихии,\nЕсли рядом со мною Иисус.', '', '', '', '', 'ua', 0, NULL),
(558, 'Біблія світло Боже засвітила', 0, 11, 'Куплет 1\nБіблія світло Боже засвітила \nІ освітила нам незнаний світ,\nВсього того вона людей навчила,\nЩо було сховане багато літ.\n\nПриспів: \nГосподи, дай нам знати Святе Слово \nІ Його правду сповіщати всім.\nОсь наступає Царство вже Христове,\nІ день заплати буде для усіх!\n\nКуплет 2\nБіблії слово все майбутнє знає,\nЩо час наступний людям принесе;\nЩо відбулося та що бути має,\nБіблія вчить нас розуміти все.\n\nКуплет 3\nБіблія путь правдиву відкриває,\nВсіх направляє на стежки святі;\nХто вказівки священні забуває,\nТой відійде від вірної путі.\n\nКуплет 4\nО, християни, Біблію читайте,\nПеремагайте її словом гріх;\nБожої правди всіх людей навчайте \nІ їх приводьте до Христових ніг.', '', '', '', '', 'ua', 0, NULL),
(559, 'Біля Ісуса радість', 0, 11, 'Куплет 1\nБіля Ісуса радість, біля Нього спокій.\nЯка в душі солодкість, що Він - Спаситель мій! \nБо коли Він зі мною, - далеко ворог мій.\nЙти стежкою земною не тяжко - легко з Ним.\n\nПриспів: \nБіля Ісуса радість, біля Нього спокій. \nЯка в душі солодкість, \nЩо Він - Спаситель мій!\n\nКуплет 2\nДавно я йду тим шляхом, що Спас мій проложив, \nТа часто перед страхом хрест тяжко так давить. \nТоді в мольбі благаю я Спаса у тиші\nІ з вірою чекаю, - поможе Він мені.\n\nКуплет 3\nЩасливі ті хвилини - приходить мій Христос \nЙ бере в тяжкі години тягар той, що я ніс.\nТоді Йому хваління від серця я несу.\nГосподь, в земних блуканнях зі мною будь, прошу.', '', '', '', '', 'ua', 6, NULL),
(560, 'Боже мій Ти серця тайни', 0, 11, 'Куплет 1\nБоже мій, Ти всі тайни серця мого знаєш,\nІ всі болі серця знаєш Ти:\nЯк стріла гріха наносить рани | знаєш Ти (Зр.)\n\nКуплет 2\nЗнаєш Ти, що я часто так вже знемагаю,\nТа я хочу все Тебе любить.\nХочу йти покірно за Тобою ¡ свято жить (Зр.)\n\nКуплет 3\nЗнаю, що Ти омив мене Своєю кров’ю,\nІ мене з безодні вирвав Ти,\nТа коли в знемозі упаду я, | Ти прости (Зр.)\n\nКуплет 4\nНа хресті Ти Себе віддав за нас у жертву \nІ Заступником зробивсь моїм.\nТи, вмираючи, благав з любов’ю | прости їм (Зр.)', '', '', '', '', 'ua', 0, NULL),
(561, 'Боже Ти над світом', 0, 11, 'Куплет 1\nБоже, Ти над світом ласки розливаєш, як дощі,\nХай же хоч одна краплина \nЗ цього припаде мені (і мені). (2р.)\n\nКуплет 2\nНе покинь мене, мій Боже, ласк Своїх не відбери,\nЯк Свою дитину, Отче,\nТи до Себе пригорни (пригорни). (2р.)\n\nКуплет 3\nНе покинь мене, мій Боже, а любити вчи мене \nЯк чинити все, що гоже,\nЯк наставити себе (вчи мене). (2р.)\n\nКуплет 4\nДовго я в гріхах валявся, довго я смутив себе \nАж тепер опам’ятався\n0 прости, прости мене! (І мене). (2р.)', '', '', '', '', 'ua', 0, NULL),
(562, 'Брате мій милий', 0, 11, 'Куплет 1\nБрате мій милий, чого ти сумуєш?\nВ Тебе на серці велика печаль,\nЯснії очі хмурні, мов та осінь,\nСерце камінне тверде, мов та сталь.\n\nКуплет 2\nГоря зазнав ти на світі багато.\nЗмучив себе ти в тяжкій боротьбі,\nСерце не було любов’ю зігріте,\nЧасто траплялось нещастя тобі.\n\nКуплет 3\nЩастя хоч було, та скоро минуло,\nГак як та квітка, що в полі росте,\nВітер повіяв, краса облетіла \nДе ж і поділось все гарне, святе?\n\nКуплет 4\nСкоро у двері загляне смерть люта,\nВ землю сирую тебе покладуть,\nВік твій скінчиться, загине вся слава,\nТвого багатства тобі не дадуть.\n\nКуплет 5\nБрате мій милий, навчися робити\nВ світі все більше і більше добра,\nВіруй у Бога, люби свого брата, —\nВ тебе на серці засяє зоря.\n\nКуплет 6\nТо зірка ясна, то Божая ласка,\nСерце камінне твоє осія.\nЩастя велике, хто Богові служить, - \nЦарство небесне тому подадуть.', '', '', '', '', 'ua', 0, NULL),
(563, 'Бушує життєвеє море', 0, 11, 'Куплет 1\nБушує життєвеє море,\nГріховні потуги киплять,\nНавколо темрява і горе \nГрозою над нами висять.\n\nПриспів: \nХристовий маяк у темряві \nНам сяє, як заклик нічний.\nТуди ми свій човен направим,\nНам видно там берег святий.\n\nКуплет 2\nБушує життєвеє море,\nСтогнанням томиться дух мій.\nА люди снуються, у горю,\nНе знаєш де ворог, де друг.\n\nКуплет 3\nБушує життєвеє море,\nЗагибеллю в пітьмі грозить.\nЗнемоги ми вірою борем,\nМолитва нам духа кріпить;\n\nКуплет 4\nБушує життєвеє море,\nТа вірим, поможе нам Бог.\nВ грозі ми пливем крізь простори \nТуди, де немає тривог.', '', '', '', '', 'ua', 0, NULL),
(564, 'Весь в ранах', 0, 11, 'Куплет 1\nВесь в ранах при шляху я довго так лежав,\nТомився, біль терпів і плакав, і страждав.\nІ думав я в собі, в тузі невисловимій:\nО, де ж моя рідня, де близький, де любимий?\n\nКуплет 2\nБагато мимо йшло, але не кожен з них \nБажав мене спасти з болючих ран моїх.\nХтось наче вже й бажав- його ж таємна сила \nМарою марноти від мене в даль манила.\n\nКуплет 3\nА іншого лякав вид ран і стогін мій;\nМене вже огортав смертельний буревій.\nУже вуста мої помітно завмирали,\nВ байдужливих очах вже сльози застигали.\n\nКуплет 4\nЗнайшовся лиш один, котрий не зміг пройти, - \nВін сльози втер мені рукою доброти.\nХоч він мене не знав, та, сповнений любові, \nСвоїх старань доклав до ран моїх і крові.\n\nКуплет 5\nОбмив, перев’язав, вживаючи бальзам,\nПривіз мене у дім, і турбувався сам.\nІ голос я в душі почув неповторимий:\n"Ось хто рідня тобі, хто близький, хто любимий."', '', '', '', '', 'ua', 0, NULL),
(565, 'Вже не раз', 0, 11, 'Куплет 1\nВже не раз в молитві щирій я Тебе, Господь, благав - \nТа чому ж, мій Боже милий, відповіді ти не дав?\n\nКуплет 2\nТа чому ж на всі благання Ти мені не відповів? - \nЧи даремно всі моління, що просив я Стільки днів?\n\nКуплет 3\nЧи в мені так віри мало, чи то гріх я затаїв,\nЧи любові вже не стало, чи я брату не простив?\n\nКуплет 4\nО, скажи, мій милий Боже, щоб я ясно зрозумів,\nЩо є в серці що не гоже, - й по Твоїй я волі жив.\n\nКуплет 5\nЗ серця змий гріха провину і душі дай віри зріст,\nІ з нового вже почину будь зі мною, Спасе мій.', '', '', '', '', 'ua', 0, NULL),
(566, 'Всі ми браття', 0, 11, 'Куплет 1\nВсі ми, браття, Христові вояки;\nЗа Христа ми до бою йдемо.  \nВід людей нам не треба подяки, — \nНам за працю віддячить Христос.\n\nКуплет 2\nВін дарує нам міцную зброю. \nТая зброя і Тори здвига.\nВін нас Сам поведе за Собою \nІ засвітить, як рання зоря.\n\nКуплет 3\nЗоря та ясна, як сонце, засяє,\nРозігріє і душу і кров.\nТа зоря на весь світ засіяє.\nЗоря та - То Христова любов.\n\nКуплет 4\nВсі ми браття, Христові вояки; \nЗа Христа ми до бою йдемо. \nНе страшні нам загрози ніякі, \nЗа Христа ми життя віддамо', '', '', '', '', 'ua', 0, NULL),
(567, 'Вчуй мене мій милий Боже', 0, 11, 'Куплет 1\nВчуй мене, мій милий Боже і на сон благослови. \nТа й у сні будь коло мене, аж до ранку стережи.\n\nКуплет 2\nЦілий день мене беріг Ти, одягав і годував. \nЩиро дякую Тобі я за ті дари, що Ти дав.\n\nКуплет 3\nВибач злі мої учинки і на сон благослови \nЗавтра вранці знов до праці, Спаситель, мене збуди.', '', '', '', '', 'ua', 0, NULL),
(568, 'Глибше глибше в любові', 0, 11, 'Куплет 1\nГлибше, глибше, в любові Ісуса,\nХочу йти щодня.\nВ мудру школу хочу йти, щоб більше \nЗнати про Христа.\n\nПриспів:\nО, глибше я молюсь, щодня я більш учусь \nІ більш мудрію в Нім, в Його Слові дорогім.\n\nКуплет 2\nГлибше, глибше вчи мене, мій Боже,\nГлибше з кожним днем:\nДоки вміститься життя в Ісусі,\nЩоб я був, як Він.\n\nКуплет 3\nГлибше, глибше, через тяжкі проби \nПоможи іти,\nВкоренитись у любві щоб міг я.\nЖити в вірності.\n\nКуплет 4\nГлибше, вище, кожний день в Ісусі,\nДоки гріх пройде,\nЩоб від злого я міг уникати, \nВірним бути все.', '', '', '', '', 'ua', 0, NULL),
(569, 'Грішнику покайся', 0, 11, 'Куплет 1\nГрішнику, покайся, доки ще є час,\nІ спасіння ласка не лишила нас,\nДоки Боже Слово світлом нашим є,\nСпасові скоріше серце дай своє.\n\nКуплет 2\nСерце дай своє, (2р.)\nСпасові скоріше (2р.)\nСерце дай своє.\n\nКуплет 3\nДруже, не вагайся, світ цей залишай \nНа дорогу правди швидше поспішай.\nДень життя минає, скоро ніч прийде,\nІ для всього людства вічність надійде.\n\nКуплет 4\nВічність надійде. (2р.)\nІ для всього людства (2р.)\nВічність надійде.\n\nКуплет 5\nБог тобі бажає щастя та добра,\nЩоб ти стався сином вічного Царя.\nТож сьогодні, друже, до Христа іди, - \nВін твій гріх обмиє, дасть життя тобі.\n\nКуплет 6\nДасть життя тобі. (2р.)\nВін твій гріх обмиє, (2р.)\nДасть життя тобі.', '', '', '', '', 'ua', 0, NULL),
(570, 'Двері ось перед тобою', 0, 11, 'Куплет 1\nДвері ось перед тобою, а за ними два шляхи.\nДруже, з щирою душею вибирай один із них\n\nКуплет 2\nЧерез ті широкі двері шлях широкий бачиш ти, \nА на нім юрба народу, що шукає марноти.\n\nКуплет 3\nНа широкій тій дорозі вічна ніч чекає всіх, \nЩо живуть тепер без Бога і не чують Його слів.\n\nКуплет 4\nНа кінці шляху тісного нас чекає вічний рай. \nІ щасливі будуть люди, що прибудуть у той Край.', '', '', '', '', 'ua', 0, NULL),
(571, 'Де Ти чудовая', 0, 11, 'Куплет 1\nДе Ти чудовая, в славі сіяюча, \nВічна, Божественна Вітчизну душі?\nЛину думками я до тебе, рідная,  \nВ тузі духовній піднімаю свій взір.\n\nПриспів: \nТак в час весняний, в синьому небі\nВ край свій вертають ключем журавль. \nВ покликах їхніх радости годос,  \nБо до Вітчизни повернулись вони.\n\nКуплет 2\nТам, в висоті небес, в краю безхмарному \nЖде мене в вічності Пастир Христос.\nКоли ж прибуду я в дивну Країну ту?-\nВсе я питаю себе в серці своїм,\n\nКуплет 3\nЗнаю, Спасителю, скоро прийдеш узять\nВ Царство Небесне Ти і мене.  \nО, дай устояти, Спасе, у вірності \nЩоб незаплямленим в вічність, ввійти.\n\nПриспів: \nО, Краю вічний мій; Чистеє небо,\nБожа Країно, Вітчизна моя!  \nСерце прийми моє серце ще юнеє\nХочу, щоб в ньому володів лиш Христос.', '', '', '', '', 'ua', 0, NULL),
(572, 'Дуже часто мені', 0, 11, 'Куплет 1\nДуже часто мені в житті тяжко буває.  \nХто спитає тоді про біль серця мого?\n\nПриспів: \nТільки Ти, Ісус, тільки Ти, Утішитель,\nТільки Ти зрозумій, Боже, серце моє!\n\nКуплет 2\nЯ ж бо знаю, що гріх, і не спить, не дрімає,\nГнітить душу мені серед світу цього!\n\nКуплет 3\nСкільки раз на землі тут приходиться плакать.\nЯ прошу: “Поможи в цій печалі моїй!"\n\nКуплет 4\nІ я певний в тому, що молитви Ти чуєш \nІ поможеш мені в цьому світі гріха.\n\nКуплет 5\nМоже ще не тепер принесеш нагороду,  \nТа я вірю, що ждеш Ти мене в небесах.', '', '', '', '', 'ua', 0, NULL),
(573, 'Застановись ти над своїм життям', 0, 11, 'Куплет 1\nЗастановись ти над своїм життям!\nХай серце плаче, стомившись в грісі.\nЧому так довго легковажиш \nТи своїм життям?\nПрийди до Господа в тиші.\n\nПриспів: \nКоли на серці тяжко є і сил не маєш ти-  \nБог близько є: так близько Він. (2р)\n\nКуплет 2\nЗастановись ти в світі суєти,\nВ сльозах молись, щоб чув Бог плач душі. \nСхились в тиші, хай серце плаче \nВід страждань душі.\nТоді Господь дасть спокій Свій.\n\nКуплет 3\nЧому Ти досі в світі ще живеш?\nЧому в гріхах до Бога не прийдеш?\nТвоє життя вже похилйлось,\nБлижче до кінця.\nНе знаєш ти, куди ти йдеш.', '', '', '', '', 'ua', 0, NULL),
(574, 'Ми дякуєм Боже за жнива', 0, 11, 'Куплет 1\nМи дякуєм, Боже, Тобі за ці жнива,\nЩо рясно вродили на-наших полях. \nЗа сонце, за вітер, за дощ літній з неба,\nЗа спокій, що маєм у наших серцях.\n\nКуплет 2\nТи все необхідне для нас посилаєш,\nЗдоров''я і працю для нас подаєш. \nЗа руку тримаєш, як батько дитину,\nВ Своє Вічне Царство до неба ведеш.\n\nКуплет 3\nНе в силі ми, Боже, Тобі відплатити \nЗа всі добродійства, що Ти нам зробив; \nЗа вічне спасіння від пекла, страждання,\nЯке в Своїм Сині для нас дарував.\n\nКуплет 4\nО, Господи Боже, як легко ми важим \nУсі добродійства, що Ти нам зробив!\nПрости Ти нам, Боже, пошли для нас сили, \nЩоб більше ніхто з нас Тебе не гнівив.', '', '', '', '', 'ua', 0, NULL),
(575, 'Наше життя відлітає', 0, 11, 'Куплет 1\nНаше життя відлітає,\nМов птах, що скоро летить.\nВ нашім житті лиш слід залишає,  \nІ знову від нас десь летить.\n\nПриспів:  \nРоки, мов ключ журавлів, десь летять \nЗнаю, ніколи назад не прилетять. (2р.)\n\nКуплет 2\nНаше життя йде так скоро,\nСльози несе нам нераз.\nЗнаєм: назад вернуть ми незможем\nУтрачений нами наш час.\n\nКуплет 3\nЧасто ми час затрачаєм,\nВтіхи з того не знаєм, \nНаше життя земне пригасає,\nМи скоро додому підем.\n\nКуплет 4\nБоже, Тебе ми благаєм,\nЩоб нас почув і простив.\nСкільки в житті даруєш нам жити, -\nЩоб кожен для Тебе лиш жив.', '', '', '', '', 'ua', 0, NULL),
(576, 'Колись як я молився', 0, 11, 'Куплет 1\nКолись, як я молився, то Мені Господь послав,—  \nЩедро в серце моє Свого Духа Святого зілляв.\nІ з цієї же хвилини відійшли мої сумніви  \nІ тепер я є щасливий, радісний назавжди вже.\n\nПриспів:\nО любов, любов, любов з’явилась для людей. \nСпасти мене прийшов Ісус Спаситель мій.\nУ любві Себе віддав, за нас Він постраждав.\nІ через ту любов тоді хрестив Духом мене.\n\nКуплет 2\nНіколи не лишаймо глибини любові знайти, \nЩоб гріх світа покинуть і за Господом все йти. \nУповаймо і молімся та пильнуймо ми завжди,\nІ тоді усі побачим, як Духа Святого зіллє.', '', '', '', '', 'ua', 0, NULL),
(577, 'Було приємно для вас співати', 0, 11, 'Куплет 1\nБуло приємно для вас співати,\nВід себе хочем вам побажати:\n\nПриспів: \nХай всякі біди вас обминають,\nХай ваші рідні щастя лиш мають, \nХай Божа милість вас не минає, \nЛюбов Христова всіх об''єднає.\n\nКуплет 2\nЗ''єднаймо руки, бо нас багато, \nНе зможе ворог нас подолати.\n\nКуплет 3\nЯкщо ви раді нам щось сказати,\nТо просим разом з нами Співати.', '', '', '', '', 'ua', 0, NULL),
(578, 'Мене любов Христова', 0, 11, 'Куплет 1\nМене любов Христова знайшла в моїх гріхах. \nЗнов до Отця привела, підтримала в нуждах.\nВелика сила звише на ноги підвела,\nВ мені життя знов дише - за те Христу хвала.\n\nПриспів:\nІ життя моє тепер є солодшим з кожним днем,\nА любов багатше, все сильніше й краще \nТягне до Христа мене.\n\nКуплет 2\nХодив Він по Юдеї віки тому назад.\nЗа Ним, як за Мойсеєм, гуртом ішов народ. \nУсіх калік зціляв Він, дав зір їхнім очам.\nІ дав також мені Він зціляючий бальзам.\n\nКуплет 3\nЛюбов Його привела, щоб Він страждав за нас, \nЩоби спасти від гніву, що мав пожерти нас.\nХай всі святі з хвалою здіймуться в небеса,\nХай вся земля і небо славить Спасителя,', '', '', '', '', 'ua', 0, NULL),
(579, 'Над світом морок', 0, 11, 'Куплет 1\nНад світом морок і тривога,\nЗайшло вже сонце за обрій.\nСвіт твердо спить В гріхах, без Бога,\nБез щастя вічного й надій.\n\nПриспів: \nВ останні дні, що йдуть \nНад нашою землею,\nДля мене, Христе, будь \nОпорою моєю.\n\nКуплет 2\nВ душі людського покоління \nЛиш неспокій та буревій...\nА я в Тобі знайшов спасіння\nІ щастя вічного спокій.\n\nКуплет 3\nКоли земля з ділами скоро \nВогнем навіки спалахне,\nІсус Христос, моя опора,\nМене до неба забере.\n\nКуплет 4\nЩасливий я, що вірю в Бога, - \nВін - Пастир добрий для овець,\nВін - світло правди і дорога,\nВін - мій початок і кінець.', '', '', '', '', 'ua', 0, NULL),
(580, 'На небі мій Отцівський дім', 0, 11, 'Куплет 1\nНа небі мій Отцівський дім - я хочу до Ісуса!\nНі сліз, ні горя в домі тім - я хочу до Ісуса!\nДо Нього лину кожну мить,\nЯ буду в Ньому вічно жить (2р.) - я хочу до Ісуса!\n\nКуплет 2\nЛюдина мріє мати дім - я хочу до Ісуса!\nВона будує щастя в нім - я Хочу до Ісуса!\nА з часом щастя промине,\nМоє ж насліддя в небі все (2р.) -я хочу До Ісуса\n\nКуплет 3\nДо дому хочу я весь час - я хочу до Ісуса!\nБо Він мене навіки спас - я хочу до,Ісуса!\nПрощай, земля! Я в дім святий\nІду туди, де спокій мій (2р.) - я хочу до Ісуса!', '', '', '', '', 'ua', 0, NULL),
(581, 'Ти так близький', 0, 11, 'Куплет 1\nТи так близький, ніби берег морю,\nМилий Ти, як мати для дітей.\nТи прийшов кінець покласти горю,\nТи прийшов простить, обнять людей.\n\nКуплет 2\nБез Тебе й життя мені не треба,\nБез Тебе я навіть не дишу.\nДо Тебе душа, як птах до неба;\nНе лишай мене, - Тебе прошу.\n\nКуплет 3\nДе з землею зустріч буде неба,\nЩоб із рук землі усіх прийнять,\nТам уперше я побачу Тебе \nВіч-на-віч і буду прославлять.\n\nКуплет 4\nА тепер з надією, щасливо \nЯ живу, поки візьмеш туди.\nТи є ближчий, ніж пісок припливу,\nІ дорожчий в спеку від води.', '', '', '', '', 'ua', 4, NULL),
(582, 'Нема Бога більшого', 0, 11, 'Куплет 1\nНема Бога більшого, як наш, нема, нема!\nНема такого Бога, як наш Великий Бог! (2р.)\n\nПриспів: \nНе нашою силою, не нашою мудрістю,\nЛиш тільки Духом Святим - \nА ми все горе переживем (Зр.)\nСилою, Духом Святим.', '', '', '', '', 'ua', 4, NULL),
(583, 'Не одна сльоза', 0, 11, 'Куплет 1\nНе одна сльоза гаряча, не один прийде ще жаль,\nЩе не раз заплачеш гірко, поки будеш в небесах.\n\nПриспів:\nАле потім з уст полине\n(Але потім з уст полине пісня Божої дитини),\nВічна слава без кінця,\nКоли Сам Господь нас стріне,\n(Коли Сам Господь нас тріне, і як тато нас обійме)\nВ славі Божій у Отця.\n\nКуплет 2\nНе один ще біль та кривду мусимо перенести, \nДоки можна буде в славу Царства вічного ввійти.\n\nКуплет 3\nНе одна ще страшна хвиля, не один гіркий ще час Зранять душу до безсилля, поки Прийде любий Спас.', '', '', '', '', 'ua', 0, NULL),
(584, 'Не цвітом весняним', 0, 11, 'Куплет 1\nНе цвітом весняним, не шовком-травою - \nКолючками вбраний мій шлях за Тобою.\nДо цілі святої іду за Тобою,\nТобі довіряю, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.\n\nКуплет 2\nСтарію літами, хворію порою,\nІ хмари з громами пливуть наді мною.\nДо цілі святої іду за Тобою,\nВ Тобі молодію, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.\n\nКуплет 3\nТебе я кохаю любов’ю палкою.\nНікого не знаю, живу лиш Тобою.\nДо цілі святої іду за Тобою.\nМій Боже коханий, Тебе я держусь,\nМій добрий Спаситель, мій вірний Ісус.', '', '', '', '', 'ua', 0, NULL),
(585, 'Обіцяв Твоє Слово прийняти', 0, 11, 'Куплет 1\nОбіцяв Твоє Слово прийняти \nЙ не піддатись спокусі гріха,\nІ для Тебе себе все віддати, \nБo знайшов я Спасіння й життя.\n\nПриспів: \nО, Отець, що є вічно у небі,\nНа землі і усюди, кругом.\nПодавай з неба хліб нам щоденний \nІ пошли в серце першу любов.\n\nКуплет 2\nЯ негідний був, грішник, я знаю,\nІ далеко від Тебе блудив - \nТвоя ласка і кров гріх мій змила,\nВсі провини мені Ти простив.\n\nКуплет 3\nЯкщо хочеш буть, друже, спасенним \nТа отримати вічне життя,\nТо сьогодні цілком ти віддайся \nДля Спасителя свого Царя.', '', '', '', '', 'ua', 0, NULL),
(586, 'О благай Христа мій друже', 0, 11, 'Куплет 1\nО, благай Христа, мій друже, кожним часом дорожи. \nВір, молись, не будь байдужим, до Спасителя спіши.\n\nПриспів:\nВін дає всім серцям тут надію, радість там. (2р.)\n\nКуплет 2\nДо Христа прийди покірно, як дитя Його проси.\nЛюбить Він тебе безмірно, від загибелі спасе.\n\nКуплет 3\nІсус серце утішає, я люблю Ім’я Його.\nВін мене лиш підкріпляє, стереже від зла всього.\n\nКуплет 4\nВірні будуть зустрічати Вічного Царя з небес; \nХриста будуть прославляти як Творця святих чудес.', '', '', '', '', 'ua', 0, NULL),
(587, 'Ой куди піду ще я', 0, 11, 'Куплет 1\nОй куди піду ще я, де мені шукать спасіння?\nДе знайде душа моя від недуги ізціління?\n\nКуплет 2\nСкрізь по світі я ходив, серце радості шукало - \nЩастя світ не подарив, в серці сумно й скорбно стало.\n\nКуплет 3\nДо людей я не піду правди, істини шукати - \nБоже мій, до Тебе йду, щоб з Тобою пробувати.\n\nКуплет 4\nЛиш у Тебе одного є утомленим спасіння.\nІ від горя свойого знайду повне утішення.\n\nКуплет 5\nО прийми, прийми мене, Боже правди і любові!\nХай гріховне все мине, дай життя почати нове.', '', '', '', '', 'ua', 0, NULL),
(588, 'Ой тяжко тяжко', 0, 11, 'Куплет 1\nОй, тяжко, тяжко в світі серед неправди жить. \nНещасним, безутішним хто радість подарить?\nХристос, тільки Він (Зр.) Тебе утішить назавжди.\n\nКуплет 2\nЯ в горю і печалі, марні мої всі дні.\nХто зітре мої сльози і поміч дасть мені?\nХристос, тільки Він (Зр.) Тебе утішить назавжди.\n\nКуплет 3\nМій гріх мене турбує - яким на суд прийду?\nНе знаю де прощення і захист де знайду?\nВ Христа одного (Зр.),мій друже, спасіння ти знайдеш.', '', '', '', '', 'ua', 0, NULL),
(589, 'Під час тривоги', 0, 11, 'Куплет 1\nПід час тривоги, смутку та сумніву \nНе бачу світла я на цій землі.\nДуша болить і томиться в сумнівах.\nСпішу, Христе, в молитві до Тебе.\n\nПриспів: \nЩасливий я, що Друга в світі маю, \nЩасливий я, - Він завжди при мені. \nЖиву я з Ним і в Ньому пробуваю. \nЩасливий я, - Він при мені всі дні.\n\nКуплет 2\nТвій образ дивний, лагідний, смиренний.\nІсусе, Ти живи в мені всі дні,\nІ будь в моєму серці Ти щоденно,\nВпасти не дай під тягарем мені.\n\nКуплет 3\nМені порою важко тут буває,\nЗдається, що Сам Бог лишив мене.\nТоді в душі Слова Твої лунають: \n- Я не покину, Я люблю Тебе!', '', '', '', '', 'ua', 0, NULL),
(590, 'О небесний спокій', 0, 11, 'Куплет 1\nО, небесний спокій є в моїй душі.\nВідчуваю я цей спокій тепер,\nБо Ісус Спас простив всі гріхи мої,\nІ вільним я є тепер.\n\nПриспів: \nВін є мій і я Його є\nЗавжди слава все Йому. (2р.)\nВін мені солодкий Свій дав спокій, \nВін повічні віки мій.\n\nКуплет 2\nІ тепер душа вже спочиває в Нім, і \nБо Він дав мені цей дивний спокій.\nВін мене хоронить від зла в світі цім \nІ повіки Він є мій.\n\nКуплет 3\nДарував мені Він радість без кінця - \nВідчуваю я радість цю тепер.\nБуду я служити Йому до кінця \nЙ прославляти Його все.\n\nКуплет 4\nІ любов Божа втішає все мене - \nВідчуваю я цю любов тепер.\nXвилі радості пливуть у душу все,\nІ солодше з кожним днем.', '', '', '', '', 'ua', 0, NULL),
(591, 'О потіш моє серце', 0, 11, 'Куплет 1\nО, потіш моє серце, Спасителю мій,\nСловом правди в любові безкраїй.\nВладно море бурхливе кругом успокій,\nЩо слабкий мій човен заливає.\n\nКуплет 2\nДай дістатись щасливо крізь хвилі страшні \nДо святої Країни спокою.\nБудь зі мною, о Спасе, усі мої дні,\nВ бурях зла не лиши самотою.\n\nКуплет 3\nПрагну голос Твій чути в темряві нічній,\nВ цьому грізному темному морі:\nАдже бурі і хвилі у владі Твоїй - \nНакажи, і затихнуть в покорі.\n\nКуплет 4\nСвятим Духом у серці моїм пробувай \nІ не будуть ті хвилі страшними;\nСловом правди й любові над мною сіяй,\nБудь душі моїй в темряві зримим.', '', '', '', '', 'ua', 0, NULL),
(593, 'Ось Ісус стіл нарядив', 0, 11, 'Куплет 1\nІсус стіл нарядив, де святих колись кормив;\nВін і нині кличе на обід всіх нас.\nВін нам манну всім дає, постачає для нас все.\nЯк з Христом солодко їсти всякий час!\n\nПриспів: \nНа обід Спаситель кличе усіх- нас,\nМожем їсти при Його столі всяк час. \nНакормив Він множество І зробив з води вино.\nНа обід Він кличе днесь усіх нас.\n\nКуплет 2\nЯк Апостоли колись вчули голос і прийшли,\nБо Спаситель Сам їх кликав на обід.\nЯк до берега прийшли, - рибу й хліб в вогні знайшли. \nВін днесь кличе всіх голодних на обід.\n\nКуплет 3\nСкоро Сам Ісус прийде, від землі своїх візьме \nІ святих всі сонми будуть в небі там.\nТо буде чудовий збір - в білім строю вбрані всі \nІ з Христом будуть кормитись вічно там.', '', '', '', '', 'ua', 0, NULL),
(594, 'Одного Боже прагну я', 0, 11, 'Куплет 1\nОдного, Боже, прагну я,\nЩоб мати серце зовсім чисте.\nОбмий мене зовсім з гріха,\nО, Боже мій, обмий мене.\n\nПриспів: \nО, Боже мій, обмий мене,\nА, як потрібно, - чисть вогнем.\nЯк хочеш чисть, щоб тільки гріх \nБільше не був в серці моїм.\n\nКуплет 2\nВід злих думок, гріха і зла,\nХоч уникаю я Щодня,\nТа, як би не старався я, - \nНечистий я, нечистий я.\n\nКуплет 3\nХоч дав би Ти, о Боже мій,\nБагатство, славу і успіх,\nТа серце чисте є важніш \nНад скарби всі, над скарби всі.\n\nКуплет 4\nЯк серце чистеє буде,\nТо вбачу я діла святі, -\nІ в славу Бог мене прийме -\nВ Небесний Дім, в Небесний Дім.', '', '', '', '', 'ua', 0, NULL),
(595, 'Перед красними дверима', 0, 11, 'Куплет 1\nПеред красними дверима храму\nЧоловік, кривий від роду, милостині все просив.\nЙшли Петро та Іван на молитву \nТой кривий руку простягнув до них.\n\nПриспів:\nСрібла і золота не маю, що ж маю, те тобі даю - \nВ ім’я Ісуса з Назарету вставай та ходи, \nПрославляючи Христа.\n\nКуплет 2\nПетро взяв його за праву руку \nІ підняв його вгору, і поставив на ноги - \nТой, підскочивши, пішов з ними в храм. \nПоходжаючи, він прославляв Христа.\n\nКуплет 3\nСкільки в світі є кривих душею,\nВсе блукають, не знають про спасіння.\nХто ж протягне їм руку утішення? - \nУмирають без Бога і прощення.', '', '', '', '', 'ua', 0, NULL),
(596, 'По скелях летючи', 0, 11, 'Куплет 1\nПо скелях летючи, шумить і вирує,\nВниз воду зливає невпинна ріка:\nІ піняться хвилі, несучи каміння, -\nїх клекіт бурхливий на мить не вмовка.\n\nКуплет 2\nНа гілці, що тут же схилилась над виром,\nЯ пташечку бачу крізь пиль водяну -\nВона над проваллям спокійно літає\nІ пісню під гуркіт співа чарівну.\n\nКуплет 3\nО, Божа пташино, хто дав тобі спокій?\nНавчи нас співати крізь бурі життя.\nСкажи, як в тім реві спокій зберігаєш,\nКрізь гуркіт щебечеш із вдячним чуттям?\n\nКуплет 4\nУ відповідь пташка, свій спів повторивши,\nПіднялась на крильцях у сяючу вись.\nІ вмить стало ясно для серця мойого:\nЯк прагнеш спокою,- у небо стремись.\n\nКуплет 5\nМолитва - це крила, які дані Богом \nНам, людям, страждальцям цієї Землі.\nУчися від пташки нести всі тривоги \nТому, Хто сіяє у вічній хвалі.', '', '', '', '', 'ua', 0, NULL),
(597, 'Послухайте цю повість', 0, 11, 'Куплет 1\nПослухайте цю повість про Спасителя Христа,\nЯк Він лишив Небесний Дім, Дім Господа Отця.\nСпитаєш ти, чом Він терпів - Я знаю, що за нас.\nЗа нас Він дав життя Своє, тому, що любить нас.\n\nПриспів: \nВін любить нас. (2р.)\nВін дав Своє життя за нас,\nТому, що любить нас.\n\nКуплет 2\nЯ рад, що мій Спаситель по Галилеї ходив,\nДо всіх звертавсь з любов’ю і святим життям Він жив.\nВін кликав за Собою, і я піду за Ним теж.\nНіколи Він не лишить нас, тому, що любить нас.', '', '', '', '', 'ua', 0, NULL),
(598, 'Поки молоді і сильні', 0, 11, 'Куплет 1\nПоки молоді і сильні, серце б’ється у груді - \nДружно всі підем у битву, переможем зло і гріх.\n\nПриспів: \nВ винограднику Христовім \nКожний труд собі знайде,\nІ, коли цей труд закінчимо,\nСонечко нам не зайде.\n\nКуплет 2\nСам Христос тут буде з нами, він поможе в боротьбі. \nТо ж вперед всі, не вагаймось, ждім на поміч з висоти.', '', '', '', '', 'ua', 0, NULL),
(599, 'Роде невірний', 0, 11, 'Куплет 1\nРоде невірний та серцем лукавий,\nГоді вже Бога святого гнівить! \nГоді грішити, неправду творити!\nТреба вже Богові вірно служить.\n\nКуплет 2\nСлавити Бога - великеє щастя. \nЗавжди повинні про це ми подбать.\nДушу і тіло на добреє діло,\nСерце повинні Йому ми віддать.\n\nКуплет 3\nНива дозріла, робітників мало,\nПраця велика потрібна кругом.\nЧасу не гайте та з Богом рушайте\nБог вам поможе усяким добром.\n\nКуплет 4\nДяка велика Тобі, наш Владико. \nСлавити будем Тебе усі ми.\nКров Твого Сина гріхи наші змила, \nНас всіх звільнила з тяжкої тюрми', '', '', '', '', 'ua', 0, NULL),
(600, 'Руки благодаті', 0, 11, 'Куплет 1\nВсе Христові руки в ранах пресвятих \nВірою я бачу: кров струмує з них.\nО, ту кров спасіння, що сплива з тих рук,  \nСлавить мого серця кожен вдячний стук.\n\nКуплет 2\nСкільки милосердя ви творили всім, \nЗмученим гріхами, хворим і сліпим.\nО, любові руки, світ вам заплатив \nТим, що вас у глумі до хреста прибив.\n\nКуплет 3\nВас, Христові руки, Бог нам розпростер,\nЩоб ніхто душею у гріхах не вмер.\nЩоб могли, омиті ми у їх крові,\nУвійти, спасенні, в Вічний Край хвали.\n\nКуплет 4\nРуки благодаті, серцем бачу вас \nВ світлі над собою скрізь і повсякчас. \nО, святії руки, з тьми гріха і зла \nВаша кров пречиста і мене спасла.', '', '', '', '', 'ua', 0, NULL),
(601, 'Світи у куточку', 0, 11, 'Куплет 1\nНе чекай, щоб що великого зробити міг,\nА будь вірним в меншім ділі ти. \nНе чекай, щоби далеко ти світити міг,\nСвіти у куточку, де ти є.\n\nПриспів: \nСвіти у куточку, де ти є! (2р.)\nЩоби ті, що у пітьмі,\nУсі до Господа прийшли - \nСвіти у куточку, де ти є.\n\nКуплет 2\nМногі люди цього світу блудять у пітьмі - \nСвоїм світлом шлях їм освіти.\nПостарайся поміч дати хоч одній душі,\nСвіти у куточку, де ти є.\n\nКуплет 3\nВсіх людей, що у темряві, Ти сам пробуди, \nА голодних хлібом накорми.\nТи раненько при зорі всіх до Христа веди, \nСвіти у куточку, де ти є.', '', '', '', '', 'ua', 0, NULL),
(602, 'Святий Боже Всемогутній', 0, 11, 'Куплет 1\nСвятий Боже Всемогутній,\nВчуй нас в цей благальний час.\nМи Тебе від серця просим:\nПрости і помилуй нас.\n\nКуплет 2\nСвятий, кріпкий, недосяжний - \nНас не кинь в непевний час,\nНе відмов нам в благодаті,\nПрости і помилуй нас.\n\nКуплет 3\nБоже, глянь: Ми - Твої діти,\nМолимо Тебе всі враз:\nДай нам сили все здоліти,\nІз гріхів звільни Ти нас.\n\nКуплет 4\nЯк без батька і без неньки \nСиротина все тужить,\nТак без Тебе, милий Боже,\nТяжко і тривожно жить.', '', '', '', '', 'ua', 0, NULL),
(603, 'Скажи мені о Боже мій', 0, 11, 'Куплет 1\nСкажи мені, о Боже мій, чому сумує душа моя? \nУсюди лиш темрява нічна. (2р.)\n\nКуплет 2\nСкінчився день, настала ніч і світла не видно навкруги, \nХоч близько Йорданські береги. (2р.)\n\nКуплет 3\nХто хоче з нас ввійти в той Край, де зникне темрява нічна?\nВеде нас туди любов одна. (2р.)\n\nКуплет 4\nЗішли любов, Спаситель мій, і світлом Твоїм Ти засвіти, \nПровини усі мої прости. (2р.)\n\nКуплет 5\nПрости, благаю я Тебе, розглянь моє серце; Спасе, Ти, \nХай вічно з Тобою душа живе!  (2р.)\n\nКуплет 6\nМій Спасе, скеле Ти моя, лиш в Тебе наука є свята-\nЯ хочу учитись лиш в Христа. (2р.)\n\nКуплет 7\nТи мій Спаситель і мій Творець, Ти мій Спаситель і мій Отець, \nЩо дасть мені золотий вінець. (2р.)\n\nКуплет 8\nКоли явишся, Спасе мій, із ангелами в славі Отця,- \nТоді вознесеться Церква жива. (2р.)\n\nКуплет 9\nВсі вірні діти, мов зірки, сіяти будуть на небесах - \nЗакон зберегли святий в серцях. (2 р.)\n\nКуплет 10\nЗате заплату Бог нам дасть, що вірні були тут на землі. \nО, слава Творцеві, так, амінь.', '', '', '', '', 'ua', 0, NULL),
(604, 'Сказав Христос', 0, 11, 'Куплет 1\nСказав Христос: хто має вуха, нехай почує голос Мій. \nВже скоро прийду в силі Духа і засвічу світильник твій.\n\nПриспів: \nРаджу тобі купити в Мене \nЗолото перечищене,\nЩоб збагатився і звеселився - \nТоді прославиш ти Мене.\n\nКуплет 2\nКупи собі одежу білу, щоб зодягнувся нею ти.\nІ одягни її на тіло, щоби не видно наготи.\n\nКуплет 3\nІ мазі до очей купити Я нині раджу Сам тобі,  \nЩоб очі твої намастити, аби не жив ти у злобі.\n\nКуплет 4\nКого я люблю - докоряю. Будь ревний і покайся.\nСтою ось під дверми й чекаю, - як чуєш, то не гайся.\n\nКуплет 5\nЯ стукаю до серця твого, а ти, як чуєш, відчини.\nХто прийме, то прийду до нього й буду вечеряти Я з ним.\n\nКуплет 6\nХто переможе - дам йому сісти зі Мною на престолі,\nНебесні блага буде їсти зі Мною по Господній волі.\n\nКуплет 7\nЯ переміг і сів навіки з Отцем моїм на небесах.\nІ ви прийміть блаженні ліки - прийду до вас у чудесах.', '', '', '', '', 'ua', 0, NULL),
(605, 'Слухай заклик Спаса', 0, 11, 'Куплет 1\nСлухай заклик Спаса, друже!\nОсь Він стука в серце знов.\nНе відкладай, ще сьогодні\nТи прийми Його любов.\n\nПриспів:\nЗахист Він від бурі світа, вірне Сховище від зла.\nВ Нім любов''ю є відкрита Царства вічного хвала.\n\nКуплет 2\nО, прийми Його - і будеш \nЖити вже життям новим,\nЖиттям віри і любові,\nЩастям сповнений святим.\n\nКуплет 3\nДорожи, упертий друже,\nНапоминанням Христа- \nУ тім стуку милосердя \nВся любов Його свята.\n\nКуплет 4\nВ цьому світі все минає - \nЛюд Христом не дорожить ...\nУ кінці ж Господь за гробом \nЗасуд Свій страшний звершить.\n\nКуплет 5\nМуки совісті страшливі \nТам байдужих огорнуть,\nЩо в житті Христа минали \nІ ганьбили Його путь.\n\nКуплет 6\nО, не гайся відізватись,\nДруже, ти на заклик цей. \nСтук Христа замовкнуть може \nДо глухих твоїх грудей.\n\nКуплет 7\nІ за вічності порогом \nТи почуєш в грізний час: \n"Пізно вже! Закриті двері,\nВідійдіть, не знаю вас."', '', '', '', '', 'ua', 0, NULL),
(606, 'Спас за мене постраждав', 0, 11, 'Куплет 1\nСпас за мене постраждав, за мій гріх Він смерть прийняв\nІ за це життя своє віддаю Йому я все.\n\nПриспів:\nО, навчи нас, любий Спасе, як прожить життя своє,\nЩоб померло грішне наше, а зросло святе Твоє.\n\nКуплет 2\nНам Христос любов явив, нас усіх Він поріднив.\nХоче Спас, щоб ти і я з Ним були одна сім’я,\n\nКуплет 3\nСкоро прийде знову Він, нас введе в Небесний Дім:\nВічно будем жити з Ним, з Спасом любим, дорогим.', '', '', '', '', 'ua', 0, NULL),
(607, 'Там за обрієм', 0, 11, 'Куплет 1\nТам, за обрієм, славна Країна \nВ ній безмежна завжди краса.\nСкінчиться труд наш, праці година \nТам, за обрієм, на небесах.\n\nКуплет 2\nТам, за обрієм, немає спеки,\nСтрашних морозів, бур і вітрів.\nБудемо жити без небезпеки \nСеред чудових Божих садів.\n\nКуплет 3\nТам, за обрієм, зустріч щаслива \nНастане з тими, що відійшли.\nРозлука в небі вже неможлива \nТим, що спасіння вічне знайшли.', '', '', '', '', 'ua', 0, NULL),
(608, 'Певно я знаю що Ісус мій', 0, 11, 'Куплет 1\nПевно я знаю, що Ісус мій,\nБо мене держить в руці Своїй!\nВін моє серце в крові святій \nОбмив і дав теж Дух Свій Святий.\n\nПриспів: \nТепер я славлю Його щодня,\nБо Його ласка мене спасла.\n\nКуплет 2\nГолос любові звучить усе,\nЩо Ісус Кров''ю звільнив мене.\nЯ є безпечний усюди є з Ним,\nБо Він заслонить щитом Своїм.\n\nКуплет 3\nВін наповняє душу мою \nСвятим спокоєм і любовію.\nЙому служити буду все я,\nБо він для мене придбав життя.', '', '', '', '', 'ua', 0, NULL),
(609, 'Тобі я прагну все співати', 0, 11, 'Куплет 1\nТобі я прагну все співати,\nМій Боже, за любов Твою.\nСпасінням побажав підняти \nСкорботну душу Ти мою. - \nНіколи я не перестану\nТобі з душі співать "Осанна!".\n\nКуплет 2\nЛиш вранці сонце заясніє - \nТобі молитись я люблю.\nВ нічній тиші, як все німіє,\nТебе я піснею хвалю.\nІ щастя більшого не треба,\nЯк йти з хвалінням до Тебе.\n\nКуплет 3\nТебе Святого прославляти \nЯ, Боже, прагну всім життям,\nТвою присутність відчувати \nНа кожнім кроці всім чуттям.\nТобі в душі моїй щасливій \nНе вмовкнуть вдячні славоспіви.', '', '', '', '', 'ua', 0, NULL),
(610, 'Ти куди йдеш подорожній', 0, 11, 'Куплет 1\nТи куди йдеш, подорожній, з палицею у руці?\n- Я іду в рідну Країну, там знайду спокій душі.\n\nКуплет 2\nЧерез гори і долини, через степи і ліси,\nЧерез пущі і рівнини я іду у рідний Край.\n\nКуплет 3\n- Що дадуть тобі в тім Краю, що веселий такий йдеш?\n- Там дадуть для мене Славу і життя навіки жде.\n\nКуплет 4\nТам течуть живії води, там є цвіт життя, плоди.\nТам є цвіт життя, плоди - все навіки жде.\n\nКуплет 5\n- Ти самотній не боїшся по дорозі цій іти?\n- Я не сам, зі мною всюди ангели Господні є!\n\nКуплет 6\nІсус завжди є при мені, стереже в кожній хвилині. \nСтереже в кожній хвилині на дорозі цій вузькій.\n\nКуплет 7\n- Візьми мене, подорожній, щоб і я бачив той Край.\n- Дуже радо, любий друже, руку свою мені дай.', '', '', '', '', 'ua', 0, NULL),
(611, 'Все в Твоїх руках святий Владико', 0, 11, 'Куплет 1\nВсе в Твоїх руках, святий Владико,\nІ як дивно Ти усе створив.\nТи по милості Своїй великій \nВід гріхів нас Кров''ю відкупив.\n\nКуплет 2\nТи поніс за нас важкі страждання,\nМуки і насмішки від людей.\nЦе - ціна за наше оправдання \nЙ дороге звання Твоїх дітей.\n\nКуплет 3\nПоможи щохвилі пам''ятати,\nЩо такого Батька діти ми.\nІ подяку від душі складати,\nЩо Ти вивів нас з недолі й тьми\n\nКуплет 4\nДай Ти нам постійно відчувати \nДуха Твого силу й благодать,  \nЩоб душа могла завжди співати,\nІ Твоє лиш ім''я прославлять', '', '', '', '', 'ua', 0, NULL),
(612, 'В бурях народжене', 0, 11, 'Куплет 1\nВ бурях народжене плем’я Христове,\nЩо йдеш за Ісусом в рішаючий бій,\nВ останні часи ці під стягом любові \nПривіт тобі, юне, привіт наш палкий!\n\nКуплет 2\nБезвір’я навколо повстало стіною,\nСтискає злобою і горем серця, - \nЙому протиставтесь душею одною \nІз полум’ям віри, стійкі до кінця.\n\nКуплет 3\nXристос-переможець іде перед вами,\nХитається зло, де любов Його йде.\nВперед же, в борінні зімкнися рядами,\nКвітуюче плем’я Христа молоде.\n\nКуплет 4\nСьогодні усіх вас Христос обнімає \nНа грудях Своїх, як любимих дітей. \nА завтра, можливо, когось вас спіткає \nСтраждання від злоби осліплих людей.\n\nКуплет 5\nНе бійсь, світлоноснеє плем’я Христове,\nЗміняйте утомлених боєм борців,\nРостіть і квітуйте суцвіттям любові,\nІ зрійте красою Христових плодів!', '', '', '', '', 'ua', 0, NULL),
(613, 'У вирій в тузі журавлі', 0, 11, 'Куплет 1\nУ вирій в тузі журавлі відлітають,\nІ вітер свистить в почорнілих лісах - \nВін з гілок останні листочки зриває  \nІ холодом віє в промоклих полях.\n\nКуплет 2\nЯк добре отим журавлям, що прямують \nНа південь, де зелень, де вічне тепло;\nДе в сонці луги незатьмарно квітують,\nДе сніжних заметів повік не було.\n\nКуплет 3\nОсь так, на Христа уповаючим душам,\nВідрадно доходить до вічності днів,\nДе їх не діткне ні страждання, ні стужа,\nДе будуть з Христом вже навіки-віків.\n\nКуплет 4\nО, друже, не тим перейматися маєш, \nЩо осінь холодна листву обрива, \nА тим, яка вічність тебе вже чекає \nЗа гранню життя, що спішить-проплива.\n\nКуплет 5\nВесна ще вернеться і буде ще літо,\nИ лілеї пахучі цвістимуть в тиші;\nАле чи ти, друже, готовий зустріти \nОбіцяне Богом блаженство душі?\n\nКуплет 6\nАдже ти Христа не чекаєш у славі,\nПри трубах архангелів світлих висот, \nЯк, тілом змінившись, полине в прославі \nНазустріч Христові спасенний народ.\n\nКуплет 7\nЗадумайсь над цим, і схились перед Богом \nПоки ще лунає Євангельський зов,\nЩоб потім не вздріти себе за порогом - \nСпіши, доки кличе Христова любов.', '', '', '', '', 'ua', 0, NULL),
(614, 'Хай буде воля Боже Твоя', 0, 11, 'Куплет 1\nХай буде воля, Боже, Твоя \nЗавжди моєю - благаю я.\nЯ, як та глина, в Твоїй руці,\nЗ мене, що хочеш, зроби Собі.\n\nКуплет 2\nХай буде воля, Боже, Твоя,\nДивись, чи чиста душа моя.\nКров’ю святою мене обмий,\nЩоб був я здібний на труд святий.\n\nКуплет 3\nХай буде воля, Боже, Твоя —\t\nТільки на Тебе надіюсь я,\nТи - моя сила і мій спокій,\nТи - моя радість, Спаситель мій.\n\nКуплет 4\nХай буде воля, Боже, Твоя —\nТи Святим Духом мене сповняй,\nЩоби побачили люди всі,\nЩо Ти, Ісусе, живеш в мені.', '', '', '', '', 'ua', 0, NULL),
(615, 'Хочу я з Тобою говорить', 0, 11, 'Куплет 1\nХочу я з Тобою говорить,\nТи найкращим Другом є моїм.\nЧуєш Ти ридання, плач душі, 2р.\nНа мене глянь оком Ти Своїм.\n\nКуплет 2\nГоре я сховаю від людей,\nЛиш Тобі одному розкажу.\nЯ надіюсь, Боже, на Тебе,\nІ від Тебе сил, спокою жду.\n\nКуплет 3\nЧасто йду до Тебе, Боже мій,\nВ час, коли темрява є кругом,\nЩоб на мене глянув Ти з небес,\nСерце освітив моє Ти знов.\n\nКуплет 4\nО, як важко, Боже, в світі жить,\nВ ці часи непевні марноти.\nСили, Боже, Ти мені пошли,\nПоможи шляхом до Тебе йти.', '', '', '', '', 'ua', 0, NULL),
(616, 'Христе Ти як те сонце', 0, 11, 'Куплет 1\nХристе, Ти - як те сонце \nЯсне, веселе - Ти є любов. (2р.)\nРадість, о, що за радість\nДаєш Ти, Христе, в моє життя. (2р.)\n\nПриспів: \nА смуток веде ближче до Бога,\nЦей смуток скінчиться скоро вже. \nТісноти на коліна приводять...\nТісноти, коли залишу вас? (2р.)\n\nКуплет 2\nXристе - Ти є надія,\nЩо скоро смутку прийде кінець. (2р.)\nШляхи там золотії,\nТам все сіяє блиском небес. (2р.)\n\nКуплет 3\nХристе, ще поки тут я\nМолю: тримай Сам біля Себе. (2р.)\nСлабий, падаю завжди, -\nВсе ж таки рвуся ближче Тебе. (2р.)', '', '', '', '', 'ua', 0, NULL),
(617, 'Цар Сіонський', 0, 11, 'Куплет 1\nЦар Сіонський, наш Спаситель,\nПрийде скоро вже до нас.\nСповняється Слово Боже,\nЩо вже близький всьому час.\n\nКуплет 2\nПринесе усім заплату,\nКожному з нас по ділах:\nСправедливим - радість вічну,\nНечестивим - плач, сором.\n\nКуплет 3\nДіти Божі всі зберуться,\nБудуть Спаса прославлять,\nЩо за гріхи всього світу \nНа Голгофі був розп’ят.\n\nКуплет 4\nГopa Сіон буде чиста,\nЯк новий Єрусалим - \nЧистішая від золота,\nНа ній буде Божий Син.\n\nКуплет 5\nПрославлять Його ангели - \nХерувим і серафим.\nПрославляють і прославлять - \nТо ж прославмо Його й ми.\n\nКуплет 6\nЯк прекрасно на Сіоні,\nДе наш Цар, Спаситель, Бог,\nБуде правити народом \nІ не буде вже тривог.\n\nКуплет 7\nНечестивих там не буде\nІ ніякого гріха.\nТільки будуть діти Божі \nПрославлять повік Христа.', '', '', '', '', 'ua', 0, NULL),
(618, 'Цей світ нам каже', 0, 11, 'Куплет 1\nЦей світ нам каже, що користі немає \nСлужить Ісусу, коли ми молоді, - \nАле ми знаєм, ми твердо це знаєм,\nЩо ми нагороду одержим від Христа.\n\nКуплет 2\nЦей світ нам каже, щоб ми йому служили, \nКоли здорові, сильні й молоді,\nАле ми знаєм, і певно це знаєм,\nЩо ми нагороду одержим від Христа.', '', '', '', '', 'ua', 0, NULL),
(619, 'Чи думав ти колись', 0, 11, 'Куплет 1\nЧи думав ти колись, чому сльози течуть \nЗ твоїх очей, коли так тяжко на душі?\nБог потішає нас, коли Він чує плач в тиші: \nБог розуміє сльози людей.\n\nКуплет 2\nКоли недоля ця спіткає нас в житті, \nНадія гасне, слабне віра і любов - \nБог все, Він поведе і сльози Сам утре: \nБог розуміє сльози людей.\n\nКуплет 3\nБог бачить сльози, всі печалі твої.\nВін бачить сльози і чує крик душі.\nБог разом плаче, відчуває біль в тобі:\nБог розуміє сльози людей.', '', '', '', '', 'ua', 0, NULL),
(620, 'Чи любиш ти брате Ісуса', 0, 11, 'Куплет 1\nЧи любиш ти, брате, Ісуса,\nЧи знаєш ти, сестро, Його?\nЧи ціниш Його ти страждання,\nЧи слухаєш слів ти Його?\nДень Божого суду вже близько, \nДень радості скоро прийде.\nВже ангели скоро являться \nЙ Ісус в Своїй славі прийде.\n\nКуплет 2\nСвятії з гробів повиходять, \nЖивії пристануть до них - \nУсі утішатися будуть,\nЩо йде вже у славі Жених. \nКайся, люба сестро і брате, \nТримайся Ісуса Христа, - \nНавколо обняла темрява \nНаука у світі людська.\n\nКуплет 3\nПанує скрізь людськая мудрість \nА голос лунає з небес,\nЩо Бог Своїм Духом підійме,\nВсіх вірних від тої землі.\nВже гори від крові розмокли \nІ трупи лежать на полях ...  \nА жаль мені тих, що немає,\nБагато братів споміж нас.\n\nКуплет 4\nІ сестри в далекому краю - \nДля них там зібрання нема ...\nПишіть, браття й сестри, у листах,\nЩо вже почалися жнива.\nКукіль уже Господь збирає,\nІ в’язкам рахунку нема.\nВже скоро збере і пшеницю,\nІ так закінчаться жнива.', '', '', '', '', 'ua', 0, NULL),
(621, 'Чи ти чуєш голос Божий', 0, 11, 'Куплет 1\nЧи ти чуєш голос Божий \nУ тиші самотніх стін? - \nПід дверима Перехожий - \nСлухай, що говорить Він.\n\nПриспів: \nНіжно мовить Спас твоїй душі,\nЖде тебе, - до Нього поспіши.\nСерце не вагайсь відкрити - \nВін ввійде, щоб ти міг жити,\nМир затрачений знайти. \nДруже, стань, до Нього йди!\n\nКуплет 2\nКлич любові чи ти чуєш? - \nОсь тебе Він кличе знов.\nВін один тебе врятує,\nДасть спокій тобі й любов.\n\nКуплет 3\nНе дивись, що ти спіткнувся,- \nЗнов до Нього підійди.\nКличе Він, щоб ти вернувся,\nПрагне Він тебе спасти.', '', '', '', '', 'ua', 0, NULL),
(622, 'Чи ходив до Спаса ти', 0, 11, 'Куплет 1\nЧи ходив до Спаса ти з своїм гріхом,\nЧи у крові із Агнця ти вмивсь? \t\nЧи щодня ти ходиш услід за Христом,\nЧи у крові із Агнця ти вмивсь?\n\nПриспів: \nВмитий ти у крові,  \nУ пречистій Христа крові, \nЧи одежа біліша над сніг твоя, \nЧи ти вмитий в Христа, крові?\n\nКуплет 2\nЧи довір я маєш до Ісуса ти, \nЧи у крові із Агнця ти вмивсь?\nЧи Його страждання відчуваєш ти,\nЧи у крові із Агнця ти вмивсь?\n\nКуплет 3\nІсус скоро прийде, чи готовий ти,\nЩоб зустрінутись з Спасом твоїм\nЧи готовий ти в Дім Божий увійти,\nЧи у крові із Агнця та вмивсь?\n\nКуплет 4\nГеть відкинь ти нині всі гріхи твої\nЧи у крові із Агнця ти вмивсь?\nБо те джерело тече для грішних всіх.\nЧи у крові із Агнця ти вмивсь?', '', '', '', '', 'ua', 0, NULL),
(623, 'Швидко дуже швидко', 0, 11, 'Куплет 1\nШвидко, дуже швидко дні ідуть\nНаче хмари, що у даль пливуть.\nНа висках ось вкралась сивина -\nСтарість вже наближує вона.\n\nПриспів: \nСум огорта; пройшли літа, \nЯ так мало потрудився для Христа.\n\nКуплет 2\nВ юності спасіння я не знав; \nГоспода тоді не прославляв.\nПолюбляв гріховні я стежки, -\nВ звабах світу йшли мої роки.\n\nКуплет 3\nМолодість вже була позаді, \nЯк з Христом зустрівся на путі;\nПізно серце я Йому розкрив:\nСивим вже на шлях Його ступив.\n\nКуплет 4\nЩастям є із юних літ прийнять \nПресвяту Христову благодать:  \nВ тім не будеш каятись, о ні, \nЯк жаліть приходиться Мені!', '', '', '', '', 'ua', 0, NULL),
(624, 'О божих слів не забувай', 0, 11, 'Куплет 1\nО, божих слів не забувай!\t\nЯскраве світло в них для нас; \nДля Бога серце відкривай,\nСпасенним будь! - це кличе Спас.\n\nПриспів: \nДень завтра може не прийти, \nІ сонце не освітить нас.\nА зараз час (Христа знайти, \nСпасенним будь! - це кличе. Спас.\n\nКуплет 2\nУсюди в світі гріх царить,\nСпокою він тобі не дасть,\nПочни по-християнськи жить, -\nСпасенним будь, - це кличе Спас.\n\nКуплет 3\nХристос до Себе всіх прийняв,\nХто оцінив спасіння час;\nЯкби Його і ти пізнав, - \nСпасенним будь! - це кличе Спас.', '', '', '', '', 'ua', 0, NULL),
(625, 'Я вже лишив гріховний шлях', 0, 11, 'Куплет 1\nЯ вже лишив гріховний шлях,\nЯким ще люди йдуть в гріхах.\t\nСпитаєш про причину в тім? - \nЯ йду в Небесний, Вічний Дім!\n\nПриспів: \nЦей світ, цей світ не є мій дім. (2р.)  \nЦей світ не є спочинок мій. ...\nЦей світ, цей світ не є мій дім.\n\nКуплет 2\nСпиняють люди тут мене,\nЗмагають знов в цей світ мене; \nТа я не піддаюся їм - \nЯ йду в Небесний, Вічний Дім.\n\nКуплет 3\nО, друже, йди зі мною ти \nВ Небесний Вічний Дім хвали.\nНе стій, скажи причину в тім, \nЧом ти не йдеш в той Вічний Дім?', '', '', '', '', 'ua', 0, NULL),
(626, 'Я знаю ріку що тихенько пливе', 0, 11, 'Куплет 1\nЯ знаю ріку, що тихенько пливе\nЗ святої ріки - джерела;\nХвилює, шепоче вода і пливе,\nЧи в душу твою увійшла?\n\nПриспів: \nО, друже, скоріше ходи\nДо джерел живої води. \nЧи чуєш? -Шепоче Вода і пливе, \nТобі спокій вже несе.\n\nКуплет 2\nЯк серце осягне ту воду живу,\nТо радість огорне тоді\nІ ласку пізнаєш велику, святу,\nЗ гріхів увільнишся повік.\n\nКуплет 3\nГлибінь ця прозора, від сонця ясніш,\nПідкріпляє серце слабких,\nВеде їх по вірі до вічних країн\nІз горя і смутків земних.\n\nКуплет 4\nРіка є життя - джерело із скали \nЗ Христових виринає ран.\nЗа тебе, мій друже, за твої гріхи \nСпасіння у Крові Він дав.', '', '', '', '', 'ua', 0, NULL),
(627, 'Як Божий спокій', 0, 11, 'Куплет 1\nЯк Божий спокій моє серце сповив -\nНехай мене буря страшить - \nЯ з вірою в Бога безстрашно іду- \nБог від зла мене захистить.\n\nПриспів: \nБог є мій, Бог є мій, я Його —\nЯ душевний спокій в Нім знайшов.\n\nКуплет 2\nГріховні кайдани Він в мене забрав,\nГріхи з мене зняв Він цілком!\nОбмив Він мене у пречистій крові,\nСпасен я могутнім Христом.\n\nКуплет 3\nО, Господи, Боже, Твого приходу я жду,\nЩоб душу узяв Ти з землі.\t\nЯ знаю, що в небі для серця знайду \nСпокій я на Твоїй груді', '', '', '', '', 'ua', 0, NULL),
(628, 'Як покличе відізвуся', 30, 11, 'Куплет 1\nЯк покличе - відізвуся (Зр.)\nБуду щиро працювати для Христа.\nБуду щиро працювати (Зр.) для Христа (2р.)\n\nКуплет 2\nЧи у горах, чи в долині, (Зр.)  \nСкрізь я буду працювати для Христа.\nСкрізь я буду працювати (Зр.) для Христа. (2р.)\n\nКуплет 3\nВінець слави я дістану, (Зр.)\nКоли буду працювати для Христа.\nКоли буду працювати (Зр.) для Христа (2р.)', '', '', '', '', 'ua', 0, NULL),
(629, 'Я тонув у морі зла', 0, 11, 'Куплет 1\nЯ тонув у морі зла, в безмежній глибині\nІ далеко від Христа грозила смерть мені.\nЛиш Ісус почув мене, як плакав я в той час,\nРуку простягнув мені й мене Він спас.\n\nПриспів: \nСпаситель мій, Спаситель мій!\nВід смерті спас мене Спаситель мій!\n\nКуплет 2\nВсе життя тут на землі для Бога я віддав.\nСлавлю завжди я Його - Він спокій мені дав.\nЛаска Божа, як ріка, з серця мого пливе,\nБо Ісус Спаситель Сам в мені живе. -\n\nКуплет 3\nЯкщо томишся в гріхах, - на поміч клич. Христа. \nРуку Він подасть тобі, врятує від гріха.\nМає владу над усім, слухайся лиш Його - \nЛюбить Він тебе над все, іди до Нього.', '', '', '', '', 'ua', 0, NULL),
(630, 'Останній ще заклик', 0, 11, 'Куплет 1\nОстанній ще заклик до тебе звучить,\nО друже, чому ти байдуже стоїш?\nСпіши до Icycа спасіння прийнять,\nЩе поки спасає Його благодать.\n\nПриспів: \nОстанній ще заклик до тебе звучить,\nО грішник, не гайся, спасіння прийми,\n\nКуплет 2\nТебе на зібрання Дух Божий привів,\nЩоб ти для душі тут спасіння знайшов.\nІ словом святим Він ще кличе: Прийди!\nЧекає тебе, але ти не спішиш.\n\nКуплет 3\nЗібрання скінчилось, стемніло кругом,\nІ заклик спасіння замовк вже давно, \nТа в серце Спаситель все стукає й жде,\nВідкрий Йому серце - Він скоро ввійде;\n\nКуплет 4\nЯк любиш життя, то весь гріх залиши.\nУ Бога спасіння - до Нього прийди.\nІсуса скоріше прийняти спіши\nI заклик останній ти в серце прийми.', '', '', '', '', 'ua', 0, NULL),
(631, 'В долині гріховній земній', 0, 11, 'Куплет 1\nВ долині гріховній земній,\nДо незгоди, нещастя, обман,\nВ рідний Край я іду неземний \nПо скорботних слідах християн.\n\nПриспів: \nВ рідний Край неземний,\nДе нема зла й не ллється вже кров,\nЯ іду і прийду, де царює святая любов.\n\nКуплет 2\nХоч як небезпечно кругом,\nІ важка є мандрівка моя, - \nЯ надіюсь і йду за Христом \nВ рідний Край, де спочину з Ним я.\n\nКуплет 3\nСміливо вперед я іду,\nІ неспокій мені не страшний.\nЯ долину земну перейду, - \nІ ввійду в Дім Небесний святий.', '', '', '', '', 'ua', 0, NULL),
(632, 'Чують вістку люди', 0, 11, 'Куплет 1\nЧують вістку люди всього світу:\nВолодар спасенної душі \nВ сяйві слави й в святості великій.\nЙде, щоб взяти Церкву від землі.\n\nПриспів: \nПрийде день і зустріч та настане \nНа долонях білосніжних хмар.\nІ Невіста перед Богом стане,\nЩо любов та вірність зберегла.\n\nКуплет 2\nБуде в небі радісне вінчання \nПри престолі Господа Отця.\nЗаспівають хори величально,\nТам блаженство, щастя без кінця.\n\nКуплет 3\nТож радій, обраниця Христова, - \nЗнак спасіння сяє на тобі !\nВір, молись і завжди будь готова \nГоспода бажанного зустріть.', '', '', '', '', 'ua', 0, NULL),
(633, 'Сходить сонце над обрієм', 0, 11, 'Куплет 1\nСходить сонце над обрієм, вже звучать святі слова: \nНаверніть до Бога, люди, зникне хай темрява вся.\n\nПриспів: \nГей, слухай люд: навернись до свого Бога! \nГей, слухай люд: бо то є свята дорога.\n\nКуплет 2\nЯк кохає мати сина, так кохає Спас тебе,\nПрокидайсь, моя Вкраїно, Доки будеш спати ще?\n\nКуплет 3\nВін залічить твої рани, нове серце тобі дасть. \nЖиття радісне настане, - будеш Спасові співать.\n\nПриспів: \nГей, Україно! Навернись до свого Бога!\nГей, Україно! Бо то є свята дорога.\n\nКуплет 4\nВірю, що ніяка сила дивну Божу благодать \nНе зуміє пересилить, - буде Бог людей спасать.', '', '', '', '', 'ua', 0, NULL),
(634, 'Без пісні я жити не можу', 0, 11, 'Куплет 1\nБез пісні я жити не можу, вона мені крила дає— \nЗдійматись над хмару ворожу, де радісно серцю стає.\n\nКуплет 2\nТам ясного неба блакиті, чудова Країна свята,\nДе вічно з Христом буду жити в оселях Отця дорогих.\n\nКуплет 3\nПостійно там буду співати, забувши страждання земні, \nСвятую любов величати, незлічені вічності дні.\n\nКуплет 4\nА зараз, хоч важко буває, - я з піснею хочу іти, - \nВона мені сил добавляє, веде до святої мети.', '', '', '', '', 'ua', 0, NULL),
(635, 'Нас в тайгу тут закинуто', 0, 11, 'Куплет 1\nНас в тайгу тут закинуто... Вкрита снігом земля.\nНаш брат, тут умираючи, чує крик журавля.\n\nПриспів:\nАх, журавлі, журавлі! З собою візьміть мене \nЗ сибірських страшних зим, де воля, спокій є.\n\nКуплет 2\nЧую, як журавлі летять в рідний теплий мій край.\nСерце плаче від цих страждань, Боже, Ти сили дай!\n\nКуплет 3\nДійсно, вірю, що мій Господь в небі мене там жде. \nВся надія лиш на Нього, - в небо мене Він веде.', '', '', '', '', 'ua', 0, NULL),
(637, 'Немає сліз не мучить страх', 0, 11, 'Куплет 1\nНемає сліз, не мучить страх, \nВсіх вище зір на небесах,\t\nПрекрасний мир в Краю святім,\nВсіх в небі жде нас Вічний Дім.\n\nПриспів: \nО, Вічний Дім, де радість, спокій, \nО, вічний день душі там моїй! \nГосподь зове, - і ми всі йдім, \nЛюбов веде в Небесний Дім,\n\nКуплет 2\nТам неземний співає хор,\nЖива вода завжди тече.\nТам чистотою сяє все,\nТам нагорода нас чека.\n\nКуплет 3\nПогаслий день зійде світліш,\nДарує Бог хвалу в уста. \nСвою рідню і друзів всіх \nМи там знайдем в ногах Христа.', '', '', '', '', 'ua', 0, NULL),
(638, 'Ти зміцняйся в Божій благодаті що в Христі', 0, 11, 'Куплет 1\nТи зміцняйся в Божій благодаті, що в Христі,\nПрапора любові вище підійми! \nТак, як вірний воїн, догоджай Христу, -\nТоді ти світлом переможеш марноту.\n\nПриспів: \nСпрямуй свій взір ти просто до неба,  \nВорог не зможе тебе здолать.\nТам вже корона тебе чекає,  \nСміло борися й не знемагай! - 2р.\n\nКуплет 2\nТи зміцняйся в Божій благодаті, що в Христі,\nІ зберігай святу науку у житті.  \nЯк мудрець, постійно практикуй знання -\nІ світ побачить Бога із твого життя.\n\nКуплет 3\nТи зміцняйся в Божій благодаті, що в Христі,\nІ розсівай насіння про любов усім.\nМужнім будь, щоб Божу правду голосить!\nЯка темрява зможе світло погасить?', '', '', '', '', 'ua', 0, NULL),
(639, 'Жити для Спаса', 0, 11, 'Куплет 1\nЖити для Спаса, з Ним умирать,\nЩо можна в світі краще бажать?\nВарто смирятись, варто боротись,\nВарто життя для Нього віддать.\n\nКуплет 2\nЖити для Спаса, день хоч малий,\nСутінок ночі подих тяжкий. \n«Не знемагати, не нарікати!\nВірно служити!» - клич наш святий.\n\nКуплет 3\nЖити для Спаса - гріх умертвить,\nРізні зневаги вміти терпіть.\nШлях як пройдемо, в небо ввійдемо,\nСлавно й безсмертно будемо жить!', '', '', '', '', 'ua', 0, NULL),
(640, 'Мій Бог є скеля', 0, 11, 'Куплет 1\nМій Бог є скеля, в Ньому я \nСпокійний під час бурі.\nМені спокоєм Він сія,\nПокровом під час бурі.\n\nПриспів: \nІсус - джерело у землі сухій,\nВ землі сухій, (2р.)\nІсус - джерело у землі сухій \nІ захист під час бурі,\n\nКуплет 2\nКоли душі нудьга грозить, - \nМене Спаситель захистить.\nЯк гори встануть на путі - \n«Не бійся!»!- чую я тоді.\n\nКуплет 3\nМій Бог - Отець Небесний мій \nІ захист під час бурі.\nНадійний, вічний і святий \nМій захист під час бурі.', '', '', '', '', 'ua', 0, NULL),
(641, 'Осанна', 0, 11, 'Куплет 1\nОсанна, осанна, осанна Царю! (2р.) \nІсуса славте, спів хай лине!\nВін з мерлих встав, і з нами нині!\nХваліть Його - Він Цар царів!\nВін - наш Всесильний Бог!\n\nПриспів: \nАлілуя! Тобі, Ісус, хвала!\nАлілуя! Глорія!\nАлілуя! Тобі лиш слава вся!\nАлілуя! Глорія!\n\nКуплет 2\nО, величай Христа хвалою!\nТворцю воскреслому співай!\nО, величай і прославляй -Він достойний похвали! \nО, величай і прославляй Ім''я Господа завжди!\nОсанна! Осанна! Осанна Царю! (2р.)', '', '', '', '', 'ua', 0, NULL),
(642, 'Про РіздвоХристове', 0, 11, 'Куплет 1\nПро Різдво-Христове ангел сповістив, \nІ радісну й нову пісню заспівав:\n«Всі люди радійте, дивну радість сійте \nВ День Різдва святий!»\n\nКуплет 2\nЯ лечу від Бога - радість дати вам: \nУ вертепі вбогім Спас родився нам! \nШвидко поспішайте Хлоп’ятко вітайте, — \nНа землі - спокій,\n\nКуплет 3\nПастухи теж знали, де ясна зоря,\nПрийшли, привітали Бога і Царя. \nБогові співали, дар Цареві склали,\nРаділи Христу.\n\nКуплет 4\nЛюди досі жили у гріхах своїх,\nЗ ними до могили переходив гріх.\nНа Різдво Христове дай життя їм нове,\nЩе й радісних днів.', '', '', '', '', 'ua', 0, NULL),
(643, 'Хоче всіх людей Ісус благословить', 0, 11, 'Куплет 1\nХоче всіх людей Ісус благословить, \nВістку добру в серце кожного вселить, \nДвері серця, друже, ти Йому відкрий, \nДасть тобі Ісус спокій.\n\nПриспів: \nІсуса ти впусти, (2р.)\nДвері серця, друже, ти Йому відкрий, \nДасть тобі Ісус спокій.\n\nКуплет 2\nВін прийшов за гріх наш на хресті страждать, \nВоскресінням Своїм перемогу дать.\nДвері серця, друже, ти Йому відкрий,\nДасть тобі Ісус спокій.\n\nКуплет 3\nХодиш ти в темряві, хочеш шлях знайти, \nЗнай, таких, як ти Ісус прийшов спасти. \nДвері серця, друже, ти Йому відкрий.\nДасть тобі Ісус спокій.\n\nКуплет 4\nЛиш щасливий той, хто до Христа прийде,\nВічну радість й щастя він собі знайде.\nДруже, двері серця ти Йому відкрий,\nДасть тобі Ісус спокій.', '', '', '', '', 'ua', 0, NULL),
(644, 'По високих горах Пастир мій іде', 0, 11, 'Куплет 1\nПо високих горах Пастир мій іде,\nСтежкою вузькою овець Своїх веде.\n\nПриспів: \nА я маленька овечка йду слідом за Ним \nСтежкою вузькою в місто Єрусалим.\n\nКуплет 2\nВін мій Пастир добрий, тихих любить Він,\nТа не любить гордих, всіх, що роблять гріх.\n\nКуплет 3\n«Я є шлях і правда, істина в житті.\nТи іди за Мною», - каже Він мені.', '', '', '', '', 'ua', 0, NULL),
(645, 'Хто створив квіточки', 0, 11, 'Куплет 1\nХто створив квіточки,-.квіточки, квіточки,\nХто створив квіточки? - Отець на небесах!\n\nКуплет 2\nХто створив зірочки, зірочки, зірочки,\nХто створив зірочки? - Отець на небесах !\n\nКуплет 3\nХто створив пташечки, пташечки, пташечки,\nХто створив пташечки?- Отець на небесах!\n\nКуплет 4\nХто створив тебе й мене, тебе й мене, тебе й мене, \nХто створив тебе й мене? - Отець на небесах!\n\nКуплет 5\nХто створив квіточки, зірочки, пташечки,\nХто створив тебе й мене? - Отець на небесах.', '', '', '', '', 'ua', 0, NULL),
(646, 'Один будує дім', 0, 11, 'Куплет 1\nОдин будує дім свій на піску. (Зр.)\nІ ось пішли дощі.\n\nКуплет 2\nПішли дощі і ріки розлились. (Зр.)\nІ дім цей не встояв.\n\nКуплет 3\nА другий дім будує на скалі. (Зр.),\nІ ось пішли дощі.\n\nКуплет 4\nПішли дощі і ріки розлились. (Зр.) \nІ дім його встояв.\n\nКуплет 5\nЗбудуй свій дім на камені-Христі, (Зр.)\nІ ві встоїть повік.\n\nКуплет 6\nМолись, щоб Бог тебе благословив, (Зр.)\nІ Він благословить!', '', '', '', '', 'ua', 0, NULL),
(647, 'Скоро скоро вже', 0, 11, 'Куплет 1\nСкоро, скоро вже ми побачимо Христа (Зр.)\n Алілуя! Алілуя! Побачимо Христа.\n\nПриспів: \nАлілуя, алілуя! (2р.)\nСльози Він зітре, як побачимо Христа. (Зр.) \nАлілуя! Алілуя! Побачимо Христа.\n\nКуплет 2\nРадість буде там — ми побачимо Христа. (Зр.)\nІ Алілуя! Алілуя! Побачимо Христа.\n\nКуплет 3\nСмерті там нема — ми побачимо Христа. (Зр.) \nАлілуя! Алілуя! Побачимо Христа.', '', '', '', '', 'ua', 0, NULL),
(648, 'Чому сумуєш ти', 0, 11, 'Куплет 1\nЧому сумуєш ти, чому в тузі душа?\nХіба не радісно з Христом тобі?\nМи діти Божі всі щасливі й радісні,\nМи найщасливіші на цій землі.\n\nКуплет 2\nВесною ранньою, душою чистою \nЧому не хочеш славити Творця?\nСпівай хвалу Йому за смерть голгофськую,\nЗа кров пролитую - співай Йому !\n\nКуплет 3\nТи мужнім будь в житті, змагайся з бурями!\nПідтримає тебе завжди Христос.\nБo обіцяв Він нам, що не залишить нас,\nЩо Він ніколи не залишить нас.\n\nКуплет 4\nЗустрінеш в небі ти свого Спасителя, \nХто на хресті простив твої гріхи.\nЛаскаво скаже Він - «До раю увійди,\nСлуга ти вірний Мій - Я Пастир твій!»', '', '', '', '', 'ua', 0, NULL),
(649, 'Серцем відчуйте', 0, 11, 'Приспів: \nСерцем відчуйте ласку Господа! \nЩасливий, хто пізнав Його! \nПрийдіть і відчуйте ласку Господа! \nЩасливий, хто пізнав Його.\n\nКуплет 1\nВін є добрий Пастир, Який завжди зі мною є. \nСеред неправди і гріха Його рука трима мене.\n\nКуплет 2\nКоли в печаль і у відчай Його дитя вмить упаде, - \nРятує Він його в біді, любов і ласку подає.\n\nКуплет 3\nНе тільки в дні спокою хвалу я буду віддавать.\nКоли через пітьму я йду,- повинен Голос мій звучать!', '', '', '', '', 'ua', 0, NULL),
(650, 'Дух Святий прийди до нас', 0, 11, 'Куплет 1\nДух Святий, прийди до нас, серця наші наповняй,\nЗ нами будь на кожний час і Христа нам відкривай.\n\nПриспів:\nО, величний Дух, прийди! Серця наші наповняй, \nВсіх, хто молить, утішай.\t\n(Ждем ми), ждем Тебе ми, о прийди!\nДух Святий, до нас прийди! О, прийди, благаєм всі,\nІ Ісуса відкривай, дивно Бога прославляй!\n\nКуплет 2\nВсе Тобі я віддаю - душу, тіло, розум мій.\nВсе життя і волю всю. Хочу буть навіки Твій.\n\nКуплет 3\nЯ Ісусові віддав би найдорожче все, що мав.\nВін за мене умирав, нам віддав життя Своє.', '', '', '', '', 'ua', 0, NULL),
(651, 'Отець Небесний із любовю', 0, 11, 'Куплет 1\nОтець Небесний, із любов''ю \nЗа все ми дякуєм Тобі!\t\nМи Сина Твойого омиті кров''ю,\nПеред Тобою в благоговінні ми стаєм.\n\nПриспів: \nСлава Всемогутньому Богу! - \nВін був, Він є і знов прийде.\nСлава Всемогутньому Богу навіки віків\n\nКуплет 2\nОтець Небесний, із любов''ю\nЗа все ми славимо Тебе!\nТи Сина Свойого послав на землю,\nБудемо щиро завжди славити Тебе!', '', '', '', '', 'ua', 0, NULL),
(652, 'Небо', 0, 11, 'Куплет 1\nНебо! Небо! О, синєє небо (небо)! \nНебо, оспіване в віршах поетів,\nПро тебе складено безліч сонетів:\nЧистий, безмежний, блакитний простір \nВабить, хто в небо підносить свій зір.\n\nКуплет 2\nА християнам небесна блакить \nЗбільшує віру сердець кожну мить;\nТам наш Ісус, наш Спаситель і Бог \nПриготував нам чудовий чертог.\n\nКуплет 3\nДе вже немає ні смутку, ні горя,\nДе нема сліз, де блаженная доля;\nВічно там сяє Христова краса,\nТак туди лине безсмертна душа.\n\nКуплет 4\nО, які любі оселі Твої,\nВ славному небі всі скарби мої!\nТам мій Спаситель, Небесний Жених \nЖде Свою Церкву - всіх любих Своїх.\n\nКуплет 5\nНебо, відкрий свою правду невірним,\nXто у житті був гріхові покірним, \nХто тішив душу у скарбах земних -  \nСпадщини в небі не буде для них.\n\nКуплет 6\nСховану думку, Затаєний гріх, \nНебо відкриє для поглядів всіх;  \nТам непідкупний Суддя-Божий Син,\nЗвіт віддадуть Йому всі, як один.\n\nКуплет 7\nЧасом буваєш ти сховане в хмари, \nБачимо ми не тебе, а примари.\nАле ми знаєм: відкриєшся знов,\nБо до всіх нас Бог являє Любов\n\nКуплет 8\nБожий народе, чекаючим будь, \nСкоро скінчиться земна твоя путь;  \nВ небо Ісус тебе прийме з Отцем  \nІ увінчає нетлінним вінцем.', '', '', '', '', 'ua', 0, NULL),
(653, 'Україно моя', 0, 11, 'Куплет 1\nУкраїно моя, батьків моїх земля,\nКрай прекрасний, чудова земля.\nНародився тут я і впізнав я Христа.\nБог призначив прожить тут мені.\n\nПриспів: \nУкраїно моя, батьків моїх земля!\nТут жили і вмирали батьки.\nТа є краща Країна на небі для нас,\nТам живуть наші близькі, нас ждуть.\nТам нас жде Авраам, і Мойсей, і Павло,\nТам чекає; нас всіх Божий син.\nО, Країно свята - Небеса!\n\nКуплет 2\nЯк прекрасні ліси, як прекрасні річки!\nУкраїнські прекрасні поля.\nТа на Небі ще краща, ще краща земля!\nТам спасенні живуть, як сім''я.', '', '', '', '', 'ua', 0, NULL),
(654, 'Сонечко влітку', 0, 11, 'Куплет 1\nСонечко влітку лагідно сяє,\nТеплим промінням радує нас. \nВипробування, так вже буває,\nНебо закриє для нас.\n\nПриспів: \nХай навіть в кошарі овець не стане \nІ виноград не дасть плода, - \nСлавити не перестану Господа Христа.\n\nКуплет 2\nЯкщо мене закружить, буває,\nВ водовороті марнотного дня, - \nВіра із марноти підіймає,\nЗнову співає душа моя.\n\nКуплет 3\nКоли в житті, буває, щось згубим, - \nСлово Ісуса згадаю в той час:\n“Де ваші скарби - там серце буде”.\nЗгуба тоді не тяжка для нас.\n\nКуплет 4\nКоли життєвий вибір настане, - \nЗадля Ісуса і слави Отця \nВсього позбудусь, скарбів не стане.\nЗнову хай пісня лунає моя.', '', '', '', '', 'ua', 0, NULL),
(655, 'Моя оселя', 0, 11, 'Куплет 1\nМоя оселя високо в Небі,\nДе радість буде вже без кінця.\nІ друзі, рідні там будуть з нами \nСпівати пісні там у Отця.\n\nКуплет 2\nОселя рідна! Там хочу бути.\nТуди бажаю, щоб відпочить.\nТам буду Бога я вічно славить \nІ в сяйві Неба Христу служить.\n\nКуплет 3\nЯк в бурю з моря моряк прямує \nПриплисти в Гавань, щоб відпочить,\nТак прагну серцем в Оселі Світла,\nДе відпочинок для всіх святих.\n\nКуплет 4\nВідрадно буде в тім Вічнім Домі, \nПобачу Спаса лицем в лице.\nВін на Голгофі страждав за гріх мій, \nЩоб примирити з Отцем мене.', '', '', '', '', 'ua', 0, NULL),
(656, 'Як тяжкий був гріховний шлях', 0, 11, 'Куплет 1\nЯк тяжкий був гріховний шлях, яким то я ішов.\nЛишив Спас славу в небесах, - мене спасти прийшов.\n\nПриспів:\nТепер співаю серцем я: Христос - Спаситель мій.  \nХай пісня все звучить моя. Він дав мені спокій.\n\nКуплет 2\nХристос з гріхів мене обмив в святій Крові Своїй. \nНавіки Він мене звільнив і дав душі спокій.\n\nКуплет 3\nВізьме мене з Собою Він в Небесну Вітчизну.\nТам радісно душею я навіки з Ним спічну.\n\nПриспів:\nТоді співати буду я: Христос - Спаситель мій.\nІ пісня зазвучить моя. Він дав мені спокій.', '', '', '', '', 'ua', 0, NULL),
(657, 'Нива моя', 0, 11, 'Куплет 1\nЯ в поле вийшов на світанку, коли ще люд спокійно спав, \nНа самоті осіннім ранком своє минуле пригадав.\nВ полоні мрій мені здавалось - я слухав старий передзвін. \nПереді мною свідки встали - діла моїх прожитих днів.\n\nПриспів: \nЯк згадаю восени безтурботні дні весни.\nПоле моє, нива моя! Чим засіяна вона?\n\nКуплет 2\nЖенці зібрати поспішали свій урожай, своє зерно,\nА поруч смужечка лежала та шелестіла бур’яном. \nТак боляче на серці стало, що мимоволі плакав я.\n"О, Боже мій, - вуста шептали, - Прости! - Це ж\n смужечка моя".\n\nКуплет 3\nЯ вдячний Богові сердечно, що Він в кінці осінніх днів \nМої гріхи, мою безпечність безмірній милості простив. \nЯ буду ниву засівати зерном добірним, не пустим,\nЩоб день великої відплати мене зненацька не', '', '', '', '', 'ua', 0, NULL),
(658, 'Памятай Господні щедроти', 0, 11, 'Куплет 1\nКоли бурі над твоїм життям ревуть,\nБолить серце, скорбні очі сльози ллють, -\nЛаску і любов Господню пригадай,\nСміло йди вперед, надії не втрачай.\n\nПриспів: \nЛаску і любов Господню пригадай, \nСміло йди вперед, надії не втрачай.\nПригадай: Він грішних полюбив. \nДивуватись будеш, що Він нам вчинив.\n\nКуплет 2\nКоли тяжке горе на душі лежить, \nСерце сум сповив глибокий, тяжко жить,- \nЛаску і любов Господню пригадай — \nСерце проясніє, зникне сум, відчай.\n\nКуплет 3\nНа Христа дивися та Його благай.\nПісля сліз та горя ввійдеш в Божий Край. \nЛаску і любов Господню не забудь.\nБурі та страждання наші всі минуть.', '', '', '', '', 'ua', 0, NULL),
(659, 'Блудний син', 30, 11, 'Куплет 1\nСтеп широкий розстелився Ген до небокраю.\nПоміж трав посохлих вітер гірко завиває.\nСонце випалило степ, ні води краплини.\nПо степу юнак іде в латаній свитині.\n\nПриспів:\nДоле ж моя, доле, що ж мені діяти?\nЯк прийти до батька в дім? Що йому сказати? \nДоле ж моя, доле, розстелися степом. \nХто ж мене такого знов додому прийме?\n\nКуплет 2\nЛишив батька, лишив дім, лишив рідну Неньку.\nПоміняв на гірку воду матінку стареньку.\nБоже! Що я наробив у ту лиху годину?!\nІ рознісся степом крик блудної дитини.\n\nКуплет 3\nСкільки горя, скільки сліз зазнав на чужині! \nПрости, батьку, тяжкий гріх ти своїй дитині. \nСерце кров’ю облилось у старого батька.\nСльози щастя на очах: - Я ж бо сина бачу!\n\nПриспів: \nСину, рідний сину, ти ж моя дитина!\nКращі шати одягни, скинь стару свитину. \nСину, рідний сину, ти ж моя дитина! \nОбійму міцніше, я забуду провину.', '', '', '', '', 'ua', 0, NULL),
(660, 'Як закінчиться мій труд', 0, 11, 'Куплет 1\nЯк закінчиться мій труд на землі,\nСпокій на небі Христос дасть мені.\nВічно там буду я з Ним пробувать \nІ дивну славу Його споглядать.\n\nПриспів: \nВ славу Свою прийме мене, (2р.)\nБуду Христа вічно я споглядать.\nВ славу Свою прийме мене.\n\nКуплет 2\nТам приготовлене в домі Отця  \nМісце для мене любов''ю Христа.\nЩо то за радість у Нім пробувать \nІ дивну славу Його споглядать!\n\nКуплет 3\nТам, у небесних оселях святих,\nРідних і друзів зустріну своїх..\nРазом там будемо пісню співать .\nІ вічно славу Христа споглядать!', '', '', '', '', 'ua', 0, NULL),
(661, 'Щиро вітаємо', 0, 11, 'Куплет 1\nЩиро вітаємо, друзі, вас нині\nІ відкриваємо наші серця.\nВи не чужі нам, ви близькі, ви рідні,\nБо одного всі ми діти Отця.\n\nПриспів: \nВ братній любові вас щиро вітаєм.\nВ наших серцях торжество, торжество.\nБогові нашому славу складаєм \nЗа ці відвідини Церкви Його.\n\nКуплет 2\nНам розкажіть, як з безодні страшної \nВ час небезпечний вас Бог врятував,  \nЯк Він повів вас рукою міцною,\nЯк дивне слово “Спасенний” сказав.\n\nКуплет 3\nНам розкажіть, як в місцевості вашій\nБог дарування Свої вам давав, \t\nЯк доброту ви пили з Його чаші,\nЯк вас любов’ю Христос оживляв.\n\nКуплет 4\nЯк через слово Євангельське чисте \nВін промовляв вам до серця нераз.\nВсі заспіваймо, брати, урочисто.\nТой самий Бог і у вас, і у нас.', '', '', '', '', 'ua', 0, NULL),
(662, 'Тємної ночі зорі засяли', 0, 11, 'Куплет 1\nТємної ночі зорі засяли,\nАнгели людям радість звіщали:\nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.\n\nПриспів: \nХристос родився! (Зр.) Всім на спасіння.\n\nКуплет 2\nЛюди, радійте, Христа вітайте,\nБожому Сину славу віддайте! \nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.\n\nКуплет 3\nСлава у небі Богу святому,\nНа землі спокій роду людському!\nУ Вифлеємі, в стайні на сіні \nХристос родився всім на спасіння.', '', '', '', '', 'ua', 0, NULL),
(663, 'Ой над Вифлеємом тихо зорі сяють', 0, 11, 'Куплет 1\nОй, над Вифлеємом тихо зорі сяють.\nВід кого ж це люди двері зачиняють? (2р.)\n\nКуплет 2\nНе хотять прийняти до своєї хати \nІсусову Мати, щоб поночувати. (2р.)\n\nКуплет 3\nСтомлена Марія вже не має сили,  \nТа іде в стаєнку, мов би до хатинки! (2р.)\n\nКуплет 4\nУ стаєнці бідній Христос ся рождає,\nДо своєї неньки ручки простягає.(2р.)\n\nКуплет 5\nАнгели співають, Спаса величають.\nПастухи вітають, радість нам звіщають. (2р.)\n\nКуплет 6\nТож ми разом нині будемо співати \nІ Христа святого завжди прославляти. (2р.)', '', '', '', '', 'ua', 0, NULL),
(664, 'Спи Ісусе спи', 0, 11, 'Куплет 1\nСпи, Ісусе, спи, спатоньки ходи.\nБуду Тебе колисати,\nПісеньками присипляти. \nСпи, Ісусе, спи маленький, люлі, люлі.\n\nКуплет 2\nСпи, Ісусе, спи, очка зажмури.\nНе питай, що колись буде,\nЩо зготовлять Тобі люди.\nСпи, Ісусе, спи маленький, люлі; люлі.\n\nКуплет 3\nСпи, Ісусе, спи, головку склони\nТи на рученьки Марії,\nБач, вона Тебе леліє.\nСпи, Ісусе, спи маленький, люлі, люлі.\n\nКуплет 4\nСпи, Ісусе, спи, а серце втворй, \nХай при ньому спочиваю \nТут, на землі, і там, в раю.\nСпи, Ісусе, спи маленький, люлі, люлі.', '', '', '', '', 'ua', 0, NULL),
(665, 'Зірка засіяла в небі України', 0, 11, 'Куплет 1\nЗірка засіяла в небі України,\nДовгожданну волю принесла.\nЦе нам подарунок Божої Дитини,\nЦе Господня ласка нам зійшла.\n\nКуплет 2\nВисихають сльози матері-Вкраїни,\nВже не чути стогону землі.\nПоклонімся щиро у Божій Святині,  \nЩо пропала нечисть десь в імлі.\n\nКуплет 3\nНенько-Україно, навернись до Бога!\nСвій народ до нього поведи - \nІ зло не досягне нашого порога,\t\nВін заступить Край наш від біди.\n\nКуплет 4\nО, Ісусе милий! - молиться Вкраїна, \nНайщирішу вдячність воздає:\n“О, Дитятко Боже, як Бог і Людина, \nЇй благословіння дай Своє”.', '', '', '', '', 'ua', 0, NULL),
(666, 'Про благодатну долю України', 0, 11, 'Куплет 1\nПро благодатну долю України,\nПро щиру єдність, віру та любов,\nПро щастя й спокій кожної родини,\nБоже, звертаємось до Тебе знов.\n\nКуплет 2\nЯскравим світлом Слово Твоє сяє.\nЦим Світлом наш народ Ти просвіти.\nІ наше хай життя відображає \nТвій славний образ миру й доброти.\n\nКуплет 3\nДай, Боже, спокій нашій Батьківщині.\nТвоє дай Царство світле нам в серця,\nЩоб ми жили Твоїм благословінням \nІ вірними лишались до кінця.', '', '', '', '', 'ua', 0, NULL),
(667, 'Боже славимо Тебе', 0, 11, 'Куплет 1\nБоже, славимо Тебе і хвалу Тобі приносим.\nМи співаємо Тобі і серця свої підносим!\nВ цей святий молитви час величаєм, Царю наш!\n\nКуплет 2\nДуші праведних святих, сонми сил Твоїх небесних \nСлавлять велич діл Твоїх, діл великих і чудесних. \nСлавлять Бога і Отця - Вседержителя Творця!\n\nКуплет 3\nТвоє Ім''я на землі Церква щиро прославляє. \nЗаповіти всі Твої і шанує, і сповняє.\nГідний слави, Боже, Ти і любові Повноти.', '', '', '', '', 'ua', 0, NULL),
(668, 'Блукав я в далекій чужій стороні', 0, 11, 'Куплет 1\nБлукав я в далекій, чужій стороні,  \nІ сонце сховалось від мене.  \nНебесний Отець не забув за мене, \nЗ висока дивився на мене.\n\nКуплет 2\nІ тіло моє, ненаситне гріха,\nВ світських похотях потопало \nІ чув я чийсь голос, до мене Він звав.\nІ душа моя чогось-то бажала.\n\nКуплет 3\nДо Отця вернутись тепер я не смію.\nІ серце в великій тривозі,\nТому що блудив я в далекій стороні,\nНіколи не думав про Бога.\n\nКуплет 4\nІ, вставши, піду я до свого Отця,\nІ скажу Йому: "Согрішив я!\nЯ вже недостоєн Твоїм сином зватись,\nТо хоч за наймита прийми мене".', '', '', '', '', 'ua', 0, NULL),
(669, 'Кожний спрагнений іди та пий', 0, 11, 'Куплет 1\nКожний спрагнений, іди та пий !\nІз джерела Води Життя,\nХто любить Сина, хто вірить в Сина,\nТвоє життя цілком обновить Він.\n\nПриспів: \nАлілуя! Тобі хвала! (Зр.)\nАлілуя! Тобі, Ісус, хвала !!\n\nКуплет 2\nЯкщо ти знеміг, нема сил іти,\nВін поміч дасть на шляху земнім —\nТягарі знімає, сили відновляє,\nЗ усіх нещасть Він визволить тебе.\n\nКуплет 3\nТи проси вогню, і Він дасть тобі,\nСтанеш радісний і вперед підеш,\nЛиш Йому довірся, на Христа надійся,\nТвоє життя цілком обновить Він.', '', '', '', '', 'ua', 6, NULL),
(670, 'Ви води озера Генісаретського', 0, 11, 'Куплет 1\nВи, води озера Генісаретського, \nВ хвилях криштальних своїх\nОбраз відбили Христа Назаретського,\nРис Його дивних, святих.\n\nКуплет 2\nНині Він Духом Святим поселяється \nТихо у наших серцях.\nЧом же виразно в них не відбивається.\nТак, як колись у водах?\n\nКуплет 3\nМоже серця вкрились хмарами кволості,\nМоже схвильовані чим?\nАбо нема в наших душах прозорості,\nЩо ми не світимо всім?\n\nКуплет 4\nХай будуть душі й серця наші чистими,\nХай зникне з них марнота!\nВ нас відіб''ється тоді променистими \nРисами образ Христа.', '', '', '', '', 'ua', 0, NULL),
(671, 'Господи, як дивно, що я жив, Тебе не знаючи.', 0, 11, 'Куплет 1\nГосподи, як дивно, що я жив, Тебе не знаючи.\nЖив без кохання, без благословення з уст Твоїх.\nА нині я з Тобою, я в сім''ї Твоїх дітей, -\nЗа це благословляти хочу Бога, хочу прославляти Бога.\n\nПриспів:\nСлавте, славте Бога! Прославляйте Бога\nПрославляйте Бога\nВce більше день за днем. \nСлавте, славте Бога! Прославляйте Бога. \nПрославляйте Бога в серці своїм.\n\n\nКуплет 2\nГосподи, як дивно, Ти прийшов - життя змінилось\nВсе засяяло навколо світлом дивним неземним\nІ нині заспіваю я хвалу і поклоніння\nПеред величчю Твоєю і Твоїм лицем\n\nКуплет 3', '', '', '', '', 'ua', 6, NULL),
(672, 'Боже славлю я Тебе', 0, 11, 'Куплет 1\nБоже, славлю я Тебе навік! Славлю я Тебе навік!\nБo Твоє Ім''я прекрасне в похвалі.\n\nКуплет 2\nВозвеличую Тебе навік! Славлю я Тебе навік!\nБо Твоє Ім''я прекрасне в похвалі.', '', '', '', '', 'ua', 0, NULL),
(674, 'Ісус Імя величне', 0, 11, 'Куплет 1\nІсус - Ім''я величне!\nДивний Спаситель, славний Господь!\nЕммануїл - Бог вічно з нами!\nНаш Визволитель! Славний Господь', '', '', '', '', 'ua', 0, NULL),
(675, 'Ми єдині в любові Христа', 0, 11, 'Куплет 1\nМи єдині в любові Христа, ми єдині в любові Його\nСтав єдиний наш дух з Духом Божим Святим,\nМи єдині в любові Христа.', '', '', '', '', 'ua', 0, NULL),
(677, 'Я благословляю тебе', 0, 11, 'Куплет 1\nЯ благословляю тебе вічним Іменем Ісуса.\nМир, радість і любов від Господа душі твоїй.\nАлілуя, алілуя! Алілуя, алілуя!', '', '', '', '', 'ua', 0, NULL),
(678, 'Лиш на Христа надіюсь я', 0, 11, 'Куплет 1\nЛиш на Христа надіюсь я,\nБо джерело моєї слави - Його хрест,\nІ кожний день життя хочу сказати я:\n“Лиш на Христа, лиш на Христа надіюсь я”.', '', '', '', '', 'ua', 0, NULL),
(679, 'Ми знову зібрались сюди', 0, 11, 'Куплет 1\nМи знову зібрались сюди та й цю пісню співаєм.\nЦе пісня про нове життя, яке у Христі ми маєм.\n\nПриспів:\nНове життя, чудне нове життя!\nПовне світла, любові і тепла.\nНове життя, зовсім нове життя В Ісусі маєм ти і я.\n\nКуплет 2\nО друже, до Бога прийди! Він любить тебе і чекає.\nВін вічність дарує тобі, з тобою зустрітись бажає.', '', '', '', '', 'ua', 0, NULL),
(680, 'За Голгофу за кров', 0, 11, 'Куплет 1\nЗа Голгофу, за кров - дякую Тобі, Господь, \nЗа воскресіння Твоє, за перемогу Твою –\nЯ дякую Тобі, Ісус! (Зр.) За все Тобі я дякую! (Зр.)', '', '', '', '', 'ua', 0, NULL),
(681, 'В Тобі моя сила', 0, 11, 'Куплет 1\nВ Тобі моя сила, в Тобі моя радість!\nВ Тобі є надія, в Тобі, мій Господь!\n\nКуплет 2\nВсю славу Тобі віддаю,  Тебе лиш одного хвалю. \nТи - сила моя! Ти - радість моя!\nГосподь, Ти є моє життя', '', '', '', '', 'ua', 0, NULL),
(682, 'Шукайте перше Царства Божого', 0, 11, 'Куплет 1\nШукайте перше Царства Божого і правди Його,\nА усе інше буде дано вам. Алілуя! Алілуя!\n\nКуплет 2\nЦарство Небесне - не їжа і пиття,\nА праведність, і мир, і радість у Дусі Святім. \nАлілуя! Алілуя!', '', '', '', '', 'ua', 0, NULL),
(683, 'Я просто хочу бути там де Ти', 0, 11, 'Куплет 1\nЯ просто хочу бути там, де Ти,\nМандрувати за Тобою,\nМолитви не з відстані нести.\nВізьми мене туди, де Ти.\n\nКуплет 2 \nХочу бути там, де Ти є,\nНавіки з Тобою поруч.\nВізьми мене туди, де Ти є.\nЯ просто хочу жити там.\n\nКуплет 3\nЯ хочу бути поруч, навіки з Тобою,\nЗа столом сидіти в сяйві Твоєї слави, - \nБіля Тебе, я хочу завжди бути там,\nХочу бути там, хочу бути там, де Ти.', '', '', '', '', 'ua', 0, NULL),
(684, 'Мій Бог великий Бог', 0, 11, 'Куплет 1\nМій Бог — великий Бог!\nСлавити хочу Його кожним словом. \nРівних Йому нема в славі,\nІ милість Його не знає кінця.\n\nПриспів:\nЗемля і небеса возвеличують славу Його.\nАнгелів ніжні слова промовляють, що Бог є любов.\nМій Бог — могутність, рятунок й фортеця моя.', '', '', '', '', 'ua', 0, NULL),
(685, 'Господь твій Бог', 0, 11, 'Куплет 1\nГосподь твій Бог з тобою є. Могутній, могутній.\nХай славлять всі Його Ім’я \nВ силі, у славі і в радості.\nКерує хай тобою Він навіки і віки. Амінь.', '', '', '', '', 'ua', 0, NULL),
(686, 'Господеві заспіваймо', 0, 11, 'Куплет 1\nГосподеві заспіваймо, Господу співай, вся земля.(2р.)\nВеликий Бог, достойний слави Він! (2р.)', '', '', '', '', 'ua', 0, NULL),
(687, 'Хто скажіть кращим є', 0, 11, 'Куплет 1\nХто, скажіть, кращим є? Хто, скажіть, дивом є?\nЦар царів, Божий Син. Чи не Він? Чи не Він?\n\nКуплет 2\nЧи не Він вмер за нас? Вмер за нас чи не Він?\nНа хресті життя віддав чи не Він? Чи не Він?\n\nКуплет 3\nЧи не Він знов воскрес? Знов воскрес чи не Він?\nДав життя, благословив. Чи не Він? Чи не Він?', '', '', '', '', 'ua', 0, NULL),
(688, 'Я люблю тебе любов’ю Христа', 0, 11, 'Куплет 1\nЯ люблю тебе любов’ю Христа! (2р.)\nІ в твоїх очах горить любов свята.\nЯ люблю тебе любов’ю Христа.', '', '', '', '', 'ua', 0, NULL),
(689, 'Творець усіх небес', 0, 11, 'Куплет 1\nТворець усіх небес, Який створив весь світ, \nНайбільше чудо Ти звершив мені:\nНебесним Духом Ти зростив в мені Свій плід - \nЛюбов, і нею я служу Тобі.\n\nПриспів:\nТобі, Господь, моя молитва лине\nВ словах сердечних і сльозах.\nТобі, Господь, моя найкраща пісня \nБринить благоговійно на устах.\n\nКуплет 2\nТворець усіх небес, Який створив весь світ,\nЛице Твоє освітить темну ніч,\nЯк я знайшов Тебе і заключив завіт,\nЗ Тобою люблю бути віч-на-віч.', '', '', '', '', 'ua', 0, NULL),
(690, 'Ти моя сила у житті', 0, 11, 'Куплет 1\nТи — моя сила у житті, Ти є та ціль, куди я йду,\nТи є для мене все! Ти є той скарб, що я шукав,\nТи є Господь мого життя, Ти є для мене все!\n\nПриспів:\nІсус - мій Господь! Славлю я Тебе! (2р.)\n\nКуплет 2\nТи взяв мій гріх, мій хрест, мій біль,\nЗнову підняв мене, я — Твій! \nТи є для мене все! \nКоли є спека, - Ти є тінь,\nКоли я прагну, - Ти - вода.\nТи є для мене все!\n\nКуплет 3\nТи на Голгофі вмер за нас,\nАле воскрес і людство спас,\nТи для мене - все!\nТи воскресіння і життя,\nІ лиш до Тебе прагну я,\nТи для мене - все!', '', '', '', '', 'ua', 9, NULL),
(691, 'Скеля мого рятунку', 0, 11, 'Куплет 1\nСкеля мого порятунку Ти є, сила мого Ти життя.\nТи благодаттю даєш спасіння,\nДо Тебе молитва моя.\n\nКуплет 2\nВ Тебе вірую, я вірую! Бо Ти любиш так мене. \nДаєш поміч Ти у час важкий.\nВірним залишусь Тобі!', '', '', '', '', 'ua', 0, NULL),
(692, 'Богу співайте Алілуя', 0, 11, 'Куплет 1\nБогу співайте "Алілуя!" (2р.)\nБогу співайте, (Зр.) "Алілуя!"\nСлавте Його в своїх серцях...\nВ Бозі надія Тобі є...\n\nКуплет 2\nВірою всі прийміть Христа...\nРадуйтесь в Господі завжди...\nВін нам дарує благодать...\nВін С шлях, істина й життя...', '', '', '', '', 'ua', 0, NULL),
(693, 'Співай Господу вся земля', 0, 11, 'Куплет 1\nСпівай Господу, вся земля!\nПро спасіння Його говори!\nЙoroчудеса і слава сповіщаються по всій землі.\n\nКуплет 2\nВеликий Господь - сильний і могутній!\nРадій, радій! Бо наш Бог царює!', '', '', '', '', 'ua', 0, NULL),
(694, 'Моя молитва нехай лине', 0, 11, 'Куплет 1\nМоя молитва нехай лине \nДо Тебе, наче фіміам;\nІ серце лине безупинно \nВ чудовий Твій небесний храм.\n\nПриспів:\nБоже, я молю за Україну,\nБоже, молю Тебе за людей:\nТи їх прости, Ти їх спаси і милість Свою нам яви.\nБоже, я знаю, що Ти будеш з нами \nВ храмі Своєму під небесами,\nРадість і мир Ти дарував, життя за людей віддав,\nВ Книгу Життя нас записав.\n\nКуплет 2\nВ Своєму слові живому \nТи для людей спасіння дав,\nЩоб люди всі молились Тому,\nХто на хресті за них вмирав.', '', '', '', '', 'ua', 4, NULL),
(695, 'О який же то Приятель', 0, 11, 'Куплет 1\nО, який же то Приятель Ісус щирий є для нас!\nВін гріхи забрав на Себе наші і увільнив нас.\nЯк же часто без потреби болі й нужду терпимо \nЧерез те, що їх в молитві Богові не несемо.\n\nКуплет 2\nЧи то в спробі, чи в спокусі, чи де клопіт є в житті,\nЩиро Богові в молитві розкажіть нужду свою.\nЧи є вірніший друг, як Спас? Хто б нам в смутку співчував? \nІсус нашу неміч знає і в житті поможе нам.\n\nКуплет 3\nЧи ви хворі, обтяжені, чи журба валить вас з ніг,- \nІсус нашим є притулком. Просіть, щоб Він вам поміг.\nЧи тебе твій друг покинув,-Господу скажи про це!\nІсус другом твоїм буде, й не залишить Бог тебе.', '', '', '', '', 'ua', 0, NULL),
(696, 'Хай радіють всі вірні', 0, 11, 'Куплет 1\nХай радіють всі вірні в Христі,\nДана радість усім нам в житті.\nНаш Ісус з мертвих встав, нам із неба послав \nДуха, що потішає в житті.\n\nКуплет 2\nХай співають щасливі серця,\nПісня слави дзвенить без кінця. \nНе сумує нехай, не впадає в відчай \nВірить хто в ласку Бога-Творця.\n\nКуплет 3\nТож довірся Йому, друже, й ти,\nБо провадить Він нас до мети.\nНа шляху до небес, до країни чудес \nЛегко з Ним і приємно іти.', '', '', '', '', 'ua', 0, NULL),
(697, 'Коли хвилювання і сум', 0, 11, 'Куплет 1\nКоли хвилювання і сум надійдуть,\nСвій зір підійми в небеса, \nДепресія й страх твою душу гризуть - \nСвій зір підійми в небеса.\n\nПриспів:\nБог є добрий, поміч в Нім,\nСила в могутніх руках.\n\nКуплет 2\nКоли твій розбитий човен сів на міль,\nСвій зір підійми в небеса,\nЗагрожують тілу хвороби і біль - \nСвій зір підійми в небеса.\n\nКуплет 3\nНаповнений страхом перед майбуттям - \nСвій зір підійми в небеса,\nГосподь смерть і тління замінить життям - \nСвій зір підійми в небеса.', '', '', '', '', 'ua', 0, NULL),
(698, 'Радісний той день', 0, 11, 'Куплет 1\nРадісний той день, (2р.) що Господь нам дав. (2р.) \nВеселімось всі (2р.) у Ісусі Христі. (2р.)\nРадісний той день, що Господь нам дав.(2р.) \nВеселімось всі (2р.) у Ісусі Христі. (2р.)', '', '', '', '', 'ua', 0, NULL),
(699, 'Прийди Дух Святий', 0, 11, 'Приспів:\nПрийди, Дух Святий, я чекаю!\nЯ так потребую Тебе!\nПрийди в Твоїй силі і владі.\nПрийди, Дух Святий, я молю!\n\nКуплет 1\nПодай для душі відпочинок,\nПодай Ти для хворих бальзам!\nПрийди, як роса світанкова,\nПрийди у сердечний мій храм!\n\nКуплет 2\nВідкрий джерело нам в пустелі,\nІ спраглим Ти дух оживляй!\nТвоя ізціляюча сила\nХай сповнить мене через край!', '', '', '', '', 'ua', 1, NULL),
(700, 'Я прийду вже Шумні води не', 0, 11, 'Куплет 1\nЯ прийду вже скоро за тобою,\nІ візьму тебе Я в небеса,\nЯ купив тебе ціною крові,\nВірная голубонько Моя!\n\nПриспів:\nШумні води не згасять любові,\nРіки світу не заллють її,\nЯ купив тебе ціною крові \nВ муках і стражданнях на хресті.\n\nКуплет 2\nДень весілля скоро наступає \nВ небі приготовлений тобі,\nТам Єрусалим тебе чекає,\nБудь до смерті вірная Мені!\n\nКуплет 3\nСкоро сурми голос залунає,\nВсі почують надзвичайний крик,\nСуд гряде над грішною землею - \nТи ж готова будь у кожну мить!', '', '', '', '', 'ua', 8, NULL),
(701, 'О як довго Закхей', 0, 11, 'Куплет 1\nО, як довго Закхей щастя в світі шукав,\nТа знайшов лиш тоді, як побачив Христа.\n\nПриспів:\nПропустіте його, пропустіть наперед!\nХоче бачити він Ісуса Христа!\n\nКуплет 2\nДуже швидко Закхей зрозумів ці слова,\nЩо Христос говорив: "Йду до дому твого".\n\nПриспів:\nПропустіте мене, пропустіть наперед!\nХочу бачити я Ісуса Христа!\n\nКуплет 3\nЯк з Христом говорив, став Закхей і сказав: \n"Кому кривду вчинив, - вчетверо я віддам!"\n\nКуплет 4\nДруже мій, як Закхей, до Христа поспіши,\nВ Ньому радість знайдеш, лиш життя все віддай.\n\nКуплет 5\nІ побачиш Христа, вчуєш голос Його: \n"Заспокойся, душе, - йду до дому твого!"', '', '', '', '', 'ua', 0, NULL),
(702, 'Чого баришся сину', 0, 11, 'Куплет 1\nЧого баришся, сину, в далекій чужині?\nЧому не йдеш додому, що в рідній стороні?\nТам твій Отець сумує і часто сльози ллє:\n“Чому не видно сина? Чом довго так не йде?”\n\nКуплет 2\nГоре тебе спіткало і щастя вже нема,\nДрузі в біді лишили, в серці тяжка пітьма.\nВ домі Отця є світло, темряви там нема,  \nТам щастя, радість, воля, там вся твоя рідня!\n\nКуплет 3\nХоч тобі є соромно і совість не мовчить,\nЩо вдіяв так недобре,- чи ж можна все простить? \nХоч і тяжке падіння, велика та вина,\nЛюбить тебе Отець твій, в Нім спадщина Твоя!', '', '', '', '', 'ua', 0, NULL),
(703, 'Луги й поля квітками вкрились', 0, 11, 'Куплет 1\nЛуги й поля квітками пишно вкрились,\nВесни несеться всюди аромат,\nУся краса природи пробудилась,\nА люди ще в гріхах так міцно сплять. (2р.)\n\nКуплет 2\nУсяка квітка до світла стремиться,\nУсяка травка теж чує тепло,\nА світ з гріха не може пробудитись, \nВесни для них неначе б не було. (2р.)\n\nКуплет 3\nПташки здалека знову повертають,\nКалендаря не мають, знають час.\nНехай вони всім людям пригадають:\nПрийшла весна, - усіх Бог кличе вас. (2р.)\n\nКуплет 4\nПо всіх кінцях вже світить Боже Слово \nІ ніжно гріє всіх Його любов.\nЧому даєте ви життя для злого?\nХристос пролив за вас святую Кров. (2р.)\n\nКуплет 5\nУже давно настало Боже літо.\nДень благодаті нині іще є.\nСпіши до Спаса, щоб ти був одітий\nУ праведність, яку Христос дає. (2р.)', '', '', '', '', 'ua', 0, NULL),
(704, 'Хоч я бідний нещасний родився', 0, 11, 'Куплет 1\nХоч я бідний, нещасний родився \nІ в цім світі гріха я страждав,\nАле радий став, як зрозумів я,\nЩо з Христом є найкраще життя (2р.)\n\nПриспів:\nО, щоб світ міг пізнати те щастя,\nЩо з Христом є найкраще життя (2р.)\n\nКуплет 2\nЦей загиблий світ нині віддався,\nЩоби йти лиш дорогою зла.\nІ не знає, що скоро вже прийде \nТой великий, страшний день суда.\n\nКуплет 3\nТоді будуть зі страхом стояти \nПеред Божим престолом вони.\nІ почують той вирок прокляття:\nВідійдіть в огонь вічний всі ви!', '', '', '', '', 'ua', 0, NULL),
(705, 'Наші дні немов птах', 0, 11, 'Куплет 1\nНаші дні немов птах пролітають так швидко,\nНе вернути тепер їх назад.\nСкільки горя і сліз пережив ти, мій друже,\nБез Ісуса у світі ти йдеш.\n\nПриспів:\nТа Ісус простягнув Свою руку до тебе,\nПоміч дасть Він тобі на земному шляху.\nТи звернися до Нього, мій друже, в молитві,- \nБуде радість і спокій у серці завжди.\n\nКуплет 2\nПодивись на чоло, - воно вкрите лиш терном, \nКраплі крові течуть по лиці.\nСкільки болю й терпінь на горі тій Голгофі,\nЩоб тобі двері раю відкрить.\n\nКуплет 3\nДруже мій, що даси ти за подвиг цей хресний? \nЗа ту кров, що текла за твій гріх?\nТи схилися до Нього в сердечній молитві, - \nСпокій вічний тобі Він приніс.', '', '', '', '', 'ua', 0, NULL),
(706, 'Самарянка та не знала', 0, 11, 'Куплет 1\nСамарянка та не знала, що Христос її шукав,\nКоли воду вона брала й пити Він її прохав.\nІ ось Він їй відкриває, як колись вона жила,\nНемов з книги Він читає, ким вона була.\n\nПриспів:\nО, довірся, милий друже, бо Спаситель тебе жде,\nІ не будь такий байдужий, бо ж Він відійде.\n\nКуплет 2\nУ тривозі, мов від дива, від криниці до своїх \nПоспішає - нещасливих сповістити всіх,\nЩо якась свята Людина в самарійський край зайшла, \nЙ що спасіння вже година для них надійшла.\n\nКуплет 3\nІ тепер вода живая ллється в Бога для людей,\nВсім сумним Він витирає сльози з їх очей.\nВ цьому світі Він шукає безталанних, щоб спасти.\nНад криницею чекає, щоб прийшов і ти.', '', '', '', '', 'ua', 0, NULL),
(707, 'В далекі часи минулі часи', 0, 11, 'Куплет 1\nВ далекі часи, минулі часи в краю Палестині \nЗ’явилась зоря небесна, вона і сяє донині.\nТо світло для нас приніс любий Спас,\nІ хто хоче взяти - даремно бери,\nТо будеш і ти яскраво палати.\n\nПриспів:\nДо Христа, до Христа поспіши.\nПеред Спасом коліна схили.\nНі дарів, ні скарбів Він не жде.\nСину, серце дай нині своє.\n\nКуплет 2\nВ блуканнях моїх нещасних доріг чимало пройшов я. \nТа щастя не мав, коли пропадав далеко від Бога.\nТа ласка Царя, Ісуса Христа,\nВказала дорогу, щоб міг я прийти,\nСпасіння знайти у Бога Святого.\n\nКуплет 3\nСьогодні ще раз лунає для вас ця вістка чудова, \nБлаженство знайдеш, коли ти прийдеш до Бога Святого.\nТо ж, друже, спіши,\nСкоріше прийми Спасіння Христове.\nСьогодні прийди, одержиш і ти життя зовсім нове.', '', '', '', '', 'ua', 2, NULL),
(708, 'Вечірні тіні скрізь лягають', 0, 11, 'Куплет 1\nВечірні тіні скрізь лягають\nІ закривають світлу путь.\nНа серці сумно, я благаю: \n“Спасителю, зі мною будь!”\n\nКуплет 2\nМій шлях далекий, через гори, \nЗемні страждання мене ждуть.\nІ скажуть люди: "Люте горе! \nСпасителю, зі мною будь!”\n\nКуплет 3\nЗ Тобою я щасливий всюди,\nЗ Тобою завжди хочу йти.\nНа цій землі нещасні люди, - \n“О, Спасе, будь зі мною Ти!”\n\nКуплет 4\nВечірні тіні скрізь лягають \nТа вірю: світлі дні прийдуть!\nВ годину сліз Тебе благаю: \n“Спасителю, зі мною будь!”', '', '', '', '', 'ua', 0, NULL),
(709, 'Коли молюся я до Бога', 0, 11, 'Куплет 1\nКоли молюся я до Бога,\nМолитва тиха, як зоря,\nТо голосна, коли тривога, - \nГорить в мені і не згора.\n\nКуплет 2\nВона, як полум''я любові,\nХолодну душу зігріва,\nЗніма журбу, тамує болі,\nГріхом залишені бува.\n\nКуплет 3\nМоя молитва - то не відчай \nПеред сльозою самоти,\nВона мене у вічність кличе \nВід справ земних і суєти.\n\nКуплет 4\nКоли буваю я свавільний,\nЧи просто гордий у житті, - \nВона, молитва, неодмінно \nНе дасть зійти мені з путі.\n\nКуплет 5\nМоя молитва в час осінній,\nКоли на скронях сивина, \nЖива надія на спасіння - \nОдним-одна, одним-одна.\n\nКуплет 6\nНехай звучить вона недовго,\nВсього два слова, і не більш,\nТа все одно єднає з Богом,\nПриносить мир душі моїй.', '', '', '', '', 'ua', 0, NULL),
(710, 'Ти навчи мене мій Господь', 0, 11, 'Куплет 1\nТи навчи мене, мій Господь, у всім\nВолю виповнять лиш Твою,\nЩоб мені за Словом Твоїм довести,\nЩо Тебе я, Спаситель, люблю.\n\nПриспів:\nТи навчи мене серед тисячі\nГолос чути лиш Твій,\nТи навчи мене за Тобою йти \nВ край бажанний, дорогий.\n\nКуплет 2\nТи навчи мене в грішнім світі жить,\nЩоби світло сіяло в мені,\nБо як місто, що на горі стоїть,\nНе сховається навіть у тьмі.\n\nКуплет 3\nТи навчи мене так життя прожить,\nЩоб в кінці почути Його:\nДобрий, вірний раб, ти скоріш ввійди \nВ радість Пана твого.', '', '', '', '', 'ua', 5, NULL),
(711, 'Ти мене любиш Боже єдиний', 0, 11, 'Куплет 1\nТи мене любиш, Боже єдиний,\nТи мене любиш, - о яке диво!\nЧасто, як сина, ніжно голубиш,\nТи мене любиш, Ти мене любиш.\n\nПриспів:\nО, я щасливий, мить незбагненна,\nДуха Святого дав Ти для мене, \nШлях переможний в хащах туману, \nТо ж, Алілуя, вічна Осанна!\n\nКуплет 2\nМаю від Тебе істини слово,\nВ серці зоріє так світанково.\nЧига на душу світ непривітний,\nРадість даруєш в щирій молитві.\n\nКуплет 3\nЗнаю, нелегко буде до болю,\nАле невпинно я йду за Тобою.\nБачу Голгофу, серцем радію, - \nТи є Спаситель, - людства надія!', '', '', '', '', 'ua', 0, NULL),
(712, 'Мій Господь в молитві', 0, 11, 'Куплет 1\nМій Господь, в молитві до Тебе схиляюсь\nІ подяку серця до Тебе несу\nЗа любов, за шлях Твій, Боже, Тебе молю:\nОсвяти, очисти все життя моє!\n\nКуплет 2\nВірний мій Спаситель відкрив мої очі,\nЯ себе побачив у гріховній тьмі, - \nІ в сльозах гарячих впав до ніг пробитих,- \nІ в ту ніч, Ісус мій, я впізнав Тебе.\n\nКуплет 3\nНіжно Ти схилився, Боже, наді мною,\nТи спитав тихенько: “Любиш ти Мене?”\nНе з докором, але з ніжною любов’ю,\nТи тоді навіки врятував мене.\n\nКуплет 4\nВсю красу земную, марноту, невір’я \nПроміняв на щастя, яке дав Христос,\nВ цім житті нічого більш мені не треба,\nЯкщо Ти, Спаситель, все його візьмеш.', '', '', '', '', 'ua', 0, NULL),
(713, 'Не вічно буду я блукати', 0, 11, 'Куплет 1\nНе вічно буду я блукати в земній долині зла й гріха.\nЯ - мандрівник в земному краю, в оселі неба прагну я.\n\nКуплет 2\nТобі служити хочу, Боже, мене Ти дорого купив.\nТи - Цар і сильний мій Володар, я весь і вічно буду Твій!\n\nКуплет 3\nТвій мир святий - це насолода безрадній і сумній душі. \nДаруй утіху у час горя і світлий, радісний спокій.\n\nКуплет 4\nДаруй, щоб з вірністю я прагнув сповняти працю все Твою, \nЩоб Твоє світло не погасло в душі покірливій - молю!\n\nКуплет 5\nКоли немає вже натхнення, вогонь любві в молитві згас, \nХай кров Твоя, Твій хрест мучення натхне на подвиг знову нас!', '', '', '', '', 'ua', 0, NULL),
(714, 'Вічна Скеле дай мені', 0, 11, 'Куплет 1\nВічна Скеле, дай мені схоронитися в Тобі.\nКров з водою, що за нас з ран Твоїх святих лилась, \nХай буде ліком моїм, о, обмий мене з гріхів.\n\nКуплет 2\nНе ділами власних рук я спасусь від вічних мук.\nХоч би потом я заливсь, хоч би я в сльозах топивсь, \nВсе ніщо, усе марне, - Ти спасаєш Сам, Христе!\n\nКуплет 3\nЯ нічого не несу, - прямо під хрест Твій спішу.\nНагий я - Ти одягни і мене благослови.\nСпасе, я до Тебе йду, обмий мене, бо помру.\n\nКуплет 4\nПоки нині ще живу: прийде час і я помру,\nТа піду у вишній світ здати з діл моїх всіх звіт.\nНічна Скеле, дай мені схоронитися в Тобі!', '', '', '', '', 'ua', 0, NULL),
(715, 'Молись в день радості і щастя', 0, 11, 'Куплет 1\nМолись в день радості і щастя,\nВ турботах й боротьбі молись!\nМолись в загрозі від нещастя,\nКоли тривожишся - молись!\n\nКуплет 2\nМолись, коли ти кривду терпиш,\nУ небезпеці ти - молись!\nМолись, коли за милих просиш,\nЗа злого ворога молись!\n\nКуплет 3\nМолись, коли слабіють сили,\nКоли міцнішаєш - молись!\nМолись також біля могили,\nІ за народжених молись.\n\nКуплет 4\nМолись, коли прийде спокуса,\nЯк переміг себе - молись!\nМолись Спасителю Ісусу,\nЩоб Він простив тобі, молись.', '', '', '', '', 'ua', 0, NULL),
(716, 'Молись тоді коли ослабне віра', 0, 11, 'Куплет 1\nМолись тоді, коли ослабне віра,\nКоли в дорозі зовсім знемагаєш.\nЗнай, що у Бога ласки є без міри,\nІ знай, що Він про тебе пам’ятає.\nМолись в хвилину горя і недолі,\nКоли ти впав і важко тобі встати.\nКоли ти сам, мов та билина в полі,\nГосподь тобі бажає поміч дати.\n\nПриспів: \nМолись Йому так просто, як ти\tвмієш,\nІ Він почує всі твої благання,\nТвою журбу Він, мов туман, розвіє, \nЛише молись, молися без вагання!\n\nКуплет 2\nМолись, коли прийде найбільше горе,\nИ життя твоє, мов море, захвилює,\nКоли погасне сонце ясне й зорі,\nМолись тоді, і Бог тебе почує!\nМолись, молись, бо це одна дорога,\nЩоб спокій серцю втомленому мати.\nМолись Йому - розвіється тривога,\nІ серце буде в радості співати!', '', '', '', '', 'ua', 0, NULL),
(717, 'О Боже споглянь на страждання', 0, 11, 'Куплет 1\nО, Боже, споглянь на страждання \nНа світі нещасних людей!\nПочуй всі сердечні зітхання,\nЩо рвуться до Тебе з грудей.\n\nКуплет 2\nСпоглянь на тих сліз океани,\nЩо ллються невпинно з очей;\nХто може загоїть ті рани,\nВсім жертвам темряви ночей.\n\nКуплет 3\nО, визволи душі на волю,\nКайдани гріховні розбий!\nВ народах, мов в чистому полі,\nТи миру насіння посій.\n\nКуплет 4\nЗасяй, Боже, ясним промінням \nНад світом обдертим, сумним,\nЙ правицю Твойого спасіння \nПодай всім страждальцям земним.\n\nКуплет 5\nХай квітками вкриються ниви,\nДе кров та лиш сльози лились,  \nЩоб райські веснянії співи\nПо буйних ланах пронеслись.\n\nКуплет 6\nЩоб там, де гриміли гармати \nІ рвали обличчя землі,\nПрийшли вороги обніматись \nДля вічного братства й хвали.', '', '', '', '', 'ua', 0, NULL),
(718, 'Не в словах натхненних молитов', 0, 11, 'Куплет 1\nНе в словах натхненних молитов \nЯ блаженство для душі знайшов;\nВсе найкраще, що є тут в житті, - \nВічне джерело моє в Христі!\n\nКуплет 2\nНе в спокою щастя я зазнав,\nНе кутка я тихого бажав:\nНасолоду маю в боротьбі, - \nВічне джерело моє в Тобі!\n\nКуплет 3\nБачиш Ти, як завжди, в кожну мить \nДо Тебе любов в мені горить:\nНе шукав нічого я собі, - \nВічне джерело моє в Тобі!\n\nКуплет 4\nТи відкрив мені любов Свою;\nЧи щасливий буду я в раю?\nЗ радощів тремтить душа в мені, - \nВічне джерело моє в Тобі!\n\nКуплет 5\nТи для мене захист, Ти - мій щит,\nБез Христа-порожній цілий світ:\nЯ без Тебе вмер би у журбі,\nВічне джерело моє в Тобі!\n\nКуплет 6\nТут навколо хижий ворог мій \nТочить проти мене лютий бій;\nПеремогу Ти даєш мені, - \nВічне джерело моє в Тобі!\n\nКуплет 7\nПісля довгих нещасливих днів\nНа землі одне я зрозумів:\nЩастя вічне лиш в Твоїй красі!\nВ Бозі є джерела мої всі!', '', '', '', '', 'ua', 0, NULL),
(719, 'Всюди я з Ісусом', 0, 11, 'Куплет 1\nВсюди я з Ісусом без страху піду,\nВсюди, де веде Він, я Його буду.\nСкрізь мені без Нього радості нема,\nВсюди я з Ісусом без страху піду.\n\nПриспів:\nВсюди з Ним (2р.)\\ Я не пропаду;\nВсюди я з Ісусом без страху піду.\n\nКуплет 2\nВсюди я з Ісусом, слабість чи біда,\nУ спокусі Він надія є тверда.\nВін пройшов спокусу, і я з Ним пройду,\nВсюди я з Ісусом правду віднайду.\n\nКуплет 3\nВсюди я з Ісусом; я не є один,\nХоч мене всі лишать, - Він зі мною все.\nХоч мене веде Він крізь пусті стежки,\nВсюди є з Ісусом мені дім хвали.\n\nКуплет 4\nВсюди я з Ісусом - море чи земля, - \nНе боюсь нічого - в Нім спасенний я.\nЯ готовий йти, як скаже мені Він,\nВсюди, де піду я - провідник Він мій.\n\nКуплет 5\nВсюди я з Ісусом спокійно засну,\nЯк гріховні тіні мене обгорнуть;\nЗнаю я, що смутку мати не буду,\nБо я скрізь з Ісусом дім собі знайду.', '', '', '', '', 'ua', 0, NULL),
(720, 'Духом в біді не упадай', 0, 11, 'Куплет 1\nДухом в біді не упадай, - Бог поміч дасть тобі!\nВ Божій любві ти проживай, Бог поміч дасть тобі!\n\nПриспів:\nБог поміч дасть\tтобі,\nВсі дні твої, в житті твоїм.\nБог поміч дасть тобі (2р.).\n\nКуплет 2\nЯк серце заболить твоє, - Бог поміч дасть тобі!\nЯк прикре є життя твоє, - Бог поміч дасть тобі!\n\nКуплет 3\nУ всіх твоїх незлих ділах Бог поміч дасть тобі.\nВ щедрих твоїх благаннях всіх Бог поміч дасть тобі\n\nКуплет 4\nНа самоті, як горе є, Бог поміч дасть тобі!\nВ неволі чи в нещасті ти, - Бог поміч дасть тобі!', '', '', '', '', 'ua', 0, NULL),
(721, 'Моя надія у Христі', 0, 11, 'Куплет 1\nМоя надія у Христі,\nВ Його крові і чесноті;\nВся людська сила - марнота,\nЯ лиш надіюсь на Христа!\n\nПриспів:\nХристос є скелею людства,\nВесь інший грунт - трясовина!\nЄдина скеля Він моя!\n\nКуплет 2\nЙого посвята, Його кров,\nНа людськім морі мій покров;\nКоли все рветься у житті - \nДуша спасеться у Христі!\n\nКуплет 3\nЯких нас Спас тоді знайде,\nКоли востаннє в світ прийде?\nМоя одежа - чеснота,\nВ ній стану я перед Христа!', '', '', '', '', 'ua', 0, NULL),
(722, 'Якщо ти будуєш свій дім', 0, 11, 'Куплет 1\nЯкщо ти будуєш свій дім - будуй ти його на скалі.\nПоллються великії води - і дім устоїть твій тоді.\n\nПриспів:\nХристос є моя скала,\nХристос є моя мета,\nХристос є моє життя,\nЛиш в Нім все моє майбуття!\n\nКуплет 2\nХто Бога шукає завжди і Духа Святого прийняв,-\nОдержить небесний спокій, бо тверду основу він мав.\n\nКуплет 3\nI пісня хвали у тобі поллється тоді від душі,\nXвалити ти будеш Христа, бо в Ньому є радість твоя.', '', '', '', '', 'ua', 0, NULL),
(723, 'Ісус є мій притулок', 0, 11, 'Куплет 1\nІсус є мій притулок, Він мій є капітан.\nНе страшні з Ним страждання, на морі ураган.\nВітри мене не зрушать, вітри мене не зб’ють, - \nІсус є мій притулок (2р.), мене Він збереже!\n\nКуплет 2\nІсус мене провадить через земне життя - \nНемов на морі човен, що в хвилях залива.\nХитає моє судно, та гавань бачу я, - \nІсус мене провадить (2р.) до берега життя!\n\nКуплет 3\nІсус є мій приятель поміж всіма людьми -\n Найкращі має ліки на всі хвороби злі.\nІ смерть мені не страшна: мене Він береже.\nІсус є мій приятель (2р.) найкращий понад все!\n\nКуплет 4\nІсус всіх закликає, бо Він є капітан.\nБуть в Його війську хочеш? В ряди скоріше встань \nВін кличе нас до бою, спереду Сам іде.\nХристос ще тебе кличе (2р.), спіши, ще Він зове!', '', '', '', '', 'ua', 0, NULL),
(724, 'Господь є пастирем моїм', 0, 11, 'Куплет 1\nГосподь є пастирем моїм, Він дав мені життя,\nІ на зелені пасовиська провадить Він мене,\n\nКуплет 2\nВін підкріпляє душу мою, на тиху воду поведе. \nСтежками праведности веде ради Ймення Свого.\n\nКуплет 3\nКоли б долиною смерті йшов, - не побоюся зла.\nТвоя рука і посох Твій підтримують мене.\n\nКуплет 4\nТи приготував стіл мені при ворогах моїх \nІ намастив голову мою оливою.\n\nКуплет 5\nЛюбов Твоя і Твоє добро супроводять мене,\nПо всі дні мого життя хочу бути в Домі Твоїм.\nАлілуя, алілуя, алілуя, алілуя,\nАлілуя, алілуя, алілуя, амінь.', '', '', '', '', 'ua', 0, NULL),
(725, 'Скорбне серце не плач', 0, 11, 'Куплет 1\nСкорбне серце, не плач, не журися \nІ не падай в тяжкій боротьбі!\nТільки в тиші Ісусу молися, - \nВін почує, поможе тобі.\n\nПриспів:\nВ цьому світі нам тяжко і сумно,\nВіє вітер і хмари пливуть,\nТа згадай - нам боротись не довго, - \nВ небі радість і щастя нас ждуть.\n\nКуплет 2\nШлях твій чорнії хмари покрили \nІ любові вогонь погаса.\nПригадай же - і радість, і сила \nЄ для тебе в Ісуса Христа!\n\nКуплет 3\nНе забудь - твій Спаситель з тобою, \nНе покине ніколи тебе,\nІ в вітчизну небесну спокою \nВід страждання і сліз приведе!', '', '', '', '', 'ua', 0, NULL),
(726, 'Свої очі я зводжу на гори', 0, 11, 'Куплет 1\nСвої очі я зводжу на гори,\nЗвідки прийде мені допомога.\nМій Господь йтиме всюди зі мною,\nМоя поміч від Господа Бога.\n\nКуплет 2\nІ нічого не вдіють злі люди,\nБо мій Сторож не спить, не дрімає.\nІ коли упаду я в знемозі,\nТо Він поміч мені посилає.\n\nПриспів:\nСам Господь - моя тінь по правиці,\nСкрізь за мною слідять Його очі, \nСеред дня мене сонце не вдарить,\nАні місяць глибокої ночі.\n\nКуплет 3\nХоч і сонце зайде за горою,\nВін мене стерегтиме від злого,\nПроясниться моя путь дорога,\nМоя поміч від Господа Бога.\n\nКуплет 4\nІ нічого не вдіють злі люди,\nБо мене береже Бог Великий,\nВ мене вихід збережений буде\nІ мій вхід від тепер аж навіки.', '', '', '', '', 'ua', 0, NULL),
(727, 'В лузі ось косарі', 0, 11, 'Куплет 1\nВ лузі ось косарі розмахалися гострими косами.\nЩо їм Божі квітки? Їм закінчить би працю свою.\nЯ на милість Твою все ж надіюсь, Спасителю Господи\nНа милість, на милість, лиш тільки на милість Твою!\n\nКуплет 2\nЩира віра, Господь, - ось подруга моя завжди вірная, \nВіра в те, що Ти всім управляєш рукою Творця.\nІ я знаю, Господь, що завжди Ти за мене заступишся. \nТи мій Камінь Рятунку, тут спиниться гостра коса.\n\nКуплет 3\nБо ж інакше нащо Ти поїв мене дивними росами,\nІ нащо показав Ти любов та батьківське тепло?\nІ для чого наповнив мене чудо-піснями, Господи?\nНе для того ж, о ні, щоб потрапить під гостру косу.\n\nКуплет 4\nКосарі із лугів повернулися з гострими косами, \nСкільки впало трави, ну а я, як раніше стою, \nПереповнений знову небесними чистими росами \nПрославляю Тебе за любов і за милість Твою.', '', '', '', '', 'ua', 3, NULL),
(728, 'Я йду пустелею безплідною', 0, 11, 'Куплет 1\nЯ йду пустелею безплідною,\nМій шлях тернистий і вузький,\nБо близько вже до краю рідного,\nМене провадить Дух Святий.\n\nКуплет 2\nЯк сонце поза гори схилиться,\nОбіймуть землю тіні тьми,\nГустою млою все покриється, - \nОсвітить шлях мій Дух Святий.\n\nКуплет 3\nЯк вороги юрбою грізною \nМене оточать навкруги,\nІ смерть в лице дихне погрозою, - \nДасть перемогу Дух Святий.\n\nКуплет 4\nЯк на шляху до краю вишнього \nЯ стану рідним, як чужий,\nІ навіть друзі всі позраджують, -\nМене не зрадить Дух Святий.\n\nКуплет 5\nКоли ж усе, що в світі маю я,\nВідніме смерті помах злий,\nІ навіть з тілом розпрощаюся, - \nЗі мною буде Дух Святий.', '', '', '', '', 'ua', 0, NULL),
(729, 'Створив Бог небо', 30, 11, 'Куплет 1\nСтворив Бог небо, сонце, місяць, зорі \nІ нашу землю, все, що є на ній, \nПід небом птахів, дивну рибу в морі,\nСади прекрасні, квіти запашні.\n\nКуплет 2\nЗемля, земля, ти голос Божий чула \nІ дала все, що Бог тобі сказав.\nЗемля, земля, яка ти гарна була,\nКоли тебе Творець людині дав.\n\nКуплет 3\nВінцем творіння був Адам і Єва.\nБлагословив їх Бог і щастя дав,\nТа ворог людський вів лукаву мову,\nПривів до смерті, щастя геть забрав.\n\nКуплет 4\n“О, сину мій, - ридала перша мати, - \nЧому мовчиш, мій любий, дорогий? \nНещасна я виною смерті стала.\nО, Боже мій, прости мій гріх важкий!”\n\nКуплет 5\nСебе у жертву дав Христос Спаситель,\nЗа людський гріх Він кров Свою пролив.\nРозбив кайдани смерті Відкупитель,\nУсі гріхи Собою Він покрив.\n\nКуплет 6\nЗемля, земля, яка ти гарна будеш! \nОбновлена від терня й марноти.\nЗемля, земля, ти всіх спасенних приймеш. \nЧи будем там, мій друже, я і ти?\n\nКуплет 7\nНа цій землі обновленій я буду \nЗ Христом Ісусом вічно буду жить,\nДе сльози й горе назавжди забуду,\nТам вічні радість, щастя і спокій.\n\nКуплет 8\nТам також гарне й нове місто буде,\nНазва його - новий Єрусалим.\nУ ньому сонце світити не буде,\nБо вічним світлом є там Божий Син.\n\nКуплет 9\nЗемля, земля, яка ти гарна будеш!\nОбновлена від терня й марноти.\nЗемля, земля, ти всіх спасенних приймеш!\nТам буду я, там будеш, друже, ти!', '', '', '', '', 'ua', 0, NULL),
(730, 'Дивлюсь я в небесну блакить', 0, 11, 'Куплет 1\nДивлюсь я в небесну блакить,\nІ рідний свій край уявляю. \nДуша наче пташка летить \nВ простори жаданого Краю.\nТам квітне чарівна весна,\nТам радість безмірна панує,\nТам рідна моя сторона,\nІ серце за нею сумує.\n\nПриспів:\nКрізь бурі земного життя,\nЯк пташка, лечу я до Тебе.\nТам світле моє майбуття,\nТам радість знайду я для себе.\n\nКуплет 2\nНа груди Христові схилюсь,\nЗабуду страждання і горе,\nІ в хори небесні ввіллюсь,\nЯк річка вливається в море.\nА покищо тільки в думках \nЯ лину до рідного Краю \nІ з вірою в серці свій шлях \nПо вузькій стежині звершаю.\n\nКуплет 3\nТа скоро, я вірю, прийде,\nОта довгожданна хвилина,\nІ зірка досвітня зійде,\nЗустріну я Божого Сина.\nДай віри, Ісусе, мені - \nДля Тебе трудитись і жити.\nКоли мої скінчаться дні,\nЩоб зміг Тебе в небі зустріти.\n\nКуплет 4\nЯ знаю - настане той час,\nХвилина бажанної мрії.\nЗустрінуться там в небесах \nЗ Ісусом Христом усі вірні.\nТам пісню Мойсея й Христа \nСпасенні усі заспівають.\nТам радість буде без кінця,\nВсім серцем туди я бажаю.', '', '', '', '', 'ua', 0, NULL),
(731, 'В край далекий гуси полетіли', 0, 11, 'Куплет 1\nВ край далекий гуси полетіли \nПо блакитнім небі голубім.\nТа не всі їх птахи розуміли,\nЧому кидають вони свій дім.\n\nКуплет 2\nУ той край нелегка є дорога - \nВітер крила рве у небесах.\nВ серці заховалася тривога,\nА надія світиться в очах.\n\nКуплет 3\nЄ у нас той вічний Край Небесний. \nПереліт - то наше все життя.\nА надія - наш Ісус воскреслий,\nВін веде нас в вічне майбуття.\n\nКуплет 4\nВ край далекий гуси полетіли \nПо блакитнім небі голубім.\nДикі гуси приклад залишили,\nЩо і нам пора в свій рідний дім.', '', '', '', '', 'ua', 0, NULL),
(732, 'Як я бажаю до Тебе Боже', 0, 11, 'Куплет 1\nЯк я бажаю до Тебе, Боже,\nЯк я хотів би в небеса!\nТільки з Тобою усе переможу \nТільки з Тобою - у серці роса. (2р.)\n\nКуплет 2\nЖиття тривожне, важко буває,\nТисне на душу грішне буття.\nЛише у Тобі, твердо я знаю,\nМаю надію на радість життя. (2р.)\n\nКуплет 3\nБоже мій, Боже, щиро благаю:\nДай мені сили твердо іти.\nВсім поділюсь я, як я бажаю \nРадісно в вічні оселі ввійти. (2р.)\n\nКуплет 4\nПісню для Тебе, Боже, співаю,\nХочу співати й там в небесах!\nХай же ця пісня повік не стихає,\nХай вона буде завжди на устах! (2р.)', '', '', '', '', 'ua', 0, NULL),
(734, 'Чудова голубінь небес', 0, 11, 'Куплет 1\nЧудова голубінь небес - наша спільна завітна мрія, \nСкільки бачу в тобі чудес, мимоволі душа радіє.\n\nКуплет 2\nІ на крилах летить туди, де Спаситель мене чекає,\nДе нема страждань і біди, де Христос, наче сонце, сяє.\n\nПриспів:\nТам закінчиться шлях земний,\nТам спасіння знайду для себе.\nІ прошу, о, Спаситель мій,\nДай ввійти в те чудове небо.\n\nКуплет 3\nСлабну я, але далі йду, моя сила лиш тільки в Бозі.\nВ небі щастя своє знайду, але покищо я в дорозі.\n\nКуплет 4\nХоч страждання терплю не раз, зустрічаю життєві грози, \nАле вірю: настане час, і осушить Спаситель сльози.\n\nКуплет 5\nСинє небо, твоя блакить бідну душу мою леліє.\nІ до тебе вона летить, за тобою тужить, сумує.\n\nКуплет 6\nРозганяючи зло і страх, забуваючи всі турботи,\nУ гарячих своїх сльозах споглядаю в твої висоти.', '', '', '', '', 'ua', 0, NULL),
(735, 'Розлуки час настав', 0, 11, 'Куплет 1\nРозлуки час настав для нас,\nІ в час цього призначення \nМи кажем: “До побачення!\nПрощай, щасливо, до побачення!”\n\nКуплет 2\nСвоїх людей Господь веде \nЗавжди рукою сильною \nІ ласкою безмірною.\nПрощай, щасливо, до побачення!\n\nКуплет 3\nОсь чути клич, слова Христа:\n"Вже скоро, скоро Я прийду,\nДо неба вірних приведу!”\nПрощай, щасливо, до побачення!\n\nКуплет 4\nДруже, відкинь зневіри страх! \nЯкщо у цей нелегкий час \nМи бачимось останній раз - \nТоді побачення - на небесах!', '', '', '', '', 'ua', 0, NULL),
(736, 'Коли час розлуки близький', 0, 11, 'Куплет 1\nКоли час розлуки близький, важко розставатись нам.\nСам Господь дає нам сили і веде нас в небеса.\nДалеко ти чи близько, - наші серця б''ються в унісон. \nБожа ласка нас поріднить, коли ми будемо з Христом. Приспів:\n\nКуплет 2\nБoдрузі є назавжди, коли дружба та в Христі, \nБoдруг такий не зрадить, не відцурається в біді.\nІ коли нарешті прийде час прощання, то нехай \nСпас покаже нам Свій шлях, друзям навік.\n\nКуплет 3\nВipaта любов Господня, і надія в нас живе.\nІ молитва друга щира є важлива над усе.\nДалеко ти чи близько, наші серця б''ються в унісон. \nБожа ласка нас поріднить, коли ми будемо з Христом.', '', '', '', '', 'ua', 0, NULL),
(737, 'Так швидко лине', 0, 11, 'Куплет 1\nТак швидко лине невблаганний час,\nІ сумно, що розлуки час прийшов.\nГосподня милість поєднала нас,\nІ хочеться зустрітись з вами знов.\n\nПриспів:\nГосподь ще подарує зустріч нам,\nЯкщо не на землі, то в небесах, \nЗустрінемося біля ніг Христа,\nДе спокій, мир і радість у серцях.\n\nКуплет 2\nПодяка до небес нехай летить \nЗа зустріч, що Господь нам дарував,\nЗа те, що Він був з нами в кожну мить \nІ кожного із нас оберігав.\n\nКуплет 3\nЯк добре бути, друзі, нам разом,\nМолитися і славити Отця.\nЗа час оцей, проведений з Христом, \nПодяка переповнює серця.\n\nКуплет 4\nНехай Господь в житті нас проведе,\nВід зла й неправди в світі захистить\nІ в небо, в Отчий дім нехай введе,\nДе будемо з Ісусом вічно жить.', '', '', '', '', 'ua', 0, NULL),
(738, 'Ми співаємо пісню подяки', 0, 11, 'Куплет 1\nМи співаємо пісню подяки і бажаєм співати Тому, \nХто з''єднав нас всіх у єдину \nУ велику Христову родину.\n\nПриспів:\nА тепер до побачення,\nЯкщо Бог нам дозволить бачення. \nА як не на землі, то у небі в красі \nМи побачимось знову усі.\n\nКуплет 2\nМи підемо своїми шляхами,\nПам''ятати будемо цей час,\nЯк було дуже добре нам з вами,\nЯк раділи, співали для вас.', '', '', '', '', 'ua', 0, NULL),
(739, 'Приємні хвилини', 0, 11, 'Куплет 1\nПриємні хвилини так швидко минають,\nІ не повернути нам спільності знов.\nІ теплі прощання слова \nСказати прийшла вже пора,\nУ кожного буде дорога своя.\n\nПриспів:\nПрощання та розлуки невід''ємні є в житті, \nТа надія не згасає: будуть зустрічі нові.\n\nКуплет 2\nХай кожний із вас в похід далі крокує,\nВ любові Ісус захистить, збереже,\nЩоб з Ним було ваше життя\nІ доля Ісуса свята\nДо зустрічі знову колись привела.\n\nКуплет 3\nПриємні хвилини так швидко минають,\nІ не повернути нам спільності мить. \nЯкщо не зустрінемось тут,\nТо вірим: хвилини прийдуть- \nДо неба дороги усіх приведуть.', '', '', '', '', 'ua', 0, NULL),
(740, 'Творець Всесильний', 0, 11, 'Куплет 1\nТворець Всесильний, Боже святий, \nТебе величить світ цілий.\nПеред Тобою все тремтить,\nПохвальні пісні голосить.\n\nКуплет 2\nСонце і зорі, небо, земля,\nМоре і ріки, луг, трава- \nСлавить Тебе все, шле свій глас, \nВсе прославляє: Бог свят наш!\n\nКуплет 3\nВсе вихваляє, Боже, Тебе,\nАле говорить і мені,\nЩоб я сердечно Тебе любив,\nВолю Твою святу сповнив.\n\nКуплет 4\nСвіту Владико! Дай же мені \nВірно служити все Тобі,\nЩиро любить Тебе в житті, - \nДуже про це Тебе молю.', '', '', '', '', 'ua', 0, NULL),
(741, 'Хочу Я тебе провадить', 0, 11, 'Куплет 1\nХочу Я тебе провадить до прекрасної мети,\nВ час нелегкої години буду Я з тобою йти.\nА як станеш спотикатись і не зможеш далі йти, - \nЯ тебе, моя дитино, на руках буду нести. (2р.)\n\nПриспів:\nІ»о любов Моя велика, і немає їй кінця,\nНе відкинь її, Мій сину, - кров''ю вилилась вона.\nЯ люблю тебе, дитино, над усе, що в Мене є, \nХочу поруч біля Себе завжди бачити тебе.\n\nКуплет 2\nНе шукай у цьому світі ти скарбниці золоті,\nВо найбільший скарб у небі - жити з Богом усі дні. \nЙди до Мене, не вагайся, руку дай Мені свою,\nЯ прощу усі провини, знай жети любов Мою.(2р.)', '', '', '', '', 'ua', 0, NULL),
(742, 'Віддаймо хвалу', 0, 11, 'Куплет 1\nВіддаймо хвалу Ісусу Христу,\nСпіваймо Йому всі пісню нову!\nМогутній і вічний, і любить Він нас,\nУ велич зодягнений наш любий Спас.\n\nКуплет 2\nНе можна в словах любов описать,\nНе можна в піснях її оспівать;\nУ сонці, у хмарах вона і в дощі,\nУ темряві ночі, в ранковій зорі.\n\nКуплет 3\nГосподня любов безмежна, свята,\nГосподня любов у наших серцях;\nВона нам відкрила джерела добра,\nСпасіння і вічне життя нам дала.', '', '', '', '', 'ua', 0, NULL),
(743, 'Хвала Тобі наш Господь', 0, 11, 'Куплет 1\nХвала Тобі наш Господь, хвала, Тобі Бог Святий \nХвала за Ісуса, Сина Твойого.\n\nПриспів:\nТепер слабий скаже: "Сильний я",\nБідний скаже: "Я багач",\nЗавдячуючи тому, що Бог дав. Хвала!', '', '', '', '', 'ua', 0, NULL),
(744, 'Тебе я величаю', 0, 11, 'Куплет 1\nТебе я величаю, о Господь!\nБог Єдиний на небі і на землі! (2р.)\n\nПриспів:\nТи Один достойний всю славу прийнять,\nВоскреслий із мертвих Агнець Господній. \nНародам усім Ти дарував спасіння.\nІ тепер ми приносим славу Тобі.', '', '', '', '', 'ua', 0, NULL),
(745, 'Осанна', 0, 11, 'Куплет 1\nОсанна, осанна, осанна Тобі, Цар царів! (2р.)\n\nПриспів:\nМи підносим Тебе серцем повним хвали,\nДухом ми піднесем Тебе. Осанна Тобі, Цар царів!\n\nКуплет 2\nМи любим (Зр.) \nТебе, Цар царів! (2р.)\n\nКуплет 3\nМи славим (Зр.) \nТебе, Цар царів! (2р.).', '', '', '', '', 'ua', 0, NULL),
(746, 'Ангели в небі Господа славлять', 0, 11, 'Куплет 1\nАнгели в небі Господа славлять,\nСлаву достойную | Богу несуть. (2р.)\n\nПриспів:\nВічная слава! (Зр.) Слава Христу! (2р.)\nВічная слава! (Зр.) Слава Христу!\n\nКуплет 2\nХочеться з ангельським співом з''єднатися,\nВ хорі відкуплених, спасенних Господом \nІ серце Господу, Богу Єдиному,\nХристу Спасителю | славу несе. (2р.)\n\nКуплет 3\nТут в низині земній Церква все томиться,\nДух прагне до Христа, до Нареченого.\nО, гряди, Господи, бачиш Невіста жде.\nТобі Єдиному славу несе (2р.)\n\nКуплет 4\nАгнець прославлений, Царствений Божий Син, \nДивний Христос Господь в небі нас жде \nІ серце Господу, Богу Єдиному,\nХристу Спасителю | славу несе. (2р.)', '', '', '', '', 'ua', 6, NULL),
(747, 'Я величаю Царя царів', 0, 11, 'Куплет 1\nЯ величаю Царя царів і Пана над панами!\nТи - мій Господь, благий навік, хвала Тобі, хвала!\n\nПриспів:\nХвала Тобі (Зр.) Одному!\nХвала Тобі (Зр.) навік!\n\nКуплет 2\nЗа те, що Ти створив на землі, за сонце і за небо, \nЗа дощ, за вітер і за сніг - за все Тобі хвала!\n\nКуплет 3\nЗа Сина, що прийшов спасти і кров''ю відкупити.\nЗа хрест, Голгофу і за смерть - за все Тобі хвала!\n\nКуплет 4\nЗа те, що ми спасенні є, за милість і за спокій, \nНадію, віру і любов - за все Тобі хвала!', '', '', '', '', 'ua', 0, NULL),
(748, 'О хвала Ісусу Христу', 0, 11, 'Куплет 1\nО, хвала Ісусу Христу, що у світі цім я живу \nІ надію маю святу. О, хвала Ісусу Христу!\n\nПриспів:\nРадість ніколи не мине,\nКоли наш Спаситель прийде,\nГоре і нещастя пройде.\nО, як там чудово буде!\n\nКуплет 2\nМи спасенні кров''ю Христа, Він за нас віддав Своє життя. \nЗаспіваймо пісню Йому радісну, щасливу й живу!', '', '', '', '', 'ua', 0, NULL),
(749, 'Буду зорю я будити', 0, 11, 'Куплет 1\nБуду зорю я будити співом чудесним хвали, - \nЦе жертва - плід уст моїх, жертва, яку приношу. \nСерце моє так зміцнилось, хочу співати Тобі,\nБо дуже велике Твоє милосердя до нас.\n\nПриспів: \nСлавлю я Тебе - слава на віки і віки,\nСлавлю я Тебе - слава Тобі Господь! \nСлавлю я Тебе - слава на віки і віки, Славлю я Тебе!\n\nКуплет 2\nХочу я бути з Тобою, славити Ім''я святе,\nЩоб завжди радіти і серцем прийняти Тебе.\nЧасу залишилось мало, скоро Ти прийдеш до нас.\nЯ буду співати, Тебе прославляти, мій Спас!', '', '', '', '', 'ua', 0, NULL),
(750, 'Алілуя алілуя ти наш Бог', 0, 11, 'Куплет 1\nАлілуя, алілуя, ти наш Бог! (2р.)\nВ благодаті Ти великий, в милосерді дивний Ти. \nАлілуя, алілуя, ти наш Бог!\n\nКуплет 2\nАлілуя, алілуя, наш Отець! (2р.)\nТи піклуєшся про всіх, не залишиш нас повік. \nАлілуя, алілуя, наш Отець!\n\nКуплет 3\nАлілуя, алілуя, (мій) Ісус! (2р.)\nТвої муки на хресті дали прощення мені.\nАлілуя, алілуя, (мій) Ісус!\n\nКуплет 4\nАлілуя, алілуя, Дух Святий! (2р.)\nЖиття й силу Ти даєш, всіх до неба нас ведеш. \nАлілуя, алілуя, Дух Святий!', '', '', '', '', 'ua', 4, NULL),
(751, 'Господи Тебе я хочу славить', 0, 11, 'Куплет 1\nГосподи, Тебе я хочу славить і Тобі подяку приносить. \nТільки Ти - одна моя надія, - хочу я Тобі служить.\n\nПриспів:\nТобі співаю Алілуя! Тобі співаю Одному.\nЗа те, що Ти страждав невинно,\nТворець мій, я Тебе люблю.\n\nКуплет 2\nІ коли в дорозі знемагаю, бачу руку помочі Твою.\nІ тоді в молитві я схиляюсь, і за все я дякую.\n\nКуплет 3\nГосподи, відкрийся, хто не знає, як Ти милостивий є до всіх,\nЩо завжди в одну мить Ти прощаєш і даруєш в серці мир.', '', '', '', '', 'ua', 0, NULL),
(753, 'Хай всіх веде Книга Біблія', 0, 11, 'Куплет 1\nХай всіх веде Книга Біблія,\nХай ця супутниця вічная \nСкрізь і повсюди буде, скрізь буде.\nХай Книга ця всім нагадує,\nХай всім нещасним життя дає.\nВ ній кожен щастя знайде.\n\nПриспів:\nНехай ця Книга наставляє,\nЯк жити людям на землі,\nНехай в любові порадує\nІ в небеса всіх веде.\n\nКуплет 2\nХай ці глаголи чудеснії,\nЯ к відголоски небеснії,\nВ смутку, недолі земній, земній,\nХай в ваше серце вливаються,\nІ небеса проявляються \nЗавжди у вашій душі.\n\nКуплет 3\nВ Ній всі ознаки збуваються,\nВ Ній дар життя здобувається,\nСерцю відрада й душі, душі.\nВ Ній всі народи єднаються,\nЗ Нею слабі утішаються,\nЩастя знаходять в житті.', '', '', '', '', 'ua', 0, NULL),
(754, 'Євангеліє', 0, 11, 'Приспів:\nЄвангеліє. Тоді\tбери цю книгу\tв руки.\nЄвангеліє. В словах діяльних та живих. \nЄвангеліє. Знайдеш розраду від розпуки. \nЄвангеліє. Спасіння ти знайдеш у них.\n\nКуплет 1\nКоли надія в тобі згасне або охопить суєта,\nКоли прийдуть випробування, і за бідою йде біда.\n\nКуплет 2\nВ цій книзі голос відізветься, і заговорить Дух Святий. \nВін над тобою пронесеться: страждай, терпи, люби, живи!\n\nКуплет 3\nТой голос ніжний і ласкавий на душу діє як бальзам. \nСкоріш відкрий для Нього серце, Ісус знайде оселю там.', '', '', '', '', 'ua', 0, NULL),
(755, 'Дитя нам Вічний Бог послав', 0, 11, 'Куплет 1\nДитя нам Вічний Бог послав, Син народивсь Його! \nМогутню владу Бог поклав на рамена Його. (2р.)\n\nКуплет 2\nЧудовий, Сильний, Бог-Творець назве Його весь світ, \nПорадник, Вічності Отець, Князь миру з роду в рід. (2р.)\n\nКуплет 3\nВін Царство вічне встановив і мир приніс у світ,\nНавіки правдою зміцнив Престол і Заповіт. (2р.)', '', '', '', '', 'ua', 0, NULL),
(756, 'Темнесенька нічка', 0, 11, 'Куплет 1\nТемнесенька нічка тьмою світ покрила.\nНа небеснім полі (2р.) зоря засвітила.\n\nКуплет 2\nЛиш одна зіронька понад все сіяє\nІ над Вифлеємом (2р.) проміння зливає.\n\nКуплет 3\nВчули вівчароньки той голос із неба,\nЗібрались на раду, (2р.) куди іти треба.\n\nКуплет 4\nЙшли вони стежкою, тою дорогою,\nТам, де ясність стала (2р.) під тою зорею.\n\nКуплет 5\nI ми підем з ними, поклін Христу даймо \nТа радісну пісню (2р.) разом заспіваймо.\n\nКуплет 6\nНині в Вифлеємі людям Спас родився. \nВеселімся, люди (2р.), Сам Бог воплотився.', '', '', '', '', 'ua', 0, NULL),
(757, 'Всесильний Царю світу', 0, 11, 'Куплет 1\nВсесильний Царю світу, Ти ясла вибрав Сам,\n1, згідно з Заповітом, лежав на сіні там.\nРелігії служитель, я людям говорив,\nЩо в яслах був Спаситель, а сам в гріхах ще жив.\n\nКуплет 2\nТа Ти й мені з’явився, і дух мій запалав,\nІ я в Тобі родився, й Твоїм дитям я став. \nЩаслива це хвилина, як в серце Ти ввійшов,\nІ, як мала Дитина, Ти ясла там знайшов.\n\nКуплет 3\nРости ж, свята Дитино, в моєму серці Ти,\nЩоб я також невпинно для Тебе міг рости.\nЩоб “я” моє маліло, а Ти в мені зростав,\nЙ життя як скінчить тіло, я б в небі жити став.', '', '', '', '', 'ua', 0, NULL),
(758, 'Радійте люди Спас прийшов', 0, 11, 'Куплет 1\nРадійте, люди, Спас прийшов! Приніс Свою любов!\nПрийміть в серця дар від Отця,\nБо Він приніс життя й гріхів всіх забуття,\nЙ гріхів, гріхів всіх забуття.\n\nКуплет 2\nРадійте, люди, в честь Христа! Бринить хай пісня та!\nНехай наш спів до гір, лісів\nУ світі долетить в оцю блаженну мить,\nВ оцю, оцю блаженну мить!\n\nКуплет 3\nХай щезне смуток і журба, й утихне боротьба!\nРадійте всі, - ви, що в грісі!\nСпасіння бо й для вас приніс на землю Спас, \nПриніс, приніс на землю Спас!\n\nКуплет 3\nНароди всіх країн землі, що в темряві, в імлі! \nСпас кличе всіх до Його ніг!\nЗнайдете всі ви знов святу Його любов;\nСвяту, святу Його любов!', '', '', '', '', 'ua', 0, NULL),
(759, 'Вночі з вітанням', 0, 11, 'Куплет 1\nВночі з вітанням Ангел появивсь:\n“Пастирі, встаньте, Спас вам народивсь;\nТож тепер часу не гайте,\nВ Вифлеєм всі поспішайте Богу на поклін!”\n\nКуплет 2\nПрийшли та бачать: в яслах Немовля,\nЯк Ангел Божий з неба промовляв;\nПеред Ним вони смирились,\nЙому щиро поклонились в радості сердець.\n\nКуплет 3\n“Ласкавий Спасе, бажаний здавен,\nУ кожнім часі будь благословен!\nБо Тебе царі й пророки\nТак чекали довгі роки; Ти ж нам об’явивсь!”', '', '', '', '', 'ua', 0, NULL),
(760, 'У Вифлеємі нині новина', 0, 11, 'Куплет 1\nУ Вифлеємі нині новина:\nПречиста Діва вродила Сина.\nВ яслах на сіні Його поклала,\nПісню тихенько Йому співала.\n\nКуплет 2\nПастухам ангел вістку звіщає:\n“Радість і спокій Бог посилає;\nДо Вифлеєму всі поспішайте,\nВ бідній Дитині - Спаса вітайте!’\n\nКуплет 3\nТам херувими з неба злітають,\nАнгельські хори Спаса вітають,\nПастух убогий несе, що може,\nЩоб привітати Дитятко Боже.\n\nКуплет 4\nА за зорею далеко, зі Сходу\nЙдуть мудреці зчужого народу\nЗолото щире, ладан та миро, \nНесуть дарунки та серця віру.\n\nКуплет 5\nЛюбий наш Спасе! Ми не багаті, \nДарів коштовних не можем дати,\nТо ж в подарунок несем від себе \nВіру та щиру любов до Тебе!', '', '', '', '', 'ua', 0, NULL),
(761, 'Господь Бог предвічний', 0, 11, 'Куплет 1\nГосподь Бог предвічний нині нам родився, \nЗ непорочной Діви в яслах народився.\nХори ангельські співають, народженого вітають.\n\nПриспів:\nСлава! (2р.) Слава во вишніх Богу!\n\nКуплет 2\nПастирям у полі ангел ся являє,\nТам їх до стаєнки мило запрошає,\nЩоб Дитятку честь віддали і весело заспівали.\n\nКуплет 3\nІз небесним хором всі днесь веселімся \nІ Христу-Дитятку низько поклонімся.\nВ Нім надію покладаймо і весело заспіваймо.', '', '', '', '', 'ua', 0, NULL),
(762, 'В Вифлеємі днесь Марія', 0, 11, 'Куплет 1\nВ Вифлеємі днесь Марія пречиста \nПородила у стаєнці нам Христа.\n\nПриспів:\nСлава во вишніх Богу (2р.) і мир всім на землі! (2р.)\n\nКуплет 2\nАнгел з неба пастирям ся являє \nІ радісну цю новину звіщає.\n\nКуплет 3\nПрибігають до стаєнки пастирі \nТа вклоняються Ісусу в покорі.\n\nКуплет 4\nА за зіркою зі Сходу йдуть царі:\nТри преславні, прерозумні звіздарі.\n\nКуплет 5\nТам в смиренні Йому поклін віддали,\nПред Ним злато, ливан, миро поклали.\n\nКуплет 6\nМи також Христу поклін свій віддаймо \nІ разом з небесним хором співаймо.', '', '', '', '', 'ua', 0, NULL),
(763, 'Воскреслому служу я', 0, 11, 'Куплет 1\nВоскреслому служу я, Він з нами в кожен час. \nСвою любов дарує, Він відродив всіх нас.\nЙого я бачу руку і голос чую теж.\nПролив Він кров і любов явив без меж.\n\nПриспів:\nЖивий, живий! Христос повік живий!\nЗі мною йде вперед, веде, дарує свій спокій.\nЖивий, живий! Спасіння Він звершив!\nЧи знаєш ти, де Він живе? Живе Він і в мені!\n\nКуплет 2\nНавколо себе бачу Господню доброту.\nКоли туга, то плачу і розкажу Христу.\nКрізь бурі і сумніви веде в Небесний Дім.\nА в славний час кожен з нас там буде з Ним.\n\nКуплет 3\nРадійте, християни, свій голос піднесіть!\nВеселими псалмами ви Бога всі хваліть! \nСтраждаючим надія, опора для слабих - \nХоронить нас кожен час Христос Господь.', '', '', '', '', 'ua', 0, NULL),
(764, 'Бачу ранком небо молодіє', 0, 11, 'Куплет 1\nБачу, ранком небо молодіє,\nПовстає так світло навкруги,\nІ душа моя не спить, радіє,\nДо його воліє берегів.\n\nКуплет 2\nНині і так легко, як ніколи,\nНе гнітить більш темрява густа.\nЯ прийшов у цій порі ранковій \nДо свого Спасителя Христа.\n\nКуплет 3\nТож відкрию серце для любові \nІ бентежну душу для добра,\nЩоб не знала ні журби, ні болю,\nІ ясніла вічно, як зоря.\n\nКуплет 4\nХоч була неблизька та дорога,\nТа збагнув я у важкій ході:\nЯкщо зараз не прийду до Нього - \nПізно буде каятись тоді!', '', '', '', '', 'ua', 0, NULL),
(765, 'Радійте ви завжди', 0, 11, 'Куплет 1\nРадійте ви завжди, бо така воля Божа є (Зр.)\nЩодо вас в Ісусі Христі!\n\nКуплет 2\nМоліться ви завжди, бо така воля Божа є (Зр.) \nЩодо вас в Ісусі Христі!\n\nКуплет 3\nДякуйте за все, бо така воля Божа є (Зр.)\nЩодо вас в Ісусі Христі!\n\nКуплет 4\nДуха не вгашайте, бо така воля Божа є (Зр.) \nЩодо вас в Ісусі Христі!\n\nКуплет 5\nКоли ти приймеш Христа (2р.)\nОчистить серце твоє Він від гріха (2р.)\n\nКуплет 6\nІ як ти прийдеш до Спаса твого,\nВін гріх твій забере \nЧерез віру в Ісуса Христа,\nВін тебе до Себе прийме (2р.)', '', '', '', '', 'ua', 0, NULL),
(766, 'Коли в житті негоди', 0, 11, 'Куплет 1\nКоли в житті негоди чи радісне життя,\nЧи вдома, чи в дорозі співаю пісню я.\n\nКуплет 2\nВона іде зі мною, ця пісня неземна,\nМаленькі з нею гори, і ями - рівнина.\n\nКуплет 3\nМелодія любові і пісня про Христа \nВедуть мене до неба, в щасливе майбуття.\n\nКуплет 4\nЗакінчиться надія, і віра теж пройде,\nМелодія любові ніколи не мине.\nМелодія любові і в небі не мине.', '', '', '', '', 'ua', 0, NULL),
(767, 'Ми вдячні Богу що знову разом', 0, 11, 'Куплет 1\nМи вдячні Богу, що знову разом \nВ сердець єднанні звучать слова:\n\nКуплет 2\nХто любить Господа (2р.),\nРазом співайте - пісня одна.\n\nКуплет 3\nКолись ми з вами були чужими,\nТепер ми стали Його дітьми.\n\nКуплет 4\nХто любить Господа (2р.),\nВ білих одежах стрінемось ми.\n\nКуплет 5\nНас потішає Господнє Слово,\nIcyс сказав, що знов прийде.\n\nКуплет 6\nХто любить Господа (2р.),\nТого Христос у небо візьме.\n\nКуплет 7\nТам на Голгофі помер Ісус наш,\nЗвільнив Він смертю нас від гріха.\n\nКуплет 8\nХто любить Господа (2р.),\nТой нехай завжди славить Христа.', '', '', '', '', 'ua', 0, NULL),
(768, 'Радій радій спасенний', 0, 11, 'Куплет 1\nРадій, радій, спасенний!\nХай буде завжди радістю тобі \nЛаскавий твій Спаситель,\nЩо за твої гріхи вмер на хресті.\n\nПриспів:\nРадій, (радій) спасенний!\nСпівай (співай) про те,\nЩо твій Христос Спаситель \nНавіки спас тебе!\n\nКуплет 2\nРадій, радій, спасенний!\nТи є безпечним під крилом Його!\nВесь світ не є у силі \nЗабрати щастя вічного твого!\n\nКуплет 3\nРадій, радій, спасенний!\nНа небесах дім вічний тебе жде!\nІ при великій славі \nСпаситель твій тебе туди введе!\n\nКуплет 4\nРадій, радій, спасенний!\nСпіши ввійти у зібрання святих!\nІ Богу за спасіння\nХай пісня слави ллється з уст твоїх!', '', '', '', '', 'ua', 0, NULL),
(769, 'Боже Вічний Всемогутній', 0, 11, 'Куплет 1\nБоже Вічний, Всемогутній, Всесвіт у Твоїх руках; \nСвітом нашим Ти керуєш і зірками в небесах.\n\nПриспів:\nНам незнаний рік майбутній,\nАле все - в руках Твоїх;\nПоможи нам, Всемогутній,\nЖить з Тобою в кожну мить.\n\nКуплет 2\nТисячі років у Тебе - мов та мить, мов день один. \nТи - Володар землі й неба, вічності, років, годин.\n\nКуплет 3\nНаші дні перед Тобою - наче спалахи зірниць. \nДай, щоб вірою святою всі для Тебе їх прожить.\n\nКуплет 4\nРік цей, Боже, перед нами, але що він принесе? \nТож, Твоїми хай слідами нас рука Твоя веде!', '', '', '', '', 'ua', 0, NULL),
(770, 'Сьогодні рік минає', 0, 11, 'Куплет 1\nСьогодні рік минає, ось настає новий,\nТа завжди пробуває тут з нами Бог Святий.\nВін рік увесь минулий усім допомагав,\nБудив серця заснулі, безсилим силу дав.\n\nКуплет 2\nВсе на землі минає: і слава і краса,\nЩо швидко так зникають, мов ранішня роса.\nА небо відкриває лише любов Христа,\nНа нові дні з’єднаєм ми наше з Ним життя.\n\nКуплет 3\nВізьми ж нас, милий Боже, веди в майбутніх днях.\nЗ Тобою переможем спокуси, гріх і страх.\nТвою пошли нам силу, щоб плід ми принесли,\nДні наші рахували і мудро тут жили.', '', '', '', '', 'ua', 0, NULL),
(771, 'Хвала Христу за рік минулий', 0, 11, 'Куплет 1\nХвала Христу за рік минулий,\nЩо в цім житті серед біди\nНераз душею ми відчули \nЙoro присутності сліди.\n\nПриспів:\n3 Новим роком (2р.) ми вітаєм друзі вас!\nВ Новім році (2р.) хай Господь провадить вас!\n\nКуплет 2\nНеначе сон, мов дим пролинув,\nНавіки розпрощавшись, рік,\nТа знову час не знає спину - \nСтупає новий на поріг.\n\nКуплет 3\nЗа роком рік життя минає, \nВідходять дні у забуття. \nХристос спасти тебе бажає, - \nВіддай Йому своє життя!', '', '', '', '', 'ua', 0, NULL),
(772, 'Сталось чудо із чудес', 0, 11, 'Куплет 1\nСталось чудо із чудес: наш Господь Ісус воскрес! \nРадощам нема кінця, щастям сповнені серця.\nМуки Божий Син терпів, кров святу за нас пролив, \nЩастя сяє нам з небес, бо Спаситель наш воскрес!\n\nКуплет 2\nГріб сторожа стерегла, та безсилою була-\nНаш Христос із мертвих встав, перемогу вірним дав!\nСмерть і пекло подолав, нам надію дарував.\nВін пішов у край небес, повний слави і чудес!\n\nКуплет 3\nМи повірили в Христа - і воскресли для життя!\nТож за Ним услід ходім, Він веде нас в вічний дім! \nБраття й сестри, всі хваліть Спаса в цю чудову мить! \nДень почався, ніч пройшла, Спас воскрес! Йому хвала!', '', '', '', '', 'ua', 0, NULL),
(773, 'Настав день воскресіння', 0, 11, 'Куплет 1\nНастав день воскресіння, це свідчить вся земля; \nНадія на спасіння посіяна в серцях.\nТо Пасхи день Господній чудовий нам настав: \nСпаситель наш сьогодні у славі з мертвих встав!\n\nКуплет 2\nХристос обмив нас кров’ю, щоб ми за Ним ішли \nІ, сповнені любов’ю, для Нього лиш жили.\nЙого слова ласкаві ми чуємо в серцях;\nХристос, воскреслий в славі, розвіяв смерті страх.\n\nКуплет 3\nХай небеса радіють, і з ними люди всі:\nХристос воскрес! - співають в гармонії краси. \nНехай хвала з’єднає усіх в акорд новий,\nХай пісню все співає: Спаситель наш живий!', '', '', '', '', 'ua', 0, NULL),
(774, 'Сьогодні день радості й щастя', 0, 11, 'Куплет 1\nСьогодні день радості й щастя \nДля вірних Господніх дітей:\nСьогодні Христовою властю \nСпасіння прийшло для людей.\n\nКуплет 2\nВ цей день Бог кайдани неволі \nЗдійняв з наших спутаних ніг,\nІ випустив душі на волю,\nІ смертю Він смерть переміг.\n\nКуплет 3\nВ цей день не ходіть на могили, \nБoтам вже Ісуса нема!\nТам ангели двері відкрили,\nІ світлом вже сяє тюрма.\n\nКуплет 4\nВ цей день хай прокинуться люди,\nХай станеться чудо з чудес:\nХай в кожному думка ця буде:\n“Віднині і я вже воскрес!”', '', '', '', '', 'ua', 0, NULL),
(775, 'Христос воскрес Радіє все', 0, 11, 'Куплет 1\nХристос воскрес! Радіє все в природі!\nСвоїм промінням сонце шле з небес\nНа землю радість, і серцям народів \nТеплом своїм звіщає: "Він воскрес!"\n\nКуплет 2\n"Христос воскрес!" - свідчить трава зелена, \nХоч ще мала, - все ж лине до небес \nВіддати честь Творцю неоціненну \nЗа те, що Божий Син Христос воскрес!\n\nКуплет 3\nХристос воскрес! Воскреслого вітає \nТворіння все, Йому даючи честь.\nМаленька пташка радісно співає\nЧудову пісеньку: "Христос воскрес!"\n\nКуплет 4\nХристос воскрес! Я хочу теж співати \nТу дивну пісню Господеві днесь,\nЙого Ім''я достойно величати \nЗа те, що мій Господь Христос воскрес!\n\nКуплет 5\nХристос воскрес! О люде, не вагайся!\nГpiхам своїм ти поклади кінець! \nЗ народом Божим назавжди з''єднайся\nІ разом з ним скажи: "Христос воскрес!"', '', '', '', '', 'ua', 0, NULL),
(776, 'Вся земля так довго', 30, 11, 'Куплет 1\nВся земля так довго на цей день чекала,\nКоли злине з неба теплий чистий дощ,\nКоли сонце правди розжене всі хмари,\nКоли пісню щастя заспіває хтось.\n\nКуплет 2\nІ цей день нарешті до нас увірвався,\nВін приніс нам віру в світле майбуття.\nЧерез Свого Сина Всемогутній Батько \nНам дарує ріки вічного життя.\n\nПриспів:\nІсусу слава! (2р.)\nЛунає пісня над схилами Дніпра.\nІсусу слава! (2р.) \nСпіває вільна Україна.\n\nКуплет 3\nЛюди України, підіймайте руки,\nПрославляйте Сина, Він - Єдиний Бог.\nВін Своєю кров''ю розірвав кайдани,\nВій достойний слави, наш Ісус Христос.', '', '', '', '', 'ua', 3, NULL),
(777, 'Одного ранку', 0, 11, 'Куплет 1\nОдного ранку, ще до світанку \nЖінки до гробу разом прийшли,\nТа гріб порожній, так, як сказав Він,\nНа третій день Він смерть переміг.\n\nПриспів:\nЯк не воскрес\tби Ісус Спаситель,\nТо де ж надія була б моя?\nСмерть подолав Він, воскрес із мертвих\nІ життя вічне нам дарував!\n\nКуплет 2\nЖиву надію Христос подав нам,\nТаку надію хто міг би дать?\nНа третій день Він воскрес із мертвих, \nКайдани смерті Він розірвав!\n\nКуплет 3\nВін обіцяв нам, що скоро прийде \nЗабрати нас до осель Своїх.\nЯк річку смерті ми перейдемо, - \nНа березі нас чекає Він.', '', '', '', '', 'ua', 0, NULL),
(778, 'Ісус мій є живий', 0, 11, 'Куплет 1\nІсус мій є живий. (Зр.) Мій Ісус навіки живий!\nІз мертвих Він воскрес, (Зр.) Мій Ісус із мертвих воскрес! \nВін дав мені життя.(Зр.) Мій Ісус мені дав життя!\nВін серце дав нове. (Зр.) Він мені дав серце нове! \nІсусу вірю я. (Зр.) Так, в Ісуса вірую я!\nЖивий, живий, живий! (Зр.) Мій Ісус навіки живий!', '', '', '', '', 'ua', 0, NULL),
(779, 'Він воскрес щоб весь світ', 0, 11, 'Куплет 1\nВін воскрес, щоб весь світ оживити.\nВін воскрес, щоб ми з вами жили,\nЩоб покірні словам Його діти \nВ Ньому вічне життя досягли.\n\nКуплет 2\nВін воскрес, щоб гріховне коріння \nСпопелити в тобі назавжди,\nЩоб зросло у серцях те насіння,\nЩо приносить лиш добрі плоди.\n\nПриспів:\nВоскресіння Христа - радість вічна, свята\nНа землі для людей і на небі.\nВоскресіння Христа - то спасіння людства,\nБог любові дарує для тебе.\n\nКуплет 3\nВін воскрес, щоб як поле пшеничне,\nБула вибрана Церква Його,\nВін воскрес, щоб життя дати вічне \nВ небесах для насліддя Свого.\n\nКуплет 4\nВін воскрес і вознісся на небо,\nЩоб нас всіх живить Духом Святим.\nВін зробив це для тебе і мене,\nТож подумаєм, друзі, над тим.', '', '', '', '', 'ua', 1, NULL),
(780, 'Христос воскрес Веселий день', 0, 11, 'Куплет 1\nХристос воскрес! Веселий день,\nСпіває люд, радіє світ.\nНесеться гомін від пісень \nВ широкий світ під небозвід.\n\nКуплет 2\nХристос воскрес! З сердець усіх \nПливе привіт сердечних слів.\nНа лицях всіх блиск щастя втіх,\nНа всіх устах веселий спів.\n\nКуплет 3\nХристос воскрес! Душе радій.\nСкінчився сон і ніч гріха.\nВже з сонця йде проміння рій,\nВіщує день новий життя.', '', '', '', '', 'ua', 0, NULL),
(781, 'Слухай слухай радісну новину', 0, 11, 'Куплет 1\nСлухай, слухай радісну новину,\nВся земля співає днесь!\nНині сталося велике диво:\t(2р.)\nЗ мертвих наш Христос воскрес!\n\nКуплет 2\nЛишень тільки стало розсвітати,\nВже Марія до гробу прийшла,\nАле тіла Господа Ісуса \nВона в ньому не знайшла.  (2р)\n\nКуплет 3\nТихо стала плакати Марія \nТам у Иосифа в саду,\nВ серці тільки думи-мрії:  \n"Де ж Ісуса я знайду?"  (2р)\n\nКуплет 4\nОсь з''явився ангел з неба \nІ сказав їй дивні слова:\n"Чи живий між мертвими буває?  (2р)\nВін воскрес! Йому хвала!"', '', '', '', '', 'ua', 0, NULL),
(782, 'Вийшла донька ваша заміж', 0, 11, 'Куплет 1\nВийшла донька ваша заміж - буде господиня!\nОй, не плачте, не журіться, - друг в неї надійний.\n\nКуплет 2\nБуде він допомагати, буде поважати,\nТа ніколи він не буде жінку ображати.\n\nКуплет 3\nЗавжди будьте в згоді з Богом, живіть у любові,\nТа не забувайте тільки, що треба служити Богу.\n\nКуплет 4\nЧому ж ти почервоніла на своїм весіллі? \nНіжна, люба й така мила, молода, вродлива!\n\nКуплет 5\nМила, знай, - літа минають, і краса зів’яне.\nАле якщо Бог буде з вами - щастя не обмане!', '', '', '', '', 'ua', 0, NULL),
(783, 'Бажаєм тепер сказати для вас', 0, 11, 'Куплет 1\nБажаєм тепер сказати для вас ми щиро усі:\nВітаємо вас, вітаємо вас із шлюбом святим!\n\nКуплет 2\nБажаєм тепер сказати для вас: живіть у любві.\nСвяте ваше “так” хай буде для вас навіки міцним!\n\nКуплет 3\nОдне бажання для вас ми маєм, одне бажання, лиш одне: \nХай Бог в житті вам помагає, старання й мудрість подає!\n\nКуплет 4\nІ чим життя вас тут не зустріне: снігами, вітром чи теплом, \nВи збережіть до смерті віру, святу надію і любов!', '', '', '', '', 'ua', 0, NULL),
(784, 'На весільне свято запросили нас', 0, 11, 'Куплет 1\nНа весільне свято запросили нас \nІ гостей багато бачимо в цей час.\nВірим, що присутній тут Творець і Бог,\nБачить Він присутніх, бачить Він вас вдвох.\n\nПриспів:\nїх благаєм, Боже, благослови,\nДай, щоб жили свято, в згоді, в любві.\nДай, щоб виповняли Твої слова і любили Христа.\n\nКуплет 2\nРозкажіть їм, друзі, приклади з життя, \nПоділіться щиро досвідом в цей час.\nЩоб помилок ваших не зробити їм,\nА щоб утішались Господом одним.\n\nКуплет 3\nСпільно величайте Господа в житті,\nДумкою й ділами всі Йому служіть.\nХай сім’ю чудову вам збудує Бог \nІ зміцнить надію, віру і любов', '', '', '', '', 'ua', 0, NULL),
(785, 'Ось Боже стали дві душі', 0, 11, 'Куплет 1\nОсь, Боже, стали дві душі з єдиним почуттям: \nНедобре їм у самоті щоденного життя.\n\nПриспів:\nО, Боже наш,\t благослови\nТи душі ці і в них живи,\nПрийми від них Ти молитви,\nУ всьому їх благослови!\n\nКуплет 2\nОдному тяжко в світі жить, змовкає часто спів,\nА на шляху життя лежить все більше труднощів.\n\nКуплет 3\nЩоб легше в світі їм жилось в майбутньому житті, \nБлагослови Ти їх, Христос, у бажаній меті!\n\nКуплет 4\nОдне одного хай вони підтримують завжди,\nА ти до неба висоти їх, Боже, доведи!', '', '', '', '', 'ua', 0, NULL),
(786, 'В цей чудовий день весільний', 0, 11, 'Куплет 1\nВ цей чудовий день весільний ми прийшли вам побажать: \nЩастя й радості в дорогу, Господа не забувать.\n\nПриспів:\nНехай щастить\tвам навесні,\nУлітку, взимку, восени.\nХай допоможе вам усім Спаситель Сам.\n\nКуплет 2\nЗгода хай між вами буде, милість та любов Христа. \nХай Живе завжди між вами невмираюча весна.', '', '', '', '', 'ua', 0, NULL),
(787, 'Будь милосердниймій Христос', 0, 11, 'Куплет 1\nБудь милосердний,мій Христос,\nТобі вину мою приніс.\nДо Тебе я прийшов з гріхом,\nЗ провинами і тяжким злом.\n\nКуплет 2\nГріхам моїм нема числа,\nПровинам і учинкам зла.\nТа більше є Твоя любов, - \nЇх може змити Твоя кров.\n\nКуплет 3\nВід всіх гріхів мене обмий,\nМоїй душі пошли спокій;\nПрости мені, о, Спасе мій,\nЩоб був навіки я вже Твій.\n\nКуплет 4\nНа суд зі мною Ти не йди, - \nЧи ж вийду чистий і святий?\nМені по ласці Ти прости, \nСвоєю кровію обмий.\n\nКуплет 5\nБо грішників Ти кличеш Сам, \nДаєш прощення вічне їм.\nІ я на голос Твій спішу, \nПрощення, Господи, прошу!', '', '', '', '', 'ua', 0, NULL),
(788, 'Я Тебе Господь благаю', 0, 11, 'Куплет 1\nЯ Тебе, Господь, благаю, не забудь мене, почуй!\nЯ в глибокому відчаї, Боже любий, порятуй!\nТи любов, в Тебе прощення, грішник я, до Тебе йду, \nЗаспокоєння, спасіння тільки в Тобі я знайду.\n\nКуплет 2\nПрихилися, Боже правди, і мене не залишай,\nЯ стомився в злі, в неправді, мир з Тобою мені дай!\nНе пригадуй, що минуло, все прости, що зле робив,\nБув я в сні гріха заснулий, кращі дні в гріхах прожив.\n\nКуплет 3\nО, Спасителю ласкавий! О, Ісусе, захист мій!\nТи прийми мене, - благаю, спокій дай душі моїй!\nЯ одного лиш бажаю, - щоб навіки був я Твій;\nТи даси спасіння - знаю, простиш гріх, введеш в спокій.', '', '', '', '', 'ua', 0, NULL),
(789, 'О Предвічний Боже відколи живу', 0, 11, 'Куплет 1\nО, Предвічний Боже, відколи живу,\nЯ Тебе гнівити не перестаю. (2р.)\nТи свідчиш мені ласки і любов Свою,\nЯ Тобі за теє злобою плачу. (2р.)\n\nКуплет 2\nТи за мене, Спасе, кров Свою проляв,\nЯ, нещасний грішник, ще її топтав. (2р.)\nТи мене все кликав, щоб я не грішив,\nЯ не слухав цього, все безбожно жив. (2р.)\n\nКуплет 3\nЯк же довго, Боже, будеш мені терпів?\nЧи безкарно грішник буде все коїв? (2р.)\nЗ уст Твоїх, Ісусе, добре знаю це,\nЩо безбожних кара певно не мине. (2р.)\n\nКуплет 4\nГрішник там по смерті вчує страшний звук:\nГеть іди, проклятий, в пекло вічних мук! (2р.) \nГеть іди, проклятий, тиМя зневажав!\nТи служив мамоні, а Мене не знав. (2р.)\n\nКуплет 5\nО, не дай, Ісусе, прошу, молю Тя,\nЩоб на мні сповнилась страшна доля та. (2р.)\nЖалую і каюсь за гріхи мої,\nБоже милосердний, о прости мені! (2р.)\n\nКуплет 6\nЯ від нині хочу все Тобі служить,\nА посмерті в небі вічно Тя хвалить. (2р.)', '', '', '', '', 'ua', 0, NULL),
(790, 'Спи тихим і спокійним сном', 0, 11, 'Куплет 1\nСпи тихим і спокійним сном \nУ гробі тут, на місці цім,\nВже скоро наш Господь прийде \nІ в вічність Сам тебе введе.\n\nКуплет 2\nБлаженні вірні у Христі,\nЩо свято жили на землі;\nКоли Христос прийде назад,\nТо Він їм життя вічне дасть.\n\nКуплет 3\nВсі вірні в приході Христа \nІз мертвих встануть для життя;\nТоді Христос їх Сам візьме\nІ в Царство вічне уведе.\n\nКуплет 4\nСпочинь спокійно у землі,\nДокіль прийдуть щасливі дні,\nКоли Спаситель і тебе \nУ Вічний Край також візьме.', '', '', '', '', 'ua', 0, NULL),
(791, 'Заснув наш брате дорогий', 0, 11, 'Куплет 1\nЗаснув, наш брате дорогий, заснув,\nПокинувши тривогу днів земних,\nНе будеш там ти знову вже страждать, \nСпокійно спи, наш брат!\n\nКуплет 2\nМи любимо і всяк із нас скорбить,\nАле Христос сильніш вміє любить,\nТебе схотів до Себе Він узять,\nСпокійно спи, наш брат!\n\nКуплет 3\nСпокійно, тихо почиваєш ти,\nНе встанеш знову жить для суєти,\nДо тебе бурі зла не долетять,\nСпокійно спи, наш брат!\n\nКуплет 4\nДоки ще зло панує на землі,\nДоки земля дріма в гріховній млі,\nІ сльози на очах людей мигтять, \nСпокійно спи, наш брат!\n\nКуплет 5\nДо дня, коли Создатель воскресить \nУсіх, хто зараз тихо, тихо спить,\nІ прийде Він Своїх від мук узять,\nСпокійно спи, наш брат!\n\nКуплет 6\nДо дня, коли ми з пальмами в руках \nЗустрінем Господа на небесах \nЙ тебе зустрінем коло вічних врат, \nСпокійно спи, наш брат!', '', '', '', '', 'ua', 0, NULL),
(793, 'Боже милий я благаю', 0, 11, 'Куплет 1\nБоже милий, я благаю: не забудь мене, згадай!\nВід страждань земного краю мені захист, поміч дай!\n\nПриспів:\nІ я знаю, що з Тобою в цьому світі перейду;\nХоч з тяжкою боротьбою, але в світлий рай ввійду.\n\nКуплет 2\nТемна ніч панує всюди, серце скорбнеє болить;\nІ нема рятунку в людях, Боже, тяжко в світі жить!\n\nКуплет 3\nГрішний в світі я блукаю, в серці радості нема.\nЯ з Тобою жить бажаю, бо без Тебе горе, тьма.\n\nКуплет 4\nБоже, Боже, покладаюсь я на Тебе, Ти спасеш;\nВід гріха, плачу й відчаю. Мене в світлий рай візьмеш.', '', '', '', '', 'ua', 0, NULL),
(794, 'Вийшов я дорогою новою', 0, 11, 'Куплет 1\nВийшов я дорогою новою,\nВ темноті тернистий шлях лежить,\nА в Краю небесного спокою \nСвітло правди вічної горить.\n\nКуплет 2\nСвітло правди і життя святого,\nОсвіти мене в дорозі цій,\nПроведи шляхом життя земного, \nПоможи прийти в батьківський дім.\n\nКуплет 3\nЦе життя, як хвилі, що по морю \nСтрашно б''ють до берега, шумлять.\nЗнаю, що не любить він спокою:\nГрішний світ манить мене назад.\n\nКуплет 4\nЯ назад вже більше не вернуся,\nХоч мій шлях далекий і тяжкий, \nПерешкод ніяких не боюся,\nТільки прагну до мети дійти.\n\nКуплет 4\nЗмарнував я все своє багатство,\nВ Рідний Край вертаюсь знову я,\nВірю, що мене прийме мій батько,\nБо вернувсь, як згублена вівця.', '', '', '', '', 'ua', 0, NULL),
(795, 'Підняв Він мене з болота гріха', 0, 11, 'Куплет 1\nПідняв Він мене з болота гріха,\nПоставив Він ноги мої на скалі.\n\nПриспів:\nТому я співаю, Йому вся хвала,\nБо Ісус прийшов і підняв Він мене.\n\nКуплет 2\nОдежу мою, як сніг, убілив,\nПростив всі провини і їх віддалив.\n\nПриспів:\nТепер я спасенний, Йому вся хвала,\nСпасенний я кров''ю Ісуса Христа.\n\nКуплет 3\nВін вічне життя мені обіцяв,\nСказав: ти зі Мною жить будеш в раю.\n\nПриспів: \nВін дав цю надію, Йому вся хвала,\nВона потішає спасенні серця.\n\nКуплет 4\nСпіватиму я у кожний час,\nАж доки Він прийде у славі Своїй.\n\nПриспів: \nЙого я чекаю, Йому вся хвала,\nГряди Ісусе, жде Церква Твоя!', '', '', '', '', 'ua', 0, NULL),
(796, 'Бажаю я щоб весь мій дім', 0, 11, 'Куплет 1\nБажаю я, щоб весь мій дім \nТобі, о, Господи, служив;\nТи ж сили дай, щоб в домі цім \nЯ сам побожно й свято жив.\n\nКуплет 2\nДопоможи в ділах моїх \nСлужити прикладом для тих,\nЗ якими я повинен жить,\nЯких повинен я любить\n\nКуплет 3\nЄдині мрії маю я,\nЩоб я і вся моя сім''я \nСтворили в душах наших храм \nТвоїм Божественним словам.\n\nКуплет 4\nТобі я щиро віддаю \nСебе і всю мою сім''ю; \nПочуй, о, Господи, молю,\nІ ласку прояви Свою.', '', '', '', '', 'ua', 0, NULL),
(797, 'Відкриття молитовного дому', 0, 11, 'Куплет 1\nВідкриття молитовного дому \nХай освятить сьогодні Бог Сам,\nЩоб Христова тут Церква у Ньому \nВсе зростала в духовний теж храм.\nХай євангельську правду Господню \nСповіщають в нім слуги Христа;\nХай тут завжди, ось так, як сьогодні, \nВиявляється віра свята!\n\nКуплет 2\nХай знайдуть в цьому домі спасіння \nВсі ті душі, що блудять в гріхах!\nІ щоб правди святої насіння \nРозсівалося в людських серцях!\nХай молитви святим фіміамом \nТут з відкуплених ллються сердець \nДо небесного Божого храму,\nДе у славі царює Творець!\n\nКуплет 3\nХай бринить в цьому домі хваління \nПолум’яних духовних псалмів!\nЗа дароване Богом спасіння \nХай подяки підноситься спів!\nХай же дім цей навіки посвятить \nСам Отець, Син і Дух Твій Святий!\nХай духовно Бог Церкву збагатить,\nЩоб і дім, і народ був святий!', '', '', '', '', 'ua', 0, NULL),
(798, 'О Боже ми в Твоє Імя', 0, 11, 'Куплет 1\nО, Боже, ми в Твоє Ім''я \nТобі присвячуєм дім цей;\nХай завжди вся Твоя сім''я \nТут бачить лиш Твоє лице.\n\nКуплет 2\nХай в ньому проповідь свята\n Бринить із Біблії до всіх;\nНехай приходять до Христа \nСюди, кого ще мучить гріх.\n\nКуплет 3\nНе це лиш місце, але й нас,\nЯк Твій правдивий Божий храм, \nБлагословляй Ти кожен час,\nАж ми прийдем до вічних брам.\n\nКуплет 4\nЩоб в серці кожному Ти був,\nЩоб Дух Святий там завжди жив, \nЩоб кожен віруючий чув \nТвою присутність, силу, вплив.', '', '', '', '', 'ua', 0, NULL),
(799, 'Кров Христа обмила мене', 0, 11, 'Куплет 1\nКров Христа обмила мене (Зр.), обмила мене. \nКров Христа звільнила мене (Зр.), звільнила мене. \nКров Христа зцілила мене (3 р.),зцілила мене. \nАлілуя! Слава Тобі (Зр.), Алілуя!', '', '', '', '', 'ua', 3, NULL),
(800, 'Я не соромлюсь визнавать', 0, 11, 'Куплет 1\nЯ не соромлюсь визнавать воскреслого Христа, \nЙого веління сповіщать і міць Його хреста.\n\nПриспів:\nУ Христі, у Христі я душею ожив,\nУ Христі навіки я прозрів (я прозрів), \nУ Христі спасіння вічне я придбав, \nВіднині щасливий я вже став.\n\nКуплет 2\nЯ не соромлюсь визнавать в Нім Господа мого, \nХто спас мене, дав благодать, і Духа дав Свого.\n\nКуплет 3\nЯ не соромлюся нести зневагу за Христа; \nБлагаю: Боже, всім прости, то - їхня біднота.\n\nКуплет 4\nНе дасть Він сумніву мені при виді зла всього,\nІ не залишить на землі мене Він одного.', '', '', '', '', 'ua', 0, NULL),
(801, 'О Боже Твій вогонь', 0, 11, 'Куплет 1\nО, Боже, Твій вогонь священний,\nТвій вогонь, Твій вогонь нам пошли!\nТебе благаємо смиренно:\nТвій вогонь, Твій вогонь нам пошли!\nМоління наших душ прийми, \nСвятим нас Духом наповни\nІ благодаттю осіни!\nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 2\nГосподь Іллі, Тебе благаєм:\nТвій вогонь, Твій вогонь нам пошли! \nТобі служити ми бажаєм,\nТвій вогонь, Твій вогонь нам пошли! \nСвітильник віри хай горить,\nЖиттям святим бажаєм жить, \nГріховне все нехай згорить,\nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 3\nУсім холодним і байдужим \nТвій вогонь, Твій вогонь нам пошли! \nЛюбов’ю щоб палали душі - \nТвій вогонь, Твій вогонь нам пошли!\nУ Тебе ласку щоб знайти,\nВсю силу зла перемогти,\nПрожити свято й відійти, - \nТвій вогонь, Твій вогонь нам пошли!\n\nКуплет 4\nСлужіння з радістю звершати - \nТвій вогонь, Твій вогонь нам пошли!\nІ грішних від гріхів звільняти - \nТвій вогонь, Твій вогонь нам пошли! \nНа вівтар Твій кладем себе,\nВсе наше сильне і слабе,\nБажаєм славить лиш Тебе, - \nТвій вогонь, Твій вогонь нам пошли!', '', '', '', '', 'ua', 0, NULL),
(802, 'Тихо в Аравії', 0, 11, 'Куплет 1\nТихо в Аравії, росами ранніми \nТам простягається путь.\nЯків з родиною степом-пустинею \nНа батьківщину ідуть.\n\nКуплет 2\nТихо в Аравії, росами ранніми,\nТільки що сонце зійшло.\nЗдалека воїни, страшно озброєні - \nВійсько Ісава ішло.\n\nКуплет 3\nДвадцять років пройшло, - миру як не було; \nБрат був неначе той звір:\nЗ братом зближається, знищить збирається \nЯкова цілий табір.\n\nКуплет 4\nЯків минулу ніч із Богом мав зустріч,\nСерцем своїм сокрушивсь,\nТяжко зітхаючи, Бога благаючи.\nБог його благословив.\n\nКуплет 5\nТихо в Аравії, росами ранніми,\nПоперед війська Ісав.\nЯків кульгаючи, брата стрічаючи,\nСім раз на землю упав.\n\nКуплет 6\nБраття стрічаючись, раптом щось сталося, - \nПеремінився Ісав:\nМеч свій відкинувши, до брата кинувся, \nНіжно його обіймав.\n\nКуплет 7\nПлакали воїни, військо озброєне,\nПлакали діти й жінки.\nБраття мирилися, перемінилися \nЇхні серця і думки.\n\nКуплет 8\nТихо в Аравії, росами ранніми,\nТам простягається путь.\nЯків з родиною степом-пустинею \nДо Ханаану ідуть.', '', '', '', '', 'ua', 0, NULL),
(803, 'Настала на світі нежданна тривога', 0, 11, 'Куплет 1\nНастала на світі нежданна тривога,\nНіхто із людей не схотів.\nВсі люди чекають і плачуть, й ридають, - \nНе знають, що Бог так звелів.\n\nКуплет 2\nПовірте ви, люди, добра вже не буде, - \nНа світі ще гірше буде.\nБо вся ця тривога - вона є від Бога,\nІ Бог світ судити прийде.\n\nКуплет 3\nЖнива же доспіли, пішли женці жати \nВеликі Господні лани, \nПшеницю ізжали, кукіль пов’язали, - \nЗостались самі бур’яни.\n\nКуплет 4\nКукіль Господь спалить вогнем невгасимим, \nПшеницю - на тік забере. \nІ радість велика буде на Сіоні,\nКоли наш Спаситель прийде.\n\nКуплет 5\nЩасливі ті люди на світ народились,\nЩо в радість велику ввійдуть.\nНещасні ті люди, що їх там не буде,\nБо муки великі їх ждуть.\n\nКуплет 6\nО, грішнії люди, сьогодні покайтесь, \nЩоб в вічнім вогні не горіть.\nСьогодні усі ви до Бога зближайтесь \nІ більше в житті не грішіть!\n\nКуплет 7\nСьогодні усіх вас Господь закликає:\n“Усі ви до Мене прийдіть.\nЯ прийму вас в Царство Своє віковічне,\nЗі Мною будете ви жить”.\n\nКуплет 8\nІ ті, що почули, - до Бога звернулись:\n“О, Боже, нас, грішних, прости.\nДо Тебе лицем ми своїм повернулись, \nПрийми нас таких, як ми є!”', '', '', '', '', 'ua', 1, NULL),
(804, 'Дяка Богові від нас', 0, 11, 'Куплет 1\nДяка Богові від нас за осінній добрий час!\nВесь врожай зібрали ми перед приходом зими.\nБог дарів нам не жалів, нас врожаєм наділив.\nДяка Богові від нас за осінній добрий час!\n\nКуплет 2\nБожа нива - кожен край, що приносить урожай.\nАле часом ворог сам куколю насіє нам.\nТоді збіжжя добре те разом з куколем росте.\nБоже, нам принести дай лиш пшеничний урожай!\n\nКуплет 3\nЗнаємо, що любий Спас прийде по врожай до нас; \nТож кукіль Він того дня скаже витяти до пня,\nТа спалити на вогні, щоб і слід пропав по нім.\nЗерно ж Богочоловік позбирає - до засік.\n\nКуплет 4\nПрийди ж, Боже, на лани та й серпом Своїм пожни; \nВсіх спасенних позбирай, освяти та оправдай,\nЩоб в присутності Твоїй спокій мали всі святий. \nЖдуть Твої дочки й сини, щоб прийшов Ти на лани!', '', '', '', '', 'ua', 0, NULL),
(805, 'Господь ось ми обрали', 0, 11, 'Куплет 1\nГосподь, ось ми обрали служителів Твоїх.\nПро це Тебе благали - Ти показав нам їх.\n\nКуплет 2\nБлагослови служіння Ти вірних слуг Твоїх,\nДай їм Твоє терпіння, щоб успіх був у них.\n\nКуплет 3\nНавчай Ти їх, як дбати, служити як усім,\nБоротись не вгавати на їх шляху земнім.\n\nКуплет 4\nТи їх зроби взірцями для Божих всіх дітей, \nЩоб словом і ділами світили для людей.\n\nКуплет 5\nУ час тривоги й смутку їх духом підкріпляй,\nСвятим благословенням їх рясно наділяй!', '', '', '', '', 'ua', 0, NULL),
(806, 'Яке є щастя', 0, 11, 'Куплет 1\nЯке є щастя, що в земній недолі \nЄ добрий Друг, Якому я в тиші \nЗвертаюся в молитві: Господи, прости;\nЗвертаюся в молитві: Нас помилуй \nІ допоможи іти до Царства, Святим Духом підкріпи!\n\nПриспів:\nМи дякуєм Тобі за все!\nЗа сонце, місяць, зорі ясні.\nІсус, Ти все створив для нас,\nЩо нам дає життя прекрасне.\nМи дякуєм Тобі за хрест,\nЗа вічний дім у небі яснім.\nНехай Тобі звучить хвала,\nІ пісня наша хай не згасне!\n\nКуплет 2\nО, мій Спасе, як в житті чудово \nДякувать за все Тобі завжди.\nДякую за хліб, за хліб насущний,\nДякую за мир в краю моїм,\nДякую за милість, що до мене \nУ свій час Ти проявив.', '', '', '', '', 'ua', 0, NULL),
(807, 'Блажен хто серцем нелукавий', 0, 11, 'Куплет 1\nБлажен, хто серцем нелукавий!\nТакому Сам Господь відкрив\nШлях до небес в країну слави,\nЩоб він в оселях Божих жив.\nБлажен, хто всю свою надію \nПоклав на Господа Христа.\nТакому завжди серце гріє \nПромінням Біблія Свята.\n\nКуплет 2\nБлажен, хто у молитві щиро \nУміє з Богом розмовлять;\nЗіллється, як запашне миро,\nНа нього Божа благодать.\nБлажен, хто в дні життя земного \nХристовим шляхом правди йде.\nУ Царстві Божому такого\nВелика нагорода жде.', '', '', '', '', 'ua', 0, NULL),
(808, 'Юнаком Ти був на світі', 0, 11, 'Куплет 1\nЮнаком Ти був на світі, веселив серця \nІ ходив у заповіті Свойого Отця.\nНаучи і нас покірно дні земнії провести \nІ служити Богу вірно, світло скрізь нести.\n\nКуплет 2\nМатір Ти любив так ніжно, кривди не чинив;\nВ праці Иосифові, рідним ділом Ти служив.\nО, навчи й нас працювати для людей своїх й чужих, \nПравду Божу розсівати всюди, де панує гріх.\n\nКуплет 3\nТи душею був готовий чин святий звершать, \nСповіщав скрізь вічне Слово, Божу благодать.\nО, Учителю ласкавий, вчи й нас правду сповіщать, \nЩоби грішний світ, лукавий, міг Твою любов пізнать.', '', '', '', '', 'ua', 0, NULL),
(809, 'Хоч ми слабі', 0, 11, 'Куплет 1\nХоч ми слабі - ми поможем будувати Божий храм; \nВсі надії покладемо на Христа - Він поміч нам. \nЛегкий труд - Він так сказав, - помагати обіцяв.\n\nПриспів:\nО, осанна, Божий Сину!\nОсь бо Він так любить нас;\nСтерегтимем цю святиню, - \nЗ неба даний нам наказ.\n\nКуплет 2\nДуш багато йдуть в погибель шляхом горя і біди;\nГолос Божий всіх скликає: наверніться всі сюди!\nМи ж з Христом, і тільки з Ним, побудуєм Божий дім.\n\nКуплет 3\nЩоби Швидко та усюди видний був духовний храм,\nЩоб спокій, любов Христова відкривалися серцям, \nБоже наш, хай заклик Твій обіймає світ людський!', '', '', '', '', 'ua', 0, NULL),
(810, 'Боже чути Слово', 0, 11, 'Куплет 1\nБоже, чути Слово Ти дозволив знову.\nНам яви Твоє лице, освіти несвітле все!\n\nКуплет 2\nЖдем Тебе з дарами миру поміж нами.\nДай нам Духа благодать, серцем дай Тебе прийнять!\n\nКуплет 3\nВихваляйте знову всі Христа живого.\nВін дає життя вінець, Він наш Пастир і Отець!', '', '', '', '', 'ua', 0, NULL),
(811, 'В багряниці Син Божий', 0, 11, 'Куплет 1\nВ багряниці Син Божий, в терновім вінці,\nМіцно зв’язані зморені руки.\nСкільки втоми, страждання на світлім лиці,\nСкільки жалю до всіх, скільки муки...\n\nКуплет 2\nТа не тілом лиш терпить Спаситель за нас,\nХоч ганебні й жахливі знущання.\nСтрашні муки душі - знати в той скорбний час,\nЩо не всі приймуть Боже спасіння.\n\nКуплет 3\nПогляд Сина до грішних любов’ю горів,\nСерце ніжно усіх пригортало.\nТа лиш дехто цю Божу любов зрозумів,\nГрішні люди Ісуса розп’яли.\n\nКуплет 4\nТак томився Спаситель і тяжко терпів,\nБеззаконний світ з Бога сміявся.\nТа за тебе, мій друже, Він вмерти схотів \nВін за тебе на муки віддався.\n\nКуплет 5\nДруже мій, не відкинь ти любові Христа,\nНе забудь Його щире бажання!\nО, прийми ж ти спасіння, яке Він придбав,\nОціни Його муки й страждання!', '', '', '', '', 'ua', 0, NULL),
(812, 'Христос розпятий на хресті', 0, 11, 'Куплет 1\nХристос, розп''ятий на хресті за нас страждав,\nВін, повний ласки й доброти, усім прощав.\n\nКуплет 2\nХристос вмирав, а світ над Ним в той час глумивсь,\nВ нестерпних муках Божий Син за люд моливсь.\n\nКуплет 3\nЛюбов небесного Отця світ не пізнав,\nГріхами лютими серця свої скував.\n\nКуплет 4\nХристос, розп''ятий на хресті за нас вмирав;\nЩоб від загибелі спасти, Він смерть прийняв.', '', '', '', '', 'ua', 0, NULL),
(813, 'Діти в Бога і для вас', 0, 11, 'Куплет 1\nДіти, в Бога і для вас труд є всякий час.\nПотрудіться для Нього,- Він заплату дасть.\n\nПриспів:\nОсь я, мій Спаситель, ти мене пошли!\nДай Твій труд звершити, ближнім помогти!\n\nКуплет 2\nВаші рідні і брати помочі скрізь ждуть.\nПоможіть ви їм пройти земну, тяжку путь!\n\nКуплет 3\nЧасу їм свого вділіть, в праці поможіть!\nНе лінуйтесь, поспішіть поміч принести!', '', '', '', '', 'ua', 0, NULL),
(814, 'Боже Отче ми до Тебе', 0, 11, 'Куплет 1\nБоже, Отче, ми до Тебе з вірою йдемо,\nЦю сімейную потребу разом несемо.\n\nПриспів:\nБоже, Боже, ось мале дитя,\nУ свої візьми Ти руки все його життя!\n\nКуплет 2\nЦю, ні в чім невинну душу, Боже, стережи\nІ від зла, гріха й спокуси в світі збережи!\n\nКуплет 3\nТак, як Анна Самуїла, це дитя батьки \nУ любові захотіли принести Тобі.', '', '', '', '', 'ua', 0, NULL),
(816, 'В Спаса мого на лоні', 0, 11, 'Куплет 1\nВ Спаса мого на лоні, в любих Його руках,\nПісля турбот і праці спічне моя душа.\nНа небесах є радість, тому що я спасен.\nГам жде мене Отець мій; там Він мене прийме.\n\nПриспів:\nВ Спаса мого на лоні, в любих Його руках\nПісля турбот і праці спічне душа моя.\n\nКуплет 2\nВ Спаса мого на лоні, далеко від журби, - \nТам є спокій, безпека, гріху там не ввійти.\nІ ніщо не розлучить тут мене із Христом.\nЯ все готов страждати і йти Його слідом.\n\nКуплет 3\nСпас є моїм притулком, за мій гріх Він умер.\nНа Нього все надіюсь, Він любить все мене. \nТут я терплю й чекаю, поки ще ніч мине.\nЖду аж діждусь, що вічне сонечко нам зійде!', '', '', '', '', 'ua', 0, NULL);`